angular.module("bestvisionWeb").controller("addRoleCtrl", ["$scope", "Popup", "$timeout", "$rootScope", "$state", "ObjectFactory", "ListFactory", "$http", function ($scope, Popup, $timeout, $rootScope, $state, ObjectFactory, ListFactory, $http) {
  $scope.obj = {};
  $scope.create = function () {
    if (!$scope.obj.roleName) {
      Popup.notice("请输入角色名称");
      return false;
    }

    $scope.createAdminFactory = new ObjectFactory();
    var promise = $scope.createAdminFactory.saveOrQuery("/admin/createAdminRole.json", $scope.obj);
    promise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 3000, function () {});
      } else {
        Popup.notice("创建成功", 3000, function () {});
        $state.go("roleAdmin");
      }
    });
  };

  $scope.deleteId = function (index) {
    $scope.hospitalInList.splice(index, 1);
  };

  $scope.searchHospital = function (keyword, event) {
    if (event) {
      event.stopPropagation();
    }
    $scope.hopitalWrapper = true;
    $scope.hospitalListFactory = new ListFactory("/admin/getCompanyList.json", 0, 20, { keyword: $scope.keyword });
    $scope.hospitalListFactory.nextPage();
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("adminAreaListCtrl", ["$scope", "Popup", "$timeout", "$stateParams", "$rootScope", "$state", "ObjectFactory", "DateUtilFactory", "ListFactory", "$http", function ($scope, Popup, $timeout, $stateParams, $rootScope, $state, ObjectFactory, DateUtilFactory, ListFactory, $http) {
  var pageSize = 10;

  $scope.status = [{ id: 0, name: "正常" }, { id: 1, name: "停用" }];
  $scope.appStatus = [{ id: 0, name: "开启" }, { id: 1, name: "停用" }];
  $scope.changeStatus = function (id, status) {
    $scope.statusObjectFactory = new ObjectFactory();
    var promise = $scope.statusObjectFactory.saveOrQuery("/admin/changeStatus.json", { id: id, status: status });
    promise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 2000, function () {});
      } else {
        Popup.notice("修改成功", 2000, function () {});
      }
    });
  };
  $scope.obj = {};

  $scope.hideModal = function () {
    $scope.adminModal = false;
    $scope.viewModal = false;
    $scope.modifyRoleModal = false;
  };
  $scope.setStatus = function (status) {
    $scope.obj.status = status;
    $scope.searchAdminList();
  };

  $scope.getSuperObejctFactory = new ObjectFactory();
  $scope.getSuperObejctFactory.saveOrQuery("/admin/selectLoginAdminSubAreaLevelList.json");
  $scope.searchAdminList = function () {
    $scope.getAdminList = new ListFactory("/admin/getLoginAdminSubAreaAdminList.json", 0, 10, $scope.obj);
    var promise = $scope.getAdminList.nextPage();
    promise.then(function (data) {
      console.log(data);
      $(".first-pagination").pagination($scope.getAdminList.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.getAdminList.clearAndSetIndex(index * pageSize);
          $scope.getAdminList.nextPage();
        }
      });
    });
  };

  $scope.searchAdminList();
}]);
"use strict";

function _defineProperty(obj, key, value) { if (key in obj) { Object.defineProperty(obj, key, { value: value, enumerable: true, configurable: true, writable: true }); } else { obj[key] = value; } return obj; }

angular.module("bestvisionWeb").controller("adminListCtrl", ["$scope", "Popup", "$timeout", "$stateParams", "$rootScope", "$state", "ObjectFactory", "DateUtilFactory", "ListFactory", "$http", function ($scope, Popup, $timeout, $stateParams, $rootScope, $state, ObjectFactory, DateUtilFactory, ListFactory, $http) {
  var pageSize = 10;
  $scope.adminRoleId = [1, 2];
  $scope.status = [{ id: 0, name: "正常" }, { id: 1, name: "停用" }];
  $scope.appStatus = [{ id: 0, name: "开启" }, { id: 1, name: "停用" }];
  $scope.changeStatus = function (id, status, appStatus) {
    $scope.statusObjectFactory = new ObjectFactory();
    var promise = $scope.statusObjectFactory.saveOrQuery("/admin/changeStatus.json", { id: id, status: status, appStatus: appStatus });
    promise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 2000, function () {});
      } else {
        Popup.notice("修改成功", 2000, function () {});
      }
    });
  };
  $scope.obj = {};
  $scope.obj.adminRoleId = null;

  $scope.getSuperObejctFactory = new ObjectFactory();
  var superPromise = $scope.getSuperObejctFactory.saveOrQuery("/admin/getSuperStateList.json", {});
  superPromise.then(function (res) {
    $scope.selectAdmin(res.result.list[0].adminStateType.id, 0);
  });

  $scope.state = {};
  $scope.selectAdmin = function (stateId, idx) {
    $scope.state.seletedStateId = stateId;
    $scope.seletedAdminArray = $scope.getSuperObejctFactory.result.list[idx].adminStateList;
  };

  $scope.viewAdmin = function (adminId) {
    $scope.stuff = [];
    $scope.viewModal = true;
    $scope.viewFactory = new ObjectFactory();
    var viewPromise = $scope.viewFactory.saveOrQuery("/admin/getUnionAdminStateList.json", _defineProperty({ adminId: adminId }, "adminId", adminId));
    viewPromise.then(function (res) {
      var arr = res.result.list;
      for (var i = 0; i < arr.length; i++) {
        $scope.stuff[i] = {
          label: arr[i].adminStateType.stateTypeName,
          selected: arr[i].checkAll,
          children: []
        };
        for (var j = 0; j < arr[i].adminStateList.length; j++) {
          $scope.stuff[i].children[j] = {
            label: arr[i].adminStateList[j].corpAdminHome.stateName,
            state: arr[i].adminStateList[j].corpAdminHome.state,
            selected: arr[i].adminStateList[j].roleHaveState,
            children: []
          };

          for (var k = 0; k < arr[i].adminStateList[j].children.length; k++) {
            $scope.stuff[i].children[j].children[k] = {
              label: arr[i].adminStateList[j].children[k].corpAdminHome.stateName,
              state: arr[i].adminStateList[j].children[k].corpAdminHome.state,
              selected: arr[i].adminStateList[j].children[k].roleHaveState,
              children: []
            };
            for (var m = 0; m < arr[i].adminStateList[j].children[k].children.length; m++) {
              $scope.stuff[i].children[j].children[k].children[m] = {
                label: arr[i].adminStateList[j].children[k].children[m].corpAdminHome.stateName,
                state: arr[i].adminStateList[j].children[k].children[m].corpAdminHome.state,
                selected: arr[i].adminStateList[j].children[k].children[m].roleHaveState,
                children: []
              };
            }
          }
        }
      }
    });
  };
  $scope.showState = function () {
    $scope.adminModal = true;
    $scope.adminname = null;
    $scope.selectAdmin($scope.getSuperObejctFactory.result.list[0].adminStateType.id, 0);
  };
  $scope.state.name = "请选择权限";
  $scope.setState = function (state, stateName, childArr) {
    if (childArr) {
      return false;
    }
    $scope.state.name = stateName;
    $scope.obj.state = state;
  };
  $scope.searchName = function () {
    $scope.searchAdminList();
    $scope.adminModal = false;
  };

  $scope.setStatus = function (status) {
    $scope.obj.status = status;
    $scope.searchAdminList();
  };

  $scope.clearState = function () {
    delete $scope.obj.state;
    $scope.state.name = "请选择权限";
    $scope.searchAdminList();
  };

  $scope.hideModal = function () {
    $scope.adminModal = false;
    $scope.viewModal = false;
    $scope.modifyRoleModal = false;
  };

  $scope.tplFolderOpen = '<span class="iconfont icon-expend_more_filled"></span>';
  $scope.tplFolderClose = '<span class="iconfont icon-expend_right_filled"></span>';

  $scope.obj.isClinicAdmin = true;
  $scope.searchAdminList = function () {
    $scope.getAdminList = new ListFactory("/admin/getAdminList.json", 0, 10, $scope.obj);
    var promise = $scope.getAdminList.nextPage();
    promise.then(function (data) {
      console.log(data);
      $(".first-pagination").pagination($scope.getAdminList.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.getAdminList.clearAndSetIndex(index * pageSize);
          $scope.getAdminList.nextPage();
        }
      });
    });
  };

  $scope.searchAdminList();
  $scope.changeRole = function (adminId, adminRoleId, index) {
    var roleChangeFactory = new ObjectFactory();
    var promise = roleChangeFactory.saveOrQuery("/admin/changeAdminRole.json", { id: adminId, adminRoleId: adminRoleId });
    promise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 2000, function () {});
      } else {
        console.log(res);
        $scope.getAdminList.items[index].stateList = res.object.stateList;
        Popup.notice("修改成功", 2000, function () {});
        // $scope.searchAdminList();
      }
    });
  };

  $scope.showModifyRole = function () {
    $scope.modifyRoleModal = true;
    $scope.transfer.adminId = null;
    $scope.searchNormalAdminList();
  };

  $scope.transfer = {};

  $scope.setRole = function () {
    console.log($scope.transfer.adminId);

    if (!$scope.transfer.adminId) {
      Popup.notice("请选择账户");
      return false;
    }
    $rootScope.leftShow = false;
    $scope.transferRoleFactory = new ObjectFactory();
    var transferPromise = $scope.transferRoleFactory.saveOrQuery("/admin/transferAdminRole.json", { adminId: $scope.transfer.adminId });
    transferPromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 2000, function () {});
      } else {
        Popup.notice("转移成功", 2000, function () {});
        $scope.modifyRoleModal = false;

        $rootScope.leftShow = true;
        $state.go("404");
      }
    });
  };
  $scope.searchNormalAdminList = function () {
    $scope.getNormalAdminList = new ListFactory("/admin/getAdminList.json", 0, 10, { status: 0, keyword: $scope.normalKeyword, isClinicAdmin: true });
    var promise = $scope.getNormalAdminList.nextPage();
    promise.then(function (data) {
      $(".second-pagination").pagination($scope.getNormalAdminList.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.getNormalAdminList.clearAndSetIndex(index * pageSize);
          $scope.getNormalAdminList.nextPage();
        }
      });
    });
  };
}]);
