angular.module("bestvisionWeb").controller("adminPasswordModifyCtrl", ["$scope", "Popup", "$stateParams", "$rootScope", "$window", "$interval", "$state", "ObjectFactory", function ($scope, Popup, $stateParams, $rootScope, $window, $interval, $state, ObjectFactory) {
  if ($scope.$state.current.name == "adminPasswordModify") {
    $scope.tab = 1;
  } else {
    $scope.tab = 2;
  }

  $scope.object = {};
  $scope.object.adminId = $stateParams.adminId;
  $scope.object.sendSms = false;

  $scope.cancel = function () {
    $window.history.back();
  };
  $scope.getAdminInfoObejctFactory = new ObjectFactory();
  $scope.getAdminInfoObejctFactory.saveOrQuery("/admin/getOtherAdminInfo.json", { adminId: $scope.object.adminId });

  $scope.savePasswordFactory = new ObjectFactory();
  $scope.modify = function () {
    if (!$scope.object.password || $scope.object.password.length < 8) {
      Popup.notice("请至少输入八位密码", 2000, function () {});
      return false;
    }
    if ($scope.object.password === $scope.password) {
      var promise = $scope.savePasswordFactory.saveOrQuery("/admin/modifyOtherPass.json", $scope.object);
      promise.then(function (res) {
        if (res.status == 0) {
          Popup.notice("修改成功", 2000, function () {});
        } else {
          Popup.notice(res.errmsg, 2000, function () {});
        }
      });
    } else {
      Popup.notice("两次密码输入不一致", 2000, function () {});
    }
  };
}]);
