angular.module("bestvisionWeb").controller("createAdminCtrl", ["$scope", "Popup", "$timeout", "$rootScope", "$state", "ObjectFactory", "ListFactory", "$http", function ($scope, Popup, $timeout, $rootScope, $state, ObjectFactory, ListFactory, $http) {
  $scope.obj = {};

  $scope.hospitalIdArray = [];
  $scope.selected = [];
  $scope.schoolInList = [];
  // $scope.obj.adminRoleId = 6;
  $scope.create = function () {
    console.log($scope.obj);

    $scope.obj.schoolIdArray = [];
    if (!$scope.obj.nickname) {
      Popup.notice("请输入姓名", 2000, function () {});
      return false;
    }
    if (!/^1[3|4|5|6|7|8|9]\d{9}$/.test($scope.obj.mobile)) {
      if ($scope.obj.mobile) {
        Popup.notice("请输入正确的手机号" + $scope.obj.mobile, 2000, function () {});
      } else {
        Popup.notice("请输入正确的手机号", 2000, function () {});
      }

      return false;
    }

    if (!$scope.obj.adminRoleId) {
      Popup.notice("请选择角色", 2000, function () {});
      return false;
    }

    for (var j = 0, len = $scope.selected.length; j < len; j++) {
      if ($scope.selected[j]) {
        $scope.obj.schoolIdArray.push($scope.selected[j]);
      }
    }

    $scope.createAdminFactory = new ObjectFactory();
    var promise = $scope.createAdminFactory.saveOrQuery("/admin/createAdmin.json", $scope.obj);
    promise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 3000, function () {});
      } else {
        Popup.notice("创建成功", 3000, function () {});
        $state.go("adminList");
      }
    });
  };

  $scope.deleteId = function (index) {
    $scope.hospitalInList.splice(index, 1);
  };

  $scope.stuff = [];
  $scope.addHospital = false;
  $scope.addSchool = false;
  $scope.object = null;
  $scope.roleObj = {};
  $scope.tplFolderOpen = '<span class="iconfont icon-expend_more_filled"></span>';
  $scope.tplFolderClose = '<span class="iconfont icon-expend_right_filled"></span>';
  $scope.selectRole = function () {
    if ($scope.roleObj) {
      $scope.obj.adminRoleId = $scope.roleObj.adminRole.id;

      $scope.getStateFactory = new ObjectFactory();
      var statePromise = $scope.getStateFactory.saveOrQuery("/admin/getRoleStateListForUpdate.json", { adminRoleId: $scope.obj.adminRoleId });
      statePromise.then(function (res) {
        var arr = res.result.list;
        for (var i = 0; i < arr.length; i++) {
          $scope.stuff[i] = {
            label: arr[i].adminStateType.stateTypeName,
            selected: arr[i].checkAll,

            children: []
          };
          for (var j = 0; j < arr[i].adminStateList.length; j++) {
            $scope.stuff[i].children[j] = {
              label: arr[i].adminStateList[j].corpAdminHome.stateName,
              state: arr[i].adminStateList[j].corpAdminHome.state,
              selected: arr[i].adminStateList[j].roleHaveState,
              children: []
            };

            for (var k = 0; k < arr[i].adminStateList[j].children.length; k++) {
              $scope.stuff[i].children[j].children[k] = {
                label: arr[i].adminStateList[j].children[k].corpAdminHome.stateName,
                state: arr[i].adminStateList[j].children[k].corpAdminHome.state,
                selected: arr[i].adminStateList[j].children[k].roleHaveState,
                children: []
              };

              for (var m = 0; m < arr[i].adminStateList[j].children[k].children.length; m++) {
                $scope.stuff[i].children[j].children[k].children[m] = {
                  label: arr[i].adminStateList[j].children[k].children[m].corpAdminHome.stateName,
                  state: arr[i].adminStateList[j].children[k].children[m].corpAdminHome.state,
                  selected: arr[i].adminStateList[j].children[k].children[m].roleHaveState,
                  children: []
                };
              }
            }
          }
        }
      });

      if ($scope.roleObj.adminRole.superType == 10) {
        $scope.addSchool = true;
      } else {
        $scope.addSchool = false;
      }
    } else {
      $scope.obj.adminRoleId = null;
    }
  };
  var corpInfo = localStorage.getItem("corpInfo");
  corpInfo = corpInfo == null ? { companyTitle: "门店", employeeTitle: "视光师" } : JSON.parse(corpInfo);
  var companyTitle = corpInfo.companyTitle;
  $scope.supplierWord = "请选择" + companyTitle;
  $scope.hide = function () {
    $scope.hopitalWrapper = false;
  };
  $scope.searchHospital = function (keyword, event) {
    if (event) {
      event.stopPropagation();
    }
    $scope.hopitalWrapper = true;
    $scope.hospitalListFactory = new ListFactory("/admin/getCompanyList.json", 0, 20, { keyword: $scope.keyword });
    $scope.hospitalListFactory.nextPage();
  };
  $scope.showMsg = function () {
    Popup.notice("角色固有权限不能修改，如需添加请使用动态授权");
  };

  $scope.searchSchool = function () {
    $scope.schoolListFactory = new ListFactory("/admin/getSchoolList.json", 0, 12, { keyword: $scope.keyword, schoolType: 0 });
    var schoolPromise = $scope.schoolListFactory.nextPage();
    schoolPromise.then(function (res) {
      var pageSize = 12;
      $(".second-pagination").pagination($scope.schoolListFactory.count, {
        items_per_page: pageSize,

        callback: function callback(index) {
          $scope.schoolListFactory.clearAndSetIndex(index * pageSize);
          $scope.schoolListFactory.nextPage();

          $scope.count = 0;
          $scope.isSelectedAllStatus = true;
        }
      });
    });
  };

  //创建变量用来保存选中结果

  var updateSelected = function updateSelected(action, id, name) {
    if (action == "add" && $scope.selected.indexOf(id) == -1) {
      $scope.selected.push(id);
      $scope.schoolInList.push(name);
    }
    if (action == "remove" && $scope.selected.indexOf(id) != -1) {
      $scope.selected.splice($scope.selected.indexOf(id), 1);
      $scope.schoolInList.splice($scope.schoolInList.indexOf(name), 1);
    }
  };

  //全选操作
  $scope.selectAll = function ($event) {
    var checkbox = $event.target;
    var action = checkbox.checked ? "add" : "remove";
    for (var i = 0; i < $scope.schoolListFactory.items.length; i++) {
      var contact = $scope.schoolListFactory.items[i];
      updateSelected(action, contact.id, contact.schoolName);
    }
  };

  //更新某一列数据的选择
  $scope.updateSelection = function ($event, id, name) {
    var checkbox = $event.target;
    if (!checkbox.checked) {
      $scope.isSelectedAllStatus = false;
    }
    var action = checkbox.checked ? "add" : "remove";
    updateSelected(action, id, name);
  };
  $scope.count = 0;
  $scope.isSelectedAllStatus = true;
  $scope.isSelected = function (id) {
    if ($scope.selected.indexOf(id) < 0) {
      $scope.count = $scope.count + 1;
    }

    console.log("checked");

    if ($scope.count) {
      $scope.isSelectedAllStatus = false;
    }

    return $scope.selected.indexOf(id) >= 0;
  };

  $scope.modifySchool = function () {
    $scope.schoolModal = false;
  };

  $scope.showSchoolModal = function () {
    $scope.searchSchool();
    $scope.schoolModal = true;
  };

  $scope.hospitalInList = [];
  $scope.schoolIdList = [];
  $scope.hopitalWrapper = false;

  $scope.selectHospitalId = function (companyName, id) {
    for (var i = 0, len = $scope.hospitalInList.length; i < len; i++) {
      if ($scope.hospitalInList[i].id == id) {
        $scope.hopitalWrapper = false;
        return;
      }
    }

    $scope.hospitalInList.push({ companyName: companyName, id: id });
    $scope.hopitalWrapper = false;
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("createAdminAreaCtrl", ["$scope", "Popup", "$state", "ObjectFactory", function ($scope, Popup, $state, ObjectFactory) {
  $scope.obj = {};
  $scope.stuff = [];

  $scope.createObj = {};

  $scope.createObj.areaLevelId = null;

  $scope.getSuperObejctFactory = new ObjectFactory();
  var levelpromise = $scope.getSuperObejctFactory.saveOrQuery("/admin/selectLoginAdminSubAreaLevelList.json");

  levelpromise.then(function (res) {
    if (res.result.list.length) {
      $scope.createObj.areaLevelId = res.result.list[0].id;
    }
  });
  $scope.getCityFactory = new ObjectFactory();
  var cityPromise = $scope.getCityFactory.saveOrQuery("/admin/getProvinceVoList.json");
  cityPromise.then(function (res) {
    $scope.data = res.result.list;
    $scope.getMyLevelObejctFactory = new ObjectFactory();
    var adminPromise = $scope.getMyLevelObejctFactory.saveOrQuery("/admin/getLoginAdminAreaLevelVo.json");
    adminPromise.then(function (resp) {
      if (resp.object.adminAreaLevel.provinceAreaId) {
        $scope.createObj.provinceAreaId = resp.object.adminAreaLevel.provinceAreaId + "";
        $scope.changeProvince();
      }
      if (resp.object.adminAreaLevel.cityAreaId) {
        $scope.createObj.cityAreaId = resp.object.adminAreaLevel.cityAreaId + "";
        $scope.chooseCity();
      }

      if (resp.object.adminAreaLevel.districtAreaId) {
        $scope.createObj.districtAreaId = resp.object.adminAreaLevel.districtAreaId + "";
      }
    });
  });
  $scope.changeProvince = function () {
    var selectedProvinceIndex;
    angular.forEach($scope.data, function (item, index) {
      if (item.code === $scope.createObj.provinceAreaId) {
        selectedProvinceIndex = index;
        return;
      }
    });
    $scope.createObj.cityAreaId = null;
    $scope.createObj.districtAreaId = null;

    $scope.citiesData = $scope.data[selectedProvinceIndex].cityList;
    $scope.districtData = [];
  };
  $scope.chooseCity = function () {
    if ($scope.createObj.cityAreaId) {
      var selectedCityIndex;
      angular.forEach($scope.citiesData, function (item, index) {
        if (item.code === $scope.createObj.cityAreaId) {
          selectedCityIndex = index;
          return;
        }
      });
      $scope.createObj.districtAreaId = null;
      $scope.districtData = $scope.citiesData[selectedCityIndex].areaList;
    }
  };

  $scope.getRoleObejctFactory = new ObjectFactory();
  var superPromise = $scope.getRoleObejctFactory.saveOrQuery("/admin/getAreaAdminRole.json");
  superPromise.then(function (res) {
    $scope.createObj.adminRoleId = res.result.object.id;
  });

  $scope.createArea = function () {
    if (!$scope.createObj.nickname) {
      Popup.notice("请输入姓名", 2000, function () {});
      return false;
    }
    if (!/^1[3|4|5|6|7|8|9]\d{9}$/.test($scope.createObj.mobile)) {
      if ($scope.createObj.mobile) {
        Popup.notice("请输入正确的手机号" + $scope.createObj.mobile, 2000, function () {});
      } else {
        Popup.notice("请输入正确的手机号", 2000, function () {});
      }

      return false;
    }
    if (!$scope.createObj.areaLevelId) {
      Popup.notice("请选择机构级别", 2000, function () {});
      return false;
    }

    $scope.createAdminFactory = new ObjectFactory();
    var promise = $scope.createAdminFactory.saveOrQuery("/admin/createAreaAdmin.json", $scope.createObj);
    promise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 3000, function () {});
      } else {
        Popup.notice("创建成功", 3000, function () {});
        $state.go("adminAreaList");
      }
    });
  };
}]);
'use strict';

angular.module('bestvisionWeb').controller('encryptUserCtrl', ['$scope', 'Popup', '$timeout', '$stateParams', '$rootScope', '$state', 'ObjectFactory', 'EscapeFactory', 'ListFactory', '$http', function ($scope, Popup, $timeout, $stateParams, $rootScope, $state, ObjectFactory, EscapeFactory, ListFactory, $http) {
    $scope.pageSize = 10;
    $scope.anzhuangShow = false;

    $scope.status = [{ id: 0, name: '正常' }, { id: 1, name: '停用' }];
    $scope.obj = {};
    $scope.obj.useWatchdog = 0;

    $scope.getSuperObejctFactory = new ObjectFactory();
    var superPromise = $scope.getSuperObejctFactory.saveOrQuery('/admin/getCorpWatchdogConf.json', {});
    superPromise.then(function (res) {
        $scope.obj.useWatchdog = res.result.object.useWatchdog;
    });

    $scope.setDog = function (val) {
        console.log(val);
        $scope.createAdminFactory = new ObjectFactory();
        var promise = $scope.createAdminFactory.saveOrQuery('/admin/saveCorpWatchdogConf.json', { useWatchdog: val });
        promise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg, 3000, function () {});
            } else {
                Popup.notice('修改成功', 3000, function () {});
            }
        });
    };

    $scope.searchAdminList = function () {
        $scope.getAdminList = new ListFactory('/admin/selectWatchdogList.json', 0, 10, { keyword: $scope.keyword });
        var promise = $scope.getAdminList.nextPage();
        promise.then(function (data) {
            console.log(data);
            $(".first-pagination").pagination($scope.getAdminList.count, {
                items_per_page: $scope.pageSize,
                callback: function callback(index) {
                    $scope.getAdminList.clearAndSetIndex(index * $scope.pageSize);
                    $scope.getAdminList.nextPage();
                }
            });
        });
    };
    $scope.searchAdminList();

    $scope.changeStatus = function (id, status) {
        $scope.statusObjectFactory = new ObjectFactory();
        var promise = $scope.statusObjectFactory.saveOrQuery('/admin/updateWatchdogStatus.json', { watchdogId: id, status: status });
        promise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg, 2000, function () {});
            } else {
                Popup.notice('修改成功', 2000, function () {});
                // $state.go('encryptUser', {}, { reload: true });
            }
        });
    };

    $scope.corpid = localStorage.getItem("corpid");

    var letval = localStorage.getItem($scope.corpid + "_userCert");
    if (letval !== "null" && letval !== null) {
        $scope.userCert = JSON.parse(EscapeFactory.uncompileStr(localStorage.getItem($scope.corpid + "_userCert")));
    } else {
        $scope.userCert = {};
    }

    console.log($scope.userCert, 'cert');

    var watchdogId = $scope.userCert ? $scope.userCert.id : null;
    $scope.getWatchdogObejctFactory = new ObjectFactory();
    $scope.getWatchdogObejctFactory.saveOrQuery('/admin/getWatchdog.json', { watchdogId: watchdogId });

    var isDeleted = function isDeleted() {
        if (!$scope.userCert) {
            return false;
        }
        $scope.isDeletedObejctFactory = new ObjectFactory();
        var deletePromise = $scope.isDeletedObejctFactory.saveOrQuery('/auth/isCertificateDeleted.json', { certificate: $scope.userCert.serialNumber, certificateVersion: $scope.userCert.version });
        deletePromise.then(function (res) {
            if (res.result.certificateDeleted) {
                localStorage.removeItem($scope.corpid + "_userCert");
                $scope.userCert = null;
            }
        });
    };

    isDeleted();

    $scope.encrypt = {};
    $scope.makeEncrypt = function (number, version) {
        $scope.encrypt.serialNumber = number;
        $scope.encrypt.version = version;
        $scope.tab = 1;
        $scope.anzhuangShow = true;
        $scope.user.remark = null;
    };

    $scope.xiezai = {};
    $scope.xiezai = { open: false };
    $scope.upload = function (number) {

        $scope.xiezaiShow = true;
        $scope.xiezai.serialNumber = number;
    };
    $scope.clearEncrypt = function () {

        $scope.clearencryptObjectFactory = new ObjectFactory();
        var clearpromise = $scope.clearencryptObjectFactory.saveOrQuery('/admin/refreshWatchdogLocalStore.json', { serialNumber: $scope.xiezai.serialNumber });
        clearpromise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg, 2000, function () {});
            } else {
                Popup.notice('卸载成功', 2000, function () {});
                $scope.xiezaiShow = false;

                $timeout(function () {
                    $state.reload();
                }, 200);
            }
        });
    };

    $scope.hideModal = function () {
        $scope.xiezaiShow = false;
        $scope.anzhuangShow = false;
    };

    $scope.addRemark = function () {

        $scope.encrypt.remark = $scope.user.remark;
        $scope.encrypt.localStore = 1;
        $scope.encryptObjectFactory = new ObjectFactory();
        var promise = $scope.encryptObjectFactory.saveOrQuery('/admin/updateWatchdogLocalStore.json', $scope.encrypt);
        promise.then(function (res) {

            if (res.status == 1) {
                Popup.notice(res.errmsg, 2000, function () {});
            } else {
                Popup.notice('安装成功', 2000, function () {});
                console.log(EscapeFactory.compileStr(JSON.stringify(res.result.object)));
                console.log($scope.corpid + "_userCert");
                $scope.anzhuangShow = false;
                localStorage.setItem($scope.corpid + "_userCert", EscapeFactory.compileStr(JSON.stringify(res.result.object)));
                $timeout(function () {
                    $state.reload();
                }, 200);
            }
        });
    };

    $scope.showRemark = function (id) {
        $scope.anzhuangShow = true;
        $scope.user.watchdogId = id;

        $scope.user.remark = null;
        $scope.tab = 2;
    };

    $scope.checkBefore = function () {

        if ($scope.tab == 1) {
            $scope.addRemark();
        } else {
            $scope.updateRemark();
        }
    };
    $scope.user = {};
    $scope.updateRemark = function () {

        $scope.updateRemarkObjectFactory = new ObjectFactory();
        var promise = $scope.updateRemarkObjectFactory.saveOrQuery('/admin/updateWatchdog.json', $scope.user);
        promise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg, 2000, function () {});
            } else {
                Popup.notice('修改成功', 2000, function () {});
                $scope.anzhuangShow = false;
                $scope.searchAdminList();
            }
        });
    };
    $scope.deleteEncrypt = function () {

        $scope.encryptObjectFactory = new ObjectFactory();
        var promise = $scope.encryptObjectFactory.saveOrQuery('/admin/updateWatchdogLocalStore.json', { serialNumber: $scope.userCert.serialNumber, localStore: 0, version: $scope.userCert.version, remark: '' });
        promise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg, 2000, function () {});
            } else {
                Popup.notice('卸载成功', 2000, function () {});
                localStorage.removeItem($scope.corpid + "_userCert");
                $state.go('encryptUser', {}, { reload: true });
            }
        });
    };
}]);
'use strict';

angular.module('bestvisionWeb').controller('memberAdminCtrl', ['$scope', 'Popup', '$timeout', '$stateParams', '$rootScope', '$state', 'ObjectFactory', 'DateUtilFactory', 'ListFactory', '$http', function ($scope, Popup, $timeout, $stateParams, $rootScope, $state, ObjectFactory, DateUtilFactory, ListFactory, $http) {
    var pageSize = 10;

    $scope.obj = {};
    $scope.obj.status = null;

    $scope.searchEmployee = function () {
        $scope.employeeListFactory = new ListFactory('/admin/selectEmployeeVoList.json', 0, 20, { keyword: $scope.doctorKeyword, status: 0 });
        $scope.employeeListFactory.nextPage();
    };
    $scope.searchEmployee();

    $scope.showModal = function (id, name) {
        $scope.employeeIdFrom = id;
        $scope.fromName = name;
        $scope.bandingCustomerListFactory = new ListFactory('/admin/selectBandingCustomerList.json', 0, 26, { keyword: $scope.bandKeyword, employeeId: id });
        $scope.bandingCustomerListFactory.nextPage();

        $scope.adminModal = true;
    };

    $scope.hideModal = function () {
        $scope.adminModal = false;
    };

    $scope.modify = function () {

        if (!$scope.employeeIdTo) {
            Popup.notice("请选择迁移的会员");
            return false;
        }

        Popup.confirm('确定将' + $scope.fromName + '的会员迁移到' + $scope.toName + '名下？', function () {

            $scope.moveCustomer();
        }, function () {});
    };
    $scope.chooseEmployeeTo = function (id, name) {
        $scope.employeeIdTo = id;
        $scope.toName = name;
    };
    $scope.moveCustomer = function () {
        $scope.moveCustomerFactory = new ObjectFactory();
        var movePromise = $scope.moveCustomerFactory.saveOrQuery("/admin/moveCustomersOfEmployee.json", { employeeIdFrom: $scope.employeeIdFrom, employeeIdTo: $scope.employeeIdTo });
        movePromise.then(function (res) {
            if (res.status == 0) {
                $scope.adminModal = false;
                $scope.obj.keyword = null;
                $scope.searchAdminList();
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };

    $scope.searchAdminList = function () {
        $scope.getAdminList = new ListFactory('/admin/getAdminCustVoList.json', 0, 10, $scope.obj);
        var promise = $scope.getAdminList.nextPage();
        promise.then(function (data) {
            console.log(data);
            $("#Pagination").pagination($scope.getAdminList.count, {
                items_per_page: pageSize,
                callback: function callback(index) {
                    $scope.getAdminList.clearAndSetIndex(index * pageSize);
                    $scope.getAdminList.nextPage();
                }
            });
        });
    };

    $scope.setStatus = function (status) {
        $scope.obj.status = status;
        $scope.searchAdminList();
    };

    $scope.searchAdminList();
}]);
"use strict";

angular.module("bestvisionWeb").controller("modifyAdminAreaCtrl", ["$scope", "Popup", "$state", "$stateParams", "ObjectFactory", function ($scope, Popup, $state, $stateParams, ObjectFactory) {
  $scope.obj = {};
  $scope.stuff = [];

  $scope.createObj = {};
  $scope.createObj.adminId = $stateParams.adminId;
  $scope.createObj.areaLevelId = null;

  $scope.getSuperObejctFactory = new ObjectFactory();
  $scope.getSuperObejctFactory.saveOrQuery("/admin/selectLoginAdminSubAreaLevelList.json");

  $scope.changeLevel = function () {
    if ($scope.createObj.areaLevelId == 1) {
      $scope.createObj.cityAreaId = null;
      $scope.createObj.districtAreaId = null;
    } else if ($scope.createObj.areaLevelId == 2) {
      $scope.createObj.districtAreaId = null;
    } else {}
  };
  $scope.getCityFactory = new ObjectFactory();
  var cityPromise = $scope.getCityFactory.saveOrQuery("/admin/getProvinceVoList.json");
  cityPromise.then(function (res) {
    $scope.data = res.result.list;
    $scope.getMyLevelObejctFactory = new ObjectFactory();
    var adminPromise = $scope.getMyLevelObejctFactory.saveOrQuery("/admin/getAdminAreaLevelVo.json", { adminId: $scope.createObj.adminId });
    adminPromise.then(function (resp) {
      $scope.createObj.nickname = resp.object.admin.nickname;
      $scope.createObj.mobile = resp.object.admin.mobile;
      $scope.createObj.governmentName = resp.object.adminAreaLevel.governmentName;
      $scope.createObj.areaLevelId = resp.object.adminAreaLevel.areaLevelId;
      if (resp.object.adminAreaLevel.provinceAreaId) {
        $scope.createObj.provinceAreaId = resp.object.adminAreaLevel.provinceAreaId + "";
        $scope.changeProvince();
      }
      if (resp.object.adminAreaLevel.cityAreaId) {
        $scope.createObj.cityAreaId = resp.object.adminAreaLevel.cityAreaId + "";
        $scope.chooseCity();
      }

      if (resp.object.adminAreaLevel.districtAreaId) {
        $scope.createObj.districtAreaId = resp.object.adminAreaLevel.districtAreaId + "";
      }
    });
  });

  $scope.getRoleObejctFactory = new ObjectFactory();
  var superPromise = $scope.getRoleObejctFactory.saveOrQuery("/admin/getAreaAdminRole.json");
  superPromise.then(function (res) {
    $scope.createObj.adminRoleId = res.result.object.id;
  });
  $scope.changeProvince = function () {
    var selectedProvinceIndex;
    angular.forEach($scope.data, function (item, index) {
      if (item.code === $scope.createObj.provinceAreaId) {
        selectedProvinceIndex = index;
        return;
      }
    });
    $scope.createObj.cityAreaId = null;
    $scope.createObj.districtAreaId = null;

    $scope.citiesData = $scope.data[selectedProvinceIndex].cityList;
    $scope.districtData = [];
  };
  $scope.chooseCity = function () {
    if ($scope.createObj.cityAreaId) {
      var selectedCityIndex;
      angular.forEach($scope.citiesData, function (item, index) {
        if (item.code === $scope.createObj.cityAreaId) {
          selectedCityIndex = index;
          return;
        }
      });
      $scope.createObj.districtAreaId = null;
      $scope.districtData = $scope.citiesData[selectedCityIndex].areaList;
    }
  };

  $scope.createArea = function () {
    if (!$scope.createObj.nickname) {
      Popup.notice("请输入姓名", 2000, function () {});
      return false;
    }
    if (!$scope.createObj.areaLevelId) {
      Popup.notice("请选择机构级别", 2000, function () {});
      return false;
    }

    $scope.createAdminFactory = new ObjectFactory();
    var promise = $scope.createAdminFactory.saveOrQuery("/admin/updateAreaAdmin.json", $scope.createObj);
    promise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 3000, function () {});
      } else {
        Popup.notice("修改成功", 3000, function () {});
        $state.go("adminAreaList");
      }
    });
  };
}]);
"use strict";

