angular.module("bestvisionWeb").controller("myAccountHistoryCtrl", ["$scope", "ListFactory", function ($scope, ListFactory) {
  // 筛选条件
  $scope.condition = {
    status: null,
    tablist: [{ status: null, name: "全部" }, { status: 1, name: "续费" }, { status: 2, name: "解锁VIP功能" }, { status: 3, name: "提需求" }, { status: 4, name: "短信" }, { status: 5, name: "语音" }],
    callback: function callback() {
      $scope.searchHistory();
    }
  };
  // 系统续费
  $scope.system_renew = {
    show: false
  };
  // 解锁功能
  $scope.lock = {
    state: "screenConditionBatch",
    needLock: false,
    lookBack: function lookBack() {
      $scope.searchHistory();
    },
    openLock: function openLock(item) {
      this.state = item.state;
      if (!this.state) {
        $scope.system_renew.show = true;
        return;
      }
      this.needLock = true;
    }
  };
  $scope.filterPayment = function (channelList) {
    if (Win_typeOf(channelList) !== "array") return "";
    var list = channelList.reduce(function (pre, next) {
      pre.push("" + window.optionsObj.coinPay[next.payChannel] + next.amount + " ");
      return pre;
    }, []);
    return list.join(",");
  };
  $scope.searchHistory = function () {
    var pageSize = 10;
    $scope.accountList = new ListFactory("/admin/selectMyCorpPaymentOrder.json", 0, pageSize, {
      sceneTypeArray: $scope.condition.status
    });
    var promise = $scope.accountList.nextPage();
    promise.then(function (data) {
      $("#Pagination").pagination($scope.accountList.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.accountList.clearAndSetIndex(index * pageSize);
          $scope.accountList.nextPage();
        }
      });
    });
  };
  $scope.searchHistory();
}]);
"use strict";

