angular.module("bestvisionWeb").controller("machineOrderListCtrl", ["$scope", "Popup", "$timeout", "$stateParams", "$rootScope", "$state", "ObjectFactory", "DateUtilFactory", "ListFactory", "$http", function ($scope, Popup, $timeout, $stateParams, $rootScope, $state, ObjectFactory, DateUtilFactory, ListFactory, $http) {
  var pageSize = 10;
  $scope.obj = {};
  $scope.obj.startTime = new Date();
  $scope.rightTime = new Date();
  $scope.obj.machineCenterId = null;
  $scope.obj.receiveStatus = null;
  $scope.centerArr = [];
  window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (res) {
    if (res) {
      $scope.companyName = res.companyName;
      $scope.obj.companyId = res.id;
      $scope.getCenterListRecordPay = new ObjectFactory();
      var centerPromise = $scope.getCenterListRecordPay.saveOrQuery("/admin/selectMachineCenterListOfProduct.json", { companyId: res.id });
      centerPromise.then(function (resp) {
        var arr = resp.result.list;
        for (var i = 0; i < arr.length; i++) {
          $scope.centerArr.push({
            id: arr[i].id,
            name: arr[i].name
          });
        }
      });

      $scope.obj.receiveStatus = 0;
      $scope.setTab(4);
    }
    $scope.setCompanyModal = !res;
  });

  $scope.searchAdminList = function () {
    if ($scope.obj.startTime && $scope.rightTime) {
      $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
      $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);

      $scope.getAdminList = new ListFactory("/admin/selectMachineCenterOrderRecordVoList.json", 0, 10, $scope.obj);
      var promise = $scope.getAdminList.nextPage();
      promise.then(function (data) {
        console.log(data);
        $(".first-pagination").pagination($scope.getAdminList.count, {
          items_per_page: pageSize,
          callback: function callback(index) {
            $scope.getAdminList.clearAndSetIndex(index * pageSize);
            $scope.getAdminList.nextPage();
          }
        });
      });
    }
  };

  $scope.receiveOrder = function (id, idx) {
    Popup.confirm("确定签收么", function () {
      $scope.receiveFactory = new ObjectFactory();
      var receivePromise = $scope.receiveFactory.saveOrQuery("/admin/receiveMachineCenterOrder.json", { machineCenterOrderId: id });
      receivePromise.then(function (re) {
        if (re.status == 0) {
          Popup.notice("签收成功");
          $scope.getAdminList.items[idx].machineCenterOrder.receiveStatus = 1;
          $scope.getAdminList.count = $scope.getAdminList.count - 1;
        } else {
          Popup.notice(re.errmsg);
        }
      });
    }, function () {});
  };
  $scope.deliveryReceiveOrder = function (id, idx) {
    Popup.confirm("确定发货么", function () {
      $scope.deliveryFactory = new ObjectFactory();
      var deliveryPromise = $scope.deliveryFactory.saveOrQuery("/admin/deliveryMachineCenterOrder.json", { machineCenterOrderId: id });
      deliveryPromise.then(function (re) {
        if (re.status == 0) {
          Popup.notice("发货成功");
          $scope.getAdminList.items[idx].medicalProductDelivery.deliveryStatus = 1;
        } else {
          Popup.notice(re.errmsg);
        }
      });
    }, function () {});
  };
  $scope.tab = 1;
  $scope.changeReceiveStatus = function (index) {
    $scope.obj.receiveStatus = index;
    $scope.searchAdminList();
  };
  $scope.setTab = function (tab) {
    if (tab == 1) {
      $scope.obj.acceptStatus = null;
      $scope.obj.statusArray = null;
    } else if (tab == 2) {
      $scope.obj.acceptStatus = 0;
      $scope.obj.statusArray = [0];
    } else if (tab == 3) {
      $scope.obj.acceptStatus = 1;
      $scope.obj.statusArray = [0, 1];
    } else if (tab == 4) {
      $scope.obj.acceptStatus = 1;
      $scope.obj.statusArray = [2];
    } else {}
    $scope.tab = tab;
    $scope.searchAdminList();
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("partBackCtrl", ["$scope", "$stateParams", "Popup", "ObjectFactory", "HttpFactory", "$state", "MultipleChoseClass", "PromiseAll", "partBackClass", "$timeout", function ($scope, $stateParams, Popup, ObjectFactory, HttpFactory, $state, MultipleChoseClass, PromiseAll, partBackClass, $timeout) {
    $scope.printShoufei = {
        show: false,
        onlyShow: true,
        options: [{
            url: "getMedicalRecordCashflowVo",
            param: { cashflowId: $stateParams.cashflowId }
        }],
        click: function click() {
            this.show = !this.show;
        }
    };
    $scope.partBack = new partBackClass();
    $scope.cashflowId = $stateParams.cashflowId;
    $scope.partBack.getPayChannel().then(function (res) {
        $timeout(function () {
            $scope.getPartRefundFeeVo();
            $scope.partBack.getPayList($scope.cashflowId).then(function (res) {
                $timeout(function () {
                    //收费清单
                    $scope.feeDetailsList = res;
                });
            });
        });
    });
    /* 获取<查询持卡人> */
    $scope.getCustomerVo = function () {
        HttpFactory.object("/admin/getCustomerVo.json", { customerId: $scope.refundFeeInfo.customer.id }).then(function (res) {
            $scope.customerName = res.customer.customerName;
        });
    };
    //判断是否显示退货按钮
    $scope.showBackGoods = false; //
    $scope.canBackItem = function () {
        if (!$scope.showBackGoods) {
            return;
        }
        var totalRefundableFee = $scope.refundFeeInfo.cashRefundFeeVoList.reduce(function (pre, next) {
            pre += next.totalRefundableFee;
            return pre;
        }, 0);
        $scope.showBackGoods = totalRefundableFee === 0;
        /*  if ($scope.showBackGoods) {
             let list = []
             list = list.concat($scope.refundFeeInfo.cashRefundFeeVoList || [])
             list = list.concat($scope.refundFeeInfo.creditRefundFeeVoList || [])
             let showBackGoods = false;
             list.forEach(v => {
                 if (v.totalRefundableFee > 0) {
                     $scope.showBackGoods = false;//
                     if (v._account) {
                         showBackGoods = true
                     }
                 }
             })
             console.log(123, $scope.showBackGoods);
             console.log(222, $scope.refundFeeInfo.cashflow.creditStatus);
             console.log(333, showBackGoods);
             if (!$scope.showBackGoods && $scope.refundFeeInfo.cashflow.creditStatus === 1 && !showBackGoods) {
                 $scope.showBackGoods = true;
             }
         } */
    };
    /* 获取<查询挂账和收银台明细项目> */
    $scope.getPartRefundFeeVo = function () {
        HttpFactory.object("/admin/getMedicalRecordRefundDetailVo.json", { cashflowId: $scope.cashflowId }).then(function (res) {
            if (res.cashflow.refundStatus === 1) {
                return $state.go('payedList');
            }
            $scope.refundFeeInfo = res;
            $scope.queryOrder(res.medicalProductRefundVoList, res.medicalExamineRefundVoList);
            var cashRefundFeeVoOfMode1 = res.cashRefundFeeVoList.find(function (vo) {
                return vo.refundMode === 1;
            }); //收银台的记账退款
            var cashRefundFeeVoOfMode2 = res.cashRefundFeeVoList.find(function (vo) {
                return vo.refundMode === 2;
            }); //收银台的原路返回
            var creditRefundFeeVoOfMode1 = res.creditRefundFeeVoList.find(function (vo) {
                return vo.refundMode === 1;
            }); //挂账的记账退款
            var creditRefundFeeVoOfMode2 = res.creditRefundFeeVoList.find(function (vo) {
                return vo.refundMode === 2;
            }); //挂账的原路返回
            if (cashRefundFeeVoOfMode1) {
                $scope.partBack.concatChannel(cashRefundFeeVoOfMode1.refundTypeFeeVoList);
                $scope.partBack.defaultBack(cashRefundFeeVoOfMode1.refundTypeFeeVoList);
                $scope.cashRefundFeeVoOfMode1 = cashRefundFeeVoOfMode1;
            } else {
                $scope.cashRefundFeeVoOfMode1 = null;
            }
            var isBalance = false;
            if (cashRefundFeeVoOfMode2) {
                $scope.partBack.concatChannel(cashRefundFeeVoOfMode2.refundTypeFeeVoList);
                $scope.partBack.defaultBack(cashRefundFeeVoOfMode2.refundTypeFeeVoList);
                $scope.cashRefundFeeVoOfMode2 = cashRefundFeeVoOfMode2;
                isBalance = $scope.partBack.getIsBalance(cashRefundFeeVoOfMode2.refundTypeFeeVoList);
                var hasBack = cashRefundFeeVoOfMode2.refundTypeFeeVoList.find(function (rType) {
                    return ['11', '12'].includes(String(rType.refundType));
                });
                $scope.showCash = !!hasBack;
            } else {
                $scope.cashRefundFeeVoOfMode2 = null;
            }
            if (creditRefundFeeVoOfMode1) {
                $scope.partBack.concatChannel(creditRefundFeeVoOfMode1.refundTypeFeeVoList);
                $scope.partBack.defaultBack(creditRefundFeeVoOfMode1.refundTypeFeeVoList, true);
                $scope.creditRefundFeeVoOfMode1 = creditRefundFeeVoOfMode1;
            } else {
                $scope.creditRefundFeeVoOfMode1 = null;
            }
            if (creditRefundFeeVoOfMode2) {
                $scope.partBack.concatChannel(creditRefundFeeVoOfMode2.refundTypeFeeVoList);
                $scope.partBack.defaultBack(creditRefundFeeVoOfMode2.refundTypeFeeVoList);
                $scope.creditRefundFeeVoOfMode2 = creditRefundFeeVoOfMode2;
                !isBalance && (isBalance = $scope.partBack.getIsBalance(creditRefundFeeVoOfMode2.refundTypeFeeVoList));
            } else {
                $scope.creditRefundFeeVoOfMode2 = null;
            }
            //判断是否有余额退款项
            if (isBalance) {
                $scope.getCustomerVo();
            }
            $scope.getCashRefundTotalFee();
            $scope.getCreditRefundTotalFee();
            $scope.getRefundTotalProduct();
            $scope.canBackItem();
        });
    };
    /* 获取<退货列表> */
    $scope.queryOrder = function (list1, list2) {
        var list = [];
        var showBackGoods = false;
        list1.forEach(function (item) {
            item._canbackNum = item.medicalProduct.useCount - item.medicalProduct.refundCount;
            if (item._canbackNum > 0) {
                showBackGoods = true;
            }
            list.push(item);
        });
        list2.forEach(function (item) {
            item._canbackNum = item.medicalExamine.useCount - item.medicalExamine.refundCount;
            if (item._canbackNum > 0 && !showBackGoods) {
                showBackGoods = true;
            }
            list.push(item);
        });
        $scope.showBackGoods = showBackGoods;
        $scope.partOrderList = list;
        $scope.setClass();
        $scope.partBackClass.allStatus = showBackGoods; //默认全选
        $scope.partBackClass.choseAll();
        $scope.getRefundTotalProduct(); // 退货：计算退款数量
    };
    $scope.canIncreaseValue = function (refundVo, refund) {
        return !refundVo.disabled && refundVo.value && (refund._account && refundVo.chose || !refund._account && !refundVo.chose);
    };
    /* 退款金额合计 */
    $scope.refundTotalCashFee = 0; //收银台应退金额
    $scope.getCashRefundTotalFee = function () {
        var list = [];
        if ($scope.cashRefundFeeVoOfMode1) {
            $scope.cashRefundFeeVoOfMode1._account = true; //记账方式
            list.push($scope.cashRefundFeeVoOfMode1);
        }
        if ($scope.cashRefundFeeVoOfMode2) {
            list.push($scope.cashRefundFeeVoOfMode2);
        }
        var value = 0;
        list.forEach(function (refund) {
            refund.refundTypeFeeVoList.forEach(function (refundVo) {
                if ($scope.canIncreaseValue(refundVo, refund)) {
                    value += refundVo.value;
                }
            });
        });
        $scope.refundTotalCashFee = Number(value.toFixed(2));
    };
    $scope.refundTotalCreditFee = 0; //挂账应退金额
    $scope.getCreditRefundTotalFee = function () {
        var list = [];
        if ($scope.creditRefundFeeVoOfMode1) {
            $scope.creditRefundFeeVoOfMode1._account = true; //记账方式
            list.push($scope.creditRefundFeeVoOfMode1);
        }
        if ($scope.creditRefundFeeVoOfMode2) {
            list.push($scope.creditRefundFeeVoOfMode2);
        }
        var value = 0;
        list.forEach(function (refund) {
            refund.refundTypeFeeVoList.forEach(function (refundVo) {
                if ($scope.canIncreaseValue(refundVo, refund)) {
                    value += refundVo.value;
                }
            });
        });
        $scope.refundTotalCreditFee = Number(value.toFixed(2));
    };
    /* 挂账情况下：区分微信扫码、支付宝扫码、pos机，选中此方式禁用其他方式 */
    $scope.diffDisable = function (index) {
        var refund = $scope.creditRefundFeeVoOfMode1.refundTypeFeeVoList[index];
        if (refund.disabled) return;
        $scope.creditRefundFeeVoOfMode1.refundTypeFeeVoList[index].chose = !$scope.creditRefundFeeVoOfMode1.refundTypeFeeVoList[index].chose;
        $scope.creditRefundFeeVoOfMode1.refundTypeFeeVoList[index].disabled = false;
        if (window.loopFn.payChannelIncludes(refund.refundType)) {
            $scope.creditRefundFeeVoOfMode1.refundTypeFeeVoList.forEach(function (m, i) {
                if (index !== i) {
                    m.disabled = $scope.creditRefundFeeVoOfMode1.refundTypeFeeVoList[index].chose;
                }
            });
        }
        $scope.getCreditRefundTotalFee();
    };
    /* 退款数量合计 */
    $scope.refundTotalProduct = 0;
    $scope.getRefundTotalProduct = function () {
        if ($scope.partOrderList) {
            var value = $scope.partOrderList.reduce(function (pre, next) {
                if (next.isChose && next.value) {
                    pre += next.value;
                }
                return pre;
            }, 0);
            $scope.refundTotalProduct = value;
        }
    };
    /* 创建退款订单 */
    $scope.verifyAuth = function (refundCashierType, bool) {
        $scope.smsPop.refundCashierType = refundCashierType;
        $scope.smsPop.isPlatform = bool;
        grantAuth.getBackAuth(ObjectFactory, "1").then(function () {
            $timeout(function () {
                $scope.createPartOrder();
            });
        }, function (err) {
            $timeout(function () {
                if (err) return Popup.notice(err);
                $scope.smsPop.show = true;
                $scope.smsPop.fn = $scope.createPartOrder;
            });
        });
    };
    $scope.createPartOrder = function () {
        if ($scope.smsPop.isPlatform) {
            if ($scope.refundFeeInfo.cashflow.creditStatus === 1) {
                return $scope.rollbackCreditFn();
            }
            return $scope.refundCreditFn();
        }
        var refundCashierType = $scope.smsPop.refundCashierType;
        $scope.getRefundTotalProduct(); // 退货：计算退款数量
        var remark = '退款退货';
        if (refundCashierType === 0) {
            remark = '退货';
        } else if ($scope.refundTotalProduct <= 0) {
            remark = '退款';
        }
        Popup.confirm("\u786E\u5B9A" + remark + "\uFF1F", function () {
            var refundTotalFee = 0;
            var list = [];
            $scope.getCashRefundTotalFee();
            refundTotalFee = $scope.refundTotalCashFee;
            if ($scope.cashRefundFeeVoOfMode1) {
                list = list.concat($scope.cashRefundFeeVoOfMode1.refundTypeFeeVoList.filter(function (vo) {
                    return vo.chose;
                }));
            }
            if ($scope.cashRefundFeeVoOfMode2) {
                list = list.concat($scope.cashRefundFeeVoOfMode2.refundTypeFeeVoList);
            }
            var refundFeeLogListJson = [],
                //退金额的数组
            refundProductLogListJson = []; //退货的数组
            var scanObj = {
                payType: '',
                fee: 0
            };
            list.forEach(function (v) {
                if (v.value) {
                    if (window.loopFn.payChannelIncludes(v.refundType)) {
                        scanObj.payType = v.refundType;
                        scanObj.fee = v.value;
                    }
                    refundFeeLogListJson.push({
                        cashflowId: $scope.cashflowId,
                        refundType: v.refundType,
                        refundFee: v.value
                    });
                }
            });
            $scope.partOrderList.forEach(function (v) {
                if (v.value && v.isChose) {
                    if (v.medicalProduct) {
                        refundProductLogListJson.push({
                            refundItemType: 1, //1:产品 2:检查
                            medicalExamineId: null,
                            medicalProductId: v.medicalProduct.id,
                            refundCount: v.value
                        });
                    } else if (v.medicalExamine) {
                        refundProductLogListJson.push({
                            refundItemType: 2, //1:产品 2:检查
                            medicalProductId: null,
                            medicalExamineId: v.medicalExamine.id,
                            refundCount: v.value
                        });
                    }
                }
            });
            var params = {
                cashflowId: $scope.cashflowId,
                customerId: $scope.refundFeeInfo.customer.id,
                refundTotalFee: refundTotalFee, // 退款金额合计
                refundTotalProduct: $scope.refundTotalProduct, //退款数量合计
                refundFeeLogListJson: JSON.stringify(refundFeeLogListJson),
                refundProductLogListJson: JSON.stringify(refundProductLogListJson)
            };
            HttpFactory.object('/admin/createPartRefund.json', params).then(function (_ref) {
                var isExistScan = _ref.isExistScan,
                    commitId = _ref.commitId;

                //同步记账
                if (!isExistScan) {
                    HttpFactory.object('/admin/commitPartRefundForNotExistScan.json', {
                        refundLogId: commitId
                    }).then(function () {
                        Popup.notice(remark + "\u6210\u529F");
                        $scope.getPartRefundFeeVo();
                    });
                    return;
                }
                $scope.asyncPartBack(scanObj, commitId);
            }).catch(function (err) {
                $scope.getPartRefundFeeVo();
            });
        });
    };
    /* 收银台的异步回调 */
    $scope.asyncPartBack = function (_ref2, refundLogId) {
        var payType = _ref2.payType,
            fee = _ref2.fee;

        /* 微信等异步退款 */
        $scope.paystatus.open({
            type: "1", //1是退款,0是支付
            payType: payType,
            fee: fee
        });
        HttpFactory.object('/admin/commitPartRefundForExistScan.json', {
            refundLogId: refundLogId
        }).then(function (res) {
            loopFn.loopPayStatus({
                ObjectFactory: ObjectFactory,
                params: {
                    url: "getRefundFeeLog",
                    params: {
                        refundFeeLogId: res.scanRefundFeeLogId
                    }
                },
                statusOption: {
                    status1: "refundStatus",
                    status2: "waitingRefundStatus",
                    back: false
                },
                successOption: {
                    moneyKey: "refundFee",
                    payTypeKey: "refundType",
                    type: "已退款",
                    voiceType: "2" //收款还是退款 (1收款，2退款)
                }
            }).then(function () {
                Popup.notice("\u9000\u6B3E\u6210\u529F\uFF01");
            }, function (errMsg) {
                Popup.notice(errMsg ? errMsg : "\u9000\u6B3E\u5931\u8D25\uFF01");
            }).finally(function () {
                $scope.paystatus.close();
                $scope.getPartRefundFeeVo();
            });
        }, function (err) {
            $scope.paystatus.close();
            $scope.getPartRefundFeeVo();
        });
    };
    /* 挂账平账 */
    $scope.rollbackCreditFn = function () {
        $scope.getCreditRefundTotalFee();
        var rollbackCreditMoney = $scope.refundTotalCreditFee;
        Popup.confirm('确定平账嘛？', function () {
            HttpFactory.object('/admin/rollbackCredit.json', {
                cashflowId: $scope.cashflowId,
                customerId: $scope.refundFeeInfo.customer.id,
                rollbackCreditMoney: rollbackCreditMoney
            }).then(function () {
                Popup.notice("\u5E73\u8D26\u6210\u529F");
            }).finally(function () {
                $scope.getPartRefundFeeVo();
            });
        });
    };
    /* 挂账退款 */
    $scope.refundCreditFn = function () {
        var list = [];
        var customerCreditLogJson = [];
        if ($scope.creditRefundFeeVoOfMode1) {
            list = list.concat($scope.creditRefundFeeVoOfMode1.refundTypeFeeVoList.filter(function (vo) {
                return vo.chose && !vo.disabled;
            }));
        }
        if ($scope.creditRefundFeeVoOfMode2) {
            list = list.concat($scope.creditRefundFeeVoOfMode2.refundTypeFeeVoList);
        }
        var isAsync = false;
        list.forEach(function (v) {
            if (v.value) {
                window.loopFn.payChannelIncludes(v.refundType) && (isAsync = true);
                customerCreditLogJson.push({
                    creditMoney: v.value,
                    payChannel: v.refundType
                });
            }
        });
        Popup.confirm('确定挂账退款嘛？', function () {
            if (!isAsync) {
                HttpFactory.object('/admin/refundCreditCashflowIdList.json', {
                    cashflowId: $scope.cashflowId,
                    customerId: $scope.refundFeeInfo.customer.id,
                    customerCreditLogJson: JSON.stringify(customerCreditLogJson)
                }).then(function () {
                    Popup.notice("\u6302\u8D26\u9000\u6B3E\u6210\u529F");
                    $scope.getPartRefundFeeVo();
                });
                return;
            }
            $scope.paystatus.open({
                type: "1", //1是退款,0是支付
                payType: list[0].refundType,
                fee: list[0].value
            });
            HttpFactory.object('/admin/refundCreditCashflowForScan.json', {
                cashflowId: $scope.cashflowId,
                customerId: $scope.refundFeeInfo.customer.id,
                creditMoney: list[0].value,
                payChannel: list[0].refundType
            }).then(function (customerCreditLogId) {
                loopFn.loopPayStatus({
                    ObjectFactory: ObjectFactory,
                    params: {
                        url: "getCustomerCreditLog",
                        params: { customerCreditLogId: customerCreditLogId }
                    },
                    statusOption: {
                        status1: "success",
                        status2: "waitingPayStatus",
                        back: true
                    },
                    successOption: {
                        moneyKey: "walletTrueMoney",
                        payTypeKey: "payChannel",
                        type: "已退款",
                        voiceType: "2" //收款还是退款 (1收款，2退款)
                    }
                }).then(function () {
                    Popup.notice("\u9000\u6B3E\u6210\u529F\uFF01");
                }, function (errMsg) {
                    Popup.notice(errMsg ? errMsg : "\u9000\u6B3E\u5931\u8D25\uFF01");
                }).finally(function () {
                    $scope.paystatus.close();
                    $scope.getPartRefundFeeVo();
                });
            }).catch(function () {
                $scope.paystatus.close();
                $scope.getPartRefundFeeVo();
            });
        });
    };
    $scope.setClass = function () {
        $scope.partBackClass = new MultipleChoseClass($scope.partOrderList);
    };
    /* 计算退款方式的合计金额 */
    $scope.workBenchCB = function (item, index, key) {
        var totalFee = item.refundableFee;
        if (key === 'cashRefundFeeVoOfMode1' || key === 'creditRefundFeeVoOfMode1') {
            //记账合计总共可退的金额
            var totalRefundableFee = $scope[key].totalRefundableFee;
            // payFee是除本次输入外合计的金额
            var payFee = $scope[key].refundTypeFeeVoList.reduce(function (pre, next, index2) {
                if (index != index2 && next.value && next.chose && !next.disabled) {
                    pre += next.value;
                }
                return pre;
            }, 0);
            totalFee = Number((totalRefundableFee - payFee).toFixed(2));
        }
        $scope[key].refundTypeFeeVoList[index].value = $scope.partBack.noZero(item.value, 0, totalFee);
        $scope.getCashRefundTotalFee();
        $scope.getCreditRefundTotalFee();
        if ($scope.partBack.isIntegral(item.refundType)) {
            $scope.partBack.getBackIntegral($scope.cashflowId, $scope[key].refundTypeFeeVoList[index].value).then(function (res) {
                $timeout(function () {
                    $scope[key].refundTypeFeeVoList[index].integral = res;
                });
            });
        }
    };
    /* 计算退货方式的合计金额 */
    $scope.productCB = function (item, index) {
        $scope.partOrderList[index].value = $scope.partBack.noZero(item.value, 0, item._canbackNum);
        $scope.getRefundTotalProduct();
    };
    /* 支付时的状态 */
    $scope.paystatus = window.optionsObj.paystatus_options({});

    $scope.smsPop = {
        /* 退款涉及短信验证:(refer) waitPayBack */
        show: false,
        fn: null,
        info: {},
        fail: function fail() {
            this.fn = null;
            this.show = false;
        },
        suc: function suc() {
            this.show = false;
            if (this.fn) {
                this.fn();
            }
            this.fn = null;
        }
    };
}]);
'use strict';

