angular.module("bestvisionWeb").controller("waitPayBackListCtrl", ["$scope", "partBackClass", "DateUtilFactory", "$state", "ObjectFactory", "ListFactory", "$http", "$timeout", "Popup", function ($scope, partBackClass, DateUtilFactory, $state, ObjectFactory, ListFactory, $http, $timeout, Popup) {
  $scope.partBack = new partBackClass();
  $scope.partBack.getPayChannel();
  $scope.obj = {};
  window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (res) {
    $scope.setCompanyModal = !res;
  });
  $scope.search = function () {
    if ($scope.obj.startTime) {
      $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
    } else {
      delete $scope.obj.startTime;
    }
    if ($scope.rightTimer) {
      $scope.obj.endTime = DateUtilFactory.plus($scope.rightTimer);
    } else {
      delete $scope.obj.endTime;
    }
    var pageSize = 12;
    $scope.memberFactory = new ListFactory("/admin/selectMedicalRecordRefundLogVoListOfCompany.json", 0, pageSize, $scope.obj);
    var promise = $scope.memberFactory.nextPage();
    promise.then(function (data) {
      $("#Pagination").pagination($scope.memberFactory.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.memberFactory.clearAndSetIndex(index * pageSize);
          $scope.memberFactory.nextPage();
        }
      });
    });
  };
  $scope.search();

  $scope.otherPay = {};
  $scope.payObjectFactory = new ObjectFactory();
  var paypromise = $scope.payObjectFactory.saveOrQuery("/admin/getCorpPayChannel.json");
  paypromise.then(function (res) {
    var obj = res.result.object;
    $scope.otherPay.channelName1 = obj.channelName1;
    $scope.otherPay.channelName2 = obj.channelName2;
    $scope.otherPay.channelName3 = obj.channelName3;
    $scope.otherPay.channelName4 = obj.channelName4;
    $scope.otherPay.channelName5 = obj.channelName5;
  });

  $scope.companyFactory = new ObjectFactory();
  $scope.companyFactory.saveOrQuery("/admin/getCompanyCashConf.json");

  $scope.printList = function (refundLogId) {
    $scope.getRefundFactory = new ObjectFactory();
    var printpromise = $scope.getRefundFactory.saveOrQuery("/admin/getMedicalRecordRefundLogVo.json", { refundLogId: refundLogId });
    printpromise.then(function (res) {
      var showPhone = res.object.customer.linkMobile;
      $scope.showPhone = window.show_phone(showPhone, !!$scope.companyFactory.object.customerMobileDisable);
      var refundFeeLogList = $scope.partBack.getPayBackList($scope.getRefundFactory.object.refundFeeLogList);
      $scope.refundFeeLogList = refundFeeLogList;
      $timeout(function () {
        $("#ele3").jqprint({
          debug: false,
          importCSS: true,
          printContainer: true,
          operaSupport: false
        });
      }, 1000);
    });
  };
}]);
