angular.module("bestvisionWeb").controller("waitPayListCtrl", ["$scope", "Popup", "$stateParams", "DateUtilFactory", "$state", "ObjectFactory", "ListFactory", "$http", "$timeout", function ($scope, Popup, $stateParams, DateUtilFactory, $state, ObjectFactory, ListFactory, $http, $timeout) {
  $scope.obj = {};

  window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (res) {
    $scope.setCompanyModal = !res;
  });
  $scope.search = function () {
    $scope.obj.status = 0;
    if ($scope.obj.startTime) {
      $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
    } else {
      delete $scope.obj.startTime;
    }
    if ($scope.rightTimer) {
      $scope.obj.endTime = DateUtilFactory.plus($scope.rightTimer);
    } else {
      delete $scope.obj.endTime;
    }
    var pageSize = 12;
    $scope.memberFactory = new ListFactory("/admin/getMedicalRecordCashflowVoListOfCompany.json", 0, pageSize, $scope.obj);
    var promise = $scope.memberFactory.nextPage();
    promise.then(function (data) {
      $("#Pagination").pagination($scope.memberFactory.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.memberFactory.clearAndSetIndex(index * pageSize);
          $scope.memberFactory.nextPage();
        }
      });
    });
  };
  $scope.search();

  $scope.cancelPay = function (id) {
    Popup.confirm("是否取消该支付", function () {
      $scope.cancelCashObjectFactory = new ObjectFactory();
      var promise = $scope.cancelCashObjectFactory.saveOrQuery("/admin/cancelMedicalRecordCashflow.json", { cashflowId: id });
      promise.then(function (res) {
        if (res.status == 1) {
          Popup.notice(res.errmsg, 2000, function () {});
        } else {
          $state.go("waitPayList", {}, { reload: true });
        }
      });
    }, function () {});
  };
}]);
"use strict";

