angular.module("bestvisionWeb").controller("adminCallCtrl", ["$scope", "ListFactory", "$interval", "$state", "HttpFactory", "$timeout", "Popup", "DateUtilFactory", "ObjectFactory", function ($scope, ListFactory, $interval, $state, HttpFactory, $timeout, Popup, DateUtilFactory, ObjectFactory) {
  window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (res) {
    $scope.setCompanyModal = !res;
    if (res) {
      $scope.consultRoom.ajaxParams.companyId = res.id;
      $scope.employeeInfo.ajaxParams.companyId = res.id;
      $scope.companyId = res.id;
      $scope.getEmployeeConsultRoom();
      // $scope.intervalCall();
    }
  });
  $scope.obj = {
    keyword: "",
    isWaiting: false
  };
  $scope.clinicPopout = {
    show: false,
    index: null,
    showP: function showP(show) {
      if (!show) {
        window.commonFn.closeMaskFun();
      } else {
        this.index = null;
        $scope.searchScreenList();
        window.commonFn.openMaskFun();
      }
      this.show = show;
    },
    choseSingle: function choseSingle(index) {
      this.index = index;
    },
    submit: function submit() {
      var _this = this;

      if (this.index !== null && this.index >= 0) {
        HttpFactory.object("/admin/setEmployeeManageBigScreenId.json", {
          manageBigScreenId: $scope.screenList.items[this.index].bigScreen.id
        }).then(function () {
          $scope.getEmployeeConsultRoom();
          _this.showP(false);
        });
      }
    }
  };
  $scope.doctorWorkBenchs = {
    status: 0,
    tablist: [{
      name: "全部状态",
      class: "maxwidth_66",
      status: 0,
      queueStatus: null, //0 等待中 1 叫号中 2 已叫号 3 已过号,
      checkinStatus: null //1:待接诊 2:接诊中 3:接诊完成
    }, {
      name: "叫号中",
      ionc: "#41b2a6",
      status: 1,
      queueStatus: 1,
      checkinStatus: null
    }, {
      name: "等待中",
      ionc: "#de6262",
      status: 2,
      queueStatus: 0,
      checkinStatus: null,
      btnList: [{
        name: "置顶",
        status: 1,
        class: "btn-primary"
      }]
    }, {
      name: "就诊中",
      ionc: "#2c95c1",
      status: 3,
      queueStatus: null,
      checkinStatus: 2
    }, {
      name: "已过号",
      ionc: "#969799",
      status: 4,
      queueStatus: 3,
      checkinStatus: null,
      btnList: [{
        name: "恢复",
        status: 2,
        class: "btn-primary"
      }]
    }, {
      name: "已完成",
      ionc: "#969799",
      status: 5,
      queueStatus: null,
      checkinStatus: 3
    }],
    transmitStatus: function transmitStatus(queueStatus, checkinStatus) {
      var info = null;
      this.tablist.forEach(function (tab) {
        if (tab.queueStatus === queueStatus || tab.checkinStatus === checkinStatus) {
          info = tab;
        }
      });
      return info || {};
    },
    callback: function callback() {
      $scope.selectEmployeeCheckinQueueVoList();
    }
  };
  $scope.dealWithBtn = function (status, employee) {
    var employeeCheckinQueueId = employee.employeeCheckinQueue.id;
    switch (status) {
      //等待 置顶
      case 1:
        HttpFactory.object("/admin/topEmployeeCheckinQueue.json", {
          employeeCheckinQueueId: employeeCheckinQueueId
        }).then(function () {
          $scope.selectEmployeeCheckinQueueVoList();
        });
        break;
      //过号 恢复
      case 2:
        Popup.confirm("\u786E\u8BA4\u6062\u590D\u6B64\u53F7\u6E90\uFF1F", function () {
          HttpFactory.object("/admin/restartEmployeeCheckinQueue.json", {
            employeeCheckinQueueId: employeeCheckinQueueId
          }).then(function () {
            $scope.selectEmployeeCheckinQueueVoList();
          });
        });
        break;
    }
  };
  $scope.consultRoom = {
    name: "consultRoom",
    idName: "consultRoom",
    ajaxUrl: "/admin/selectConsultRoomVoListOfCompany.json",
    ajaxParams: {
      companyId: null,
      status: 0
    },
    isshow: false,
    id: "",
    inputVal: "",
    inputPlaceHolder: "请选择诊室",
    info: null,
    key: "consultRoom",
    key2: "consultRoomName",
    fn: function fn() {
      $scope.selectEmployeeCheckinQueueVoList();
    },
    type: "List"
  };
  $scope.employeeInfo = {
    name: "employeeInfo",
    idName: "employeeInfo",
    ajaxUrl: "/admin/selectEmployeeVoList.json",
    ajaxParams: {
      companyId: null,
      status: 0
    },
    isshow: false,
    id: "",
    inputVal: "",
    inputPlaceHolder: "请选择医师",
    info: null,
    key: "employee",
    key2: "employeeName",
    fn: function fn() {
      $scope.selectEmployeeCheckinQueueVoList();
    },
    type: "List"
  };
  $scope.pageSize = 10;
  $scope.searchScreenList = function () {
    var findClinicIndex = function findClinicIndex() {
      if ($scope.clinicInfo.bigScreen) {
        var index = $scope.screenList.items.findIndex(function (c) {
          return c.bigScreen.id === $scope.clinicInfo.bigScreen.id;
        });
        $scope.clinicPopout.index = index;
      }
      console.log($scope.screenList.items);

      $scope.screenList.items.forEach(function (v) {
        v.consultRoomListFilter = v.consultRoomVoList.map(function (room) {
          return room.consultRoom.consultRoomName;
        }).join("、");
      });
    };
    $scope.screenList = new ListFactory("/admin/selectBigScreenConfVoListOfCompany.json", 0, $scope.pageSize, {
      companyId: $scope.companyId,
      sceneType: 1
    });
    $scope.screenList.nextPage().then(function () {
      findClinicIndex();
      $(".Paginations").pagination($scope.screenList.count, {
        items_per_page: $scope.pageSize,
        callback: function callback(index) {
          $scope.screenList.clearAndSetIndex(index * $scope.pageSize);
          $scope.screenList.nextPage().then(findClinicIndex);
        }
      });
    });
  };
  $scope.rotate = false;
  $scope.refresh = function () {
    $scope.rotate = true;
    $scope.selectEmployeeCheckinQueueVoList();
    $timeout(function () {
      $scope.rotate = false;
    }, 1000);
  };
  $scope.selectEmployeeCheckinQueueVoList = function () {
    $scope.refreshScreen();
    var time = new Date();
    var params = DateUtilFactory.closeLeftOpenRight(time, time);
    params.employeeId = $scope.clinicInfo.employee.id;
    params.keyword = $scope.obj.keyword;
    var _$scope$doctorWorkBen = $scope.doctorWorkBenchs.tablist[$scope.doctorWorkBenchs.status],
        queueStatus = _$scope$doctorWorkBen.queueStatus,
        checkinStatus = _$scope$doctorWorkBen.checkinStatus;

    params.queueStatus = queueStatus;
    params.checkinStatus = checkinStatus;
    var pageSize = 10;
    params.bigScreenId = $scope.clinicInfo.bigScreen.id;
    params.consultRoomId = $scope.consultRoom.id;
    params.employeeId = $scope.employeeInfo.id;
    $scope.selectEmployeeCheckinQueueOfBigScreenList = new ListFactory("/admin/selectEmployeeCheckinQueueVoListOfBigScreen.json", 0, pageSize, params);
    $scope.selectEmployeeCheckinQueueOfBigScreenList.nextPage().then(function () {
      $(".secondpagination").pagination($scope.selectEmployeeCheckinQueueOfBigScreenList.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.selectEmployeeCheckinQueueOfBigScreenList.clearAndSetIndex(index * pageSize);
          $scope.selectEmployeeCheckinQueueOfBigScreenList.nextPage();
        }
      });
    });
  };
  $scope.getEmployeeConsultRoom = function () {
    HttpFactory.object("/admin/getEmployeeConsultRoomVo.json").then(function (res) {
      $scope.clinicInfo = res;
      if (!$scope.clinicInfo.bigScreen) {
        return $scope.clinicPopout.showP(true);
      }
      $scope.selectEmployeeCheckinQueueVoList();
    });
  };
  $scope.refreshScreen = function () {
    if (!$scope.clinicInfo || !$scope.clinicInfo.bigScreen) {
      return;
    }
    HttpFactory.object("/admin/getNowCallingCheckinQueueOfBigScreen.json", {
      bigScreenId: $scope.clinicInfo.bigScreen.id
    }).then(function (res) {
      $scope.callNow = res;
    });
  };
  /*  $scope.setInterval = null;
  $scope.intervalCall = () => {
    $scope.setInterval = $interval(() => {
      $scope.refreshScreen();
    }, 2000);
  }; */
  $scope.$on("$destroy", function () {
    // $scope.setInterval && $interval.cancel($scope.setInterval);
    window.commonFn.closeMaskFun();
  });
}]);
