angular.module("bestvisionWeb").controller("screenQueueCtrl", ["$scope", "Popup", "$window", "$stateParams", "$timeout", "HttpFactory", "ObjectFactory", "ListFactory", "$interval", function ($scope, Popup, $window, $stateParams, $timeout, HttpFactory, ObjectFactory, ListFactory, $interval) {
  window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (res) {
    if (res) {
      $scope.setCompanyModal = res;
    }
  });
  window.toggleFull(true);
  window.commonFn.openMaskFun();
  $scope.time = {
    today: new Date(),
    weekDay: new Date().getDay()
  };
  $scope.intervalQueue = null;
  $scope.storeTimes = {
    resetTimes: 60,
    times: 60
  }; //一分钟清除一次
  $scope.storeBigScreenIdList = []; //用来存储叫号人员的id
  $scope.callSb = {
    startCall: false, //开始呼叫，调用语音，
    calling: false, //语音调用返回，开始呼叫
    callIndex: 0, //当前呼叫的下标
    resetTime: 5, //设定阈值为5秒，一直播放5秒钟
    time: 5
  }; //是否叫到某人

  /* 获取叫号信息 */
  $scope.refreshScreen = function () {
    if (!$stateParams.bigScreenId) {
      return Popup.notice("请绑定大屏！");
    }
    HttpFactory.object("/admin/getNowCallingCheckinQueueOfBigScreen.json", {
      bigScreenId: $stateParams.bigScreenId
    }).then(function (res) {
      // console.log(res);
      if (res.length) {
        res.forEach(function (p) {
          var employeeCheckinQueueId = p.employeeCheckinQueue.id;
          // console.log(employeeCheckinQueueId);
          //去重
          // console.log($scope.storeBigScreenIdList, patientId);
          if (!$scope.storeBigScreenIdList.find(function (v) {
            return v.id === employeeCheckinQueueId;
          })) {
            $scope.storeBigScreenIdList.push({
              consultRoomName: p.consultRoom.consultRoomName, //诊室
              checkinNumber: p.customerCheckin.checkinNumber, //号数
              patientName: p.patient.patientName, //姓名
              playVoice: "\uFF1A" + ("0000" + p.customerCheckin.checkinNumber).slice(-3) + "\u53F7" + p.patient.patientName + "\uFF0C\u8BF7\u524D\u5F80" + p.consultRoom.consultRoomName + "\u5C31\u8BCA",
              id: employeeCheckinQueueId
            });
          }
        });
      }
      $scope.playVoiceInQueue();
    });
  };
  /* 播放语音队列处理 */
  $scope.playVoiceInQueue = function () {
    var length = $scope.storeBigScreenIdList.length;
    // console.log("调用语音队列：", length, "游标：", $scope.callSb.callIndex);

    if (!length || $scope.callSb.callIndex >= length || !$scope.clinicList.length) {} else {
      //当前没有声音播放，则开始播放
      if (!$scope.callSb.startCall) {
        $scope.callSb.startCall = true;
        //播放声音
        window.handleSpeak.speak(ObjectFactory, $scope.storeBigScreenIdList[$scope.callSb.callIndex].playVoice).then(function () {
          $timeout(function () {
            $scope.callSb.calling = true;
          });
        });
      }
    }
    var playing = function playing() {
      if (!$scope.callSb.startCall || !$scope.callSb.calling) return;
      // console.log("播放中，剩余：", $scope.callSb.time);
      //播放5秒后，置空，将播放下标移动到下一位
      if ($scope.callSb.time <= 0) {
        $scope.callSb.startCall = false;
        $scope.callSb.calling = false;
        $scope.callSb.time = $scope.callSb.resetTime;
        $scope.callSb.callIndex++;
        return;
      }
      $scope.callSb.time -= 1;
    };
    playing();
  };
  $scope.calculationTime = function () {
    $scope.intervalQueue = $interval(function () {
      var date = new Date();
      $scope.time.today = date;
      $scope.time.weekDay = date.getDay();
      if ($scope.storeTimes.times <= 0) {
        $scope.storeTimes.times = $scope.storeTimes.resetTimes;
        $scope.storeBigScreenIdList.splice(0, $scope.callSb.callIndex); //固定时间清一次内存，清除至当前叫号的下标，确保当前叫号人员不受影响
        $scope.callSb.callIndex = 0;
      }
      /* console.log(
        "一分钟清一次内存：",
        $scope.storeBigScreenIdList,
        $scope.callSb.callIndex
      ); */
      $scope.storeTimes.times--;
      console.log("剩余时间：", $scope.storeTimes.times);
      $scope.storeTimes.times % 2 === 0 && $scope.searchScreenList();
      $scope.refreshScreen();
    }, 1000);
  };
  $scope.calculationTime();
  $scope.clinicList = [];
  //不用了
  $scope.searchScreenList = function () {
    new ListFactory("/admin/selectBigScreenQueueVoList.json", 0, 7, {
      bigScreenId: $stateParams.bigScreenId,
      queueSize: 4 //等待人数个数
    }).nextPage().then(function (res) {
      $scope.clinicList = res.items;
    });
  };
  $scope.searchScreenList();
  $scope.back = function () {
    $window.history.back();
  };
  $scope.$on("$destroy", function () {
    window.commonFn.closeMaskFun();
    window.toggleFull(false);
    $interval.cancel($scope.intervalQueue);
  });
}]);
"use strict";

angular.module("bestvisionWeb").controller("analysisCtrl", ["$scope", "DateUtilFactory", "CalulateClass", "$state", "DefineFollowUp", "HttpFactory", function ($scope, DateUtilFactory, CalulateClass, $state, DefineFollowUp, HttpFactory) {}]);
