    var setKeyNameToObj = function setKeyNameToObj(vo) {
      if (vo.id) {
        obj[vo.keys] = vo.id;
        obj[vo.keys + "Name"] = vo.name;
      }
    };
    //接诊人
    setKeyNameToObj($scope.Patienter);
    //验配师
    setKeyNameToObj($scope.Opticianer);
    //会员推荐人
    setKeyNameToObj($scope.Referrer);
    //成交人
    setKeyNameToObj($scope.Transactor);
    //维护人
    setKeyNameToObj($scope.Maintainer);
    var time = DateUtilFactory.closeLeftOpenRight($scope.obj.firstVisitStartTime, $scope.rightTimer);
    Utils.handleField(obj, 'firstVisitStartTime', time.startTime);
    Utils.handleField(obj, 'firstVisitEndTime', time.endTime);
    var time2 = DateUtilFactory.closeLeftOpenRight($scope.obj.lastVisitStartTime, $scope.rightTimer2);
    Utils.handleField(obj, 'lastVisitStartTime', time2.startTime);
