angular.module('bestvisionWeb').controller('couponHistoryCtrl', ['$scope', '$stateParams', 'Popup', 'DateUtilFactory', '$state', 'ObjectFactory', 'ListFactory', '$http', '$timeout', function ($scope, $stateParams, Popup, DateUtilFactory, $state, ObjectFactory, ListFactory, $http, $timeout) {
    $scope.status = [{ id: null, name: '全部' }, { id: 0, name: '未使用' }, { id: 1, name: '已使用' }, { id: 2, name: '已作废' }];

    $scope.obj = {};
    $scope.obj.status = null;

    $scope.searchList = function () {

        var pageSize = 5;
        $scope.couponFactory = new ListFactory('/admin/selectCustomerCouponVoList.json', 0, pageSize, $scope.obj);
        var promise = $scope.couponFactory.nextPage();
        promise.then(function (data) {
            $(".pagination-record").pagination($scope.couponFactory.count, {
                items_per_page: pageSize,
                callback: function callback(index) {
                    $scope.couponFactory.clearAndSetIndex(index * pageSize);
                    $scope.couponFactory.nextPage();
                }
            });
        });
    };
    $scope.searchList();

    $scope.searchTab = function (status) {
        $scope.obj.status = status;
        $scope.searchList();
    };

    $scope.showCouponModify = function (id, event) {
        $scope.customerCouponId = id;
        event.stopPropagation();

        $scope.couponModify = true;
        $scope.getCouponVoFactory = new ObjectFactory();
        $scope.getCouponVoFactory.saveOrQuery('/admin/getCustomerCouponVo.json', { customerCouponId: id });
    };

    $scope.hideCouponModal = function () {

        $scope.couponModify = false;
    };

    $scope.modifycoupon = function () {
        $scope.useCouponFactory = new ObjectFactory();
        var usePromise = $scope.useCouponFactory.saveOrQuery('/admin/useCoupon.json', { customerCouponId: $scope.customerCouponId });
        usePromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice('核销成功');
            } else {
                Popup.notice(res.errmsg);
            }
            $scope.hideCouponModal();
            $scope.searchList();
        });
    };
}]);
