angular.module("bestvisionWeb").controller("blueToothTransferCtrl", ["$scope", "Popup", "DateUtilFactory", "HttpFactory", "ListFactory", "CommonTabClass", function ($scope, Popup, DateUtilFactory, HttpFactory, ListFactory, CommonTabClass) {
    $scope.pageIndex = 0;
    $scope.data = {
        recordId: '',
        startTime: null,
        endTime: null
    };
    $scope.transferStatus = {
        status: null,
        tablist: CommonTabClass.transferStatus,
        callback: function callback() {
            $scope.selectOtherEyeCheckLogList(0, true);
        }
    };
    $scope.selectOtherEyeCheckLogList = function (index, isFirst) {
        var data = DateUtilFactory.closeLeftOpenRight($scope.data.startTime, $scope.data.endTime);
        var vo = Object.assign({
            sendStatus: $scope.transferStatus.status, //'0:未传输 1:已传输 2:传输失败'
            recordId: $scope.data.recordId,
            index: index,
            length: 10
        }, data);
        HttpFactory.list('/admin/selectOtherEyeCheckLogList.json', vo).then(function (res) {
            $scope.otherEyeCheckLogList = res;
            isFirst && HttpFactory.pagination('#Pagination', res, $scope.selectOtherEyeCheckLogList);
        });
    };
    $scope.thirdPartyVo = {
        httpPostUrl: '',
        sendType: 0 //0:不传输 1:按定制记录格式传输
    };
    $scope.thirdPartySystem = ['不传输', '按定制方式格式传输'];
    $scope.updateThirdPartySystemIndex = function (i) {
        $scope.thirdPartyVo.sendType = i;
    };
    $scope.saveThirdPartyVo = function (i) {
        HttpFactory.object('/admin/saveOtherSystem.json', $scope.thirdPartyVo).then(function () {
            Popup.notice('修改成功!');
            $scope.selectOtherSystemByCorpId();
        });
    };
    $scope.selectOtherSystemByCorpId = function () {
        HttpFactory.object('/admin/selectOtherSystemByCorpId.json').then(function (res) {
            $scope.thirdPartyVo.sendType = res.sendType;
            $scope.thirdPartyVo.httpPostUrl = res.httpPostUrl;
        });
    };
    $scope.trigger = function (index) {
        $scope.pageIndex = index;
        switch (index) {
            case 0:
                $scope.selectOtherEyeCheckLogList(0, true);
                break;
            case 1:
                $scope.selectOtherSystemByCorpId();
                break;
        }
    };
    $scope.trigger(1);
    $scope.trigger(0);
    $scope.reload = function () {
        Popup.confirm("\u5171" + $scope.otherEyeCheckLogList.count + "\u6761\u89C6\u529B\u68C0\u67E5\u7ED3\u679C\u4F1A\u8C03\u7528\u63A5\u53E3" + $scope.httpPostUrl + "\u4F20\u8F93\u5230\u8FDC\u7A0B\u7CFB\u7EDF\uFF0C\u53EF\u80FD\u4F1A\u6309\u8BB0\u5F55ID\u8986\u76D6\u6389\u8FDC\u7A0B\u7CFB\u7EDF\u91CC\u7684\u6570\u636E\uFF0C\u8BF7\u8C28\u614E\u64CD\u4F5C\uFF0C\u786E\u5B9A\u6267\u884C\u4E48\uFF1F", function () {
            var data = DateUtilFactory.closeLeftOpenRight($scope.data.startTime, $scope.data.endTime);
            var vo = Object.assign({
                sendStatus: $scope.transferStatus.status, //'0:未传输 1:已传输 2:传输失败'
                recordId: $scope.data.recordId
            }, data);
            HttpFactory.object('/admin/reTransferOtherEyeCheckLogList.json', vo).then(function (res) {
                Popup.notice('重传成功!');
                $scope.selectOtherEyeCheckLogList(0, true);
            });
        });
    };

    /*tab2*/
    $scope.obj = {
        startStatus: null, // 0:未开始 1:开始
        endStatus: null // 0:未结束 1:成功 2:失败
    };
    $scope.pageSize = 100;
    $scope.searchSupplierList = function () {
        var params = angular.copy($scope.obj);
        params = Object.assign(params, DateUtilFactory.closeLeftOpenRight($scope.startTime, $scope.rightTime));
        $scope.getSupplierListFactory = new ListFactory("/admin/selectSchoolMateCheckSendLogVoList.json", 0, $scope.pageSize, params);
        var promise = $scope.getSupplierListFactory.nextPage();

        promise.then(function (data) {
            $("#Pagination1").pagination($scope.getSupplierListFactory.count, {
                items_per_page: $scope.pageSize,
                callback: function callback(index) {
                    $scope.getSupplierListFactory.clearAndSetIndex(index * $scope.pageSize);
                    $scope.getSupplierListFactory.nextPage();
                }
            });
        });
    };
    $scope.searchSupplierList();

    $scope.setStatus = function (key, idx) {
        $scope.obj[key] = idx;
        $scope.searchSupplierList();
    };
}]);
