angular.module("bestvisionWeb").controller("addGrouponCtrl", ["$scope", "Popup", "$stateParams", "$rootScope", "$state", "ObjectFactory", "QiniuFactory", "ListFactory", "$q", "$http", function ($scope, Popup, $stateParams, $rootScope, $state, ObjectFactory, QiniuFactory, ListFactory, $q, $http) {
  $scope.unitNames = window.optionsObj.unitNames;
  $scope.modelNames = [{ id: "颜色", name: "颜色" }, { id: "度数", name: "度数" }, { id: "材质", name: "材质" }, { id: "重量", name: "重量" }, { id: "尺码", name: "尺码" }, { id: "规格", name: "规格" }, { id: "型号", name: "型号" }, { id: "设计", name: "设计" }, { id: "容量", name: "容量" }, { id: "疗程", name: "疗程" }, { id: "近视度数", name: "近视度数" }, { id: "散光度数", name: "散光度数" }, { id: "轴位", name: "轴位" }, { id: "功能", name: "功能" }];
  $scope.obj = {};
  $scope.obj.modelType = "0";
  $scope.obj.model1Name = "无";
  $scope.obj.model2Name = "无";
  $scope.obj.simulateGroupon = 1;
  $scope.maximumPurchaseFrequency = "0";

  $scope.obj.expressType = 1;
  $scope.obj.totalCount = 10000;
  $scope.obj.remainCount = 10000;
  $scope.startTime = moment().format("YYYY-MM-DD HH:mm");
  $scope.endTime = moment().add(1, "days").format("YYYY-MM-DD HH:mm");
  $scope.changeType = function (status) {
    if (status == 0) {
      $scope.model1 = false;
      $scope.model2 = false;
    } else if (status == 1) {
      $scope.model1 = true;
      $scope.model2 = false;
    } else {
      $scope.model1 = true;
      $scope.model2 = true;
      $scope.obj.model1 = null;
      $scope.obj.model2 = null;
    }
  };
  $scope.common = function () {
    if ($scope.obj.model1Name == $scope.obj.model2Name) {
      Popup.notice("规格不能选择相同", 2000, function () {});
    }
  };

  $scope.addSecKill = function () {
    $scope.obj.startTime = moment($scope.startTime)._d;
    $scope.obj.endTime = moment($scope.endTime)._d;

    console.log($scope.obj.simulateGroupon);

    if (!$scope.obj.productName) {
      Popup.notice("请输入商品名称", 3000, function () {});
      return false;
    }
    if (!$scope.obj.modelPicture) {
      Popup.notice("请选择图片", 3000, function () {});
      return false;
    }
    if ($scope.obj.modelType == 0) {
      $scope.obj.model1 = "无";
      $scope.obj.model2 = "无";
    } else if ($scope.obj.modelType == 1) {
      $scope.obj.model2 = "无";
      if ($scope.obj.model1Name == "无") {
        Popup.notice("请选择规格", 2000, function () {});
        return false;
      }
      if (!$scope.obj.model1) {
        Popup.notice("请填写规格", 2000, function () {});
        return false;
      }
    } else if ($scope.obj.modelType == 2) {
      if ($scope.obj.model1Name == "无" || $scope.obj.model2Name == "无") {
        Popup.notice("请选择规格", 2000, function () {});
        return false;
      }
      if (!$scope.obj.model1 || !$scope.obj.model2) {
        Popup.notice("请填写规格", 2000, function () {});
        return false;
      }
    } else {}

    // if (!$scope.obj.unitName) {
    //     Popup.notice('请选择单位', 3000, function() {});
    //     return false;
    // }

    if ($scope.marketPrice == null || $scope.marketPrice == undefined) {
      Popup.notice("市场价不能为空", 3000, function () {});
      return false;
    }
    if ($scope.marketPrice > 0) {
      $scope.obj.marketPrice = $scope.marketPrice.toFixed(2);
    } else {
      Popup.notice("市场价不能小于0", 3000, function () {});
      return false;
    }

    if ($scope.seckillPrice == null || $scope.seckillPrice == undefined) {
      Popup.notice("成团价不能为空", 3000, function () {});
      return false;
    }

    if ($scope.seckillPrice - $scope.marketPrice > 0) {
      console.log($scope.seckillPrice - $scope.marketPrice);

      Popup.notice("成团价必须小于市场价", 3000, function () {});
      return false;
    }

    if ($scope.seckillPrice > 0) {
      $scope.obj.seckillPrice = $scope.seckillPrice.toFixed(2);
    } else {
      Popup.notice("成团价格不能小于0", 3000, function () {});

      return false;
    }

    if ($scope.obj.minimumGrouponMembers) {
      if ($scope.obj.minimumGrouponMembers >= 2) {
        if (!/^[1-9]\d*$/.test($scope.obj.minimumGrouponMembers)) {
          Popup.notice("成团人数请输入正整数", 3000, function () {});
          return false;
        }
      } else {
        Popup.notice("成团人数不能小于2");
        return false;
      }
    } else {
      Popup.notice("请输入成团人数");
      return false;
    }

    if (!$scope.obj.promotionName) {
      Popup.notice("请输入活动名称", 3000, function () {});
      return false;
    }

    if ($scope.maximumPurchaseFrequency == "0") {
      $scope.obj.maximumPurchaseFrequency = 0;
    } else {
      if ($scope.obj.maximumPurchaseFrequency == null || $scope.obj.maximumPurchaseFrequency == undefined) {
        Popup.notice("请输入限购次数", 3000, function () {});
        return false;
      }

      if (0 >= $scope.obj.maximumPurchaseFrequency) {
        Popup.notice("限购次数不能小于0", 3000, function () {});
        return false;
      }
    }

    if ($scope.obj.expressType == 1) {
      if (!$scope.obj.address) {
        Popup.notice("请输入提货地址", 3000, function () {});
        return false;
      }
    }

    $scope.addFactory = new ObjectFactory();
    var addPromise = $scope.addFactory.saveOrQuery("/admin/createGrouponProduct.json", $scope.obj);
    addPromise.then(function (res) {
      if (res.status == 0) {
        Popup.notice("保存成功");
        $state.go("grouponList");
      } else {
        Popup.notice(res.errmsg);
      }
    });
  };

  $scope.chooseImg = function () {
    $scope.imgModalModify = true;
  };

  $scope.setTab = function (idx) {
    $scope.tab = idx;
  };
  $scope.setNull = function (idx) {
    $scope.tab = null;
  };
}]);
'use strict';

