angular.module('bestvisionWeb').controller('grouponOrderCtrl', ['$scope', 'Popup', '$stateParams', '$timeout', '$rootScope', '$state', 'ObjectFactory', 'ListFactory', '$http', function ($scope, Popup, $stateParams, $timeout, $rootScope, $state, ObjectFactory, ListFactory, $http) {

    $scope.grouponProductId = $stateParams.grouponProductId;

    $scope.search = function () {

        $scope.secKillFactory = new ListFactory('/admin/selectGrouponOrderVoList.json', 0, 10, { grouponProductId: $scope.grouponProductId });
        var searchPromise = $scope.secKillFactory.nextPage();

        searchPromise.then(function (data) {
            var pageSize = 10;

            $timeout(function () {

                for (var i = 0; i < $scope.secKillFactory.items.length; i++) {

                    var endTime = $scope.secKillFactory.items[i].groupon.endTime;
                    var nowTime = Date.parse(new Date());
                    if (endTime > nowTime) {
                        var firsecond = (endTime - nowTime) / 1000;

                        var day = Math.floor(firsecond / 86400);
                        var hr = Math.floor(firsecond / 3600 % 24);
                        var mr = Math.floor(firsecond / 60 % 60);
                        // var sr = Math.floor((firsecond % 60));
                        $scope.secKillFactory.items[i].leftTime = day + '天' + hr + "时" + mr + "分";
                    } else {
                        $scope.secKillFactory.items[i].leftTime = '0时0分0秒';
                    }
                }
            }, 500);

            $("#Pagination").pagination($scope.secKillFactory.count, {

                items_per_page: pageSize,

                callback: function callback(index) {

                    $scope.secKillFactory.clearAndSetIndex(index * pageSize);
                    $scope.secKillFactory.nextPage();
                }
            });
        });
    };
    $scope.search();
}]);
"use strict";

angular.module("bestvisionWeb").controller("getGlassNotifyListCtrl", ["$scope", "Popup", "$timeout", "$stateParams", "$rootScope", "HttpFactory", "ObjectFactory", "DateUtilFactory", "ListFactory", "$http", function ($scope, Popup, $timeout, $stateParams, $rootScope, HttpFactory, ObjectFactory, DateUtilFactory, ListFactory, $http) {
  $scope.choseTable = {
    show: false,
    key: "sms", //sms,voice
    sceneType: 3,
    props: {}, //从模板中选中信息返回
    smsInfo: null,
    voiceInfo: null,
    openPopout: function openPopout(key, id) {
      this.key = key;
      this.props = {};
      this.props.id = id;
      this.show = true;
    },
    back: function back() {
      HttpFactory.object("/admin/sendTakeMirrorNotice.json", {
        medicalRecordId: $scope.choseTable.medicalRecordId,
        smsTemplateId: this.props.smsTemplate.id
      }).then(function (res) {
        if (res.status) {
          return Popup.notice(res.errmsg);
        }
        Popup.notice("已发送成功");
        $scope.getGlassNotifyList.items[$scope.choseTable.index].receiveSmsLog = res.receiveSmsLog;
      });
    }
  };
  var pageSize = 5;
  window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (res) {
    $scope.setCompanyModal = !res;
  });
  $scope.searchGetGlassNotifyList = function () {
    var obj = {};
    if ($scope.firstVisitFrom) {
      $scope.firstVisitFrom = DateUtilFactory.origin($scope.firstVisitFrom);
    }
    if ($scope.rightTimer) {
      $scope.firstVisitTo = DateUtilFactory.plus($scope.rightTimer);
    }
    if (!$scope.rightTimer && $scope.firstVisitFrom) {
      obj = {
        keyword: $scope.keyword,
        firstVisitFrom: $scope.firstVisitFrom
      };
    } else if ($scope.rightTimer && !$scope.firstVisitFrom) {
      obj = { keyword: $scope.keyword, firstVisitTo: $scope.firstVisitTo };
    } else if (!$scope.rightTimer && !$scope.firstVisitFrom) {
      obj = { keyword: $scope.keyword };
    } else {
      obj = {
        keyword: $scope.keyword,
        firstVisitFrom: $scope.firstVisitFrom,
        firstVisitTo: $scope.firstVisitTo
      };
    }

    $scope.getGlassNotifyList = new ListFactory("/admin/getMedicalRecordListOfReceiveSms.json", 0, 5, obj);
    var promise = $scope.getGlassNotifyList.nextPage();
    promise.then(function (data) {
      console.log(data);
      $("#Pagination").pagination($scope.getGlassNotifyList.count, {
        items_per_page: pageSize,

        callback: function callback(index) {
          $scope.getGlassNotifyList.clearAndSetIndex(index * pageSize);
          $scope.getGlassNotifyList.nextPage();
        }
      });
    });
  };
  $scope.searchGetGlassNotifyList();

  $scope.sendmsg = function (medicalRecordId, $index) {
    $scope.choseTable.medicalRecordId = medicalRecordId;
    $scope.choseTable.index = $index;
    $scope.choseTable.openPopout('sms');
  };
}]);
