angular.module("bestvisionWeb").controller("homeCtrl", ["$scope", "ListFactory", "$stateParams", "$state", "ObjectFactory", "$timeout", "Popup", function ($scope, ListFactory, $stateParams, $state, ObjectFactory, $timeout, Popup) {
  // $scope.testurl = `${API_HOST}/pc/pc_test/wei_star/index.html#/testwei`;
  $scope.commonList = [{
    icon: "#icon-shenqingkaipiao",
    content: "申请开票",
    fun: function fun() {
      $scope.showPhoto = true;
    }
  }, {
    icon: "#icon-tijiaoxuqiu-mianxing",
    content: "提交需求",
    fun: function fun() {
      $state.go("requirement");
    }
  }, {
    icon: "#icon-shenqingkaipiao-copy",
    content: "短信充值",
    fun: function fun() {
      $scope.payComponent.show = true;
    }
  }];
  // 获取我的账户数据
  $scope.getMyaccount = function () {
    new ObjectFactory().saveOrQuery("/admin/getCorpTimeData.json").then(function (result) {
      var _result$object = result.object,
          isCorpNearExpiredOfTwoWeeks = _result$object.isCorpNearExpiredOfTwoWeeks,
          diffDays = _result$object.diffDays,
          corpTime = _result$object.corpTime;

      $scope.maxEndTime = corpTime.endTime;
      $scope.remainDay = diffDays; //剩余时间;
      var deg = window.calcRemainTime(corpTime.startTime, $scope.maxEndTime);
      $scope.corpNearExpired = isCorpNearExpiredOfTwoWeeks;
      var color = $scope.corpNearExpired ? "#D9534F" : "#41b2a6";
      if ($scope.corpNearExpired) {
        $scope.renew();
      }
      $timeout(function () {
        $scope.transform = {
          deg: deg,
          color: color
        };
      }, 100);
    });
  };
  $scope.getMyaccount();
  $scope.selectAdminSystemNoticeVoList = function () {
    $scope.adminSystemNoticeVoList = new ListFactory("/admin/selectAdminSystemNoticeVoList.json", 0, 10);
    $scope.adminSystemNoticeVoList.nextPage().then(function (res) {
      if (res.items.length) {
        $scope.getSingle(res.items[0].adminSystemNotice.id);
      }
    });
  };

  $scope.selectAdminSystemNoticeVoList();
  // 查询单条记录
  $scope.getSingle = function (adminSystemNoticeId) {
    new ObjectFactory().saveOrQuery("/admin/getAdminSystemNoticeVo.json", {
      adminSystemNoticeId: adminSystemNoticeId
    }).then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
        return;
      }
      var imgList = [];
      if (res.object.systemNotice.images) {
        imgList = res.object.systemNotice.images.split(",");
      }
      $scope.systemNotice = res.object.systemNotice;
      $scope.systemNotice.imgList = imgList;
    });
  };
  $scope.changeStatus = function (state) {
    var adminSystemNoticeId = state.adminSystemNotice.id;
    new ObjectFactory().saveOrQuery("/admin/readAdminSystemNotice.json", {
      adminSystemNoticeId: adminSystemNoticeId
    });
    $state.go("homeAnnouncementDetails", {
      id: adminSystemNoticeId
    });
  };
  $scope.system_renew = {
    show: false
  };
  $scope.renew = function () {
    $scope.system_renew.show = true;
  };
  $scope.payComponent = {
    show: false,
    getCorpId: function getCorpId() {
      new ObjectFactory().saveOrQuery("/admin/selectCorpSmsByCorpId.json").then(function (res) {
        $scope.corpId = res.result.object.corpId;
      });
    },
    callBack: function callBack() {
      Popup.notice("充值成功");
      $scope.getMyaccount();
    }
  };
  $scope.payComponent.getCorpId();
  // 如果是点击续费进来的，则直接打开续费弹框
  if ($stateParams.renew) {
    $scope.renew();
  }
  $scope.location = function () {
    $state.go("homeAnnouncement");
  };
}]);
