angular.module("bestvisionWeb").controller("loginCtrl", ["$scope", "Popup", "$rootScope", "$state", "ObjectFactory", "ListFactory", "$timeout", "websocketFactory", function ($scope, Popup, $rootScope, $state, ObjectFactory, ListFactory, $timeout, websocketFactory) {
  $scope.nowDate = +new Date();
  // $scope.passwordOnlyRead = true;/*  */
  $scope.user = {
    name: "",
    password: "",
    corpId: null
  };
  $rootScope.leftShow = false;
  $scope.saveLoginInfo = function () {
    return new Promise(function (resolve) {
      var companyPromise = new ObjectFactory().saveOrQuery("/admin/getCompanyOfMine.json");
      companyPromise.then(function (res) {
        window.sessionStorage.setItem("userInfo", JSON.stringify(res.object));
        // openWebsocket && websocketFactory.init();
        resolve(true);
      });
    });
  };
  $scope.init = function () {
    var token = localStorage.getItem("pcToken");

    if (token !== null && token !== "null") {
      var objectFactory = new ObjectFactory();
      var promise = objectFactory.saveOrQuery("/auth/isAdminTokenOk.json", {
        adminToken: token
      });
      promise.then(function (data) {
        if (objectFactory.status == 0) {
          // 设置别名
          try {
            var employeeId = objectFactory.result.employeeId;
            var alias = JPUSH_VERSION + "_2_" + employeeId;
            var tags = [JPUSH_VERSION];
            window.plugins.jPushPlugin.setTagsWithAlias(tags, alias);
          } catch (exception) {}
          $rootScope.leftShow = true;
          window.sessionStorage.setItem("loginInfo", JSON.stringify(data.result.admin));
          $scope.saveLoginInfo().then(function (r) {
            $state.go("home");
          });
        } else {
          localStorage.setItem("pcToken", null);
        }
      });
    }
  };

  $scope.init();

  $scope.loginTab = 1;
  $scope.setTab = function (index) {
    $scope.loginTab = index;
  };
  $scope.call = function (e) {
    if (e.keyCode === 13) {
      // 回车
      $scope.login();
    }
  };

  $scope.findpassword = {};
  $scope.findPasswordFactory = new ObjectFactory();
  $scope.modify = function () {
    var corpId = $scope.user.corpId;
    var mobile = $scope.findpassword.mobile;
    if (!/^1[3|4|5|6|7|8|9]\d{9}$/.test(mobile)) {
      Popup.notice("请输入正确的手机号", 2000, function () {});
      return false;
    }
    if (!corpId) {
      $scope.setTab(1);
      return Popup.notice("请选择机构！");
    }

    var promise = $scope.findPasswordFactory.saveOrQuery("/auth/adminSendPass.json", {
      corpId: corpId,
      mobile: mobile
    });
    promise.then(function (res) {
      if (res.status == 0) {
        Popup.notice("密码已发送至您的手机", 2000, function () {});
        $scope.setTab(1);
      } else {
        Popup.notice(res.errmsg, 2000, function () {});
      }
    });
  };

  $scope.mobileChange = function () {
    $scope.corpList = new ListFactory("/auth/getMyAdminCorpList.json", 0, 20, {
      mobile: $scope.user.name
    });
    var promise2 = $scope.corpList.nextPage();
    promise2.then(function (data) {
      if ($scope.corpList.count >= 1) {
        console.log(data);
        $scope.user.corpId = $scope.corpList.items[0].id;
        $scope.companyLogo = $scope.corpList.items[0].logo;
        $scope.companyName = $scope.corpList.items[0].corporationName;
      } else {
        $scope.user.corpId = null;
      }
    });
  };
  $scope.mobileChange2 = function () {
    $scope.corpList2 = new ListFactory("/auth/getMyAdminCorpList.json", 0, 20, {
      mobile: $scope.findpassword.mobile
    });
    var promise2 = $scope.corpList2.nextPage();
    promise2.then(function (data) {
      if ($scope.corpList2.count >= 1) {
        $scope.user.corpId = $scope.corpList2.items[0].id;
        $scope.companyLogo = $scope.corpList2.items[0].logo;
        $scope.companyName = $scope.corpList2.items[0].corporationName;
      } else {
        $scope.user.corpId = null;
      }
    });
  };
  $scope.selectCompany = function () {
    for (var i = 0, len = $scope.corpList.items.length; i < len; i++) {
      if ($scope.corpList.items[i].id == $scope.user.corpId) {
        $scope.companyLogo = $scope.corpList.items[i].logo;
        $scope.companyName = $scope.corpList.items[i].corporationName;
      }
    }
  };
  $scope.selectCompany2 = function () {
    for (var i = 0, len = $scope.corpList2.items.length; i < len; i++) {
      if ($scope.corpList2.items[i].id == $scope.user.corpId) {
        $scope.companyLogo = $scope.corpList2.items[i].logo;
        $scope.companyName = $scope.corpList2.items[i].corporationName;
      }
    }
  };
  $scope.loginFactory = new ObjectFactory();
  $scope.login = function () {
    var username = $scope.user.name,
        password = $scope.user.password,
        corpId = $scope.user.corpId;
    if (!corpId) return Popup.notice('请选择门店！');
    window.Win_SetSHA256(username, corpId, password).then(function (result) {
      var md5 = result.md5,
          ts = result.ts;

      $timeout(function () {
        $scope.loginFactory.saveOrQuery("/auth/adminLogin.json", {
          username: username,
          md5: md5,
          ts: ts,
          corpId: corpId
        }).then(function (data) {
          localStorage.setItem("corpid", corpId);
          var _data$result = data.result,
              type = _data$result.type,
              allow = _data$result.allow;
          //组织数据

          if (!allow) {
            $scope.loginFactory.errmsg && Popup.notice($scope.loginFactory.errmsg);
            if (type) {
              //  type:sms:短信欠费,voice:语音欠费,expire:系统欠费
              if (type === "expire") {
                var maxEndTime = data.result.corpEndTime;
                window.popout_expired(maxEndTime).then(function (res) {
                  $timeout(function () {
                    res && $scope.getCorp(corpId);
                  });
                });
                return;
              }
              $scope.payComponent.type = type;
              $scope.payComponent.show = true;
            }
            return;
          }
          new ObjectFactory().saveOrQuery("/admin/getCorpTypeConfVo.json").then(function (resp) {
            var corpInfo = {};
            corpInfo.companyTitle = resp.result.object.corpType.companyTitle;
            corpInfo.employeeTitle = resp.result.object.corpType.employeeTitle;
            corpInfo.username = username;
            localStorage.setItem("corpInfo", JSON.stringify(corpInfo));
          });
          localStorage.setItem("pcToken", $scope.loginFactory.result.token);
          $rootScope.appid = $scope.loginFactory.result.appid;
          localStorage.setItem("appid", $scope.loginFactory.result.appid);
          localStorage.setItem("username", $scope.loginFactory.result.admin.nickname);
          window.sessionStorage.setItem("loginInfo", JSON.stringify($scope.loginFactory.result.admin));
          $scope.saveLoginInfo().then(function (r) {
            $state.go("home");
          });
          $rootScope.leftShow = true;
        });
      });
    });
  };
  $scope.payComponent = {
    show: false,
    type: "",
    callBack: function callBack() {
      $scope.login();
    }
  };
  $scope.system_renew = {
    show: false,
    corpId: null,
    main: true
  };
  $scope.getCorp = function (corpId) {
    $scope.system_renew.corpId = corpId;
    $scope.system_renew.show = true;
  };
  $scope.$on("$destroy", function () {
    if (angular.isDefined($scope.timer)) {
      $timeout.cancel($scope.timer);
    }
  });
}]);
