angular.module("bestvisionWeb").controller("modifyPasswordCtrl", ["$scope", "Popup", "$rootScope", "$window", "$interval", "$state", "ObjectFactory", function ($scope, Popup, $rootScope, $window, $interval, $state, ObjectFactory) {
  // var token = localStorage.getItem("pcToken");
  // const userInfo = JSON.parse(localStorage.getItem("corpInfo"));
  $scope.obj = {
    code: "",
    password: ""
  };
  $scope.adminObjectFactory = new ObjectFactory();
  var promises = $scope.adminObjectFactory.saveOrQuery("/admin/getAdminInfo.json");
  promises.then(function (data) {
    $scope.obj.mobile = data.object.mobile; //显示手机号
  });
  $scope.cancel = function () {
    $window.history.back();
  };
  $scope.paracont = "发送验证码";
  $scope.sendCode = function () {
    $scope.codeFactory = new ObjectFactory();
    var promise = $scope.codeFactory.saveOrQuery("/admin/sendCodeToMe.json");
    promise.then(function (res) {
      if (res.status) {
        Popup.notice(res.errmsg);
      }
      return Popup.notice("验证码已发送，请注意查收");
    });
    var second = 60;
    var timePromise = $interval(function () {
      $scope.disabledClick = true;
      if (second <= 0) {
        $interval.cancel(timePromise);
        second = 60;
      } else {
        second--;
        $scope.paracont = second + "秒";
        if (second == 0) {
          $scope.paracont = "发送验证码";
          $scope.disabledClick = false;
        }
      }
    }, 1000, 60);
  };
  $scope.savePasswordFactory = new ObjectFactory();
  $scope.modify = function () {
    if ($scope.obj.password.length < 8) {
      Popup.notice("请至少输入八位密码", 2000, function () {});
      return false;
    }
    if ($scope.obj.password === $scope.password) {
      var promise = $scope.savePasswordFactory.saveOrQuery("/admin/modifyPass.json", $scope.obj);
      promise.then(function (res) {
        if (res.status == 0) {
          Popup.notice("修改成功", 2000, function () {});
        } else {
          Popup.notice(res.errmsg, 2000, function () {});
        }
      });
    } else {
      Popup.notice("两次密码输入不一致", 2000, function () {});
    }
  };
}]);
