angular.module('bestvisionWeb').controller('addHospitalCtrl', ['$scope', 'Popup', '$rootScope', '$state', 'ObjectFactory', 'ListFactory', '$http', function ($scope, Popup, $rootScope, $state, ObjectFactory, ListFactory, $http) {

    $scope.addHospitalFactory = new ObjectFactory();
    $scope.hoslistTab = 2;

    $scope.provincesData = null;
    $scope.citiesData = null;
    var addressData = {};

    $scope.obj = {
        companyName: '',
        description: ''
    };

    $scope.copinfoFactory = new ObjectFactory();
    $scope.copinfoFactory.saveOrQuery('/admin/getCorpConf.json');

    $scope.cityListFactory = new ObjectFactory();
    var promise = $scope.cityListFactory.saveOrQuery('/admin/getAllCityMap.json');
    promise.then(function (res) {
        console.log(res);
        addressData = res.vo;
        $scope.provincesData = res.vo['86'];
    });
    $scope.chooseProvince = function () {
        var selectedProvinceIndex;
        angular.forEach($scope.provincesData, function (item, index) {
            if (item === $scope.obj.province) {
                selectedProvinceIndex = index;
                return;
            }
        });

        $scope.citiesData = addressData[selectedProvinceIndex + ""];
    };

    $scope.update = function () {
        if (!$scope.obj.companyName || !$scope.obj.description || !$scope.obj.province || !$scope.obj.city) {
            Popup.notice('请填写完整信息', 3000, function () {});
        } else {
            var promise = $scope.addHospitalFactory.saveOrQuery('/admin/addHospital.json', $scope.obj);
            promise.then(function (data) {
                console.log(data);
                if (data.status == 0) {
                    $state.go('hospital.updateHospital.adminHospital', {
                        id: data.object.id,
                        companyId: data.object.id
                    }, { reload: true });
                } else {
                    Popup.notice(data.errmsg, 3000, function () {});
                }
            });
        }
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("adminClinicCtrl", ["$scope", "Popup", "WechatConfig", "$stateParams", "ObjectFactory", "HttpFactory", "ListFactory", "$http", "$timeout", function ($scope, Popup, WechatConfig, $stateParams, ObjectFactory, HttpFactory, ListFactory, $http, $timeout) {
  // 当前门店
  window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (result) {
    $timeout(function () {
      if (result) {
        $scope.companyInfo = result;
      } else {
        Popup.notice("未设置门店!");
      }
    });
  });
  $scope.keyword = "";
  $scope.status = [{ id: 0, name: "启用" }, { id: 1, name: "停用" }];
  $scope.changeStatus = function (consultRoomId, status, index) {
    HttpFactory.object("/admin/updateConsultRoomStatus.json", {
      consultRoomId: consultRoomId,
      status: status
    }).then(function () {
      $scope.searchLine(consultRoomId, index);
    });
  };
  $scope.setLine = function (params, index) {
    $scope.clinicPopout.showP(true, angular.copy(params), index);
  };
  $scope.clinicPopout = {
    show: false,
    title: "新增诊室",
    index: null, //修改某一行的诊室下标
    params: {},
    examineList: [],
    addExamineList: function addExamineList(examine) {
      this.examineList.push(examine);
    },
    delExamineList: function delExamineList(exam) {
      var i = this.examineList.findIndex(function (examine) {
        return examine.id === exam.examine.id;
      });
      this.examineList.splice(i, 1);
    },

    showP: function showP(show, params, index) {
      show && $scope.getExamineVoList();
      if (params) {
        this.index = index;
        this.params = params.consultRoom;
        this.examineList = params.examineList;
        this.title = "更新诊室";
      }
      this.show = show;
      if (!show) {
        this.params = {};
        this.examineList = [];
        this.index = null;
      }
    },
    submit: function submit() {
      if (!this.params.consultRoomName) {
        return Popup.notice("请输入诊室名称！");
      }
      var examineIdArray = this.examineList.map(function (examine) {
        return examine.id;
      });
      this.params.examineIdArray = examineIdArray;
      if (this.params.id) {
        this.params.consultRoomId = this.params.id;
        $scope.updateClinic(this.params, this.index);
      } else {
        this.params.companyId = $stateParams.companyId;
        $scope.addClinic(this.params);
      }
    }
  };
  $scope.addClinic = function (params) {
    HttpFactory.object("/admin/addConsultRoom.json", params).then(function () {
      Popup.notice("添加诊室成功！");
      $scope.clinicPopout.showP(false);
      $scope.searchScreenList();
    });
  };
  $scope.updateClinic = function (params, index) {
    HttpFactory.object("/admin/updateConsultRoomInfo.json", params).then(function (res) {
      Popup.notice("修改诊室成功！");
      $scope.searchLine(params.consultRoomId, index);
    });
  };
  $scope.searchLine = function (consultRoomId, index) {
    HttpFactory.object("/admin/getConsultRoomVo.json", {
      consultRoomId: consultRoomId
    }).then(function (res) {
      $scope.screenList.items[index] = res;
      $scope.clinicPopout.showP(false);
    });
  };
  $scope.pageSize = 10;
  $scope.searchScreenList = function () {
    $scope.screenList = new ListFactory("/admin/selectConsultRoomVoListOfCompany.json", 0, $scope.pageSize, {
      companyId: $stateParams.companyId,
      keyword: $scope.keyword
    });
    $scope.screenList.nextPage().then(function () {
      $(".Paginations").pagination($scope.screenList.count, {
        items_per_page: $scope.pageSize,
        callback: function callback(index) {
          $scope.screenList.clearAndSetIndex(index * $scope.pageSize);
          $scope.screenList.nextPage();
        }
      });
    });
  };
  $scope.getExamineVoList = function () {
    var length = 5;
    /* 每页都要对比选中id */
    var nextStep = function nextStep() {
      if ($scope.clinicPopout.examineList.length) {
        $scope.examineList.items.forEach(function (examine) {
          examine.isChose = $scope.clinicPopout.examineList.find(function (examined) {
            return examined.id === examine.examine.id;
          });
        });
      }
    };
    $scope.examineList = new ListFactory("/admin/getExamineVoList.json", 0, length, {
      status: 0,
      examineType: 1
    });
    $scope.examineList.nextPage().then(function () {
      nextStep();
      $(".Paginations1").pagination($scope.examineList.count, {
        items_per_page: length,
        callback: function callback(index) {
          $scope.examineList.clearAndSetIndex(index * length);
          $scope.examineList.nextPage().then(nextStep);
        }
      });
    });
  };
  $scope.choseSingle = function (item, index) {
    $scope.examineList.items[index].isChose = !$scope.examineList.items[index].isChose;
    $scope.examineList.items[index].isChose ? $scope.clinicPopout.addExamineList(item.examine) : $scope.clinicPopout.delExamineList(item);
  };
  $scope.searchScreenList();
  // 诊室管理：诊室二维码
  $scope.printConsultRoomQrCode = function (consultRoom) {
    $scope.consultRoomName = consultRoom.consultRoom.consultRoomName;
    WechatConfig.getWechatAppid(function (appid) {
      var qrCode = WechatConfig.setWechatUrl(appid, "checkSignIn?consultRoomId=" + consultRoom.consultRoom.id);
      $scope.consultRoomQrcode = qrCode;
      $timeout(function () {
        $(".ele6").jqprint({
          debug: false,
          importCSS: true,
          printContainer: true,
          operaSupport: false,
          timeout: 2000
        });
      }, 0);
    });
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("adminMapCtrl", ["$scope", "Popup", "$uibModal", "$stateParams", "$state", "ObjectFactory", "ListFactory", "$http", "$timeout", function ($scope, Popup, $uibModal, $stateParams, $state, ObjectFactory, ListFactory, $http, $timeout) {
  $scope.provincesData = null;
  $scope.citiesData = null;

  $scope.obj = {
    address: "",
    id: "",
    province: "",
    city: "",
    longitude: "",
    latitude: ""
  };
  var addressData = {};
  $scope.cityListFactory = new ObjectFactory();
  var promise = $scope.cityListFactory.saveOrQuery("/admin/getAllCityMap.json");
  promise.then(function (res) {
    console.log(res);
    addressData = res.vo;
    $scope.provincesData = res.vo["86"];

    $scope.adminMapFactory = new ObjectFactory();
    var promiseHospital = $scope.adminMapFactory.saveOrQuery("/admin/getHospitalInfo.json", { id: $scope.id });
    promiseHospital.then(function (data) {
      console.log(data);
      if (data.object.longitude) {
        $scope.obj.longitude = data.object.longitude;
      } else {
        $scope.obj.longitude = 116.397428;
      }
      if (data.object.latitude) {
        $scope.obj.latitude = data.object.latitude;
      } else {
        $scope.obj.latitude = 39.90923;
      }

      // $scope.obj.latitude = data.object.latitude;
      $scope.obj.address = data.object.address;
      $scope.add = data.object.companyName;

      $scope.obj.province = data.object.province;
      $scope.obj.city = data.object.city;
      $scope.chooseProvince();

      var map = new AMap.Map("container", {
        resizeEnable: true,
        zoom: 15,
        center: [$scope.obj.longitude, $scope.obj.latitude]
      });

      var marker = new AMap.Marker({
        map: map,
        bubble: true
      });

      map.plugin(["AMap.ToolBar"], function () {
        map.addControl(new AMap.ToolBar());
      });
      map.on("click", function (e) {
        console.log(e);
        $timeout(function () {
          $scope.obj.longitude = e.lnglat.getLng();
          $scope.obj.latitude = e.lnglat.getLat();
        }, 500);
        marker.setPosition(e.lnglat);
      });
      var auto = new AMap.Autocomplete({
        input: "tipinput"
      });
      AMap.event.addListener(auto, "select", select); //注册监听，当选中某条记录时会触发
      function select(e) {
        console.log(e);
        if (e.poi && e.poi.location) {
          map.setZoom(15);
          map.setCenter(e.poi.location);
          marker.setPosition(e.poi.location);
          $timeout(function () {
            $scope.obj.longitude = e.poi.location.lng;
            $scope.obj.latitude = e.poi.location.lat;
            $scope.obj.address = e.poi.district + e.poi.address;
          }, 500);
        }
      }
    });
  });
  $scope.chooseProvince = function () {
    var selectedProvinceIndex;
    angular.forEach($scope.provincesData, function (item, index) {
      if (item === $scope.obj.province) {
        selectedProvinceIndex = index;
        return;
      }
    });

    $scope.citiesData = addressData[selectedProvinceIndex + ""];
  };
  $scope.chooseCity = function () {};

  $scope.obj.id = $stateParams.companyId;
  $scope.mapDepartment = function () {
    if ($scope.obj.province && $scope.obj.city) {
      $scope.adminMapFactory.saveOrQuery("/admin/updateHospitalMap.json", $scope.obj);
      Popup.notice("提交成功", 3000, function () {});
    } else {
      Popup.notice("请选择省份和城市", 3000, function () {});
    }
  };
}]);
'use strict';

