angular.module('bestvisionWeb').controller('updateAdminHospitalCtrl', ['$scope', '$rootScope', 'Popup', '$uibModal', '$stateParams', '$state', 'ObjectFactory', 'ListFactory', '$http', '$q', '$timeout', 'QiniuFactory', function ($scope, $rootScope, Popup, $uibModal, $stateParams, $state, ObjectFactory, ListFactory, $http, $q, $timeout, QiniuFactory) {
    $scope.id = $stateParams.id;
    $scope.isactive = false;
    $scope.isloading = false;
    $scope.loadingdone = false;
    $scope.toggleactive = function () {
        $scope.isactive = !$scope.isactive;
    };

    $scope.updateAdminHospitalQiniuFactory = new QiniuFactory();
    $scope.updateAdminHospitalQiniuFactory.getToken();

    //取到所七牛的token
    function getbase() {
        var defer = $q.defer();
        var base64_code;
        var imgupload = document.getElementById("adminhospital-img");
        imgupload.addEventListener('change', readFile, false);

        function readFile() {
            var file = this.files[0];
            var reader = new FileReader();
            reader.onload = function () {
                base64_code = this.result.replace(/^.*?,/, '');
                // console.log(base64_code);  
                defer.resolve(base64_code);
            };
            reader.readAsDataURL(file);
        };
        return defer.promise;
    }

    function putb64(base64_code) {
        var url = $scope.updateAdminHospitalQiniuFactory.UPLOAD_HOST;
        var xhr = new XMLHttpRequest();
        xhr.onreadystatechange = function () {
            if (xhr.readyState == 4) {
                console.log(xhr.responseText);
                var resultObj = JSON.parse(xhr.responseText);
                var avatar = $scope.updateAdminHospitalQiniuFactory.IMAGE_HOST + "/" + resultObj.key;
                $scope.keyimg = $scope.updateAdminHospitalQiniuFactory.IMAGE_HOST + "/" + resultObj.key;

                $scope.updateHospitalFactory.object.picture = $scope.updateAdminHospitalQiniuFactory.IMAGE_HOST + "/" + resultObj.key;
                console.log(resultObj.key);
                var formData = $scope.updateHospitalFactory.object;
                $http({
                    url: API_HOST + "/admin/updateHospital.json",
                    method: 'POST',
                    data: $.param(formData),
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
                }).then(function (response) {
                    if (response.status === 200) {
                        $scope.isloading = false;
                        $scope.loadingdone = true;
                    }
                });
            }
        };
        xhr.open("POST", url, true);
        xhr.setRequestHeader("Content-Type", "application/octet-stream");
        xhr.setRequestHeader("Authorization", "UpToken " + $scope.updateAdminHospitalQiniuFactory.UPLOAD_TOKEN);
        xhr.send(base64_code);
    };

    $scope.uploadimg = function () {
        $scope.isloading = true;

        getbase().then(function (res) {
            putb64(res);
        });
    };

    $scope.chooseImg = function () {

        $scope.imgModalModify = true;
    };

    $scope.picArr = [];
    $scope.myImage = '';
    $scope.myCroppedImage = '';

    var handleFileSelect = function handleFileSelect(evt) {
        var file = evt.currentTarget.files[0];
        var reader = new FileReader();
        reader.onload = function (evt) {
            $scope.$apply(function ($scope) {
                $scope.myImage = evt.target.result;
            });
        };
        reader.readAsDataURL(file);
    };
    angular.element(document.querySelector('#fileInputModify')).on('change', handleFileSelect);

    $scope.getBaseCode = function () {

        $rootScope.$broadcast("ajax-start");
        var base64_code = $scope.myCroppedImage.replace(/^.*?,/, '');
        putb64(base64_code);
        $scope.imgModalModify = false;
    };

    $scope.updateHospitalFactory = new ObjectFactory();
    var promise = $scope.updateHospitalFactory.saveOrQuery('/admin/getHospitalInfo.json', { id: $scope.id });
    promise.then(function (data) {

        $scope.keyimg = $scope.updateHospitalFactory.object.picture;
    });

    $scope.modify = function () {

        $scope.updateHospitalFactory.object.id = $stateParams.id;
        var params = $scope.updateHospitalFactory.object;

        if ($scope.updateHospitalFactory.object.phone) {
            if (!/[1-9\-]\d*$/.test($scope.updateHospitalFactory.object.phone)) {
                Popup.notice('请输入正确的手机号或电话号', 2000, function () {});
                return;
            }
        };
        $scope.isloading = true;

        $http({
            url: API_HOST + '/admin/updateHospital.json',
            method: 'POST',
            data: $.param(params ? angular.copy(params) : {}),
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
        }).then(function (response) {
            console.log(response);
            if (response.data.json.status == "1") {
                $scope.isloading = false;
                Popup.notice(response.data.json.errmsg, 2000, function () {});
            }
            if (response.data.json.status == "0") {
                $state.go('hospital.updateHospital.adminHospital', { id: $scope.id }, { reload: true });
            }
        });
    };

    $scope.selectImg = function () {
        // console.log("selectImg");
        //这里很关键,是打开模态框的过程
        var modalInstance = $uibModal.open({
            templateUrl: 'updateHospitalModalContent.html',
            controller: 'updateAdminHospitalModalInstanceCtrl'

        });

        modalInstance.result.then(function (keyimg) {
            //这是一个接收模态框返回值的函数
            var imageMkd = '\r\n![](' + keyimg + ')';
            $scope.updateHospitalFactory.object.description = $scope.updateHospitalFactory.object.description + imageMkd;
        }, function () {});
    };
}]);
angular.module('bestvisionWeb').controller('updateAdminHospitalModalInstanceCtrl', ['$scope', '$uibModalInstance', '$http', '$q', '$timeout', 'QiniuFactory', function ($scope, $uibModalInstance, $http, $q, $timeout, QiniuFactory) {

    $scope.isactive = false;
    $scope.isloading = false;
    $scope.loadingdone = false;
    $scope.modelloading = true;
    $scope.toggleactive = function () {
        $scope.isactive = !$scope.isactive;
    };
    $scope.modalQiniuFactory = new QiniuFactory();
    $scope.modalQiniuFactory.getToken();
    // console.log($scope.modalQiniuFactory);
    function getbase() {
        var defer = $q.defer();
        var base64_code;
        var imgload = document.getElementById("adminhospital-imgmodal");
        imgload.addEventListener('change', readFile, false);

        function readFile() {
            var file = this.files[0];
            var reader = new FileReader();
            reader.onload = function () {
                base64_code = this.result.replace(/^.*?,/, '');
                // console.log(base64_code);  
                defer.resolve(base64_code);
            };
            reader.readAsDataURL(file);
        };
        return defer.promise;
    }

    function putb64(base64_code) {
        var url = $scope.modalQiniuFactory.UPLOAD_HOST;
        var xhr = new XMLHttpRequest();
        xhr.onreadystatechange = function () {
            if (xhr.readyState == 4) {
                console.log(xhr.responseText);
                var resultObj = JSON.parse(xhr.responseText);
                var avatar = $scope.modalQiniuFactory.IMAGE_HOST + "/" + resultObj.key;
                $scope.keyimg = $scope.modalQiniuFactory.IMAGE_HOST + "/" + resultObj.key;
                if ($scope.keyimg) {
                    $scope.isloading = false;
                    $scope.loadingdone = true;
                }
                $scope.$digest();
                var formData = {
                    'avatar': avatar
                };
                // $http({
                //     url: API_HOST + "/doct/saveEmployeeAvatar.json",
                //     method: 'POST',
                //     data: $.param(formData),
                //     headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                // }).then(function(response) {
                //     //组织数据
                //     if (response.status === 200) {
                //         $scope.isloading = false;
                //         $scope.modelloading = false;
                //         $scope.loadingdone = true;
                //     }
                // });
                $scope.isloading = false;
                $scope.modelloading = false;
                $scope.loadingdone = true;
            }
        };
        xhr.open("POST", url, true);
        xhr.setRequestHeader("Content-Type", "application/octet-stream");
        xhr.setRequestHeader("Authorization", "UpToken " + $scope.modalQiniuFactory.UPLOAD_TOKEN);
        xhr.send(base64_code);
    };

    $scope.loadimg = function () {

        //将图片转换为base64格式
        $scope.isloading = true;
        $scope.modelloading = true;

        getbase().then(function (res) {
            putb64(res);
        });
    };

    $scope.ok = function () {
        $uibModalInstance.close($scope.keyimg);
    };

    $scope.cancel = function () {
        $uibModalInstance.dismiss('cancel');
    };
}]);
