angular.module("bestvisionWeb").controller("machineOrderCtrl", ["$scope", "$stateParams", "Popup", "DateUtilFactory", "$state", "ObjectFactory", "ListFactory", "$http", "$timeout", function ($scope, $stateParams, Popup, DateUtilFactory, $state, ObjectFactory, ListFactory, $http, $timeout) {
  // jj
  $scope.toggle = 2;
  $scope.obj = {};
  $scope.obj.status = null;
  $scope.obj.companyId = "";

  $scope.obj.startTime = new Date();
  $scope.rightTime = new Date();
  $scope.search = function () {
    if ($scope.obj.startTime && $scope.rightTime) {
      $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
      $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);

      var pageSize = 12;
      $scope.memberFactory = new ListFactory("/admin/selectInStoreMachineCenterCashflowVoList.json", 0, pageSize, $scope.obj);
      var promise = $scope.memberFactory.nextPage();
      promise.then(function (data) {
        $("#Pagination").pagination($scope.memberFactory.count, {
          items_per_page: pageSize,
          callback: function callback(index) {
            $scope.memberFactory.clearAndSetIndex(index * pageSize);
            $scope.memberFactory.nextPage();
          }
        });
      });
    }
  };
  $scope.search();

  $scope.hideAddModal = function () {
    $scope.addOrderModal = false;
  };
  $scope.methodGlassRecord = {};
  $scope.showRecord = function (id) {
    $scope.methodGlassRecordVoFactory = new ObjectFactory();
    var methodPromise = $scope.methodGlassRecordVoFactory.saveOrQuery("/admin/getMethodGlassRecordVo.json", { medicalRecordId: id });
    methodPromise.then(function (res) {
      if (res.result.vo.methodGlassRecord) {
        if ($scope.methodGlassRecordVoFactory.vo.methodGlassRecord.right45 === "右") {
          $scope.mainOpticEye = "右";
        }
        if ($scope.methodGlassRecordVoFactory.vo.methodGlassRecord.left45 === "左") {
          $scope.mainOpticEye = "左";
        }

        $scope.methodGlassRecord.right84 = $scope.methodGlassRecordVoFactory.vo.methodGlassRecord.right84;

        $scope.methodGlassRecord.left84 = $scope.methodGlassRecordVoFactory.vo.methodGlassRecord.left84;

        $scope.methodGlassRecord.right83 = $scope.methodGlassRecordVoFactory.vo.methodGlassRecord.right83;

        $scope.methodGlassRecord.left83 = $scope.methodGlassRecordVoFactory.vo.methodGlassRecord.left83;
      }
    });
    $scope.RecordVoFactory = new ObjectFactory();
    $scope.RecordVoFactory.saveOrQuery("/admin/getMedicalRecord.json", {
      id: id
    });

    $scope.addOrderModal = true;
  };

  $scope.setTab = function (idx) {
    $scope.obj.status = idx;
    $scope.search();
  };

  $scope.common = {};
  $scope.startOrder = function (id, medicalRecordId, idx) {
    $scope.common.url = "/admin/startMachineCenterOrder.json";
    $scope.common.machineCenterOrderId = id;
    $scope.common.medicalRecordId = medicalRecordId;
    $scope.common.idx = idx;
    Popup.confirm("确定开始制作么？", function () {
      $scope.commonOrder();
    }, function () {});
  };

  $scope.processProduct = function (cashflowId, idx) {
    $scope.getProcessFactory = new ObjectFactory();
    var cashPromise = $scope.getProcessFactory.saveOrQuery("/admin/getCanBeProcessSkuInListOfProduct.json", { cashflowId: cashflowId });
    cashPromise.then(function (resp) {
      $scope.stockDetail = true;
    });
  };

  $scope.saveStock = function () {
    var arr = [];
    var medicalProductStockBatctPoListJson = [];

    var productArr = $scope.getProcessFactory.result.list;
    for (var i = 0; i < productArr.length; i++) {
      arr[i] = [];
      for (var j = 0; j < productArr[i].deliveryStockInSkuVoList.length; j++) {
        if (productArr[i].deliveryStockInSkuVoList[j].deliveryCount > 0) {
          arr[i].push({
            stockInSkuId: productArr[i].deliveryStockInSkuVoList[j].stockInSku.id,
            deliveryCount: productArr[i].deliveryStockInSkuVoList[j].deliveryCount
          });
        } else if (productArr[i].deliveryStockInSkuVoList[j].deliveryCount < 0) {
          Popup.notice("发货数量必须大于0");
          return false;
        } else {}
      }
      if (arr[i].length) {
        medicalProductStockBatctPoListJson.push({
          medicalProductId: productArr[i].medicalProduct.id,
          medicalProductStocks: arr[i]
        });
      }
    }
    if (!medicalProductStockBatctPoListJson.length) {
      Popup.notice("发货数量必须大于0");
      return false;
    }

    $scope.saveStockFactory = new ObjectFactory();
    var savePromise = $scope.saveStockFactory.saveOrQuery("/admin/saveToBeProcessSkuInListOfProduct.json", {
      medicalProductStockBatctPoListJson: JSON.stringify(medicalProductStockBatctPoListJson)
    });
    savePromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        Popup.notice("保存成功");
        $scope.stockDetail = false;
      }
    });
  };

  $scope.completeOrder = function (id, medicalRecordId, idx) {
    $scope.common.url = "/admin/completeMachineCenterOrder.json";
    $scope.common.machineCenterOrderId = id;
    $scope.common.medicalRecordId = medicalRecordId;
    $scope.common.idx = idx;
    Popup.confirm("确定制作完成么？", function () {
      $scope.commonOrder();
    }, function () {});
  };
  $scope.closeOrder = function (id, medicalRecordId, idx) {
    $scope.common.url = "/admin/closeMachineCenterOrder.json";
    $scope.common.medicalRecordId = medicalRecordId;
    $scope.common.machineCenterOrderId = id;
    $scope.common.idx = idx;
    Popup.confirm("确定关闭么？", function () {
      $scope.commonOrder();
    }, function () {});
  };
  $scope.commonOrder = function () {
    $scope.commonOrderFactory = new ObjectFactory();
    var commonPromise = $scope.commonOrderFactory.saveOrQuery($scope.common.url, { machineCenterOrderId: $scope.common.machineCenterOrderId });
    commonPromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        $scope.getOrderFactory = new ObjectFactory();
        var orderPromise = $scope.getOrderFactory.saveOrQuery("/admin/getMachineCenterOrder.json", { medicalRecordId: $scope.common.medicalRecordId });
        orderPromise.then(function (resp) {
          $scope.memberFactory.items[$scope.common.idx].machineCenterOrder.status = resp.result.object.status;
        });
      }
    });
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("machineOrderBrokenCtrl", ["$scope", "Popup", "$window", "$stateParams", "$rootScope", "$state", "$timeout", "ListFactory", "ObjectFactory", function ($scope, Popup, $window, $stateParams, $rootScope, $state, $timeout, ListFactory, ObjectFactory) {
  $scope.cashflowId = $stateParams.cashflowId;
  $scope.machineCenterId = $stateParams.machineCenterId;
  $scope.chain = $stateParams.chain;
  $scope.obj = {};

  var searchStock = function searchStock() {
    $scope.getStockObjectFactory = new ObjectFactory();
    $scope.getStockObjectFactory.saveOrQuery("/admin/getMachineCenterCashflowVo.json", {
      cashflowId: $scope.cashflowId,
      machineCenterId: $scope.machineCenterId
    });
  };
  searchStock();
  $scope.modal = { stockLossShow: false };
  $scope.hideModal = function () {
    $scope.modal.stockLossShow = false;
  };

  $scope.goBack = function () {
    window.history.back();
  };
  $scope.loss = {};

  var getAdminId = function getAdminId() {
    var getAdminFactory = new ObjectFactory();
    var adminPromise = getAdminFactory.saveOrQuery("/admin/getAdminInfo.json");
    adminPromise.then(function (res) {
      $scope.loss.lossAdminId = res.result.object.id;
      $scope.adminname = res.result.object.nickname;
    });
  };

  $scope.modifyLoss = function () {
    // $scope.loss.lossAdminId = 1;
    if (!$scope.loss.lossAdminId) {
      Popup.notice("请选择报损责任人");
      return false;
    }
    if (!$scope.modal.lossReasonId) {
      Popup.notice("请选择报损原因");
      return false;
    }
    $scope.loss.medicalStockLossSkuListJson = JSON.stringify([{
      medicalProductStockId: $scope.medicalProductStockId,
      lossCount: $scope.lossCount,
      lossReasonId: $scope.modal.lossReasonId,
      remark: $scope.modal.remark
    }]);
    var ceateLossFactory = new ObjectFactory();
    var lossPromise = ceateLossFactory.saveOrQuery("/admin/createMedicalStockLoss.json", $scope.loss);
    lossPromise.then(function (res) {
      if (res.status == 0) {
        Popup.notice("报损成功");
        $scope.modal.stockLossShow = false;
        searchStock();
      } else {
        Popup.notice(res.errmsg);
      }
    });
  };
  $scope.showLoss = function (stockId, count, idx) {
    $scope.medicalProductStockId = stockId;
    $scope.modal.lossReasonId = null;
    getAdminId();
    $scope.lossCount = count;
    $scope.modal.remark = null;
    $scope.loss.machineCenterOrderId = $scope.getStockObjectFactory.result.object.machineCenterOrderVoList[idx].machineCenterOrder.id;
    $scope.productName = $scope.getStockObjectFactory.result.object.machineCenterOrderVoList[idx].medicalProduct.productName;

    $scope.modal.stockLossShow = true;
  };
  $scope.completeOrder = function () {
    Popup.confirm("确定完成么", function () {
      var completeFactory = new ObjectFactory();
      var completePromise = completeFactory.saveOrQuery("/admin/completeMachineCenterOrder.json", {
        cashflowId: $scope.cashflowId,
        machineCenterId: $scope.machineCenterId
      });
      completePromise.then(function (res) {
        if (res.status == 0) {
          Popup.notice("完成成功");
          if ($scope.chain == 1) {
            $state.go("machineOrderChainTesting");
          } else {
            $state.go("machineOrderTesting");
          }
        } else {
          Popup.notice(res.errmsg);
        }
      });
    }, function () {});
  };
}]);
"use strict";

