angular.module("bestvisionWeb").controller("stockLossListCtrl", ["$scope", "Popup", "$timeout", "$stateParams", "$rootScope", "$state", "ObjectFactory", "DateUtilFactory", "ListFactory", "$http", function ($scope, Popup, $timeout, $stateParams, $rootScope, $state, ObjectFactory, DateUtilFactory, ListFactory, $http) {
  var pageSize = 10;
  $scope.obj = {};
  $scope.obj.startTime = moment(new Date()).add(-3, "months")._d;
  $scope.rightTime = new Date();

  var getCount = function getCount() {
    $scope.getOrderCountFactory = new ObjectFactory();
    var countPromise = $scope.getOrderCountFactory.saveOrQuery("/admin/statMachineCenterCashflowStatusCount.json", {
      machineCenterId: $scope.obj.machineCenterId,
      startTime: $scope.obj.startTime,
      endTime: $scope.obj.endTime
    });
  };
  $scope.searchAdminList = function () {
    if ($scope.obj.startTime && $scope.rightTime) {
      $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
      $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);

      getCount();

      $scope.getAdminList = new ListFactory("/admin/selectMedicalStockLossVoList.json", 0, 10, $scope.obj);
      var promise = $scope.getAdminList.nextPage();
      promise.then(function (data) {
        console.log(data);
        $(".first-pagination").pagination($scope.getAdminList.count, {
          items_per_page: pageSize,
          callback: function callback(index) {
            $scope.getAdminList.clearAndSetIndex(index * pageSize);
            $scope.getAdminList.nextPage();
          }
        });
      });
    }
  };

  $scope.setStatus = function (tab) {
    $scope.obj.checked = tab;
    $scope.searchAdminList();
  };
  $scope.showLossDetail = function (id) {
    $scope.getStockTakingObjectFactory = new ObjectFactory();
    $scope.getStockTakingObjectFactory.saveOrQuery("/admin/getMedicalStockLossVo.json", { medicalStockLossId: id });
    $scope.stockDetail = true;
  };
  var url = "";
  if ($scope.$state.current.name == "stockLossList") {
    url = "/admin/getCompanyMachineCenterOfMine.json";
    $scope.tab = 1;
  } else {
    url = "/admin/getChainMachineCenterOfMine.json";
    $scope.tab = 2;
  }

  $scope.getMachineCenterIdFactory = new ObjectFactory();
  var centerPromise = $scope.getMachineCenterIdFactory.saveOrQuery(url);
  centerPromise.then(function (resp) {
    if (resp.status == 0) {
      if (resp.result.object) {
        $scope.obj.machineCenterId = resp.result.object.machineCenter.id;
        $scope.searchAdminList();
      }
    } else {
      $scope.setCompanyModal = true;
      $scope.msg = resp.errmsg;
    }
  });
}]);
'use strict';

