angular.module("bestvisionWeb").controller("modifySecKillProductCtrl", ["$scope", "Popup", "$stateParams", "$rootScope", "$state", "ObjectFactory", "QiniuFactory", "ListFactory", "$q", "$http", function ($scope, Popup, $stateParams, $rootScope, $state, ObjectFactory, QiniuFactory, ListFactory, $q, $http) {
  $scope.unitNames = window.optionsObj.unitNames;
  $scope.modelNames = [{ id: "颜色", name: "颜色" }, { id: "度数", name: "度数" }, { id: "材质", name: "材质" }, { id: "重量", name: "重量" }, { id: "尺码", name: "尺码" }, { id: "规格", name: "规格" }, { id: "型号", name: "型号" }, { id: "设计", name: "设计" }, { id: "容量", name: "容量" }, { id: "疗程", name: "疗程" }, { id: "近视度数", name: "近视度数" }, { id: "散光度数", name: "散光度数" }, { id: "轴位", name: "轴位" }, { id: "功能", name: "功能" }];

  $scope.obj = {};
  $scope.obj.seckillProductId = $stateParams.seckillProductId;
  $scope.getSecKillFactory = new ObjectFactory();
  var getPromise = $scope.getSecKillFactory.saveOrQuery("/admin/getSeckillProductVo.json", { seckillProductId: $scope.obj.seckillProductId });
  getPromise.then(function (res) {
    $scope.obj.productName = res.object.seckillProduct.productName;
    $scope.obj.description = res.object.seckillProduct.description;
    // $scope.obj.modelPicture = res.object.seckillProduct.modelPicture;
    $scope.picArr = res.object.seckillProduct.modelPicture.split(",");
    $scope.obj.skuCode = res.object.seckillProduct.skuCode;
    $scope.obj.unitName = res.object.seckillProduct.unitName;
    $scope.obj.modelType = String(res.object.seckillProduct.modelType);
    $scope.obj.model1Name = res.object.seckillProduct.model1Name;
    $scope.obj.model2Name = res.object.seckillProduct.model2Name;
    if (res.object.seckillProduct.model1 != "无") {
      $scope.obj.model1 = res.object.seckillProduct.model1;
    }
    if (res.object.seckillProduct.model2 != "无") {
      $scope.obj.model2 = res.object.seckillProduct.model2;
    }
    if (res.object.seckillProduct.model1 != "无") {
      $scope.model1 = true;
    }
    if (res.object.seckillProduct.model2 != "无") {
      $scope.model2 = true;
    }

    $scope.marketPrice = res.object.seckillProduct.marketPrice;
    $scope.seckillPrice = res.object.seckillProduct.seckillPrice;
    $scope.obj.totalCount = res.object.seckillProduct.totalCount;
    if (res.object.seckillProduct.startTime) {
      // $scope.obj.startTime = new Date(res.object.seckillProduct.startTime);
      $scope.startTime = moment(res.object.seckillProduct.startTime).format("YYYY-MM-DD HH:mm");
    }

    if (res.object.seckillProduct.endTime) {
      $scope.endTime = moment(res.object.seckillProduct.endTime).format("YYYY-MM-DD HH:mm");
    }
  });

  $scope.changeType = function (status) {
    if (status == 0) {
      $scope.model1 = false;
      $scope.model2 = false;
    } else if (status == 1) {
      $scope.model1 = true;
      $scope.model2 = false;
    } else {
      $scope.model1 = true;
      $scope.model2 = true;
    }
  };

  $scope.common = function () {
    if ($scope.obj.model1Name == $scope.obj.model2Name) {
      Popup.notice("规格不能选择相同", 2000, function () {});
    }
  };

  $scope.goBack = function () {
    window.history.back();
  };

  $scope.imgModalModify = false;
  $scope.chooseImg = function () {
    if ($scope.picArr.length > 4) {
      Popup.notice("最多上传5张图片");
      return false;
    }
    $scope.imgModalModify = true;
  };

  $scope.setTab = function (idx) {
    $scope.tab = idx;
  };
  $scope.setNull = function (idx) {
    $scope.tab = null;
  };

  $scope.setFirst = function (url, idx) {
    $scope.picArr.splice(idx, 1);
    $scope.picArr.unshift(url);
  };
  $scope.deleteImg = function (idx) {
    $scope.picArr.splice(idx, 1);
  };

  $scope.addSecKill = function () {
    $scope.obj.startTime = moment($scope.startTime)._d;
    $scope.obj.endTime = moment($scope.endTime)._d;

    $scope.obj.modelPicture = $scope.picArr.join(",");

    if (!$scope.obj.productName) {
      Popup.notice("请输入商品名称", 3000, function () {});
      return false;
    }
    if (!$scope.obj.modelPicture) {
      Popup.notice("请选择图片", 3000, function () {});
      return false;
    }

    if ($scope.obj.modelType == 0) {
      $scope.obj.model1Name = "无";
      $scope.obj.model2Name = "无";
      $scope.obj.model1 = "无";
      $scope.obj.model2 = "无";
    } else if ($scope.obj.modelType == 1) {
      $scope.obj.model2 = "无";
      $scope.obj.model2Name = "无";
      if ($scope.obj.model1Name == "无") {
        Popup.notice("请选择规格", 2000, function () {});
        return false;
      }
      if (!$scope.obj.model1) {
        Popup.notice("请填写规格", 2000, function () {});
        return false;
      }
    } else if ($scope.obj.modelType == 2) {
      if ($scope.obj.model1Name == "无" || $scope.obj.model2Name == "无") {
        Popup.notice("请选择规格", 2000, function () {});
        return false;
      }
      if (!$scope.obj.model1 || !$scope.obj.model2) {
        Popup.notice("请填写规格", 2000, function () {});
        return false;
      }
    } else {}

    if ($scope.marketPrice > 0) {
      $scope.obj.marketPrice = $scope.marketPrice.toFixed(2);
    } else {
      Popup.notice("市场价不能小于0", 3000, function () {});
      return false;
    }
    if ($scope.seckillPrice > 0) {
      $scope.obj.seckillPrice = $scope.seckillPrice.toFixed(2);
    } else {
      Popup.notice("秒杀价不能小于0", 3000, function () {});
      return false;
    }

    if (!/^[1-9]\d*$/.test($scope.obj.totalCount)) {
      Popup.notice("发放数量请输入正整数", 3000, function () {});
      return false;
    }

    $scope.addFactory = new ObjectFactory();
    var addPromise = $scope.addFactory.saveOrQuery("/admin/updateSeckillProduct.json", $scope.obj);
    addPromise.then(function (res) {
      if (res.status == 0) {
        Popup.notice("修改成功");

        $state.go("modifySecKillProduct", { seckillProductId: $scope.obj.seckillProductId }, { reload: true });
      } else {
        Popup.notice(res.errmsg);
      }
    });
  };

  $scope.active = function () {
    $scope.obj.startTime = moment($scope.startTime)._d;
    $scope.obj.endTime = moment($scope.endTime)._d;
    $scope.obj.modelPicture = $scope.picArr.join(",");

    if (!$scope.obj.productName) {
      Popup.notice("请输入商品名称", 3000, function () {});
      return false;
    }
    if (!$scope.obj.modelPicture) {
      Popup.notice("请选择图片", 3000, function () {});
      return false;
    }

    if ($scope.obj.modelType == 0) {
      $scope.obj.model1Name = "无";
      $scope.obj.model2Name = "无";
      $scope.obj.model1 = "无";
      $scope.obj.model2 = "无";
    } else if ($scope.obj.modelType == 1) {
      $scope.obj.model2 = "无";
      $scope.obj.model2Name = "无";
      if ($scope.obj.model1Name == "无") {
        Popup.notice("请选择规格", 2000, function () {});
        return false;
      }
      if (!$scope.obj.model1) {
        Popup.notice("请填写规格", 2000, function () {});
        return false;
      }
    } else if ($scope.obj.modelType == 2) {
      if ($scope.obj.model1Name == "无" || $scope.obj.model2Name == "无") {
        Popup.notice("请选择规格", 2000, function () {});
        return false;
      }
      if (!$scope.obj.model1 || !$scope.obj.model2) {
        Popup.notice("请填写规格", 2000, function () {});
        return false;
      }
    } else {}

    if ($scope.marketPrice > 0) {
      $scope.obj.marketPrice = $scope.marketPrice.toFixed(2);
    } else {
      Popup.notice("市场价不能小于0", 3000, function () {});
      return false;
    }
    if ($scope.seckillPrice > 0) {
      $scope.obj.seckillPrice = $scope.seckillPrice.toFixed(2);
    } else {
      Popup.notice("秒杀价不能小于0", 3000, function () {});
      return false;
    }

    if (!/^[1-9]\d*$/.test($scope.obj.totalCount)) {
      Popup.notice("发放数量请输入正整数", 3000, function () {});
      return false;
    }

    $scope.addFactory = new ObjectFactory();
    var addPromise = $scope.addFactory.saveOrQuery("/admin/updateSeckillProduct.json", $scope.obj);
    addPromise.then(function (res) {
      if (res.status == 0) {
        $scope.activeFactory = new ObjectFactory();
        var activePromise = $scope.activeFactory.saveOrQuery("/admin/activeSeckillProduct.json", { seckillProductId: $scope.obj.seckillProductId });
        activePromise.then(function (response) {
          if (response.status == 0) {
            Popup.notice("生效成功");
            window.history.back();
          } else {
            Popup.notice(response.errmsg);
          }
        });
      } else {
        Popup.notice(res.errmsg);
      }
    });
  };
}]);
