angular.module('bestvisionWeb').controller('myCouponCtrl', ['$scope', 'Popup', '$uibModal', '$stateParams', '$rootScope', '$state', 'ObjectFactory', 'ListFactory', '$http', function ($scope, Popup, $uibModal, $stateParams, $rootScope, $state, ObjectFactory, ListFactory, $http) {
    $scope.obj = {};
    $scope.obj.customerId = $stateParams.customerId;

    $scope.couponIdList = [];

    $scope.status = [{ id: null, name: '全部' }, { id: 0, name: '未使用' }, { id: 1, name: '已使用' }, { id: 2, name: '已作废' }];
    $scope.obj.status = null;

    $scope.modify = function () {
        if (!$scope.couponIdList.length) {
            Popup.notice('请选择优惠券');
            return false;
        }
        for (var i = 0; i < $scope.couponIdList.length; i++) {
            if ($scope.couponIdList[i] != null) {
                $scope.sendCouponFactory = new ObjectFactory();
                var sendPromise = $scope.sendCouponFactory.saveOrQuery('/admin/sendCoupon.json', { customerId: $scope.obj.customerId, couponId: $scope.couponIdList[i] });
                sendPromise.then(function (res) {
                    $scope.search();
                });
            }
        }
        $scope.hideCouponModal();
    };
    // $scope.havenotFactory = new ListFactory('/admin/selectCustomerCouponVoList.json', 0, 10, { customerId: $scope.obj.customerId, status: 0 });
    // $scope.havenotFactory.nextPage();
    // $scope.haveFactory = new ListFactory('/admin/selectCustomerCouponVoList.json', 0, 10, { customerId: $scope.obj.customerId, status: 1 });
    // $scope.haveFactory.nextPage();


    $scope.selectFactory = new ListFactory('/admin/selectCustomerCouponVoList.json', 0, 10, $scope.obj);
    $scope.selectFactory.nextPage();

    $scope.getCount = new ObjectFactory();
    $scope.getCount.saveOrQuery('/admin/statCustomerCouponStatus.json', { customerId: $scope.obj.customerId });
    $scope.search = function () {

        $scope.otherFactory = new ListFactory('/admin/selectCustomerCouponVoList.json', 0, 10, $scope.obj);
        var patientPromise = $scope.otherFactory.nextPage();

        patientPromise.then(function (data) {
            console.log(data);
            var pageSize = 10;
            $(".pagination-point").pagination($scope.otherFactory.count, {

                items_per_page: pageSize,

                callback: function callback(index) {

                    $scope.otherFactory.clearAndSetIndex(index * pageSize);
                    $scope.otherFactory.nextPage();
                }
            });
        });
    };
    $scope.search();
    $scope.couponModal = false;

    $scope.showSendModal = function () {
        $scope.couponIdList = [];
        $scope.couponModal = true;
        $scope.searchList();
    };
    $scope.hideCouponModal = function () {
        $scope.couponModal = false;
        $scope.couponDetail = false;
        $scope.couponModify = false;
    };
    $scope.couponModify = false;
    $scope.showCouponModify = function (id, event) {
        $scope.customerCouponId = id;
        event.stopPropagation();

        $scope.couponModify = true;
        $scope.getCouponVoFactory = new ObjectFactory();
        $scope.getCouponVoFactory.saveOrQuery('/admin/getCustomerCouponVo.json', { customerCouponId: id });
    };

    $scope.modifycoupon = function () {
        $scope.useCouponFactory = new ObjectFactory();
        var usePromise = $scope.useCouponFactory.saveOrQuery('/admin/useCoupon.json', { customerCouponId: $scope.customerCouponId });
        usePromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice('核销成功');
            } else {
                Popup.notice(res.errmsg);
            }
            $scope.hideCouponModal();
            $scope.search();
        });
    };

    $scope.searchList = function () {

        $scope.couponListFactory = new ListFactory('/admin/selectCouponVoList.json', 0, 3, { status: 1, keyword: $scope.keyword });
        var couponPromise = $scope.couponListFactory.nextPage();

        couponPromise.then(function (data) {
            var pageSize = 3;
            $(".pagination-record").pagination($scope.couponListFactory.count, {

                items_per_page: pageSize,

                callback: function callback(index) {

                    $scope.couponListFactory.clearAndSetIndex(index * pageSize);
                    $scope.couponListFactory.nextPage();
                }
            });
        });
    };
}]);
