angular.module('bestvisionWeb').controller('patientListCtrl', ['$scope', '$stateParams', '$timeout', '$state', 'ObjectFactory', 'Popup', 'HttpFactory', function ($scope, $stateParams, $timeout, $state, ObjectFactory, Popup, HttpFactory) {
    $scope.historyModal = false;
    $scope.patientId = null;
    $scope.customerId = $stateParams.customerId;
    MiniVersion.IsMiniVersion(ObjectFactory).then(function (isMiniVersion) {
        $timeout(function () {
            $scope.miniVersion = isMiniVersion; //true为小版本
        });
    });
    $scope.addUser = {
        show: false,
        switch: function _switch(bool, info) {
            this.edit = false;
            this.show = bool;
        },
        editInfo: function editInfo(info) {
            if (!info) {
                this.edit = false;
                this.show = false;
                $scope.search(0, true);
                return;
            }
            this.edit = info;
            this.show = true;
        }
    };
    $scope.openHistory = function (id) {
        $scope.patientId = id;
        $scope.historyModal = true;
    };
    $scope.hideHistory = function () {
        $scope.patientId = null;
        $scope.historyModal = false;
    };
    $scope.search = function (index, loadPagin) {
        HttpFactory.list('/admin/getPatientVoList.json', {
            customerId: $scope.customerId,
            index: index,
            length: 9
        }).then(function (res) {
            $scope.patientList = res.list;
            loadPagin && HttpFactory.pagination("#Pagination", res, $scope.search);
        });
    };
    $scope.search(0, true);
    $scope.showPatientModal = function (patientId, patientIndex) {
        $scope.patientIndex = patientIndex;
        $scope.updateStudentInfo.params.patientId = patientId;
        $scope.updateStudentInfo.show = true;
    };
    $scope.updateStudentInfo = {
        show: false,
        params: {},
        callback: function callback(result) {
            $scope.patientList[$scope.patientIndex].customer.customerName = result.customerName;
            $scope.patientList[$scope.patientIndex].customer.linkMobile = result.linkMobile;
            $scope.patientList[$scope.patientIndex].patient.patientName = result.patientName;
            if (result.patientBirthday) {
                $scope.patientList[$scope.patientIndex].patient.patientBirthday = new Date(result.patientBirthday);
            }
            $scope.patientList[$scope.patientIndex].patient.patientGender = result.patientGender;
            $scope.patientList[$scope.patientIndex].patient.patientRemark = result.patientRemark;
            Popup.notice("修改患者信息成功!");
            $scope.patientIndex = null;
            $scope.updateStudentInfo.show = false;
        }
    };
}]);
