angular.module('bestvisionWeb').controller('selectOrderListCtrl', ['$scope', 'Popup', 'DateUtilFactory', '$stateParams', 'HttpFactory', '$state', 'ObjectFactory', 'ListFactory', '$http', function ($scope, Popup, DateUtilFactory, $stateParams, HttpFactory, $state, ObjectFactory, ListFactory, $http) {

    $scope.statusArr = [{ id: 0, name: '未发货' }, { id: 1, name: '待收货' }, { id: 2, name: '已收货' }];
    $scope.typeArr = [{ id: 1, name: '到店自提' }, { id: 2, name: '快递发货' }];

    $scope.obj = {};
    $scope.obj.keyword = $stateParams.keyword;

    $scope.obj.orderTypeArray = [50, 60];
    $scope.obj.orderStatus = null;
    $scope.search = function () {
        if ($scope.obj.startTime && $scope.rightTime) {
            $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
            $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);
        } else if ($scope.obj.startTime && !$scope.rightTime) {
            $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
            delete $scope.obj.endTime;
        } else if (!$scope.obj.startTime && $scope.rightTime) {
            $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);
            delete $scope.obj.startTime;
        } else {
            delete $scope.obj.startTime;
            delete $scope.obj.endTime;
        }
        if ($scope.obj.orderStatus !== 1) {
            delete $scope.obj.expressStatus;
            delete $scope.obj.refundStatus;
        }
        $scope.selectOrderListFactory = new ListFactory('/admin/selectOrderVoListByCorpId.json', 0, 10, $scope.obj);
        var searchPromise = $scope.selectOrderListFactory.nextPage();
        searchPromise.then(function (data) {
            var pageSize = 10;
            $("#Pagination").pagination($scope.selectOrderListFactory.count, {
                items_per_page: pageSize,
                callback: function callback(index) {
                    $scope.selectOrderListFactory.clearAndSetIndex(index * pageSize);
                    $scope.selectOrderListFactory.nextPage();
                }
            });
        });
    };
    $scope.search();

    $scope.clearKeyword = function () {
        $scope.obj.keyword = null;
        $scope.search();
    };

    $scope.searchOrder = function (status) {

        $scope.obj.orderStatus = status;
        $scope.obj.expressStatus = null;
        $scope.search();
    };
    $scope.searchExpress = function (status) {

        $scope.obj.expressStatus = status;
        $scope.search();
    };
    $scope.searchType = function (status) {
        $scope.obj.expressType = status;
        $scope.search();
    };
    $scope.setRefundStatus = function (refundStatus) {
        $scope.obj.refundStatus = refundStatus;
        $scope.search();
    };

    $scope.pickUp = function (id, idx) {

        Popup.confirm('确定提货么', function () {

            $scope.pickUpFactory = new ObjectFactory();
            var pickPromise = $scope.pickUpFactory.saveOrQuery('/admin/pickUpOrder.json', { orderId: id });
            pickPromise.then(function (res) {
                if (res.status == 0) {
                    Popup.notice('提货成功');

                    $scope.getOrderDetailFactory = new ObjectFactory();
                    var orderPromise = $scope.getOrderDetailFactory.saveOrQuery('/admin/getOrderVo.json', { orderId: id });
                    orderPromise.then(function (resp) {

                        $scope.selectOrderListFactory.items[idx].customerOrder.status = resp.result.object.customerOrder.status;

                        $scope.selectOrderListFactory.items[idx].orderExpress.expressStatus = resp.result.object.orderExpress.expressStatus;

                        $scope.selectOrderListFactory.items[idx].orderExpress.expressType = resp.result.object.orderExpress.expressType;
                    });
                } else {
                    Popup.notice(res.errmsg);
                }
            });
        }, function () {});
    };
    /* 支付时的状态 */
    $scope.paystatus = window.optionsObj.paystatus_options({});
    $scope.refund = function (order) {
        Popup.confirm('确定退款么', function () {
            HttpFactory.object('/admin/createRefundOrderLog.json', {
                customerId: order.customer.id,
                cashflowId: order.cashflow.id
            }).then(function (commit) {
                if (commit) {
                    var refundOrderLogId = commit.commitId;
                    HttpFactory.object('/admin/commitRefundOrderLog.json', {
                        refundOrderLogId: refundOrderLogId
                    }).then(function () {
                        $scope.paystatus.open({
                            type: "1", //1是退款,0是支付
                            payType: order.cashflow.payType,
                            fee: order.cashflow.totalPayment
                        });
                        loopFn.loopPayStatus({
                            ObjectFactory: ObjectFactory,
                            params: {
                                url: "getRefundOrderLog",
                                params: { refundOrderLogId: refundOrderLogId }
                            },
                            statusOption: {
                                status1: "refundStatus",
                                status2: "waitingRefundStatus"
                                // back: true,
                            },
                            successOption: {
                                moneyKey: "addMoney",
                                payTypeKey: "",
                                type: "",
                                voiceType: ""
                            }
                        }).then(function () {
                            Popup.notice('\u9000\u6B3E\u6210\u529F\uFF01');
                        }, function (errMsg) {
                            Popup.notice(errMsg ? errMsg : '\u9000\u6B3E\u5931\u8D25\uFF01');
                        }).finally(function () {
                            $scope.paystatus.close();
                            $scope.search();
                        });
                    });
                }
            });
        });
    };

    $scope.deliveryObj = {};
    $scope.expressCompany = [{ id: '', name: '请选择快递公司' }, { id: '1', name: '顺丰速运' }, { id: '14', name: '百世快递' }, { id: '2', name: '中通快递' }, { id: '3', name: '申通快递' }, { id: '4', name: '圆通速递' }, { id: '5', name: '韵达速递' }, { id: '6', name: '邮政快递包裹' }, { id: '7', name: 'EMS' }, { id: '8', name: '天天快递' }, { id: '9', name: '京东快递' }, { id: '10', name: '优速快递' }, { id: '11', name: '德邦快递' }, { id: '12', name: '宅急送' }, { id: '13', name: '其他' }];

    $scope.selectedId = '';

    $scope.selectCompany = function () {

        if ($scope.selectedId == 1) {
            $scope.deliveryObj.expressCompany = "顺丰速运";
            $scope.deliveryObj.expressCompanyId = "SF";
        } else if ($scope.selectedId == 2) {
            $scope.deliveryObj.expressCompany = "中通快递";
            $scope.deliveryObj.expressCompanyId = "ZTO";
        } else if ($scope.selectedId == 3) {
            $scope.deliveryObj.expressCompany = "申通快递";
            $scope.deliveryObj.expressCompanyId = "STO";
        } else if ($scope.selectedId == 4) {
            $scope.deliveryObj.expressCompany = "圆通速递";
            $scope.deliveryObj.expressCompanyId = "YTO";
        } else if ($scope.selectedId == 5) {
            $scope.deliveryObj.expressCompany = "韵达速递";
            $scope.deliveryObj.expressCompanyId = "YD";
        } else if ($scope.selectedId == 6) {
            $scope.deliveryObj.expressCompany = "邮政快递包裹";
            $scope.deliveryObj.expressCompanyId = "YZPY";
        } else if ($scope.selectedId == 7) {
            $scope.deliveryObj.expressCompany = "EMS";
            $scope.deliveryObj.expressCompanyId = "EMS";
        } else if ($scope.selectedId == 8) {
            $scope.deliveryObj.expressCompany = "天天快递";
            $scope.deliveryObj.expressCompanyId = "HHTT";
        } else if ($scope.selectedId == 9) {
            $scope.deliveryObj.expressCompany = "京东快递";
            $scope.deliveryObj.expressCompanyId = "JD";
        } else if ($scope.selectedId == 10) {
            $scope.deliveryObj.expressCompany = "优速快递";
            $scope.deliveryObj.expressCompanyId = "UC";
        } else if ($scope.selectedId == 11) {
            $scope.deliveryObj.expressCompany = "德邦快递";
            $scope.deliveryObj.expressCompanyId = "DBL";
        } else if ($scope.selectedId == 12) {
            $scope.deliveryObj.expressCompany = "宅急送";
            $scope.deliveryObj.expressCompanyId = "ZJS";
        } else if ($scope.selectedId == 13) {
            $scope.deliveryObj.expressCompany = "其它";
            $scope.deliveryObj.expressCompanyId = "OTHERS";
        } else if ($scope.selectedId == 14) {
            $scope.deliveryObj.expressCompany = "百世快递";
            $scope.deliveryObj.expressCompanyId = "HTKY";
        } else {
            $scope.deliveryObj.expressCompany = "";
            $scope.deliveryObj.expressCompanyId = "";
        }
    };

    $scope.showDelivery = function (id, idx) {
        $scope.deliveryModal = true;
        $scope.deliveryObj.orderId = id;
        $scope.deliveryObj.idx = idx;
    };
    $scope.deliveryGood = function () {

        if (!$scope.selectedId) {
            Popup.notice("请选择快递公司");
            return false;
        }

        if (!$scope.deliveryObj.expressCode) {
            Popup.notice("请输入快递单号");
            return false;
        }

        $scope.deliveryOrderFactory = new ObjectFactory();
        var pickPromise = $scope.deliveryOrderFactory.saveOrQuery('/admin/deliveryOrder.json', $scope.deliveryObj);
        pickPromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice('发货成功');

                $scope.getOrderDetailFactory = new ObjectFactory();
                var orderPromise = $scope.getOrderDetailFactory.saveOrQuery('/admin/getOrderVo.json', { orderId: $scope.deliveryObj.orderId });
                orderPromise.then(function (resp) {

                    $scope.selectOrderListFactory.items[$scope.deliveryObj.idx].customerOrder.status = resp.result.object.customerOrder.status;

                    $scope.selectOrderListFactory.items[$scope.deliveryObj.idx].orderExpress.expressStatus = resp.result.object.orderExpress.expressStatus;

                    $scope.selectOrderListFactory.items[$scope.deliveryObj.idx].orderExpress.expressType = resp.result.object.orderExpress.expressType;
                });
            } else {
                Popup.notice(res.errmsg);
            }
            $scope.deliveryModal = false;
        });
    };

    $scope.unActive = function (id) {

        $scope.unActiveFactory = new ObjectFactory();
        var promise = $scope.unActiveFactory.saveOrQuery('/admin/invalidSeckillProduct.json', { seckillProductId: id });
        promise.then(function (res) {
            if (res.status == 0) {
                Popup.notice('失效成功');
                $scope.search();
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };
}]);
