angular.module("bestvisionWeb").controller("sendPlatformCtrl", ["$scope", "Popup", "ObjectFactory", "ListFactory", "$state", function ($scope, Popup, ObjectFactory, ListFactory, $state) {
  $scope.selectList = function () {
    var pageSize = 10;
    $scope.selectOrderListFactory = new ListFactory("/admin/selectTaskTemplateBatchSendList.json", 0, pageSize);
    var promise = $scope.selectOrderListFactory.nextPage();
    promise.then(function (data) {
      $("#Pagination").pagination($scope.selectOrderListFactory.count, {
        items_per_page: pageSize,

        callback: function callback(index) {
          $scope.selectOrderListFactory.clearAndSetIndex(index * pageSize);
          $scope.selectOrderListFactory.nextPage();
        }
      });
    });
  };
  $scope.selectList();
  $scope.newAddGroup = function () {
    $state.go("groupSend");
  };
  $scope.lookDetails = function (taskTemplateBatchSendId) {
    $state.go("groupSendLook", {
      taskTemplateBatchSendId: taskTemplateBatchSendId
    });
  };
  $scope.cancelTask = function (taskTemplateBatchSendId, nowIndex) {
    Popup.confirm("确认取消发送？", function () {
      new ObjectFactory().saveOrQuery("/admin/cancelTemplateBatchSendTask.json", {
        taskTemplateBatchSendId: taskTemplateBatchSendId
      }).then(function (result) {
        if (result.status) {
          return Popup.notice(result.errmsg);
        }
        $scope.selectOrderListFactory.items[nowIndex] = result.object;
      });
    }, function () {});
  };
  $scope.lookCondition = function (taskTemplateBatchSendId) {
    $state.go("groupSend", {
      taskTemplateBatchSendId: taskTemplateBatchSendId
    });
  };
}]);
