angular.module("bestvisionWeb").controller("updateMemberCtrl", ["$scope", "$interval", "Popup", "$window", "CommonRequest", "$stateParams", "WechatConfig", "$state", "ObjectFactory", "HttpFactory", "$http", function ($scope, $interval, Popup, $window, CommonRequest, $stateParams, WechatConfig, $state, ObjectFactory, HttpFactory, $http) {
  $scope.customerId = $stateParams.customerId;

  // 会员标签
  $scope.memberArrayStatus = {
    show: false,
    addLabel: true,
    hideAll: true,
    fix: false,
    key: "tagName",
    type: "list",
    url: "/admin/selectTagList.json",
    params: {
      sortName: "id",
      sortType: "ASC"
    },
    fixList: [],
    callback: function callback() {}
  };
  $scope.common = {};
  $scope.customerFactory = new ObjectFactory();
  var getCustomerPromise = $scope.customerFactory.queryVo("/admin/getCustomerVo.json", { customerId: $scope.customerId });
  getCustomerPromise.then(function (res) {
    $scope.oldCustomerIdArr = res.result.vo.tagList.map(function (v) {
      return v.id;
    });
    $scope.memberArrayStatus.show = true;
    $scope.common.channel = res.result.vo.customer.channel;
    $scope.common.channelTagId = res.result.vo.customer.channelTagId;
    $scope.address = res.result.vo.address || {};
  });
  $scope.showCommon = function () {
    $scope.common.selectChannelModal = true;
  };

  $scope.saveCustomerInfo = function () {
    if (!$scope.customerFactory.vo.customer.customerName) {
      Popup.notice("请输入会员姓名", 2000, function () {});
      return false;
    }
    if ($scope.customerFactory.vo.customer.linkMobile) {
      if (!/^1[3|4|5|6|7|8|9]\d{9}$/.test($scope.customerFactory.vo.customer.linkMobile)) {
        Popup.notice("请输入正确的手机号", 2000, function () {});
        return false;
      }
    }
    var saveInfo = function saveInfo(addressId) {
      new ObjectFactory().saveOrQuery("/admin/updateCustomerTags.json", {
        customerId: $scope.customerId,
        tagIdArray: $scope.oldCustomerIdArr
      });

      $scope.trueName = $scope.customerFactory.vo.customer.customerName;
      var customer = {
        id: $scope.customerId,
        channel: $scope.common.channel,
        channelTagId: $scope.common.channelTagId,
        trueName: $scope.trueName,
        linkMobile: $scope.customerFactory.vo.customer.linkMobile
      };
      addressId && (customer.addressId = addressId);
      new ObjectFactory().saveOrQuery("/admin/saveCustomerInfo.json", customer).then(function (res) {
        if (res.status == 1) {
          Popup.notice(res.errmsg, 2000, function () {});
        } else {
          Popup.notice("保存成功", 2000, function () {});
          // history.back(-1);
        }
      });
    };
    CommonRequest.setAddress($scope.address, saveInfo);
  };
  $scope.connectWeixin = function () {
    $scope.connectWeixinFactory = new ObjectFactory();
    var promise = $scope.connectWeixinFactory.saveOrQuery("/admin/getBandingWechatQrcode.json", { customerId: $scope.customerId });
    promise.then(function (res) {
      $scope.imgSrc = WechatConfig.showqrcode(res.object);
      $scope.modifyAdmin = true;
      $scope.connectWechat = true;
    });
    $scope.mytimeout = $interval(function () {
      $scope.bandWechatFactory = new ObjectFactory();
      var promise = $scope.bandWechatFactory.saveOrQuery("/admin/isBandingWechat.json", { customerId: $scope.customerId });
      promise.then(function (res) {
        if (res.result.object) {
          $scope.hidePatient();
          $window.location.reload();
        }
      });
    }, 3000);
  };

  $scope.bandWechatFactory = new ObjectFactory();
  $scope.bandWechatFactory.saveOrQuery("/admin/isBandingWechat.json", {
    customerId: $scope.customerId
  });

  $scope.hidePatient = function () {
    $scope.modifyAdmin = false;
    $scope.connectWechat = false;
    $interval.cancel($scope.mytimeout);
  };
  $scope.$on("$destroy", function () {
    if (angular.isDefined($scope.timePromise)) {
      $interval.cancel($scope.mytimeout);
    }
  });
  $scope.cancelBind = function () {
    var customerId = $scope.customerId;
    Popup.confirm("确定取消绑定微信？", function () {
      new ObjectFactory().saveOrQuery("/admin/disBandingWechatByCustomerId.json", {
        customerId: customerId
      }).then(function (res) {
        if (res.status == 0) {
          Popup.notice("取消绑定微信成功");
          $window.location.reload();
        } else {
          Popup.notice(res.errmsg);
        }
      });
    }, function () {});
  };
}]);
"use strict";

