angular.module("bestvisionWeb").controller("addProductBivariateTableCtrl", ["$scope", "Popup", "maxStoreLength", "HttpFactory", "$timeout", "$stateParams", "$state", "ListFactory", "daochuFactory", "ObjectFactory", function ($scope, Popup, maxStoreLength, HttpFactory, $timeout, $stateParams, $state, ListFactory, daochuFactory, ObjectFactory) {
    $scope.obj = {};
    $scope.obj.storehouseId = $stateParams.storehouseId;
    $scope.obj.productId = $stateParams.productId;

    HttpFactory.object("/admin/getStorehouseVo.json", {
        id: $scope.obj.storehouseId
    }).then(function (res) {
        $scope.storeName = res.storehouse.name;
    });

    var bivariateTableList = [{ status: -1, name: "负" }, { status: 1, name: "正" }];
    $scope.getList = null;
    $scope.pageSize = 20;
    $scope.sign = {
        model1CompareToZero: null,
        model2CompareToZero: null
    };
    $scope.bivariateTable1 = {
        status: "",
        tablist: angular.copy(bivariateTableList),
        callback: function callback() {
            $scope.sign.model1CompareToZero = this.status;
            if ($scope.getList.result.object.product.modelType === 2 && ($scope.getList.result.object.product.model2Name === "球镜" || $scope.getList.result.object.product.model2Name === "柱镜")) {
                $scope.sign.model2CompareToZero = $scope.bivariateTable2.status;
            }
            $scope.getEr($scope.sign);
        }
    };
    $scope.bivariateTable2 = {
        status: "",
        tablist: angular.copy(bivariateTableList),
        callback: function callback() {
            $scope.sign.model2CompareToZero = this.status;
            if ($scope.getList.result.object.product.model1Name === "球镜" || $scope.getList.result.object.product.model1Name === "柱镜") {
                $scope.sign.model1CompareToZero = $scope.bivariateTable1.status;
            }
            $scope.getEr($scope.sign);
        }
    };

    $scope.choseShop = {
        btnStr: ["选择商品", "切换商品"],
        statusList: ["btn-primary", "report-nav_btn"],
        status: 0, //
        showComp: false,
        shopInfo: {
            brandId: "", //全部品牌的id
            keyword: "", //产品名称、拼音或条形码
            productType: 1, //，库存1，定制2
            categoryId: null, //左侧treeId
            productName: "",
            id: "",
            status: 0
        },
        callBack: function callBack() {
            this.showComp = true;
        },
        closeBack: function closeBack() {
            this.showComp = false;
            /* 如果选中了商品，则要将仓库状态改变 */
            if (this.shopInfo.id) {
                this.status = 1;
                return $scope.getEr();
            } else {
                this.status = 0;
            }
        }
    };
    $scope.storeInfo = {
        idName: "excuteDoctor",
        ajaxUrl: "/admin/selectStorehouseVoList.json",
        isshow: true,
        id: null,
        inputVal: "",
        inputPlaceHolder: "全部仓库",
        info: null,
        key: "storehouse",
        key2: "name",
        fn: function fn() {
            $scope.getEr();
        },
        callBack: function callBack() {
            $scope.getEr();
        },
        type: "List"
    };
    $scope.model = {
        model1Keyword: "",
        model2Keyword: "",
        skuCodeKeyword: ""
    };
    $scope.isShowCondition = false;
    $scope.getEr = function (vo) {
        if (!vo) {
            $scope.sign = {};
            $scope.bivariateTable1.status = '';
            $scope.bivariateTable2.status = '';
        }
        var obj = Object.assign({
            model1Keyword: $scope.model.model1Keyword,
            model2Keyword: $scope.model.model2Keyword,
            skuCodeKeyword: $scope.model.skuCodeKeyword //条形码
        }, $scope.obj, $scope.sign);
        $scope.getList = new ObjectFactory();
        $scope.getList.saveOrQuery("/admin/getStockCountForTwoDimensionalTable.json", obj).then(function (res) {
            $scope.isShowCondition = $scope.getList.result.object.product.modelType ? true : false;
        });
    };
    $scope.getEr();
    window.getStockSet(ObjectFactory).then(function (res) {
        $timeout(function () {
            $scope.direction = {
                0: {
                    xName: "model1Name",
                    yName: "model2Name"
                },
                1: {
                    xName: "model2Name",
                    yName: "model1Name"
                }
            }[res.modelShow];
        });
    });
    $scope.changeCount = function (item) {
        item.add = true;
        item.stockInSkuExistCount2 = Math.ceil(item.stockInSkuExistCount2);
        item.newCount = item.stockInSkuExistCount2;
        item.stockInSkuExistCounts = item.stockInSkuExistCount2 - item.stockInSkuExistCount;
    };

    $scope.saveInventory = function () {
        if (!$scope.obj.storehouseId) {
            Popup.notice("请选择要盘点的仓库");
            return false;
        }
        // console.log($scope.getList);
        var stringArr = [];
        $scope.getList.result.object.skuExistCountPlane.forEach(function (list) {
            list.forEach(function (v) {
                if (v && v.add) {
                    stringArr.push({
                        oldCount: v.stockInSkuExistCount,
                        productSkuId: v.productSkuId,
                        newCount: v.newCount
                    });
                }
            });
        });
        // console.log('stringArr', stringArr);
        if (!stringArr.length) {
            return Popup.notice("请输入盘点数量");
        }

        var productSkuExistCountPoListJson = JSON.stringify(stringArr);
        HttpFactory.object("/admin/createStockTakingByProductSku.json", {
            productSkuExistCountPoListJson: productSkuExistCountPoListJson,
            storehouseId: $scope.obj.storehouseId
        }).then(function () {
            Popup.notice("新建成功");
            $state.go("goods.materialCompanyInventory");
        });
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("addProductDeliveryCtrl", ["$scope", "Popup", "maxStoreLength", "$rootScope", "$timeout", "$state", "$stateParams", "ListFactory", "ObjectFactory", function ($scope, Popup, maxStoreLength, $rootScope, $timeout, $state, $stateParams, ListFactory, ObjectFactory) {
  $scope.obj = {};
  $scope.create = {};
  $scope.productKeyword = "请选择商品";
  $scope.create.outDate = new Date();
  $scope.create.outType = 1;
  $scope.create.productType = $stateParams.productType;
  $scope.obj.status = 0;
  $scope.obj.productType = $stateParams.productType;
  $scope.obj.withDetail = false;
  // sessionStorage.setItem('materialDeliveryType',$stateParams.productType);
  $scope.obj.storehouseId = $stateParams.storehouseId ? $stateParams.storehouseId : null;

  $scope.getBrandFactory = new ObjectFactory();
  $scope.getBrandFactory.saveOrQuery("/admin/getBrandListOfProduct.json");

  $scope.storehouseArr = [{ id: null, name: "请选择仓库" }];

  $scope.supplierWord = "请选择领用人";
  $scope.outType = [{ id: 1, name: "科室出库" }, { id: 2, name: "退货出库" }, { id: 3, name: "报损出库" }, { id: 99, name: "其它出库" }];

  $scope.getSupplierListFactory = new ListFactory("/admin/selectStorehouseVoList.json", 0, maxStoreLength, { status: 0 });
  var depotPromise = $scope.getSupplierListFactory.nextPage();

  depotPromise.then(function (res) {
    for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
      $scope.storehouseArr.push({
        id: $scope.getSupplierListFactory.items[i].storehouse.id,
        name: $scope.getSupplierListFactory.items[i].storehouse.name
      });
    }
  });

  $scope.stockInSkuList = [];
  $scope.totalprice = 0;
  $scope.outCount = 0;
  $scope.$watch("stockInSkuList", function (newValue, oldValue) {
    $scope.totalprice = 0;
    $scope.outCount = 0;
    newValue.forEach(function (item) {
      $scope.totalprice = $scope.totalprice + item.unLockExistSkuCount;
      $scope.outCount = $scope.outCount + item.outCount || 0;
    });
  }, true);
  $scope.searchProductWord = function (keyword, event) {
    if (event) {
      event.stopPropagation();
      return;
    }

    $scope.product = {};
    $scope.select = {};
    $scope.getProductListFactory = new ListFactory("/admin/getProductSkuInVoList.json", 0, 50, $scope.obj);
    var promise = $scope.getProductListFactory.nextPage();
    promise.then(function (res) {
      console.log(res);
    });
  };

  $scope.updateList = true;
  $scope.product = {};
  $scope.idx = -1;
  $scope.selectProductName = function (id, idx) {
    if (idx == $scope.select.idx) {
      return;
    }

    $scope.updateList = false;
    $scope.product.productSkuId = id;

    $scope.select.idx = idx;
    $scope.updateList = true;
  };

  $scope.showAddModal = function () {
    if ($scope.tab == 1) {
      if ($scope.obj.storehouseId == null) {
        Popup.notice("请选择仓库");
        return false;
      }
    }

    $scope.addProductModal = true;
    $scope.modelKeyword = null;

    $scope.productword = null;
    $scope.searchProductWord();
  };

  if ($scope.$state.current.name == "addDelivery") {
    $scope.tab = 1;
  } else {
    $scope.tab = 2;
    var getStoreHouseFactory = new ObjectFactory();
    var storePromise = getStoreHouseFactory.saveOrQuery("/admin/getStorehouseVo.json", { id: $scope.obj.storehouseId });
    storePromise.then(function (res) {
      $scope.storeName = res.result.object.storehouse.name;
    });
  }

  $scope.countDate = function (date, day) {
    var nowTime = new Date().getTime();
    var dayTime = day * 24 * 60 * 60 * 1000;
    var totalTime = nowTime + dayTime;

    if (totalTime > date) {
      return true;
    } else {
      return false;
    }
  };

  $scope.select = {};
  $scope.selectProduct = function () {
    if (!$scope.product.productSkuId) {
      Popup.notice("请选择商品");
      return false;
    }

    $scope.stockInSkuList.push({
      brandName: $scope.getProductListFactory.items[$scope.select.idx].brand.brandName,
      categoryName: $scope.getProductListFactory.items[$scope.select.idx].category.categoryName,
      productName: $scope.getProductListFactory.items[$scope.select.idx].product.productName,
      unitName: $scope.getProductListFactory.items[$scope.select.idx].productSku.unitName,
      factory: $scope.getProductListFactory.items[$scope.select.idx].product.factory,

      marketPrice: $scope.getProductListFactory.items[$scope.select.idx].productSku.marketPrice,
      skuPrice: "",
      skuTotalPrice: "",
      model1: $scope.getProductListFactory.items[$scope.select.idx].productSku.model1,
      model1Name: $scope.getProductListFactory.items[$scope.select.idx].product.model1Name,
      model2: $scope.getProductListFactory.items[$scope.select.idx].productSku.model2,
      model2Name: $scope.getProductListFactory.items[$scope.select.idx].product.model2Name,
      name: $scope.getProductListFactory.items[$scope.select.idx].storehouse.name,
      skuCode: $scope.getProductListFactory.items[$scope.select.idx].productSku.skuCode,
      warningQuantity: $scope.getProductListFactory.items[$scope.select.idx].productSku.warningQuantity,
      warningExpiresDays: $scope.getProductListFactory.items[$scope.select.idx].productSku.warningExpiresDays,
      outCount: null,
      productSkuId: $scope.product.productSkuId,
      unLockExistSkuCount: $scope.getProductListFactory.items[$scope.select.idx].unLockExistSkuCount
    });

    $scope.addProductModal = false;
  };
  $scope.showInfo = function (item) {
    // console.log(item);
  };
  $scope.showsupplierList = function (event) {
    event.stopPropagation();
    $scope.supplierKeyword = "";
    $scope.supplierList = true;
    $scope.searchSupplierList();
  };
  $scope.hideReceipt = function () {
    $scope.supplierList = false;
  };

  $scope.addDelivery = function () {
    var productSkuList = [];
    if ($scope.tab == 1) {
      if ($scope.obj.storehouseId == null) {
        Popup.notice("请选择仓库");
        return false;
      }
    }

    for (var i = 0; i < $scope.stockInSkuList.length; i++) {
      productSkuList[i] = {
        outCount: $scope.stockInSkuList[i].outCount,
        productSkuId: $scope.stockInSkuList[i].productSkuId
      };
    }

    $scope.create.storehouseId = $scope.obj.storehouseId;
    console.log($scope.stockInSkuList);

    $scope.create.productSkuListJson = JSON.stringify(productSkuList);

    $scope.addReceiptObjectFactory = new ObjectFactory();
    var promise = $scope.addReceiptObjectFactory.saveOrQuery("/admin/createStockOutByProductSku.json", $scope.create);
    promise.then(function (res) {
      if (res.status == 0) {
        Popup.notice("新建成功", 2000, function () {});

        if ($scope.tab == 1) {
          $state.go("materialDelivery");
        } else {
          $state.go("goods.materialCompanyDelivery");
        }
      } else {
        Popup.notice(res.errmsg, 2000, function () {});
      }
    });
  };
  $scope.deleteReceipt = function (index) {
    $scope.stockInSkuList.splice(index, 1);
  };
  $scope.searchSupplierList = function (keyword, event) {
    if (event) {
      event.stopPropagation();
    }
    $scope.getSupplierListFactory = new ListFactory("/admin/selectEmployeeByName.json", 0, 10, { keyword: keyword });
    $scope.getSupplierListFactory.nextPage();
    console.log($scope.getSupplierListFactory);
  };
  $scope.selectSupplier = function (id, name) {
    $scope.supplierWord = name;
    $scope.create.drawEmployeeId = id;
    $scope.supplierList = false;
  };

  $scope.clearSupplier = function () {
    $scope.supplierWord = "";
    $scope.create.drawEmployeeId = "";
  };

  $scope.hideProductModal = function () {
    $scope.addProductModal = false;
  };
  window.getStockSet(ObjectFactory).then(function (res) {
    $timeout(function () {
      $scope.enableStockDateChangeBool = !!res.enableStockDateChange;
    }, 50);
  });
}]);
"use strict";

angular.module("bestvisionWeb").controller("addProductInventoryCtrl", ["$scope", "Popup", "maxStoreLength", "HttpFactory", "$timeout", "$stateParams", "$state", "ListFactory", "daochuFactory", "PopoutClass", function ($scope, Popup, maxStoreLength, HttpFactory, $timeout, $stateParams, $state, ListFactory, daochuFactory, PopoutClass) {
  $scope.obj = {
    keyword: "",
    modelKeyword: ""
  };

  $scope.obj.status = 0;
  // $scope.obj.productType = 1;

  $scope.storehouseArr = [{ id: 0, name: "请选择要盘点的仓库" }];
  $scope.obj.storehouseId = $stateParams.storehouseId ? $stateParams.storehouseId : 0;
  $scope.obj.withDetail = false;
  $scope.obj.moreThanZero = false;
  $scope.obj.equalToZero = false;
  $scope.obj.lessThanZero = false;
  // $scope.obj.storehouseId = 0;
  HttpFactory.object("/admin/getCategoryTree2Level.json").then(function (res) {
    $scope.categoryList = res;
  });
  $scope.setCustomer = function (tab) {
    $scope.obj.productType = tab;
    if (tab) {
      $scope.obj.productType = tab;
    } else {
      delete $scope.obj.productType;
    }
    $scope.searchStock();
  };
  $scope.setStatus = function (status) {
    $scope.obj.status = status;
    $scope.searchStock();
  };
  $scope.chooseCategory = function (id, bool) {
    $scope.obj.categoryId = id;
    $scope.seletedCategory = id;
    $scope.seletedCategoryId = null;

    if (bool) {
      $scope.categoryAll = true;
    } else {
      $scope.categoryAll = false;
    }
    $scope.searchStock();
  };
  $scope.chooseCategoryId = function (id, event) {
    event.stopPropagation();
    $scope.seletedCategoryId = id;
    $scope.obj.categoryId = id;
    $scope.searchStock();
  };

  $scope.getSupplierListFactory = new ListFactory("/admin/selectStorehouseVoList.json", 0, maxStoreLength, { status: 0 });
  var depotPromise = $scope.getSupplierListFactory.nextPage();

  depotPromise.then(function (res) {
    for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
      $scope.storehouseArr.push({
        id: $scope.getSupplierListFactory.items[i].storehouse.id,
        name: $scope.getSupplierListFactory.items[i].storehouse.name
      });
    }
  });
  $scope.downloadIndex = 0;
  $scope.pageSize = 100;
  $scope.searchStock = function () {
    if ($scope.obj.storehouseId == null || $scope.obj.storehouseId == 0) {
      Popup.notice("请选择要盘点的仓库");
      return false;
    }
    $scope.downloadIndex = 0;

    $scope.getStockListFactory = new ListFactory("/admin/getProductSkuInVoList.json", 0, $scope.pageSize, $scope.obj);
    var promise = $scope.getStockListFactory.nextPage();
    promise.then(function (data) {
      for (var i = 0, len = $scope.getStockListFactory.items.length; i < len; i++) {
        $scope.getStockListFactory.items[i].newCount = null;
        for (var j = 0, jlen = $scope.stockTakingSkuListJson.length; j < jlen; j++) {
          if ($scope.getStockListFactory.items[i].productSku.id == $scope.stockTakingSkuListJson[j].productSkuId) {
            $scope.getStockListFactory.items[i].newCount = $scope.stockTakingSkuListJson[j].newCount;
          }
        }
      }
      $("#Pagination").pagination($scope.getStockListFactory.count, {
        items_per_page: $scope.pageSize,
        callback: function callback(index) {
          $scope.downloadIndex = index * $scope.pageSize;
          $scope.getStockListFactory.clearAndSetIndex(index * $scope.pageSize);
          var nextPromise = $scope.getStockListFactory.nextPage();
          nextPromise.then(function (resp) {
            $timeout(function () {
              for (var i = 0, len = $scope.getStockListFactory.items.length; i < len; i++) {
                $scope.getStockListFactory.items[i].newCount = null;
                for (var j = 0, jlen = $scope.stockTakingSkuListJson.length; j < jlen; j++) {
                  if ($scope.getStockListFactory.items[i].productSku.id == $scope.stockTakingSkuListJson[j].productSkuId) {
                    $scope.getStockListFactory.items[i].newCount = $scope.stockTakingSkuListJson[j].newCount;
                  }
                }
              }
            }, 200);
          });
        }
      });
    });
  };
  $scope.changeStore = function () {
    $scope.stockTakingSkuListJson = [];
    $scope.searchStock();
  };
  // $scope.searchStock();

  if ($scope.$state.current.name == "addInventory") {
    $scope.tab = 1;
  } else {
    $scope.tab = 2;
    HttpFactory.object("/admin/getStorehouseVo.json", {
      id: $scope.obj.storehouseId
    }).then(function (res) {
      $scope.storeName = res.storehouse.name;
    });
    $scope.changeStore();
  }

  $scope.stockTakingSkuListJson = [];

  $scope.addInventory = function (newCount, productSkuId, existCount) {
    if (newCount == null || newCount == undefined) {
      return false;
    }

    for (var i = 0; i < $scope.stockTakingSkuListJson.length; i++) {
      if ($scope.stockTakingSkuListJson[i].productSkuId == productSkuId) {
        $scope.stockTakingSkuListJson[i].newCount = newCount;
        return false;
      }
    }

    $scope.stockTakingSkuListJson.push({
      oldCount: existCount,
      productSkuId: productSkuId,
      newCount: newCount
    });

    console.log($scope.stockTakingSkuListJson);
  };
  $scope.saveInventory = function () {
    if ($scope.obj.storehouseId == null || $scope.obj.storehouseId == 0) {
      Popup.notice("请选择要盘点的仓库");
      return false;
    }

    var stringArr = [];
    for (var i = 0, len = $scope.stockTakingSkuListJson.length; i < len; i++) {
      for (var j = i + 1; j < len; j++) {
        if ($scope.stockTakingSkuListJson[i].productSkuId === $scope.stockTakingSkuListJson[j].productSkuId) {
          j = ++i;
        }
      }

      if ($scope.stockTakingSkuListJson[i].newCount < 0) {
        Popup.notice("数量请输入正整数");
        return false;
      }

      stringArr.push({
        oldCount: $scope.stockTakingSkuListJson[i].oldCount,
        productSkuId: $scope.stockTakingSkuListJson[i].productSkuId,
        newCount: $scope.stockTakingSkuListJson[i].newCount
      });
    }

    if (!stringArr.length) {
      Popup.notice("请输入盘点数量");
      return false;
    }

    var productSkuExistCountPoListJson = JSON.stringify(stringArr);
    HttpFactory.object("/admin/createStockTakingByProductSku.json", {
      productSkuExistCountPoListJson: productSkuExistCountPoListJson,
      storehouseId: $scope.obj.storehouseId
    }).then(function () {
      Popup.notice("新建成功");
      if ($scope.tab == 1) {
        $state.go("materialInventory");
      } else {
        $state.go("goods.materialCompanyInventory");
      }
    });
  };
  $scope.downloadModal = false;
  $scope.daochu = function () {
    var params = {
      storehouseId: $scope.obj.storehouseId,
      categoryId: $scope.obj.categoryId,
      brandId: $scope.obj.brandId,
      keyword: encodeURIComponent($scope.obj.keyword),
      modelKeyword: encodeURIComponent($scope.obj.modelKeyword),
      model1Keyword: "",
      model2Keyword: "",
      productType: $scope.obj.productType,
      moreThanZero: $scope.obj.moreThanZero,
      lessThanZero: $scope.obj.lessThanZero,
      equalToZero: $scope.obj.equalToZero,
      index: $scope.downloadIndex,
      length: $scope.pageSize
    };
    daochuFactory.EXPOSE("downloadProductSkuVoListForStockTaking", params);
    $scope.downloadModal = false;
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("addPurchasementCtrl", ["$scope", "Popup", "maxStoreLength", "$rootScope", "$timeout", "$state", "ListFactory", "ObjectFactory", function ($scope, Popup, maxStoreLength, $rootScope, $timeout, $state, ListFactory, ObjectFactory) {
  $scope.obj = {};
  $scope.purchase = {};
  $scope.tab = {};
  $scope.storehouseArr = [{ id: null, name: "全部仓库" }];
  $scope.obj.storehouseId = null;
  $scope.purchase.purchaseDate = new Date();

  $scope.purchase.purchaseType = 1;
  $scope.purchase.otherPrice = 0;
  $scope.obj.status = 0;
  $scope.getSupplierListFactory = new ListFactory("/admin/selectStorehouseVoList.json", 0, maxStoreLength, { status: 0 });
  var depotPromise = $scope.getSupplierListFactory.nextPage();

  depotPromise.then(function (res) {
    for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
      $scope.storehouseArr.push({
        id: $scope.getSupplierListFactory.items[i].storehouse.id,
        name: $scope.getSupplierListFactory.items[i].storehouse.name
      });
    }
  });

  $scope.searchCategoryObjectFactory = new ObjectFactory();
  $scope.searchCategoryObjectFactory.saveOrQuery("/admin/getCategoryTree2Level.json");

  $scope.getBrandFactory = new ObjectFactory();
  $scope.getBrandFactory.saveOrQuery("/admin/getBrandListOfProduct.json");

  $scope.chooseCategory = function (id, bool) {
    $scope.obj.categoryId = id;
    $scope.seletedCategory = id;
    $scope.seletedCategoryId = null;

    if (bool) {
      $scope.categoryAll = true;
    } else {
      $scope.categoryAll = false;
    }
    $scope.searchStock();
  };
  $scope.chooseCategoryId = function (id, event) {
    event.stopPropagation();
    $scope.seletedCategoryId = id;
    $scope.obj.categoryId = id;
    $scope.searchStock();
  };
  $scope.pageSize = 20;
  $scope.searchStock = function () {
    $scope.getStockListFactory = new ListFactory("/admin/getProductSkuExistCountVoList.json", 0, $scope.pageSize, $scope.obj);
    var promise = $scope.getStockListFactory.nextPage();
    promise.then(function (data) {
      for (var i = 0; i < $scope.getStockListFactory.items.length; i++) {
        if ($scope.getStockListFactory.items[i].mainSupplier) {
          $scope.getStockListFactory.items[i].supplierId = $scope.getStockListFactory.items[i].mainSupplier.id;
        } else {
          $scope.getStockListFactory.items[i].supplierId = null;
        }
      }

      $("#Pagination").pagination($scope.getStockListFactory.count, {
        items_per_page: $scope.pageSize,
        callback: function callback(index) {
          $scope.getStockListFactory.clearAndSetIndex(index * $scope.pageSize);
          var nextPromise = $scope.getStockListFactory.nextPage();
          nextPromise.then(function (resp) {
            $timeout(function () {
              for (var i = 0, len = $scope.getStockListFactory.items.length; i < len; i++) {
                if ($scope.getStockListFactory.items[i].mainSupplier) {
                  $scope.getStockListFactory.items[i].supplierId = $scope.getStockListFactory.items[i].mainSupplier.id;
                } else {
                  $scope.getStockListFactory.items[i].supplierId = null;
                }
                $scope.getStockListFactory.items[i].skuCount = null;
                for (var j = 0, jlen = $scope.stockTakingSkuListJson.length; j < jlen; j++) {
                  if ($scope.getStockListFactory.items[i].productSku.id == $scope.stockTakingSkuListJson[j].skuId) {
                    $scope.getStockListFactory.items[i].skuCount = $scope.stockTakingSkuListJson[j].skuCount;
                    $scope.getStockListFactory.items[i].mainSupplier.supplierName = $scope.stockTakingSkuListJson[j].supplierWord;
                  }
                }
              }
            }, 200);
          });
        }
      });
    });
  };

  $scope.searchStock();

  $scope.changeStore = function () {
    $scope.stockTakingSkuListJson = [];
    $scope.searchStock();
  };
  $scope.stockTakingSkuListJson = [];

  $scope.addInventory = function (skuCount, skuId, supplierId, supplierWord, idx) {
    if (skuCount === null || skuCount === undefined) {
      $scope.getStockListFactory.items[idx].skuCount = null;

      var arr = [];
      for (var i = 0; i < $scope.stockTakingSkuListJson.length; i++) {
        if ($scope.stockTakingSkuListJson[i].skuId !== skuId) {
          arr.push({
            skuCount: $scope.stockTakingSkuListJson[i].skuCount,
            skuId: $scope.stockTakingSkuListJson[i].skuId,
            supplierId: $scope.stockTakingSkuListJson[i].supplierId,
            supplierWord: $scope.stockTakingSkuListJson[i].supplierWord
          });
        }
      }

      $scope.stockTakingSkuListJson = arr;

      return false;
    }

    if (skuCount <= 0) {
      Popup.notice("采购数量必须大于0");
      $scope.getStockListFactory.items[idx].skuCount = null;

      var arr = [];
      for (var i = 0; i < $scope.stockTakingSkuListJson.length; i++) {
        if ($scope.stockTakingSkuListJson[i].skuId !== skuId) {
          arr.push({
            skuCount: $scope.stockTakingSkuListJson[i].skuCount,
            skuId: $scope.stockTakingSkuListJson[i].skuId,
            supplierId: $scope.stockTakingSkuListJson[i].supplierId,
            supplierWord: $scope.stockTakingSkuListJson[i].supplierWord
          });
        }
      }

      $scope.stockTakingSkuListJson = arr;
    } else {
      for (var i = 0; i < $scope.stockTakingSkuListJson.length; i++) {
        if ($scope.stockTakingSkuListJson[i].skuId == skuId) {
          $scope.stockTakingSkuListJson[i].skuCount = skuCount;
          $scope.stockTakingSkuListJson[i].supplierId = supplierId;
          $scope.stockTakingSkuListJson[i].supplierWord = supplierWord;
          return;
        }
      }
      $scope.stockTakingSkuListJson.push({
        skuCount: skuCount,
        skuId: skuId,
        supplierId: supplierId,
        supplierWord: supplierWord
      });
    }
  };

  $scope.totalCountPrice = function () {
    var total = 0;

    if ($scope.viewFactory && $scope.viewFactory.result.list) {
      for (var i = 0; i < $scope.viewFactory.result.list.length; i++) {
        total = total + $scope.viewFactory.result.list[i].stockPurchaseSku.skuCount * $scope.viewFactory.result.list[i].productSku.costPrice;
      }
      return total;
    }
  };
  $scope.totalCount = function () {
    var total = 0;

    if ($scope.viewFactory && $scope.viewFactory.result.list) {
      for (var i = 0; i < $scope.viewFactory.result.list.length; i++) {
        total = total + $scope.viewFactory.result.list[i].stockPurchaseSku.skuCount;
      }
      return total;
    }
  };

  $scope.autoChange = function (count, id, idx) {
    if (count === null || count === undefined) {
      var arr = [];
      for (var i = 0; i < $scope.stockTakingSkuListJson.length; i++) {
        if ($scope.stockTakingSkuListJson[i].skuId !== id) {
          arr.push({
            skuCount: $scope.stockTakingSkuListJson[i].skuCount,
            skuId: $scope.stockTakingSkuListJson[i].skuId,
            supplierId: $scope.stockTakingSkuListJson[i].supplierId
          });
        }
      }

      for (var i = 0; i < $scope.getStockListFactory.items.length; i++) {
        if ($scope.getStockListFactory.items[i].productSku.id == id) {
          $scope.getStockListFactory.items[i].skuCount = null;
        }
      }

      $scope.stockTakingSkuListJson = arr;
      return false;
    }

    if (count <= 0) {
      Popup.notice("数量必须大于0");

      $scope.viewFactory.result.list[idx].stockPurchaseSku.skuCount = null;
      var arr = [];
      for (var i = 0; i < $scope.stockTakingSkuListJson.length; i++) {
        if ($scope.stockTakingSkuListJson[i].skuId !== id) {
          arr.push({
            skuCount: $scope.stockTakingSkuListJson[i].skuCount,
            skuId: $scope.stockTakingSkuListJson[i].skuId,
            supplierId: $scope.stockTakingSkuListJson[i].supplierId
          });
        }
      }

      $scope.stockTakingSkuListJson = arr;
      for (var i = 0; i < $scope.getStockListFactory.items.length; i++) {
        if ($scope.getStockListFactory.items[i].productSku.id == id) {
          $scope.getStockListFactory.items[i].skuCount = null;
        }
      }
    } else {
      for (var i = 0; i < $scope.getStockListFactory.items.length; i++) {
        if ($scope.getStockListFactory.items[i].productSku.id == id) {
          $scope.getStockListFactory.items[i].skuCount = count;
        }
      }
      for (var i = 0; i < $scope.stockTakingSkuListJson.length; i++) {
        if ($scope.stockTakingSkuListJson[i].skuId == id) {
          $scope.stockTakingSkuListJson[i].skuCount = count;
        }
      }
    }
  };

  $scope.preview = function () {
    var stringArr = [];
    for (var i = 0, len = $scope.stockTakingSkuListJson.length; i < len; i++) {
      for (var j = i + 1; j < len; j++) {
        if ($scope.stockTakingSkuListJson[i].skuId === $scope.stockTakingSkuListJson[j].skuId) {
          j = ++i;
        }
      }

      if ($scope.stockTakingSkuListJson[i].skuCount < 0) {
        Popup.notice("数量请输入正整数");
        return false;
      }

      stringArr.push({
        skuCount: $scope.stockTakingSkuListJson[i].skuCount,
        skuId: $scope.stockTakingSkuListJson[i].skuId,
        supplierId: $scope.stockTakingSkuListJson[i].supplierId
      });
    }

    if (!stringArr.length) {
      Popup.notice("请输入采购数量");
      return false;
    }

    $scope.viewFactory = new ObjectFactory();
    var viewPromise = $scope.viewFactory.saveOrQuery("/admin/viewStockPurchaseSkuVoList.json", { stockPurchaseSkuListJson: JSON.stringify(stringArr) });
    viewPromise.then(function (res) {
      if (res.status == 0) {
        $scope.addProductModal = true;
      } else {
        Popup.notice(res.errmsg);
      }
    });
  };

  $scope.hideProductModal = function () {
    $scope.addProductModal = false;
  };

  $scope.setTab = function () {
    $scope.setAllModal = true;
    $scope.tab.count = null;
  };
  $scope.setCountTab = function () {
    $scope.setModal = true;

    $scope.tab.purchaseCount = null;
  };

  $scope.setProduct = function (count) {
    if (count <= 0) {
      Popup.notice("数量必须大于0");
      return false;
    }

    for (var i = 0; i < $scope.stockTakingSkuListJson.length; i++) {
      $scope.stockTakingSkuListJson[i].skuCount = count;
    }
    for (var i = 0; i < $scope.viewFactory.result.list.length; i++) {
      $scope.viewFactory.result.list[i].stockPurchaseSku.skuCount = count;
    }

    for (var j = 0; j < $scope.getStockListFactory.items.length; j++) {
      for (var k = 0; k < $scope.stockTakingSkuListJson.length; k++) {
        if ($scope.getStockListFactory.items[j].productSku.id == $scope.stockTakingSkuListJson[k].skuId) {
          console.log("ok");
          $scope.getStockListFactory.items[j].skuCount = count;
        }
      }
    }

    $scope.setModal = false;
  };

  $scope.setAllProduct = function (count) {
    if (count <= 0) {
      Popup.notice("数量必须大于0");
      return false;
    }

    var len = $scope.stockTakingSkuListJson.length;

    for (var i = 0; i < $scope.getStockListFactory.items.length; i++) {
      $scope.getStockListFactory.items[i].skuCount = count;

      if (len) {
        for (var k = 0; k < len; k++) {
          if ($scope.getStockListFactory.items[i].productSku.id == $scope.stockTakingSkuListJson[k].skuId) {
            $scope.stockTakingSkuListJson[k].skuCount = count;
          } else {
            $scope.stockTakingSkuListJson.push({
              skuCount: count,
              skuId: $scope.getStockListFactory.items[i].productSku.id,
              supplierId: $scope.getStockListFactory.items[i].mainSupplier.id
            });
          }
        }
      } else {
        $scope.stockTakingSkuListJson.push({
          skuCount: count,
          skuId: $scope.getStockListFactory.items[i].productSku.id,
          supplierId: $scope.getStockListFactory.items[i].mainSupplier.id
        });
      }
    }

    $scope.setAllModal = false;
  };

  $scope.makePurchase = function () {
    var len = $scope.stockTakingSkuListJson.length;
    if (!len) {
      Popup.notice("请输入采购数量");
      return false;
    }
    var arr = [];
    for (var j = 0; j < len; j++) {
      if ($scope.stockTakingSkuListJson[j].supplierId == null || $scope.stockTakingSkuListJson[j].supplierId == "") {
        Popup.notice("请选择供应商");
        return false;
      }

      if (arr.indexOf($scope.stockTakingSkuListJson[j].supplierId) === -1) {
        arr.push($scope.stockTakingSkuListJson[j].supplierId);
      }
    }
    $scope.len = len;
    $scope.orderLength = arr.length;
    $scope.dialog = { open: true };
  };
  $scope.addPurchase = function () {
    var stringArr = [];
    for (var i = 0, len = $scope.stockTakingSkuListJson.length; i < len; i++) {
      for (var j = i + 1; j < len; j++) {
        if ($scope.stockTakingSkuListJson[i].skuId === $scope.stockTakingSkuListJson[j].skuId) {
          j = ++i;
        }
      }

      if ($scope.stockTakingSkuListJson[i].skuCount < 0) {
        Popup.notice("数量请输入正整数");
        return false;
      }

      stringArr.push({
        skuCount: $scope.stockTakingSkuListJson[i].skuCount,
        skuId: $scope.stockTakingSkuListJson[i].skuId,
        supplierId: $scope.stockTakingSkuListJson[i].supplierId
      });
    }

    if (!stringArr.length) {
      Popup.notice("请输入采购数量");
      return false;
    }
    $scope.dialog = { open: false };
    $scope.purchase.stockPurchaseSkuListJson = JSON.stringify(stringArr);
    $scope.saveInventoryObjectFactory = new ObjectFactory();
    var promiseSave = $scope.saveInventoryObjectFactory.saveOrQuery("/admin/createStockPurchaseAndSkuList.json", $scope.purchase);
    promiseSave.then(function (res) {
      if (res.status == 0) {
        Popup.notice("新建成功", 2000, function () {});
        $state.go("purchase.materialPurchase");
      } else {
        Popup.notice(res.errmsg, 2000, function () {});
      }
    });
  };
}]);
