      factory: $scope.getProductListFactory.items[$scope.select.idx].product.factory,
      marketPrice: $scope.getProductListFactory.items[$scope.select.idx].productSku.marketPrice,
      skuPrice: "",
      skuTotalPrice: "",

      model1: $scope.getProductListFactory.items[$scope.select.idx].productSku.model1,
      model1Name: $scope.getProductListFactory.items[$scope.select.idx].product.model1Name,
      model2Name: $scope.getProductListFactory.items[$scope.select.idx].product.model2Name,
      model2: $scope.getProductListFactory.items[$scope.select.idx].productSku.model2,

      skuCode: $scope.getProductListFactory.items[$scope.select.idx].productSku.skuCode,
      warningQuantity: $scope.getProductListFactory.items[$scope.select.idx].productSku.warningQuantity,
