angular.module('bestvisionWeb').controller('adminBillCtrl', ['$scope', 'daochuFactory', 'Popup', '$rootScope', '$timeout', 'DateUtilFactory', "StorageFactory", '$state', 'ListFactory', 'ObjectFactory', 'reportMaterialProvider', function ($scope, daochuFactory, Popup, $rootScope, $timeout, DateUtilFactory, StorageFactory, $state, ListFactory, ObjectFactory, reportMaterialProvider) {
    $scope.obj = {};
    $scope.rightTime = new Date();
    $scope.obj.startTime = new Date();
    // var store = JSON.parse(StorageFactory.getItem('am_materialPurchase'));
    // $scope.obj = store ? store : {};
    $scope.resultObj = {
        lookdMsg: ''
    };
    $scope.msgObj = {
        page: 0
    };
    $scope.index = 0;
    $scope.getSaveTime = function () {
        var chooseTime = JSON.parse(window.sessionStorage.getItem('chooseTime'));
        console.log(chooseTime);
        if (chooseTime && chooseTime.startTime) {
            $scope.obj.startTime = new Date(chooseTime.startTime);
        }
        if (chooseTime && chooseTime.endTime) {
            $scope.rightTime = new Date(chooseTime.endTime);
        }
    };
    $scope.getSaveTime();
    $scope.$watch('obj.supplierId', function (newValue, oldValue) {
        $scope.searchStock();
    });
    $scope.searchStock = function () {
        var pageSize = 10;
        var cTime = {};
        if ($scope.obj.startTime && $scope.rightTime) {
            $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
            $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);
            cTime.startTime = $scope.obj.startTime;
            cTime.endTime = $scope.rightTime;
        } else if ($scope.obj.startTime && !$scope.rightTime) {
            $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
            delete $scope.obj.endTime;
            cTime.startTime = $scope.obj.startTime;
            delete cTime.endTime;
        } else if (!$scope.obj.startTime && $scope.rightTime) {
            $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);
            delete $scope.obj.startTime;
            cTime.endTime = $scope.rightTime;
            delete cTime.startTime;
        } else {
            delete $scope.obj.startTime;
            delete $scope.obj.endTime;
            delete cTime.startTime;
            delete cTime.endTime;
        }
        window.sessionStorage.setItem('chooseTime', JSON.stringify(cTime));
        StorageFactory.setItem('am_materialPurchase', JSON.stringify($scope.obj));
        $scope.getBillListFactory = new ListFactory('/admin/selectSettlementBySupplier.json', 0, pageSize, $scope.obj);
        var promise = $scope.getBillListFactory.nextPage();
        promise.then(function (res) {
            $scope.resultObj.lookdMsg = res;
            $("#Pagination").pagination($scope.getBillListFactory.count, {
                items_per_page: pageSize,
                callback: function callback(index) {
                    StorageFactory.setItem('am_materialPurchase', JSON.stringify($scope.obj));
                    $scope.index = index * pageSize;
                    $scope.getBillListFactory.clearAndSetIndex(index * pageSize);
                    $scope.getBillListFactory.nextPage();
                }
            });
        });
    };
    $scope.toSearchStock = function () {
        $scope.rightTime = new Date();
        $scope.searchStock();
    };
    var authStr = daochuFactory.getAuthStr();
    $scope.daochu = function () {
        if (!$scope.obj.supplierId) {
            $scope.obj.supplierId = "";
        }
        window.location.href = API_HOST + "/admin/downloadSettlementBySupplier.htm?supplierId=" + $scope.obj.supplierId + "&startTimeLong=" + $scope.obj.startTime.getTime() + "&endTimeLong=" + $scope.obj.endTime.getTime() + authStr;
    };
    $scope.printList = function (id) {
        // $scope.getCashflowObjectFactory = new ObjectFactory();
        // var promise = $scope.getCashflowObjectFactory.saveOrQuery(
        //     "/admin/getStockTransferVo.json",
        //     { id: id, withDetail: true }
        // );
        // promise.then(function (res) {
        $timeout(function () {
            $("#ele3").jqprint({
                debug: false,
                importCSS: true,
                printContainer: true,
                operaSupport: false
            });
        }, 1000);
        // });
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("adminBillDetialCtrl", ["$scope", "$stateParams", "Popup", "$rootScope", "$timeout", "DateUtilFactory", "StorageFactory", "$state", "ListFactory", "ObjectFactory", "daochuFactory", "HttpFactory", function ($scope, $stateParams, Popup, $rootScope, $timeout, DateUtilFactory, StorageFactory, $state, ListFactory, ObjectFactory, daochuFactory, HttpFactory) {
  $scope.resultObj = {
    lookdMsg: ""
  };
  $scope.jieZhangStatus = "";
  $scope.paramsObj = {
    supplierId: parseInt($stateParams.supplierId),
    settlementType: "",
    keyword: "",
    verifySettlement: "",
    allSettlement: ""
  };
  $scope.msgObj = {
    dialogShow: false,
    jieSuanDialogShow: false,
    addFeeDialogShow: false,
    dialogTitle: "",
    stockSettlementId: "",
    jieSuanObj: {
      waitMoney: "",
      payMoney: "",
      jieSuanRemark: ""
    }
  };
  $scope.feeParamsObj = {
    supplierId: parseInt($stateParams.supplierId),
    settlementType: "3",
    totalPrice: "",
    remark: ""
  };
  $scope.index = 0;
  $scope.rightTime = null;
  $scope.supplierName = "";

  // 新增费用
  $scope.sureAddFee = function () {
    // $scope.feeParamsObj.settlementType
    console.log($scope.feeParamsObj, "-----------------");

    if (!$scope.feeParamsObj.totalPrice) {
      return Popup.notice("请填写金额！");
    }
    var settlementType = {
      3: 'createStockSettlementForAdd',
      4: 'createStockSettlementForSub'
    }[$scope.feeParamsObj.settlementType];
    HttpFactory.object("/admin/" + settlementType + ".json", $scope.feeParamsObj).then(function (res) {
      Popup.notice("新增成功");
      $scope.feeParamsObj.totalPrice = "";
      $scope.closeDialog();
      $scope.getOneBill();
    });
    return;
    if (parseFloat($scope.feeParamsObj.totalPrice)) {
      $scope.jieSuanFactory = new ObjectFactory();
      var jieSuanFactoryPromise = $scope.jieSuanFactory.saveOrQuery("/admin/createStockSettlementFromTranferOrBack.json", $scope.feeParamsObj);
      jieSuanFactoryPromise.then(function (res) {
        $scope.feeParamsObj.settlementType = $scope.feeParamsObj.settlementType + "";
        $scope.feeParamsObj.totalPrice = "";
        if (res.status == 1) {
          Popup.notice("新增失败" + res.errmsg, 2000, function () {});
        } else {
          Popup.notice("新增成功", 2000, function () {});
        }
        $scope.closeDialog();
        $scope.getOneBill();
      });
    } else {
      $scope.feeParamsObj.settlementType = $scope.feeParamsObj.settlementType + "";
      $scope.feeParamsObj.totalPrice = "";
      Popup.notice("内容为数字且不能为空或0", 2000, function () {});
      return;
    }
  };
  $scope.expose = function () {
    daochuFactory.EXPOSE("downloadSettlementDetail", {
      supplierId: $scope.feeParamsObj.supplierId,
      settlementType: $scope.paramsObj.settlementType,
      keyword: encodeURIComponent($scope.paramsObj.keyword),
      startTimeLong: +$scope.paramsObj.startTime,
      endTimeLong: +$scope.paramsObj.endTime,
      verifySettlement: $scope.paramsObj.verifySettlement,
      allSettlement: $scope.paramsObj.allSettlement
    });
  };
  $scope.getGongYingShangName = function () {
    $scope.getGongYingShangNameFactory = new ObjectFactory();
    var getGongYingShangNameFactoryPromise = $scope.getGongYingShangNameFactory.saveOrQuery("/admin/getSupplier.json", { id: $scope.feeParamsObj.supplierId });
    getGongYingShangNameFactoryPromise.then(function (res) {
      $scope.supplierName = res.result.object.supplierName;
    });
  }();
  // 过滤单据
  $scope.getBillType = function (n) {
    return {
      1: "采购入库",
      2: "采购退货",
      3: "加账",
      4: "减账"
    }[n];
  };
  // 过滤结算类型
  $scope.getStatus = function (m, n) {
    return {
      0: function _() {
        return ["待对账", "#5cb85c"];
      },
      1: function _() {
        return {
          0: ["待结算", "#DE6262"],
          1: ["部分结算", "#DE6262"],
          2: ["已结算", "#aeafb1"]
        }[n];
      }
    }[m]();
  };
  // 获取列表数据
  $scope.getSaveTime = function () {
    var chooseTime = JSON.parse(window.sessionStorage.getItem("chooseTime"));
    console.log(chooseTime);
    if (chooseTime && chooseTime.startTime) {
      $scope.paramsObj.startTime = new Date(chooseTime.startTime);
    }
    if (chooseTime.endTime) {
      $scope.rightTime = new Date(chooseTime.endTime);
    }
    // console.log($scope.paramsObj.startTime);
    // console.log($scope.rightTim);
  };
  $scope.getSaveTime();
  $scope.getOneBill = function () {
    var pageSize = 10;
    var cTime = {};
    if ($scope.paramsObj.startTime && $scope.rightTime) {
      $scope.paramsObj.startTime = DateUtilFactory.origin($scope.paramsObj.startTime);
      $scope.paramsObj.endTime = DateUtilFactory.plus($scope.rightTime);
      cTime.startTime = $scope.paramsObj.startTime;
      cTime.endTime = $scope.rightTime;
    } else if ($scope.paramsObj.startTime && !$scope.rightTime) {
      $scope.paramsObj.startTime = DateUtilFactory.origin($scope.paramsObj.startTime);
      delete $scope.paramsObj.endTime;
      cTime.startTime = $scope.paramsObj.startTime;
      delete cTime.endTime;
    } else if (!$scope.paramsObj.startTime && $scope.rightTime) {
      $scope.paramsObj.endTime = DateUtilFactory.plus($scope.rightTime);
      delete $scope.paramsObj.startTime;
      cTime.endTime = $scope.rightTime;
      delete cTime.startTime;
    } else {
      delete $scope.paramsObj.startTime;
      delete $scope.paramsObj.endTime;
      delete cTime.startTime;
      delete cTime.endTime;
    }
    window.sessionStorage.setItem("chooseTime", JSON.stringify(cTime));
    $scope.getBillListFactory = new ListFactory("/admin/selectStockSettlementVoList.json", 0, pageSize, $scope.paramsObj);
    var promise = $scope.getBillListFactory.nextPage();
    promise.then(function (res) {
      // console.log(res)
      // console.log('------------------------------');
      $scope.resultObj.lookdMsg = res;
      $("#Pagination").pagination($scope.getBillListFactory.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.index = index * pageSize;
          $scope.getBillListFactory.clearAndSetIndex(index * pageSize);
          $scope.getBillListFactory.nextPage();
        }
      });
    });
  };
  $scope.getOneBill();
  $scope.targerJieSuanStatus = function () {
    switch ($scope.jieZhangStatus) {
      case "0":
        $scope.paramsObj.verifySettlement = 0;
        $scope.paramsObj.allSettlement = 0;
        break;
      case "1":
        $scope.paramsObj.verifySettlement = 1;
        $scope.paramsObj.allSettlement = 0;
        break;
      case "2":
        $scope.paramsObj.verifySettlement = 1;
        $scope.paramsObj.allSettlement = 1;
        break;
      case "3":
        $scope.paramsObj.verifySettlement = 1;
        $scope.paramsObj.allSettlement = 2;
        break;
      default:
        $scope.paramsObj.verifySettlement = "";
        $scope.paramsObj.allSettlement = "";
        break;
    }
    $scope.getOneBill();

    // let map = {
    //     0: {
    //         verifySettlement: 0,
    //         allSettlement: 0,
    //     },
    //     1: {
    //         verifySettlement: 1,
    //         allSettlement: 0
    //     },
    //     2: {
    //         verifySettlement: 1,
    //         allSettlement: 1
    //     },
    //     3: {
    //         verifySettlement: 1,
    //         allSettlement: 2
    //     }
    // }
    // const object = map[$scope.jieZhangStatus];
    // if (object) {
    //     for (let i in object) {
    //         $scope.paramsObj[i] = object[i]
    //     }
    // } else {
    //     $scope.paramsObj.verifySettlement = ''
    //     $scope.paramsObj.allSettlement = ''
    // }
    // $scope.getOneBill()
  };
  // 对账
  $scope.openSureDialog = function (p) {
    $scope.msgObj.stockSettlementId = p;
    Popup.confirm("确认对账？", function () {
      $scope.duiZhangFactory = new ObjectFactory();
      var duiZhangFactoryPromise = $scope.duiZhangFactory.saveOrQuery("/admin/verifySettlement.json", { stockSettlementId: $scope.msgObj.stockSettlementId });
      duiZhangFactoryPromise.then(function (res) {
        if (res.status == 0) {
          Popup.notice("对账成功");
          $scope.getOneBill();
          // $state.go("purchaseModify", { purchaseId: res.result.object.id })
        } else {
          Popup.notice(res.errmsg, 2000, function () {});
        }
      });
    }, function () {});
  };
  // 结算
  $scope.openJieSuanDialog = function (p, q) {
    $scope.settlementType = q;
    $scope.msgObj.jieSuanDialogShow = true;
    console.log(p);
    $scope.msgObj.stockSettlementId = p;
    var jieSuanFactory = new ObjectFactory();
    var jieSuanFactoryPromise = jieSuanFactory.saveOrQuery("/admin/getUnPaymentOfStockSettlement.json", { stockSettlementId: $scope.msgObj.stockSettlementId });
    jieSuanFactoryPromise.then(function (res) {
      $scope.msgObj.jieSuanObj.waitMoney = res.result.object;
      $scope.msgObj.jieSuanObj.payMoney = res.result.object;
    });
  };
  // 验证
  $scope.yanZeng = function (p, q, r, s) {
    if (parseFloat(p)) {
      if (s) {
        $scope[q][r][s] = parseFloat(p).toFixed(2);
      } else {
        $scope[q][r] = parseFloat(p).toFixed(2);
      }
    } else {
      if (s) {
        $scope[q][r][s] = "";
      } else {
        $scope[q][r] = "";
      }
      Popup.notice("内容为数字且不能为空或0", 2000, function () {});
      return;
    }
  };
  // 确认结算
  $scope.sureJieSuan = function () {
    if ($scope.settlementType == 2 || $scope.settlementType == 4) {
      if (parseFloat($scope.msgObj.jieSuanObj.payMoney)) {
        $scope.msgObj.jieSuanObj.payMoney = parseFloat($scope.msgObj.jieSuanObj.payMoney).toFixed(2);
        var jieSuanSureFactory = new ObjectFactory();
        var jieSuanSureFactoryPromise = jieSuanSureFactory.saveOrQuery("/admin/completeSupplierSettlementBack.json", {
          stockSettlementId: $scope.msgObj.stockSettlementId,
          payment: $scope.msgObj.jieSuanObj.payMoney,
          remark: $scope.msgObj.jieSuanObj.jieSuanRemark
        });
        jieSuanSureFactoryPromise.then(function (res) {
          if (res.status == 1) {
            Popup.notice("结算失败" + res.errmsg, 2000, function () {});
          } else {
            Popup.notice("结算成功", 2000, function () {});
          }
          $scope.closeDialog();
          $scope.getOneBill();
        });
      } else {
        $scope.msgObj.jieSuanObj.payMoney = "";
        Popup.notice("内容为数字且不能为空或0", 2000, function () {});
        return;
      }
    } else {
      if (parseFloat($scope.msgObj.jieSuanObj.payMoney)) {
        $scope.msgObj.jieSuanObj.payMoney = parseFloat($scope.msgObj.jieSuanObj.payMoney).toFixed(2);
        var jieSuanSure2Factory = new ObjectFactory();
        var jieSuanSure2FactoryPromise = jieSuanSure2Factory.saveOrQuery("/admin/completeSupplierSettlement.json", {
          stockSettlementId: $scope.msgObj.stockSettlementId,
          payment: $scope.msgObj.jieSuanObj.payMoney,
          remark: $scope.msgObj.jieSuanObj.jieSuanRemark
        });
        jieSuanSure2FactoryPromise.then(function (res) {
          if (res.status == 1) {
            Popup.notice("结算失败" + res.errmsg, 2000, function () {});
          } else {
            Popup.notice("结算成功", 2000, function () {});
          }
          $scope.closeDialog();
          $scope.getOneBill();
        });
      } else {
        $scope.msgObj.jieSuanObj.payMoney = "";
        Popup.notice("内容为数字且不能为空或0", 2000, function () {});
        return;
      }
    }
  };

  // 关闭弹窗
  $scope.closeDialog = function () {
    $scope.msgObj.stockSettlementId = "";
    $scope.msgObj.jieSuanObj.payMoney = "";
    $scope.msgObj.jieSuanObj.jieSuanRemark = "";
    $scope.msgObj.jieSuanObj.waitMoney = "";
    $scope.msgObj.dialogShow = false;
    $scope.msgObj.jieSuanDialogShow = false;
    $scope.msgObj.addFeeDialogShow = false;
    $scope.feeParamsObj.remark = "";
    $scope.feeParamsObj.totalPrice = "";
  };
}]);
'use strict';

angular.module('bestvisionWeb').controller('adminBillOneDetialCtrl', ['$scope', '$stateParams', 'Popup', '$rootScope', '$timeout', 'DateUtilFactory', "StorageFactory", '$state', 'ListFactory', 'ObjectFactory', function ($scope, $stateParams, Popup, $rootScope, $timeout, DateUtilFactory, StorageFactory, $state, ListFactory, ObjectFactory) {
    $scope.supplierId = parseInt($stateParams.supplierId);
    $scope.paramsObj = {
        stockSettlementId: parseInt($stateParams.stockSettlementId)
    };
    $scope.resultMsg = {};
    $scope.ruKuCount = 0;
    $scope.chuKuCount = 0;
    $scope.flag = null;
    $scope.jieSuanflag = null;
    $scope.duiZhangflag = null;
    // 获取数据
    $scope.getDetailList = function (p) {
        $scope.getDetailListFactory = new ObjectFactory();
        var getDetailListFactoryPromise = $scope.getDetailListFactory.saveOrQuery('/admin/getStockSettlementVoDetail.json', $scope.paramsObj);
        getDetailListFactoryPromise.then(function (res) {
            $scope.resultMsg = res.result.object;
            if ($scope.resultMsg.stockPurchaseInVo) {
                for (var i = 0; i < $scope.resultMsg.stockPurchaseInVo.skuList.length; i++) {
                    var inSkuCount = 0;
                    $scope.resultMsg.stockPurchaseInVo.skuList[i].stockPurchaseInSkuList.forEach(function (stockPurchase) {
                        $scope.ruKuCount += stockPurchase.inSkuCount;
                        inSkuCount += stockPurchase.inSkuCount;
                    });
                    $scope.resultMsg.stockPurchaseInVo.skuList[i].inSkuCount = inSkuCount;
                }
            }
            if ($scope.resultMsg.stockPurchaseOutVo) {
                // let outCount = 0
                for (var _i = 0; _i < $scope.resultMsg.stockPurchaseOutVo.skuList.length; _i++) {
                    $scope.resultMsg.stockPurchaseInVo.skuList[_i].stockPurchaseOutSkuList.forEach(function (stockPurchase) {
                        $scope.chuKuCount += stockPurchase.outCount;
                        // outCount += stockPurchase.outCount
                    });
                    // $scope.resultMsg.stockPurchaseInVo.skuList[i].outCount = outCount
                }
            }
            $scope.flag = $scope.resultMsg.stockSettlement.settlementType;
            $scope.jieSuanflag = $scope.resultMsg.stockSettlement.allSettlement;
            $scope.duiZhangflag = $scope.resultMsg.stockSettlement.verifySettlement;
        });
    };
    $scope.getDetailList();
}]);
'use strict';

angular.module('bestvisionWeb').controller('deliveryDeleteCtrl', ['$scope', 'Popup', '$stateParams', '$rootScope', '$state', 'ListFactory', 'ObjectFactory', function ($scope, Popup, $stateParams, $rootScope, $state, ListFactory, ObjectFactory) {
    $scope.stockOutId = $stateParams.stockOutId;
    $scope.obj = {};
    $scope.stockInSkuList = [];
    $scope.totalprice = 0;
    $scope.totalExistCount = 0;
    if ($scope.$state.current.name == "deliveryDetail") {
        $scope.tab = 1;
    } else {
        $scope.tab = 2;
    }
    $scope.getStockObjectFactory = new ObjectFactory();
    var promise = $scope.getStockObjectFactory.saveOrQuery('/admin/getStockOutVo.json', { id: $scope.stockOutId });
    promise.then(function (res) {
        console.log(res);
        $scope.obj = res.object;
        var arr = res.object.skuList;
        for (var i = 0; i < arr.length; i++) {

            if (arr[i].stockOutSku.outCount) {
                $scope.totalprice += arr[i].stockOutSku.outCount;
            }
            if (arr[i].unLockExistSkuCount) {
                $scope.totalExistCount += arr[i].unLockExistSkuCount;
            }
        };
    });
    $scope.disable = function () {
        console.log('0000');
        $scope.disableFactory = new ObjectFactory();
        var promise = $scope.disableFactory.saveOrQuery('/admin/cancelStockOutForPurchaseOut.json', { stockOutId: $scope.stockOutId });
        promise.then(function (res) {
            console.log(res);
            if (res.status == 0) {
                Popup.notice('已作废', 2000, function () {});
                $state.go('goods.materialCompanyDelivery');
            } else {
                Popup.notice(res.errmsg, 2000, function () {});
            };
        });
    };
}]);
"use strict";

