angular.module('bestvisionWeb').controller('materialInventoryCtrl', ['$scope', 'Popup', 'maxStoreLength', '$timeout', 'CommonTabClass', 'PopoutClass', "StorageFactory", '$state', 'ListFactory', 'ObjectFactory', function ($scope, Popup, maxStoreLength, $timeout, CommonTabClass, PopoutClass, StorageFactory, $state, ListFactory, ObjectFactory) {
    $scope.showMoreFun = new PopoutClass();
    $scope.setShowMoreFun = function (show, event) {
        event && event.stopPropagation();
        $scope.showMoreFun.setShow(show);
    };
    $scope.jump = function (event) {
        $scope.setShowMoreFun(false, event);
        $state.go('goods.addProductInventory', { storehouseId: $scope.obj.storehouseId });
    };
    $scope.bivariateTable = new PopoutClass();
    $scope.openBivariate = function () {
        $scope.bivariateTable.setShow(true, function () {
            $scope.bivariateTable.obj = {
                storehouseId: $scope.obj.storehouseId
            };
        });
    };
    $scope.storehouseArr = [{ id: null, name: '全部仓库' }];
    $scope.materialReceiptTab = angular.copy(CommonTabClass.materialReceiptTab);
    $scope.materialReceiptTab.pop();
    $scope.checkedTab = {
        status: null,
        tablist: $scope.materialReceiptTab,
        callback: function callback() {
            $scope.obj.checked = this.status;
            $scope.searchStock();
        }
    };
    var store = JSON.parse(StorageFactory.getItem('materialInventory'));
    $scope.obj = store ? store : {};
    $scope.obj.storehouseId = $scope.obj.storehouseId ? $scope.obj.storehouseId : null;
    $scope.obj.byProduct = StorageFactory.getItem('materialInventoryTab') ? StorageFactory.getItem('materialInventoryTab') : 1;
    $scope.getSupplierListFactory = new ListFactory('/admin/selectStorehouseVoList.json', 0, maxStoreLength, { status: 0 });
    var depotPromise = $scope.getSupplierListFactory.nextPage();

    depotPromise.then(function (res) {
        for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
            $scope.storehouseArr.push({
                id: $scope.getSupplierListFactory.items[i].storehouse.id,
                name: $scope.getSupplierListFactory.items[i].storehouse.name
            });
        }
    });

    $scope.companyFactory = new ObjectFactory();
    $scope.companyFactory.saveOrQuery('/admin/getCorpInfo.json');

    $scope.printListProduct = function (id) {
        $scope.getStockTakingListObjectFactory = new ObjectFactory();
        var productPromise = $scope.getStockTakingListObjectFactory.saveOrQuery('/admin/getStockTakingProductVoList.json', { stockTakingId: id });
        productPromise.then(function (resp) {

            $scope.getProductObjectFactory = new ObjectFactory();
            var promise = $scope.getProductObjectFactory.saveOrQuery('/admin/getStockTakingVo.json', { id: id, withDetail: true });
            promise.then(function (res) {

                $timeout(function () {
                    $('#ele2').jqprint({
                        debug: false,
                        importCSS: true,
                        printContainer: true,
                        operaSupport: false
                    });
                }, 1000);
            });
        });
    };

    $scope.printList = function (id) {
        $scope.getCashflowObjectFactory = new ObjectFactory();
        var promise = $scope.getCashflowObjectFactory.saveOrQuery('/admin/getStockTakingVo.json', { id: id, withDetail: true });
        promise.then(function (res) {

            $timeout(function () {
                $('#ele3').jqprint({
                    debug: false,
                    importCSS: true,
                    printContainer: true,
                    operaSupport: false
                });
            }, 1000);
        });
    };

    $scope.changeStore = function () {
        $scope.obj.page = 0;
        $scope.searchStock();
    };
    $scope.pageSize = 10;
    $scope.searchStock = function () {

        var pageStart = $scope.obj.page ? $scope.obj.page * $scope.pageSize : 0;

        StorageFactory.setItem('materialInventory', JSON.stringify($scope.obj));
        $scope.getStockListFactory = new ListFactory('/admin/getStockTakingVoList.json', pageStart, $scope.pageSize, { storehouseId: $scope.obj.storehouseId, byProduct: $scope.obj.byProduct, checked: $scope.obj.checked });
        var promise = $scope.getStockListFactory.nextPage();
        promise.then(function (data) {
            $("#Pagination").pagination($scope.getStockListFactory.count, {
                items_per_page: $scope.pageSize,
                current_page: $scope.obj.page,
                callback: function callback(index) {
                    $scope.obj.page = index;
                    StorageFactory.setItem('materialInventory', JSON.stringify($scope.obj));
                    $scope.getStockListFactory.clearAndSetIndex(index * $scope.pageSize);
                    $scope.getStockListFactory.nextPage();
                }
            });
        });
    };

    $scope.setCustomer = function (tab) {
        StorageFactory.setItem('materialInventoryTab', tab);
        $scope.obj.byProduct = tab;
        $scope.changeStore();
    };
    if ($scope.$state.current.name == "materialInventory") {

        $scope.tab = 1;
        $scope.searchStock();
    } else {
        var adminOk = new ObjectFactory();
        var promiseAdmin = adminOk.saveOrQuery('/admin/isAdminRoleStateOK.json', { state: $scope.$state.current.name });
        promiseAdmin.then(function (data) {

            if (!data.object) {
                $state.go('404');
            }
        });
        $scope.tab = 2;
    }

    $scope.deleteStock = function (id) {

        Popup.confirm("确认删除么", function () {

            $scope.deleteStockObjectFactory = new ObjectFactory();
            var promise = $scope.deleteStockObjectFactory.saveOrQuery('/admin/deleteStockTaking.json', { id: id });
            promise.then(function (res) {
                if (res.status == 0) {
                    Popup.notice('删除成功', 2000, function () {});
                    $scope.changeStore();
                } else {
                    Popup.notice(res.errmsg, 2000, function () {});
                };
            });
        }, function () {});
    };
}]);
