angular.module('bestvisionWeb').controller('materialOutportRecordCtrl', ['$scope', '$location', '$stateParams', 'QiniuFactory', '$timeout', 'Popup', '$rootScope', '$state', 'ListFactory', 'ObjectFactory', function ($scope, $location, $stateParams, QiniuFactory, $timeout, Popup, $rootScope, $state, ListFactory, ObjectFactory) {
    $scope.storehouseId = $stateParams.storehouseId;

    $scope.getStoreNameFactory = new ObjectFactory();
    $scope.getStoreNameFactory.saveOrQuery("/admin/getStorehouseVo.json", { id: $scope.storehouseId });
    if ($scope.$state.current.name == "materialOutportRecord") {

        $scope.tab = 1;
    } else {

        $scope.tab = 2;
    }

    $scope.searchSupplierList = function () {
        $scope.getStockListFactory = new ListFactory('/admin/getStockOutVoList.json', 0, 10, { outType: 10, storehouseId: $scope.storehouseId, productType: 1 });
        var promise = $scope.getStockListFactory.nextPage();

        promise.then(function (data) {

            var pageSize = 10;
            $(".pagination-account").pagination($scope.getStockListFactory.count, {
                items_per_page: pageSize,
                callback: function callback(index) {
                    $scope.getStockListFactory.clearAndSetIndex(index * pageSize);
                    $scope.getStockListFactory.nextPage();
                }
            });
        });
    };
    $scope.searchSupplierList();

    $scope.deleteStock = function (id) {
        $scope.deleteObjectFactory = new ObjectFactory();
        var deletepromise = $scope.deleteObjectFactory.saveOrQuery('/admin/deleteStockOut.json', { id: id });
        deletepromise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg, 2000, function () {});
            } else {
                Popup.notice('删除成功', 2000, function () {});
                $scope.searchSupplierList();
            }
        });
    };
}]);
