angular.module("bestvisionWeb").controller("purchaseModifyCtrl", ["$scope", "Popup", "$stateParams", "$rootScope", "$state", "ListFactory", "ObjectFactory", function ($scope, Popup, $stateParams, $rootScope, $state, ListFactory, ObjectFactory) {
  $scope.getLinkCodeFactory = new ObjectFactory();
  $scope.getLinkCodeFactory.saveOrQuery("/admin/getChildrenLinkAndCode.json", { state: "goods" });
  $scope.isCheck = function (str) {
    if ($scope.getLinkCodeFactory.result.object && $scope.getLinkCodeFactory.result.object.childrenCode.indexOf(str) > -1) {
      return true;
    }
    return false;
  };
  $scope.computePrice = function (skuCount, price, totalPrice, idx) {
    if (skuCount == null || skuCount == undefined) {
      Popup.notice("请输入采购数量", 3000, function () {});
      return;
    }

    if (skuCount > 0) {
      if (!/^[1-9]\d*$/.test(skuCount)) {
        Popup.notice("采购数量必须为正整数", 3000, function () {});
        return;
      }
    } else {
      Popup.notice("采购数量必须大于0", 3000, function () {});
      return;
    }

    var computeTotal = true;
    if (totalPrice) {
      computeTotal = false;
    }
    var computePriceFactory = new ObjectFactory();
    var pricePromise = computePriceFactory.saveOrQuery("/admin/computePrice.json", {
      count: skuCount,
      price: price,
      totalPrice: totalPrice,
      computeTotal: computeTotal
    });
    pricePromise.then(function (res) {
      $scope.InventoryArr[idx].stockPurchaseSku.skuPrice = res.result.object.price;
      $scope.InventoryArr[idx].stockPurchaseSku.skuCount = res.result.object.count;
      $scope.InventoryArr[idx].stockPurchaseSku.skuTotalPrice = res.result.object.totalPrice;
    });
  };
  $scope.obj = {};
  $scope.purchase = {};
  $scope.purchase.stockPurchaseId = $stateParams.purchaseId;
  $scope.InventoryArr = [];
  $scope.getStockTakingObjectFactory = new ObjectFactory();
  $scope.supplier = {};
  var promise = $scope.getStockTakingObjectFactory.saveOrQuery("/admin/getStockPurchaseVo.json", { stockPurchaseId: $scope.purchase.stockPurchaseId });
  promise.then(function (res) {
    $scope.purchase.purchaseDate = new Date(res.object.stockPurchase.purchaseDate);
    $scope.purchase.remark = res.object.stockPurchase.remark;
    $scope.purchase.purchaser = res.object.stockPurchase.purchaser;
    $scope.purchase.otherPrice = res.object.stockPurchase.otherPrice;
    $scope.supplier = {
      supplierName: res.object.supplier.supplierName,
      id: res.object.supplier.id
    };
    $scope.InventoryArr = res.object.skuList;
  });

  $scope.showMore = function (id, e) {
    e.stopPropagation();
    $scope.selectedId = id;
  };

  $scope.deleteReceipt = function (id, index) {
    $scope.deletePurchaseObjectFactory = new ObjectFactory();
    var deletepromise = $scope.deletePurchaseObjectFactory.saveOrQuery("/admin/checkDeleteStockPurchaseSku.json", { stockPurchaseSkuId: id });

    deletepromise.then(function (res) {
      if (res.status == 0) {
        $scope.InventoryArr.splice(index, 1);
      } else {
        Popup.notice(res.errmsg, 2000, function () {});
      }
    });
  };

  $scope.totalCountPrice = function () {
    var total = 0;
    if ($scope.InventoryArr.length) {
      for (var i = 0; i < $scope.InventoryArr.length; i++) {
        total = total + $scope.InventoryArr[i].stockPurchaseSku.skuTotalPrice;
      }
      return total;
    }
  };
  $scope.totalCount = function () {
    var total = 0;
    if ($scope.InventoryArr.length) {
      for (var i = 0; i < $scope.InventoryArr.length; i++) {
        total = total + $scope.InventoryArr[i].stockPurchaseSku.skuCount;
      }
      return total;
    }
  };

  $scope.getModelValue = function (id, outIndex, innerIndex, e, val) {
    if (e) {
      e.stopPropagation();
    }

    $scope.outindex = outIndex;
    $scope.innerindex = innerIndex;
    $scope.modelValueArr = [];
    $scope.modelValeObjectFactory = new ObjectFactory();
    var valuePromise = $scope.modelValeObjectFactory.saveOrQuery("/admin/selectModelValueList.json", { modelNameId: id, keyword: val });
    valuePromise.then(function (res) {
      $scope.modelValueArr = res.result.list;
    });
  };

  $scope.hideReceipt = function () {
    $scope.outindex = null;
    $scope.selectedId = null;
  };
  $scope.selectModelName = function (val) {
    $scope.InventoryArr[$scope.outindex].modelList[$scope.innerindex].modelValue = val;
    $scope.modelValueArr = [];
  };

  var skuListJson = [];

  $scope.saveInventory = function () {
    if (!$scope.supplier.id) {
      return Popup.notice('请选择供应商!');
    }
    var stockTakingSkuListJson = [];

    for (var i = 0, len = $scope.InventoryArr.length; i < len; i++) {
      stockTakingSkuListJson[i] = {
        id: $scope.InventoryArr[i].stockPurchaseSku.id,
        skuId: $scope.InventoryArr[i].productSku.id,
        supplierId: $scope.InventoryArr[i].supplier.id,
        skuCount: $scope.InventoryArr[i].stockPurchaseSku.skuCount || 0,
        skuTotalPrice: $scope.InventoryArr[i].stockPurchaseSku.skuTotalPrice || 0,
        remark: $scope.InventoryArr[i].stockPurchaseSku.remark,
        modelList: $scope.InventoryArr[i].modelList,
        customerInfo: $scope.InventoryArr[i].stockPurchaseSku.customerInfo
      };
    }
    $scope.purchase.stockPurchaseSkuListJson = JSON.stringify(stockTakingSkuListJson);
    $scope.saveInventoryObjectFactory = new ObjectFactory();
    $scope.purchase.supplierId = $scope.supplier.id;
    var promise = $scope.saveInventoryObjectFactory.saveOrQuery("/admin/updateStockPurchaseAndSkuList.json", $scope.purchase);
    promise.then(function (res) {
      if (res.status == 0) {
        Popup.notice("修改成功", 2000, function () {});
        $state.go("purchase.materialPurchase");
      } else {
        Popup.notice(res.errmsg, 2000, function () {});
      }
    });
  };
  $scope.checkSupplier = function () {
    if (!$scope.supplier.id) {
      return Popup.notice('请选择供应商!');
    }
    Popup.confirm("确认审核么", function () {
      var stockTakingSkuListJson = [];

      for (var i = 0, len = $scope.InventoryArr.length; i < len; i++) {
        stockTakingSkuListJson[i] = {
          id: $scope.InventoryArr[i].stockPurchaseSku.id,
          skuId: $scope.InventoryArr[i].productSku.id,
          supplierId: $scope.InventoryArr[i].supplier.id,
          skuCount: $scope.InventoryArr[i].stockPurchaseSku.skuCount,
          skuTotalPrice: $scope.InventoryArr[i].stockPurchaseSku.skuTotalPrice,
          remark: $scope.InventoryArr[i].stockPurchaseSku.remark,
          modelList: $scope.InventoryArr[i].modelList,
          customerInfo: $scope.InventoryArr[i].stockPurchaseSku.customerInfo
        };
      }
      $scope.purchase.stockPurchaseSkuListJson = JSON.stringify(stockTakingSkuListJson);

      $scope.purchase.supplierId = $scope.supplier.id;
      $scope.saveInventoryObjectFactory = new ObjectFactory();
      var promise = $scope.saveInventoryObjectFactory.saveOrQuery("/admin/updateStockPurchaseAndSkuList.json", $scope.purchase);
      promise.then(function (res) {
        if (res.status == 0) {
          $scope.checkSupplierObjectFactory = new ObjectFactory();
          var savepromise = $scope.checkSupplierObjectFactory.saveOrQuery("/admin/commitStockPurchase.json", { stockPurchaseId: $scope.purchase.stockPurchaseId });
          savepromise.then(function (res) {
            if (res.status == 0) {
              Popup.notice("审核成功", 2000, function () {});
              $state.go("purchase.materialPurchase");
            } else {
              Popup.notice(res.errmsg, 2000, function () {});
            }
          });
        } else {
          Popup.notice(res.errmsg, 2000, function () {});
        }
      });
    }, function () {});
  };
  $scope.addPurchaseModify = function () {};
}]);
'use strict';

angular.module('bestvisionWeb').controller('purchaseRecieptCtrl', ['$scope', 'Popup', 'maxStoreLength', '$stateParams', 'BindUdi', '$state', 'ListFactory', 'ObjectFactory', function ($scope, Popup, maxStoreLength, $stateParams, BindUdi, $state, ListFactory, ObjectFactory) {
    $scope.bindUdi = new BindUdi({
        skuCountKey: 'inSkuCount'
    });
    $scope.getLinkCodeFactory = new ObjectFactory();
    $scope.getLinkCodeFactory.saveOrQuery("/admin/getChildrenLinkAndCode.json", { state: "goods" });

    $scope.isCheck = function (str) {
        if ($scope.getLinkCodeFactory.result.object && $scope.getLinkCodeFactory.result.object.childrenCode.indexOf(str) > -1) {
            return true;
        }
        return false;
    };
    $scope.obj = {};
    $scope.purchase = {};
    $scope.purchase.stockPurchaseId = $stateParams.purchaseId;

    $scope.purchase.storehouseId = null;
    $scope.purchase.stockInDate = new Date();
    $scope.storehouseArr = [{ id: null, name: '请选择仓库' }];

    $scope.showMore = function (id, e) {
        e.stopPropagation();
        $scope.selectedId = id;
    };
    $scope.hideReceipt = function (id) {
        $scope.selectedId = null;
    };

    var getPurchaseInfo = function getPurchaseInfo() {
        $scope.getStockTakingObjectFactory = new ObjectFactory();
        var promise = $scope.getStockTakingObjectFactory.saveOrQuery('/admin/getStockPurchaseVoWithExistSkuCount.json', { stockPurchaseId: $scope.purchase.stockPurchaseId });
        promise.then(function (res) {
            var list = [];
            // $scope.bindUdi.list = res.object.skuList;
            var yearNow = new Date().getFullYear() + 3;
            res.object.skuList.forEach(function (arrSku) {
                list.push({
                    id: arrSku.product.id,
                    productName: arrSku.product.productName,
                    productCode: arrSku.product.productCode,
                    productType: arrSku.product.productType,
                    modelType: arrSku.product.modelType,
                    modelList: arrSku.modelList,
                    factory: arrSku.product.factory,
                    factoryLicense: arrSku.product.factoryLicense, //生产许可证号
                    model1: arrSku.productSku.model1,
                    model1Name: arrSku.product.model1Name,
                    model2: arrSku.productSku.model2,
                    model2Name: arrSku.product.model2Name,
                    skuCode: arrSku.productSku.skuCode,
                    unitName: arrSku.productSku.unitName,
                    skuCount: arrSku.stockPurchaseSku.skuCount,
                    existSkuCount: arrSku.existSkuCount,
                    skuPrice: arrSku.stockPurchaseSku.skuPrice,
                    marketPrice: arrSku.productSku.marketPrice,
                    costPrice: arrSku.productSku.costPrice,
                    batchNo: "",
                    uniqueCode: "",
                    skuId: arrSku.productSku.id,
                    productionDate: new Date(arrSku.product.gmtCreate),
                    expiresDate: new Date(yearNow, 11, 31),
                    brandName: arrSku.brand.brandName,
                    categoryName: arrSku.category.categoryName,
                    remark: arrSku.stockPurchaseSku.remark,
                    customerName: arrSku.stockPurchaseSku.customerInfo && arrSku.stockPurchaseSku.customerInfo.customerName,
                    requestSkuMergeRemark: arrSku.requestSkuMergeRemark,
                    stockPurchaseSkuId: arrSku.stockPurchaseSku.id,
                    inSkuCount: arrSku.stockPurchaseSku.skuCount - arrSku.existSkuCount,
                    skuTotalPrice: arrSku.stockPurchaseSku.skuTotalPrice,
                    rowSpan: 1,
                    refundCount: arrSku.medicalProduct && arrSku.medicalProduct.refundCount
                });
            });
            $scope.bindUdi.list = list;
        });
    };

    getPurchaseInfo();

    $scope.inventoryList = [];
    $scope.getInventoryInfo = function () {
        $scope.getInventoryInfoObjectFactory = new ObjectFactory();
        $scope.getInventoryInfoObjectFactory.saveOrQuery('/admin/selectStockPurchaseInVoList.json', { stockPurchaseId: $scope.purchase.stockPurchaseId }).then(function (res) {
            var inventoryList = [];
            res.result.list.forEach(function (inventory) {
                var inventoryList2 = [];
                inventory.skuList.forEach(function (invent) {
                    invent.stockPurchaseInSkuList.forEach(function (inv, i) {
                        var obj = {};
                        if (!i) {
                            Object.assign(obj, invent, { first: true });
                        }
                        inventoryList2.push(Object.assign(obj, inv));
                    });
                });
                inventory.skuList = inventoryList2;
                inventoryList.push(inventory);
            });
            $scope.inventoryList = inventoryList;
        });
    };
    $scope.getInventoryInfo();

    $scope.recieptHistory = true;
    $scope.toggleReciept = function () {
        $scope.recieptHistory = !$scope.recieptHistory;
    };
    $scope.addRecieptStatus = true;
    $scope.toggleAddReciept = function () {
        $scope.addRecieptStatus = !$scope.addRecieptStatus;
    };
    $scope.getSupplierListFactory = new ListFactory('/admin/selectStorehouseVoList.json', 0, maxStoreLength, { status: 0, useType: 1 });
    var depotPromise = $scope.getSupplierListFactory.nextPage();

    depotPromise.then(function (res) {
        for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
            $scope.storehouseArr.push({
                id: $scope.getSupplierListFactory.items[i].storehouse.id,
                name: $scope.getSupplierListFactory.items[i].storehouse.name
            });
        }
    });

    $scope.tab = {};

    $scope.setTab = function (idx) {
        $scope.tabIdx = idx;
        $scope.setAllModal = true;

        $scope.tab.batchNo == null;
        $scope.tab.time == null;
        $scope.tab.time2 == null;
    };

    $scope.setAllProduct = function () {

        if ($scope.tabIdx == 2) {

            if ($scope.tab.batchNo) {
                for (var i = 0; i < $scope.bindUdi.list.length; i++) {
                    $scope.bindUdi.list[i].batchNo = $scope.tab.batchNo;
                }
            } else {
                Popup.notice('请输入批号');
            }
        }
        if ($scope.tabIdx == 3) {
            if ($scope.tab.time) {
                for (var i = 0; i < $scope.bindUdi.list.length; i++) {
                    $scope.bindUdi.list[i].expiresDate = new Date($scope.tab.time);
                }
            } else {
                Popup.notice('请选择日期');
            }
        }
        if ($scope.tabIdx == 4) {
            if ($scope.tab.time2) {
                for (var i = 0; i < $scope.bindUdi.list.length; i++) {
                    $scope.bindUdi.list[i].productionDate = new Date($scope.tab.time2);
                }
            } else {
                Popup.notice('请选择日期');
            }
        }

        $scope.setAllModal = false;
    };

    $scope.compute = function (count, idx) {
        if (count === null || count === '') {
            return;
        }
        if (count < 0) {
            Popup.notice('入库数量必须大于0');
            $scope.bindUdi.list[idx].inSkuCount = null;
        }
    };
    $scope.setToModal = false;
    $scope.showAddPurchase = function () {
        if (!$scope.purchase.storehouseId) {
            Popup.notice('请选择仓库');
            return false;
        }

        $scope.goodsType = 0;
        $scope.goodsCount = 0;
        var goodsMap = new Map();
        for (var i = 0, len = $scope.bindUdi.list.length; i < len; i++) {
            var item = $scope.bindUdi.list[i];
            if (item.inSkuCount) {
                var num = goodsMap.get(item.id);
                num ? goodsMap.set(item.id, num) : goodsMap.set(item.id, 1);
                $scope.goodsCount = $scope.goodsCount + $scope.bindUdi.list[i].inSkuCount;
            }
        };
        $scope.goodsType = goodsMap.size;

        $scope.getStoreName = new ObjectFactory();
        $scope.getStoreName.saveOrQuery('/admin/getStorehouseVo.json', { id: $scope.purchase.storehouseId });
        $scope.setToModal = true;
    };

    $scope.addPurchase = function () {

        if (!$scope.purchase.stockInDate) {

            Popup.notice('请选择入库日期');
            return false;
        }
        var stockTakingSkuListJson = [];

        for (var i = 0, len = $scope.bindUdi.list.length; i < len; i++) {

            if ($scope.bindUdi.list[i].inSkuCount) {
                if (!$scope.bindUdi.list[i].expiresDate) {
                    Popup.notice('请选择有效期');
                    return false;
                }
                stockTakingSkuListJson.push({
                    stockPurchaseSkuId: $scope.bindUdi.list[i].stockPurchaseSkuId,
                    inSkuCount: $scope.bindUdi.list[i].inSkuCount,
                    batchNo: $scope.bindUdi.list[i].batchNo,
                    expiresDate: $scope.bindUdi.list[i].expiresDate.getTime(),
                    productionDate: $scope.bindUdi.list[i].productionDate.getTime(),
                    uniqueCode: $scope.bindUdi.list[i].uniqueCode
                });
            }
        };
        $scope.purchase.stockPurchaseInSkuListJson = JSON.stringify(stockTakingSkuListJson);
        $scope.saveInventoryObjectFactory = new ObjectFactory();
        var promise = $scope.saveInventoryObjectFactory.saveOrQuery('/admin/createStockPurchaseInAndSkuList.json', $scope.purchase);
        promise.then(function (res) {
            if (res.status == 0) {
                var commitFactory = new ObjectFactory();
                var commitpromise = commitFactory.saveOrQuery('/admin/commitStockPurchaseIn.json', { stockPurchaseInId: res.result.object.id });
                commitpromise.then(function (resp) {
                    if (resp.status == 0) {
                        // $state.go('materialPurchase');
                        getPurchaseInfo();
                        $scope.getInventoryInfo();
                        $scope.setToModal = false;
                    } else {
                        Popup.notice(resp.errmsg, 2000, function () {});
                    };
                });
            } else {
                Popup.notice(res.errmsg, 2000, function () {});
            };
        });
    };
    $scope.printRukudan = {
        stockInId: null,
        show: false,
        open: function open(show, stockPurchase) {
            this.stockInId = stockPurchase.stockPurchaseIn.stockInId;
            this.show = show;
        }
    };
}]);
'use strict';

angular.module('bestvisionWeb').controller('purchaseRequestCheckCtrl', ['$scope', 'Popup', '$rootScope', '$timeout', 'DateUtilFactory', '$state', 'ListFactory', 'ObjectFactory', function ($scope, Popup, $rootScope, $timeout, DateUtilFactory, $state, ListFactory, ObjectFactory) {
    $scope.obj = {};
    $scope.obj.processStatus = 0;

    $scope.purchaseRequestIdArray = [];

    $scope.myproducts = new ListFactory('/admin/getCompanyList.json', 0, 50, { status: 0 });
    $scope.myproducts.nextPage();

    $scope.companyIdArray = [];
    $scope.searchAllCateId = function () {
        $scope.companyIdArray = [];
        $scope.obj.companyIdArray = [];
        $scope.searchStock();
    };

    $scope.searchCateId = function () {

        var arr = [];
        for (var i = 0; i < $scope.companyIdArray.length; i++) {
            if ($scope.companyIdArray[i] !== null && $scope.companyIdArray[i] !== 'null' && $scope.companyIdArray[i] !== undefined) {

                arr.push($scope.companyIdArray[i]);
            }
        }

        if (!arr.length) {
            $scope.companyIdArray = [];
            $scope.obj.companyIdArray = [];
        }
        $scope.obj.companyIdArray = arr;

        $scope.searchStock();
    };

    $scope.obj.productType = null;
    $scope.setType = function (idx) {
        $scope.typeStatus = idx;
        $scope.obj.productType = idx;

        $scope.searchStock();
    };

    $scope.companyFactory = new ObjectFactory();
    $scope.companyFactory.saveOrQuery('/admin/getCorpInfo.json');

    var url = '/admin/getPurchaseRequestVoList.json';

    $scope.obj.checked = 1;

    $scope.pageSize = 20;

    $scope.searchStock = function () {

        if ($scope.obj.startTime && $scope.rightTime) {
            $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
            $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);
        } else if ($scope.obj.startTime && !$scope.rightTime) {
            $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);

            delete $scope.obj.endTime;
        } else if (!$scope.obj.startTime && $scope.rightTime) {
            $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);
            delete $scope.obj.startTime;
        } else {}

        $scope.getStockListFactory = new ListFactory(url, 0, $scope.pageSize, $scope.obj);
        var promise = $scope.getStockListFactory.nextPage();
        promise.then(function (data) {

            $("#Pagination").pagination($scope.getStockListFactory.count, {
                items_per_page: $scope.pageSize,
                callback: function callback(index) {
                    $scope.getStockListFactory.clearAndSetIndex(index * $scope.pageSize);
                    $scope.getStockListFactory.nextPage();

                    $scope.count = 0;
                    // $scope.checked.isSelectedAllStatus = true;
                }
            });
        });
    };
    $scope.searchStock();

    $scope.setTab = function (idx) {
        $scope.obj.processStatus = idx;
        $scope.searchStock();
    };
    $scope.selected = [];
    var updateSelected = function updateSelected(action, id) {
        if (action == 'add' && $scope.selected.indexOf(id) == -1) {
            $scope.selected.push(id);
        }
        if (action == 'remove' && $scope.selected.indexOf(id) != -1) {
            $scope.selected.splice($scope.selected.indexOf(id), 1);
        }

        // var arr = [];

        // for (var i = 0; i < $scope.selected.length; i++) {
        //     if ($scope.selected[i]) {
        //         arr.push($scope.selected[i])
        //     }

        // }
        // console.log(arr)
        // if (arr.length === $scope.getStockListFactory.items.length) {
        //     $scope.isSelectedAllStatus = true;
        // }

    };

    $scope.selectAll = function ($event) {
        var checkbox = $event.target;
        var action = checkbox.checked ? 'add' : 'remove';
        for (var i = 0; i < $scope.getStockListFactory.items.length; i++) {
            var contact = $scope.getStockListFactory.items[i];
            if (contact.purchaseRequest.processStatus === 0) {
                updateSelected(action, contact.purchaseRequest.id);
            }
        }
    };

    $scope.checked = {};

    //更新某一列数据的选择
    $scope.updateSelection = function ($event, id) {
        var checkbox = $event.target;

        if (!checkbox.checked) {
            $scope.checked.isSelectedAllStatus = false;
        }

        var action = checkbox.checked ? 'add' : 'remove';
        updateSelected(action, id);
    };
    $scope.count = 0;
    $scope.checked.isSelectedAllStatus = false;
    $scope.isSelected = function (id) {

        if ($scope.selected.indexOf(id) < 0) {
            $scope.count = $scope.count + 1;
        }

        if ($scope.count) {
            $scope.checked.isSelectedAllStatus = false;
        } else {
            $scope.checked.isSelectedAllStatus = true;
        }

        return $scope.selected.indexOf(id) >= 0;
    };

    $scope.deleteStock = function (id) {
        $scope.deleteObjectFactory = new ObjectFactory();
        var promise = $scope.deleteObjectFactory.saveOrQuery('/admin/deletePurchaseRequest.json', { purchaseRequestId: id });
        promise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg, 2000, function () {});
            } else {
                Popup.notice('删除成功', 2000, function () {});
                $scope.searchStock();
            }
        });
    };

    $scope.totalCount = function () {
        var total = 0;
        if ($scope.InventoryArr.length) {
            for (var i = 0; i < $scope.InventoryArr.length; i++) {
                total = total + Number($scope.InventoryArr[i].purchaseRequestSku.skuCount);
            }
            return total;
        }
    };
    $scope.totalPurchaseCount = function () {
        var total = 0;
        if ($scope.createOrderObjectFactory.result.list.length) {
            for (var i = 0; i < $scope.createOrderObjectFactory.result.list.length; i++) {
                total = total + Number($scope.createOrderObjectFactory.result.list[i].purchaseRequestCount);
            }
            return total;
        }
    };

    $scope.getSupplierListFactory = new ListFactory('/admin/getSupplierList.json', 0, 50, { status: 0 });
    $scope.getSupplierListFactory.nextPage();
    /*  $scope.getPurchaseRequestCountListFactory = new ListFactory('/admin/getPurchaseRequestVoList.json', 0, 0, { checked: 1, processStatus: 0 });
     $scope.getPurchaseRequestCountListFactory.nextPage(); */

    $scope.createOrder = function () {

        if (!$scope.selected.length) {
            Popup.notice("请选择未处理过的申请单");
            return false;
        }

        $scope.isProcessedFactory = new ObjectFactory();
        var processPromise = $scope.isProcessedFactory.saveOrQuery("/admin/isPurchaseRequestProcessed.json", { purchaseRequestIdArray: $scope.selected });
        processPromise.then(function (res) {

            if (res.result.object) {

                Popup.alert("采购申请已处理过，不能重复采购");
            } else {

                $scope.getPurchaseRequestListFactory = new ListFactory('/admin/getPurchaseRequestVoList.json', 0, $scope.selected.length, { idArray: $scope.selected });
                $scope.getPurchaseRequestListFactory.nextPage();

                $scope.createOrderObjectFactory = new ObjectFactory();
                var promise = $scope.createOrderObjectFactory.saveOrQuery('/admin/mergePurchaseRequestSku.json', { purchaseReqeustIdArray: $scope.selected });
                promise.then(function (res) {

                    if (res.status == 1) {
                        Popup.notice(res.errmsg, 2000, function () {});
                    } else {

                        for (var i = 0; i < $scope.createOrderObjectFactory.result.list.length; i++) {
                            if ($scope.createOrderObjectFactory.result.list[i].mainSupplier) {
                                $scope.createOrderObjectFactory.result.list[i].supplierId = $scope.createOrderObjectFactory.result.list[i].mainSupplier.id;
                            } else {
                                $scope.createOrderObjectFactory.result.list[i].supplierId = null;
                            }
                        }
                        $scope.addSaleModal = true;
                    }
                });
            }
        });
    };

    $scope.showOrder = function () {

        var len = $scope.createOrderObjectFactory.result.list.length;

        var arr = [];
        for (var j = 0; j < len; j++) {

            if ($scope.createOrderObjectFactory.result.list[j].supplierId == null) {

                Popup.notice("请选择供应商");
                return false;
            }

            if (arr.indexOf($scope.createOrderObjectFactory.result.list[j].supplierId) === -1) {
                arr.push($scope.createOrderObjectFactory.result.list[j].supplierId);
            }
        }
        $scope.len = len;
        $scope.orderLength = arr.length;
        $scope.dialog = { open: true };
    };

    $scope.selectOrderModal = function () {
        var arrJson = [];

        for (var i = 0; i < $scope.createOrderObjectFactory.result.list.length; i++) {

            arrJson[i] = {
                skuId: $scope.createOrderObjectFactory.result.list[i].productSku.id,
                skuCount: $scope.createOrderObjectFactory.result.list[i].purchaseRequestCount,
                supplierId: $scope.createOrderObjectFactory.result.list[i].supplierId,
                remark: $scope.createOrderObjectFactory.result.list[i].purchaseRequestSkuRemark,
                purchaseRequestSkuId: $scope.createOrderObjectFactory.result.list[i].purchaseRequestSkuId,
                purchaseRequestSkuIdList: $scope.createOrderObjectFactory.result.list[i].purchaseRequestSkuIdList,
                modelList: $scope.createOrderObjectFactory.result.list[i].modelList,
                customerInfo: $scope.createOrderObjectFactory.result.list[i].purchaseRequestSkuCustomerInfo
            };
        }
        $scope.dialog = { open: false };

        $scope.selectOrderObjectFactory = new ObjectFactory();
        var promise = $scope.selectOrderObjectFactory.saveOrQuery('/admin/createStockPurchaseFromRequest.json', { purchaseRequestIdArray: $scope.selected, stockPurchaseSkuPoListJson: JSON.stringify(arrJson) });
        promise.then(function (res) {

            if (res.status == 1) {
                Popup.notice(res.errmsg);
            } else {

                $state.go("purchase.materialPurchase");
            }
        });
    };

    $scope.selectOrder = function () {

        var len = $scope.createOrderObjectFactory.result.list;

        var arr = [];
        for (var j = 0; j < len.length; j++) {

            if (arr.indexOf(len[j].supplierId) === -1) {
                arr.push(len[j].supplierId);
            }
        }

        Popup.confirm('确认转为采购订单? 共' + len.length + '种商品，按' + arr.length + '供应商拆分采购单', function () {

            var arrJson = [];

            for (var i = 0; i < $scope.createOrderObjectFactory.result.list.length; i++) {

                arrJson[i] = {
                    skuId: $scope.createOrderObjectFactory.result.list[i].productSku.id,
                    skuCount: $scope.createOrderObjectFactory.result.list[i].purchaseRequestCount,
                    supplierId: $scope.createOrderObjectFactory.result.list[i].supplierId,
                    remark: $scope.createOrderObjectFactory.result.list[i].purchaseRequestSkuRemark,
                    purchaseRequestSkuId: $scope.createOrderObjectFactory.result.list[i].purchaseRequestSkuId,
                    purchaseRequestSkuIdList: $scope.createOrderObjectFactory.result.list[i].purchaseRequestSkuIdList,
                    modelList: $scope.createOrderObjectFactory.result.list[i].modelList,
                    customerInfo: $scope.createOrderObjectFactory.result.list[i].purchaseRequestSkuCustomerInfo
                };
            }

            $scope.selectOrderObjectFactory = new ObjectFactory();
            var promise = $scope.selectOrderObjectFactory.saveOrQuery('/admin/createStockPurchaseFromRequest.json', { purchaseRequestIdArray: $scope.selected, stockPurchaseSkuPoListJson: JSON.stringify(arrJson) });
            promise.then(function (res) {

                if (res.status == 1) {
                    Popup.notice(res.errmsg);
                } else {

                    $state.go("purchase.materialPurchase");
                }
            });
        }, function () {});
    };

    $scope.detail = {};
    $scope.detail.purchaseRequestId = -1;
    $scope.showCheckDetail = function (id) {

        $scope.detail.purchaseRequestId = id;

        $scope.getStockTakingObjectFactory = new ObjectFactory();
        var promise = $scope.getStockTakingObjectFactory.saveOrQuery('/admin/getPurchaseRequestVo.json', { purchaseRequestId: id });
        promise.then(function (res) {

            $scope.InventoryArr = res.object.skuList;
            $scope.viewSaleModal = true;

            $scope.detail.remark = res.object.purchaseRequest.remark;
            $scope.detail.requestTime = new Date(res.object.purchaseRequest.requestTime);
        });
    };
}]);
'use strict';

