angular.module("bestvisionWeb").controller("receiptDetailCtrl", ["$scope", "Popup", "$window", "$stateParams", "HttpFactory", "$state", "$timeout", "ListFactory", "ObjectFactory", function ($scope, Popup, $window, $stateParams, HttpFactory, $state, $timeout, ListFactory, ObjectFactory) {
  HttpFactory.object('/admin/getStockConf.json').then(function (corpInfo) {
    //>=1380
    if (corpInfo && corpInfo.enableFeier == 1) {
      //视为新客户
      $scope.newCustomer = true;
    } else {
      $scope.newCustomer = false;
    }
  });
  $scope.stockInId = $stateParams.stockInId;
  $scope.stockInSkuId = $stateParams.stockInSkuId;
  $scope.obj = {};
  $scope.keyword = "";
  $scope.stockInSkuList = [];
  $scope.totalprice = 0;
  $scope.totalfee = 0;

  HttpFactory.object("/admin/getStockInVo.json", {
    id: $scope.stockInId
  }).then(function (res) {
    $scope.obj = res;
  });
  $scope.stockList = [];
  $scope.getStockList = function () {
    HttpFactory.object("/admin/getStockInSkuVoListOfStockIn.json", {
      stockInId: $scope.stockInId,
      keyword: $scope.keyword,
      index: undefined,
      length: undefined
    }).then(function (arr) {
      var totalPrice = 0,
          totalfee = 0;
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].stockInSku.skuCount) {
          totalPrice += arr[i].stockInSku.skuCount;
          totalfee += arr[i].stockInSku.skuTotalPrice;
        }
      }
      $scope.totalprice = totalPrice;
      $scope.totalfee = totalfee;
      $scope.stockList = arr;
    });
  };
  $scope.getStockList();
  $scope.pageSize = 5000;
  $scope.getCashflowQrcodeCountObjectFactory = new ListFactory("/admin/getSkuCodeVoListOfStockIn.json", 0, 1, {
    stockInId: $scope.stockInId,
    withSkuCount: true,
    keyword: $scope.keyword
  });
  $scope.getCashflowQrcodeCountObjectFactory.nextPage();

  $scope.printQrcode = function (idx, stockInSkuId) {
    var params = { stockInId: $scope.stockInId, keyword: $scope.keyword };
    if (idx == 1) {
      params.withSkuCount = true;
    } else {
      params.withSkuCount = false;
      params.stockInSkuId = stockInSkuId;
    }

    $scope.getCashflowQrcodeObjectFactory = new ListFactory("/admin/getSkuCodeVoListOfStockIn.json", 0, $scope.pageSize, params);
    var codepromise = $scope.getCashflowQrcodeObjectFactory.nextPage();
    codepromise.then(function () {
      $timeout(function () {
        $("#ele1").jqprint({
          debug: false,
          importCSS: true,
          printContainer: true,
          operaSupport: false
        });
      }, 3000);

      $("#Pagination").pagination($scope.getCashflowQrcodeObjectFactory.count, {
        items_per_page: $scope.pageSize,
        callback: function callback(index) {
          $scope.getCashflowQrcodeObjectFactory.clearAndSetIndex(index * $scope.pageSize);
          $scope.getCashflowQrcodeObjectFactory.nextPage();
        }
      });
    });
  };

  if ($scope.$state.current.name == "receiptDetail") {
    $scope.tab = 1;
  } else {
    $scope.tab = 2;
  }

  $scope.back = function () {
    $window.history.go(-1);
  };

  $scope.cloud = {};
  $scope.cloud.cloudPrinterId = null;
  $scope.printAll = function (idx, stockInSkuId) {
    $scope.cloud.cloudPrinterId = null;
    $scope.printerList = new ListFactory("/admin/selectCloudPrinterList.json", 0, 50, { status: 0 });
    var printpromise = $scope.printerList.nextPage();
    printpromise.then(function () {
      if ($scope.printerList.items.length) {
        $scope.printAllModel = true;
        if (stockInSkuId) {
          $scope.cloud.stockInSkuId = stockInSkuId;
        } else {
          delete $scope.cloud.stockInSkuId;
        }
      } else {
        $scope.isshow = true;
      }
    });
  };
  $scope.selectPrintDevice = function () {
    if (!$scope.cloud.cloudPrinterId) {
      return Popup.notice("请选择打印机");
    }
    $scope.cloud.stockInId = $scope.stockInId;
    new ObjectFactory().saveOrQuery("/admin/sendSkuToCloudPrinter.json", $scope.cloud).then(function () {
      $scope.printAllModel = false;
    });
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("receiptInvalidCtrl", ["$scope", "Popup", "$window", "$stateParams", "$rootScope", "$state", "$timeout", "HttpFactory", "ObjectFactory", function ($scope, Popup, $window, $stateParams, $rootScope, $state, $timeout, HttpFactory, ObjectFactory) {
  $scope.stockInId = $stateParams.stockInId;
  $scope.stockInSkuId = $stateParams.stockInSkuId;
  $scope.obj = {};
  $scope.stockInSkuList = [];
  $scope.totalprice = 0;

  $scope.getStockObjectFactory = new ObjectFactory();
  var promise = $scope.getStockObjectFactory.saveOrQuery("/admin/getStockInVo.json", { id: $scope.stockInId });
  promise.then(function (res) {
    $scope.obj = res.object;
  });
  $scope.stockList = [];
  $scope.getStockList = function () {
    HttpFactory.object("/admin/getStockInSkuVoListOfStockIn.json", {
      stockInId: $scope.stockInId,
      keyword: $scope.keyword,
      index: undefined,
      length: undefined
    }).then(function (arr) {
      var totalPrice = 0;
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].stockInSku.skuCount) {
          totalPrice += arr[i].stockInSku.skuCount;
        }
      }
      $scope.totalprice = totalPrice;
      $scope.stockList = arr;
    });
  };
  $scope.getStockList();
  if ($scope.$state.current.name == "receiptInvalid") {
    $scope.tabState = 1;
  } else {
    $scope.tabState = 2;
  }

  var invalidAll = function invalidAll() {
    $scope.invalidAllObjectFactory = new ObjectFactory();
    var allpromise = $scope.invalidAllObjectFactory.saveOrQuery("/admin/cancelStockIn.json", { stockInId: $scope.stockInId });
    allpromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        Popup.notice("作废成功");
        if ($scope.tabState == 1) {
          $state.go("materialReceipts");
        } else {
          $state.go("goods.companyMaterialReceipts");
        }
      }
    });
  };
  var invalidSingle = function invalidSingle() {
    $scope.invalidSingleObjectFactory = new ObjectFactory();
    var singlepromise = $scope.invalidSingleObjectFactory.saveOrQuery("/admin/cancelStockInSku.json", { stockInSkuId: $scope.stockInSkuId });
    singlepromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        Popup.notice("作废成功");
        $scope.invalidShow = false;
        $state.reload();
      }
    });
  };

  $scope.singleShow = function (stockInSkuId) {
    $scope.stockInSkuId = stockInSkuId;
    $scope.tab = 1;
    $scope.invalidShow = true;
  };

  $scope.allShow = function () {
    $scope.tab = 2;
    $scope.invalidShow = true;
  };

  $scope.modify = function () {
    if ($scope.tab == 1) {
      invalidSingle();
    } else {
      invalidAll();
    }
  };

  $scope.hideModal = function () {
    $scope.invalidShow = false;
  };

  $scope.back = function () {
    $window.history.go(-1);
  };
}]);
