angular.module("bestvisionWeb").controller("stockChangeCtrl", ["$scope", "Popup", "maxStoreLength", "$rootScope", "$timeout", "DateUtilFactory", "StorageFactory", "$state", "ListFactory", "ObjectFactory", function ($scope, Popup, maxStoreLength, $rootScope, $timeout, DateUtilFactory, StorageFactory, $state, ListFactory, ObjectFactory) {
  var store = JSON.parse(StorageFactory.getItem("stockChange"));
  $scope.obj = store ? store : {};
  $scope.obj.outStorehouseId = $scope.obj.outStorehouseId ? $scope.obj.outStorehouseId : null;
  $scope.obj.inStorehouseId = $scope.obj.inStorehouseId ? $scope.obj.inStorehouseId : null;
  $scope.obj.keyword = $scope.obj.keyword ? $scope.obj.keyword : "";
  $scope.obj.modelKeyword = $scope.obj.modelKeyword ? $scope.obj.modelKeyword : "";

  $scope.obj.byProduct = StorageFactory.getItem("materialInventoryTab") ? StorageFactory.getItem("materialInventoryTab") : 1;
  if ($scope.obj.outStartTime) {
    $scope.obj.outStartTime = new Date($scope.obj.outStartTime);
  }
  if ($scope.obj.rightTime) {
    $scope.rightTime = new Date($scope.obj.rightTime);
  }

  // $scope.rightTime = new Date();
  // $scope.obj.outStartTime = new Date();
  $scope.storehouseOutArr = [{ id: null, name: "请选择调出仓" }];
  $scope.storehouseInArr = [{ id: null, name: "请选择调入仓" }];

  $scope.companyFactory = new ObjectFactory();
  $scope.companyFactory.saveOrQuery("/admin/getCorpInfo.json");

  $scope.printList = function (id) {
    $scope.getCashflowObjectFactory = new ObjectFactory();
    var promise = $scope.getCashflowObjectFactory.saveOrQuery("/admin/getStockTransferVo.json", { id: id, withDetail: true });
    promise.then(function (res) {
      $timeout(function () {
        $("#ele3").jqprint({
          debug: false,
          importCSS: true,
          printContainer: true,
          operaSupport: false
        });
      }, 1000);
    });
  };

  $scope.printProductList = function (id) {
    $scope.getProductTransferListObjectFactory = new ObjectFactory();
    var productPromise = $scope.getProductTransferListObjectFactory.saveOrQuery("/admin/getStockTransferProductVoList.json", { stockTransferId: id });
    productPromise.then(function (resp) {
      $scope.getProductTransferObjectFactory = new ObjectFactory();
      var promise = $scope.getProductTransferObjectFactory.saveOrQuery("/admin/getStockTransferVo.json", { id: id, withDetail: false });
      promise.then(function (res) {
        $timeout(function () {
          $("#ele2").jqprint({
            debug: false,
            importCSS: true,
            printContainer: true,
            operaSupport: false
          });
        }, 1000);
      });
    });
  };
  $scope.getSupplierListFactory = new ListFactory("/admin/selectStorehouseVoList.json", 0, maxStoreLength, { status: 0 });
  var depotPromise = $scope.getSupplierListFactory.nextPage();

  depotPromise.then(function (res) {
    for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
      $scope.storehouseOutArr.push({
        id: $scope.getSupplierListFactory.items[i].storehouse.id,
        name: $scope.getSupplierListFactory.items[i].storehouse.name
      });
      $scope.storehouseInArr.push({
        id: $scope.getSupplierListFactory.items[i].storehouse.id,
        name: $scope.getSupplierListFactory.items[i].storehouse.name
      });
    }
  });
  $scope.clearPage = function () {
    $scope.obj.page = 0;
    $scope.searchStock();
  };

  $scope.setProduct = function (tab) {
    StorageFactory.setItem("materialInventoryTab", tab);
    $scope.obj.byProduct = tab;
    $scope.searchStock();
  };

  $scope.pageSize = 10;
  $scope.searchStock = function () {
    if ($scope.rightTime) {
      $scope.obj.rightTime = $scope.rightTime;
    }

    if ($scope.obj.outStartTime && $scope.rightTime) {
      $scope.obj.outStartTime = DateUtilFactory.origin($scope.obj.outStartTime);
      $scope.obj.outEndTime = DateUtilFactory.plus($scope.rightTime);
    } else if ($scope.obj.outStartTime && !$scope.rightTime) {
      $scope.obj.outStartTime = DateUtilFactory.origin($scope.obj.outStartTime);

      delete $scope.obj.outEndTime;
    } else if (!$scope.obj.outStartTime && $scope.rightTime) {
      $scope.obj.outEndTime = DateUtilFactory.plus($scope.rightTime);
      delete $scope.obj.outStartTime;
    } else {}
    var pageStart = $scope.obj.page ? $scope.obj.page * $scope.pageSize : 0;
    StorageFactory.setItem("stockChange", JSON.stringify($scope.obj));

    $scope.getStockListFactory = new ListFactory("/admin/getStockTransferVoList.json", pageStart, $scope.pageSize, $scope.obj);
    var promise = $scope.getStockListFactory.nextPage();
    promise.then(function (data) {
      console.log(data);
      $("#Pagination").pagination($scope.getStockListFactory.count, {
        items_per_page: $scope.pageSize,
        current_page: $scope.obj.page,
        callback: function callback(index) {
          $scope.obj.page = index;
          StorageFactory.setItem("stockChange", JSON.stringify($scope.obj));

          $scope.getStockListFactory.clearAndSetIndex(index * $scope.pageSize);
          $scope.getStockListFactory.nextPage();
        }
      });
    });
  };
  // $scope.searchStock();
  if ($scope.$state.current.name == "stockChange") {
    $scope.tab = 1;
    $scope.searchStock();
  } else {
    var adminOk = new ObjectFactory();
    var promiseAdmin = adminOk.saveOrQuery("/admin/isAdminRoleStateOK.json", {
      state: $scope.$state.current.name
    });
    promiseAdmin.then(function (data) {
      if (!data.object) {
        $state.go("404");
      }
    });
    $scope.tab = 2;
  }

  $scope.deleteStock = function (id) {
    Popup.confirm("确认删除么", function () {
      $scope.deleteObjectFactory = new ObjectFactory();
      var promise = $scope.deleteObjectFactory.saveOrQuery("/admin/deleteStockTransfer.json", { id: id });
      promise.then(function (res) {
        if (res.status == 1) {
          Popup.notice(res.errmsg, 2000, function () {});
        } else {
          Popup.notice("删除成功", 2000, function () {});
          $scope.clearPage();
        }
      });
    }, function () {});
  };

  $scope.setTab = function (idx) {
    $scope.checkStatus = idx;
    $scope.obj.checkStatus = idx;
    if (idx == 0) {
      $scope.obj.checked = 0;
      $scope.obj.transferStatus = null;
    } else if (idx == 1) {
      $scope.obj.checked = 1;
      $scope.obj.transferStatus = 0;
    } else if (idx == 2) {
      $scope.obj.checked = 1;
      $scope.obj.transferStatus = 1;
    } else {
      $scope.obj.checked = null;
      $scope.obj.transferStatus = null;
    }
    $scope.searchStock();
  };
}]);
