angular.module("bestvisionWeb").controller("stockListCtrl", ["$scope", "Popup", "maxStoreLength", "$interval", "DateUtilFactory", "daochuFactory", "$state", "ListFactory", "ObjectFactory", function ($scope, Popup, maxStoreLength, $interval, DateUtilFactory, daochuFactory, $state, ListFactory, ObjectFactory) {
  $scope.obj = {};
  $scope.stockTab = 1;
  $scope.categoryAll = true;
  $scope.obj.moreThanZero = false;
  $scope.obj.equalToZero = false;
  $scope.obj.lessThanZero = false;
  $scope.obj.expiresWarning = false;
  $scope.obj.countWarning = false;
  $scope.obj.model1Keyword = "";
  $scope.obj.model2Keyword = "";
  $scope.obj.batchNoKeyword = "";
  $scope.obj.categoryId = "";
  $scope.obj.brandId = "";
  $scope.obj.keyword = "";
  $scope.checkedSupplierIds = [];
  $scope.storehouseArr = [{ id: "", name: "全部仓库" }];
  $scope.keyword = "选择供应商";
  $scope.token = localStorage.getItem("pcToken");
  $scope.obj.storehouseId = "";

  $scope.setCustomer = function (tab) {
    $scope.obj.productType = tab;
    if (tab) {
      $scope.obj.productType = tab;
    } else {
      delete $scope.obj.productType;
    }
    $scope.getstockList();
  };

  $scope.searchCategoryObjectFactory = new ObjectFactory();
  $scope.searchCategoryObjectFactory.saveOrQuery("/admin/getCategoryTree2Level.json");

  $scope.getBrandFactory = new ObjectFactory();
  $scope.getBrandFactory.saveOrQuery("/admin/getBrandListOfProduct.json");

  $scope.chooseCategory = function (id, bool) {
    $scope.obj.categoryId = id;

    $scope.seletedCategory = id;
    $scope.seletedCategoryId = null;

    if (bool) {
      $scope.categoryAll = true;
    } else {
      $scope.categoryAll = false;
    }

    $scope.getstockList();
  };
  $scope.chooseCategoryId = function (id, event) {
    event.stopPropagation();
    $scope.seletedCategoryId = id;
    $scope.obj.categoryId = id;
    $scope.getstockList();
  };

  $scope.daochuPop = {};
  $scope.showDaochu = function (e) {
    $scope.daochuPop.modal = true;
    e.stopPropagation();
  };

  $scope.getSupplierListFactory = new ListFactory("/admin/selectStorehouseVoList.json", 0, maxStoreLength, { status: 0 });
  var depotPromise = $scope.getSupplierListFactory.nextPage();

  depotPromise.then(function (res) {
    for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
      $scope.storehouseArr.push({
        id: $scope.getSupplierListFactory.items[i].storehouse.id,
        name: $scope.getSupplierListFactory.items[i].storehouse.name
      });
    }
  });

  $scope.obj.status = 0;
  $scope.obj.withDetail = false;
  $scope.obj.productType = 1;
  $scope.pageSize = 20;
  $scope.downloadIndex = 0;

  $scope.searchStock = function () {
    var obj = angular.copy($scope.obj);
    delete obj.batchNoKeyword;
    if (obj.productType != 1) {
      delete obj.countWarning;
      delete obj.highCountWarning;
      delete obj.nearExpiresWarning;
      delete obj.expiresWarning;
    }
    var url = $scope.stockTab == 1 ? 'getProductSkuInVoList' : 'getProductExistVoList';
    $scope.getStockListFactory = new ListFactory("/admin/" + url + ".json", 0, $scope.pageSize, obj);
    var promise = $scope.getStockListFactory.nextPage();
    promise.then(function (data) {
      $("#Pagination").pagination($scope.getStockListFactory.count, {
        items_per_page: $scope.pageSize,
        callback: function callback(index) {
          $scope.downloadIndex = index * $scope.pageSize;

          $scope.getStockListFactory.clearAndSetIndex(index * $scope.pageSize);
          $scope.getStockListFactory.nextPage();
        }
      });
    });
  };
  // $scope.searchStock();
  if ($scope.$state.current.name == "stockList" || $scope.$state.current.name == "viewStockList") {
    $scope.searchStock();
  }

  $scope.getstockList = function () {
    $scope.downloadIndex = 0;
    var stockT = {
      1: 'searchStock',
      2: 'searchNewStock',
      3: 'searchStock'
    }[$scope.stockTab];
    stockT && $scope[stockT] && $scope[stockT]();
  };

  $scope.setStockTab = function (tab) {
    $scope.stockTab = tab;
    $scope.getstockList();
  };

  $scope.showStoreModal = function (item) {
    var name = item.product.productName;
    var model1 = item.productSku && item.productSku.model1;
    var model2 = item.productSku && item.productSku.model2;
    var url = 'selectStorehouseExistSkuCountVoList';
    var obj = {};
    if ($scope.stockTab == 3) {
      url = 'selectStorehouseExistProductCountVoList';
      obj.productId = item.product.id;
      obj.status = 0;
    } else {
      obj.productSkuId = item.productSku.id;
    }
    $scope.existStoreModal = true;
    $scope.modalName = name;
    $scope.model1Val = model1;
    $scope.model2Val = model2;

    var pageSize = 15;
    if ($scope.obj.storehouseId !== "") {
      obj.storehouseId = $scope.obj.storehouseId;
    }
    $scope.getStoreExistList = new ListFactory("/admin/" + url + ".json", 0, pageSize, obj);
    var stpromise = $scope.getStoreExistList.nextPage();
    stpromise.then(function (data) {
      $(".second-pagination").pagination($scope.getStoreExistList.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.getStoreExistList.clearAndSetIndex(index * pageSize);
          $scope.getStoreExistList.nextPage();
        }
      });
    });
  };
  $scope.hideStoreModal = function () {
    $scope.existStoreModal = false;
  };

  $scope.toggleSearch = function () {
    $scope.obj.moreThanZero = false;
    $scope.obj.lessThanZero = false;
    $scope.obj.expiresWarning = false;
    $scope.obj.countWarning = false;
    $scope.getstockList();
  };
  $scope.getLinkCodeFactory = new ObjectFactory();
  $scope.getLinkCodeFactory.saveOrQuery("/admin/getChildrenLinkAndCode.json", { state: "goods" });
  $scope.isCheck = function (str) {
    if ($scope.getLinkCodeFactory.result.object && $scope.getLinkCodeFactory.result.object.childrenCode.indexOf(str) > -1) {
      return true;
    }
    return false;
  };

  $scope.searchNewStock = function () {
    var obj = angular.copy($scope.obj);

    if (obj.productType != 1) {
      delete obj.countWarning;
      delete obj.highCountWarning;
      delete obj.nearExpiresWarning;
      delete obj.expiresWarning;
    }
    $scope.getStockListFactory = new ListFactory("/admin/getStockInSkuVoList.json", 0, $scope.pageSize, obj);
    var promise = $scope.getStockListFactory.nextPage();
    promise.then(function (data) {
      // console.log(data);
      $("#Pagination").pagination($scope.getStockListFactory.count, {
        items_per_page: $scope.pageSize,
        callback: function callback(index) {
          $scope.downloadIndex = index * $scope.pageSize;

          $scope.getStockListFactory.clearAndSetIndex(index * $scope.pageSize);
          $scope.getStockListFactory.nextPage();
        }
      });
    });
  };

  $scope.modify = function () {
    $scope.searchStock();
  };

  $scope.showDetail = function (stockInSkuId) {
    $scope.stockDetail = true;
    $scope.getStockObjectFactory = new ObjectFactory();
    $scope.getStockObjectFactory.saveOrQuery("/admin/getStockInSkuVo.json", {
      stockInSkuId: stockInSkuId
    });
  };
}]);
"use strict";

