angular.module("bestvisionWeb").controller("stockListssCtrl", ["$scope", "Popup", "$timeout", "$interval", "DateUtilFactory", "daochuFactory", "$state", "ListFactory", "ObjectFactory", function ($scope, Popup, $timeout, $interval, DateUtilFactory, daochuFactory, $state, ListFactory, ObjectFactory) {
  var bivariateTableList = [{ status: -1, name: "负" }, { status: 1, name: "正" }];
  $scope.getList = null;
  $scope.pageSize = 20;
  $scope.sign = {
    model1CompareToZero: null,
    model2CompareToZero: null
  };
  $scope.bivariateTable1 = {
    status: "",
    tablist: angular.copy(bivariateTableList),
    callback: function callback() {
      $scope.sign.model1CompareToZero = this.status;
      if ($scope.getList.result.object.product.modelType === 2 && ($scope.getList.result.object.product.model2Name === "球镜" || $scope.getList.result.object.product.model2Name === "柱镜")) {
        $scope.sign.model2CompareToZero = $scope.bivariateTable2.status;
      }
      $scope.getEr($scope.sign);
    }
  };
  $scope.bivariateTable2 = {
    status: "",
    tablist: angular.copy(bivariateTableList),
    callback: function callback() {
      $scope.sign.model2CompareToZero = this.status;
      if ($scope.getList.result.object.product.model1Name === "球镜" || $scope.getList.result.object.product.model1Name === "柱镜") {
        $scope.sign.model1CompareToZero = $scope.bivariateTable1.status;
      }
      $scope.getEr($scope.sign);
    }
  };

  $scope.choseShop = {
    btnStr: ["选择商品", "切换商品"],
    statusList: ["btn-primary", "report-nav_btn"],
    status: 0, //
    showComp: false,
    shopInfo: {
      brandId: "", //全部品牌的id
      keyword: "", //产品名称、拼音或条形码
      productType: 1, //，库存1，定制2
      categoryId: null, //左侧treeId
      productName: "",
      id: "",
      status: 0
    },
    callBack: function callBack() {
      this.showComp = true;
    },
    closeBack: function closeBack() {
      this.showComp = false;
      /* 如果选中了商品，则要将仓库状态改变 */
      if (this.shopInfo.id) {
        this.status = 1;
        return $scope.getEr();
      } else {
        this.status = 0;
      }
    }
  };
  $scope.storeInfo = {
    idName: "excuteDoctor",
    ajaxUrl: "/admin/selectStorehouseVoList.json",
    isshow: true,
    id: null,
    inputVal: "",
    inputPlaceHolder: "全部仓库",
    info: null,
    key: "storehouse",
    key2: "name",
    fn: function fn() {
      $scope.getEr();
    },
    callBack: function callBack() {
      $scope.getEr();
    },
    type: "List"
  };
  $scope.model = {
    model1Keyword: "",
    model2Keyword: "",
    skuCodeKeyword: ""
  };
  $scope.isShowCondition = false;
  $scope.getEr = function (vo) {
    if (!$scope.choseShop.shopInfo.id) {
      return;
    }
    if (!vo) {
      $scope.sign = {};
      $scope.bivariateTable1.status = '';
      $scope.bivariateTable2.status = '';
    }
    var obj = Object.assign({
      storehouseId: $scope.storeInfo.id, //仓库id
      productId: $scope.choseShop.shopInfo.id, //商品id
      model1Keyword: $scope.model.model1Keyword,
      model2Keyword: $scope.model.model2Keyword,
      skuCodeKeyword: $scope.model.skuCodeKeyword //条形码
    }, $scope.sign);
    $scope.getList = new ObjectFactory();
    $scope.getList.saveOrQuery("/admin/getStockCountForTwoDimensionalTable.json", obj).then(function (res) {
      $scope.isShowCondition = $scope.getList.result.object.product.modelType ? true : false;
    });
  };
  $scope.daochu = function () {
    var obj = Object.assign({
      storehouseId: $scope.storeInfo.id, //仓库id
      productId: $scope.choseShop.shopInfo.id, //商品id
      model1Keyword: $scope.model.model1Keyword,
      model2Keyword: $scope.model.model2Keyword,
      skuCodeKeyword: $scope.model.skuCodeKeyword, //条形码
      token: localStorage.getItem("pcToken")
    }, $scope.sign);
    var url = API_HOST + "/admin/downloadProductSkuStockPlaneVo.htm?";
    for (var i in obj) {
      if (obj[i]) {
        url += i + "=" + encodeURIComponent(obj[i]) + "&";
      }
    }
    url = url.substring(0, url.length - 1);
    window.location.href = url;
  };
  window.getStockSet(ObjectFactory).then(function (res) {
    $timeout(function () {
      $scope.direction = {
        0: {
          xName: "model1Name",
          yName: "model2Name"
        },
        1: {
          xName: "model2Name",
          yName: "model1Name"
        }
      }[res.modelShow];
    });
  });
}]);
'use strict';

angular.module('bestvisionWeb').controller('stockProductChangeCheckCtrl', ['$scope', '$stateParams', 'Popup', '$rootScope', '$state', 'ListFactory', 'ObjectFactory', function ($scope, $stateParams, Popup, $rootScope, $state, ListFactory, ObjectFactory) {

    $scope.obj = {};
    $scope.obj.id = $stateParams.id;
    $scope.storehouseId = $stateParams.storehouseId;
    $scope.stockInSkuList = [];

    $scope.inDate = new Date();
    if ($scope.$state.current.name == "stockChangeCheck") {
        $scope.tab = 1;
    } else {
        $scope.tab = 2;
    }

    $scope.totalprice = 0;
    $scope.totalExistCount = 0;
    $scope.getTransferListFactory = new ObjectFactory();
    var productPromise = $scope.getTransferListFactory.saveOrQuery('/admin/getStockTransferProductVoList.json', { stockTransferId: $scope.obj.id });
    productPromise.then(function (res) {
        $scope.stockInSkuList = res.result.list;
        var arr = res.result.list;
        for (var i = 0; i < arr.length; i++) {

            if (arr[i].stockTransferProduct.transferCount) {
                $scope.totalprice += arr[i].stockTransferProduct.transferCount;
            }
            if (arr[i].unLockExistSkuCount) {
                $scope.totalExistCount += arr[i].unLockExistSkuCount;
            }
        };
    });

    $scope.getTransferFactory = new ObjectFactory();
    var transferPromise = $scope.getTransferFactory.saveOrQuery('/admin/getStockTransferVo.json', { id: $scope.obj.id, withDetail: false });
    transferPromise.then(function (res) {
        $scope.obj.outDate = new Date(res.result.object.stockTransfer.outDate);
        $scope.obj.remark = res.result.object.stockTransfer.remark;
        $scope.obj.operator = res.result.object.stockTransfer.operator;
        $scope.obj.checkName = res.result.object.stockTransfer.checkName;
        $scope.obj.checkDate = res.result.object.stockTransfer.checkDate;
    });

    $scope.modify = function () {
        if (!$scope.inDate) {
            Popup.notice('请选择调入日期', 2000, function () {});
            return false;
        }
        var checkObj = { id: $scope.obj.id, inDate: $scope.inDate };
        if ($scope.tab == 2) {
            checkObj.manageStorehouseId = $scope.storehouseId;
        }

        Popup.confirm('确认将调拨单入库到' + $scope.getTransferFactory.result.object.inStorehouse.name + '？此操作不可撤销。', function () {

            $scope.completeFactory = new ObjectFactory();
            var promise = $scope.completeFactory.saveOrQuery("/admin/completeStockTransfer.json", checkObj);
            promise.then(function (res) {
                if (res.status == 0) {
                    Popup.notice('入库成功', 2000, function () {});

                    if ($scope.tab == 1) {
                        $state.go('stockChange');
                    } else {
                        $state.go('goods.stockCompanyChange');
                    }
                } else {
                    Popup.notice(res.errmsg, 2000, function () {});
                };
            });
        }, function () {});
    };
}]);
'use strict';

angular.module('bestvisionWeb').controller('addNewCtrl', ['$scope', 'Popup', '$timeout', '$sce', 'QiniuFactory', '$stateParams', '$rootScope', '$state', 'ObjectFactory', 'DateUtilFactory', 'ListFactory', '$q', '$http', function ($scope, Popup, $timeout, $sce, QiniuFactory, $stateParams, $rootScope, $state, ObjectFactory, DateUtilFactory, ListFactory, $q, $http) {

    $scope.obj = {};
    $scope.getCategoryFactory = new ObjectFactory();
    var promise = $scope.getCategoryFactory.saveOrQuery('/admin/getNewsCategoryTree2Level.json');
    promise.then(function (res) {
        $scope.arr = res.result.list;
    });

    $scope.setCategory = function (id) {
        for (var i = 0; i < $scope.arr.length; i++) {
            if ($scope.arr[i].root.id == id) {
                $scope.arrTree = $scope.arr[i].childList;
            }
        }
    };

    $scope.modalQiniuFactory = new QiniuFactory();
    $scope.modalQiniuFactory.getToken();

    $scope.uploadimg = function () {

        function getbase() {
            var defer = $q.defer();
            var base64_code;
            var imgload = document.getElementById('add-new_img');
            imgload.addEventListener('change', readFile, false);

            function readFile() {
                $rootScope.$broadcast("ajax-start");
                var file = this.files[0];
                var reader = new FileReader();
                reader.onload = function (e) {
                    base64_code = this.result.replace(/^.*?,/, '');
                    // console.log(base64_code);  

                    defer.resolve(base64_code);
                };

                if (file) {
                    reader.readAsDataURL(file);
                }
            };
            return defer.promise;
        }

        function putb64(base64_code) {
            var url = $scope.modalQiniuFactory.UPLOAD_HOST;
            console.log(url);
            var xhr = new XMLHttpRequest();
            xhr.onreadystatechange = function () {
                if (xhr.readyState == 4) {
                    console.log(xhr.responseText);
                    var resultObj = JSON.parse(xhr.responseText);
                    var avatar = $scope.modalQiniuFactory.IMAGE_HOST + "/" + resultObj.key;
                    $scope.keyimg = $scope.modalQiniuFactory.IMAGE_HOST + "/" + resultObj.key;
                    $scope.obj.newsPicture = $scope.modalQiniuFactory.IMAGE_HOST + "/" + resultObj.key;
                    $scope.$digest();
                    $rootScope.$broadcast("ajax-end");
                }
            };
            xhr.open("POST", url, true);
            xhr.setRequestHeader("Content-Type", "application/octet-stream");
            xhr.setRequestHeader("Authorization", "UpToken " + $scope.modalQiniuFactory.UPLOAD_TOKEN);
            xhr.send(base64_code);
        };
        getbase().then(function (res) {

            putb64(res);
        });
    };

    $scope.addNew = function () {
        if (!$scope.obj.newsCategoryId) {
            Popup.notice('类型不能为空');
        }
        if (!$scope.obj.newsTitle) {
            Popup.notice('标题不能为空');
        }
        if (!$scope.obj.newsAuthor) {
            Popup.notice('作者不能为空');
        }

        $scope.obj.newsContent = $scope.editor;

        $scope.addNewFactory = new ObjectFactory();
        var insertPromise = $scope.addNewFactory.saveOrQuery('/admin/insertNews.json', $scope.obj);
        insertPromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice('新增成功');
                $state.go('newsList');
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };
}]);
'use strict';

