angular.module("bestvisionWeb").controller("addSaleRecordCtrl", ["$scope", "$stateParams", "DateUtilFactory", "Popup", "$state", "ObjectFactory", "ListFactory", "StorageFactory", "$http", "$timeout", function ($scope, $stateParams, DateUtilFactory, Popup, $state, ObjectFactory, ListFactory, StorageFactory, $http, $timeout) {
    var store = JSON.parse(StorageFactory.getItem("addSaleRecord"));
    $scope.data = store ? store : {};

    if ($scope.data.haveOrder === undefined) {
        $scope.data.haveOrder = true;
    }
    $scope.data.keyword = $scope.data.keyword ? $scope.data.keyword : "";
    $scope.data.productKeyword = $scope.data.productKeyword ? $scope.data.productKeyword : "";
    // $scope.hasPoint = $scope.data.haveOrder ? 2 : 1;
    $scope.hasPoint = 2;
    if ($scope.data.firstVisitFrom) {
        $scope.data.firstVisitFrom = new Date($scope.data.firstVisitFrom);
    }
    if ($scope.data.rightTime) {
        $scope.rightTime = new Date($scope.data.rightTime);
    }

    // $scope.hasPoint = 1;//默认传true，不选中
    $scope.searchList = function () {
        console.log($scope.hasPoint);
        if ($scope.hasPoint == 1) {
            $scope.data.haveOrder = true;
        } else {
            $scope.data.haveOrder = false;
        }

        var pageSize = 12;
        var pageStart = $scope.data.page ? $scope.data.page * pageSize : 0;
        if ($scope.rightTime) {
            $scope.data.rightTime = $scope.rightTime;
        }
        if ($scope.data.firstVisitFrom && $scope.rightTime) {
            $scope.data.firstVisitFrom = DateUtilFactory.origin($scope.data.firstVisitFrom);
            $scope.data.firstVisitTo = DateUtilFactory.plus($scope.rightTime);
        } else if ($scope.data.firstVisitFrom && !$scope.rightTime) {
            $scope.data.firstVisitFrom = DateUtilFactory.origin($scope.data.firstVisitFrom);

            delete $scope.data.firstVisitTo;
        } else if (!$scope.data.firstVisitFrom && $scope.rightTime) {
            $scope.data.firstVisitTo = DateUtilFactory.plus($scope.rightTime);
            delete $scope.data.firstVisitFrom;
        } else {
            delete $scope.data.firstVisitFrom;
            delete $scope.data.firstVisitTo;
        }
        StorageFactory.setItem("addSaleRecord", JSON.stringify($scope.data));
        $scope.selectOrderListFactory = new ListFactory("/admin/getHaveOrderMedicalRecordVoList.json", pageStart, 12, $scope.data);
        var searchPromise = $scope.selectOrderListFactory.nextPage();

        searchPromise.then(function (data) {
            $(".secondpagination").pagination($scope.selectOrderListFactory.count, {
                items_per_page: pageSize,
                current_page: $scope.data.page,
                callback: function callback(index) {
                    $scope.data.page = index;
                    StorageFactory.setItem("addSaleRecord", JSON.stringify($scope.data));
                    $scope.selectOrderListFactory.clearAndSetIndex(index * pageSize);
                    $scope.selectOrderListFactory.nextPage();
                }
            });
        });
    };
    $scope.searchList();

    $scope.data.payedStatus = null;
    $scope.data.refundStatusArray = null;
    $scope.deliveryStatus = 4;
    $scope.setTab = function (tab) {
        $scope.deliveryStatus = tab;
        if (tab == 1) {
            $scope.data.payedStatus = 0;
            delete $scope.data.refundStatusArray;
        } else if (tab == 2) {
            $scope.data.payedStatus = 1;
            $scope.data.refundStatusArray = [0, 2];
        } else if (tab == 3) {
            $scope.data.payedStatus = 1;
            $scope.data.refundStatusArray = [1];
        } else {
            delete $scope.data.payedStatus;
            delete $scope.data.refundStatusArray;
        }
        $scope.clearPage();
    };

    $scope.clearPage = function () {
        $scope.data.page = 0;
        $scope.searchList();
    };
    window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (res) {
        $scope.setCompanyModal = !res;
    });

    $scope.choseUser = {
        show: false,
        open: function open() {
            this.show = true;
        },
        showChufang: true,
        register: function register() {
            $state.go("addCheckin");
        },
        affirm: function affirm(item, custView) {
            if (!item.patient.id) {
                return Popup.notice("请选择用户");
            }
            var obj = {
                patientId: item.patient.id,
                medicalRecordType: custView == 1 ? 1 : 5
            };
            new ObjectFactory().saveOrQuery("/admin/addMedicalRecord.json", obj).then(function (res) {
                if (res.status == 0) {
                    Popup.notice("新增成功");

                    if (res.object.medicalRecordType == 5) {
                        $state.go("adminSalesRecord.myMaterialBill", {
                            medicalRecordId: res.object.id,
                            patientId: res.object.patientId
                        });
                    } else {
                        $state.go("adminMyRecord.myMaterialBill", {
                            medicalRecordId: res.object.id,
                            patientId: res.object.patientId
                        });
                    }
                } else {
                    Popup.notice(res.errmsg);
                }
            });
        }
    };

    $scope.goRecord = function (medicalRecordId, medicalRecordType, patientId) {
        console.log(medicalRecordType, 'medicalRecordType');
        if (medicalRecordType == 5) {
            $state.go("adminSalesRecord.myMaterialBill", {
                medicalRecordId: medicalRecordId,
                patientId: patientId
            });
        } else {
            $state.go("adminMyRecord.myMaterialBill", {
                medicalRecordId: medicalRecordId,
                patientId: patientId
            });
        }
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("adminMyRecordCtrl", ["$scope", "HttpFactory", "Popup", "$stateParams", "$state", "ObjectFactory", "ListFactory", "$http", "$timeout", function ($scope, HttpFactory, Popup, $stateParams, $state, ObjectFactory, ListFactory, $http, $timeout) {
    $scope.medicalRecordId = $stateParams.medicalRecordId;
    $scope.$on("changeTab", function (event, msg) {
        $scope.tab = msg;
    });
    $scope.reload = {};
    $scope.reload.reloadStatus = false;
    $scope.corpMedicalConf = {};
    $scope.selectCorpMedicalConfByCorpId = function () {
        HttpFactory.object("/admin/selectCorpMedicalConfByCorpId.json").then(function (res) {
            $scope.corpMedicalConf = res;
        });
    };
    $scope.selectCorpMedicalConfByCorpId();
    /* $scope.$watch("reload.reloadStatus", function (newValue, oldValue) {
      console.log(newValue, oldValue);
      if (newValue !== oldValue) {
        if ($scope.tab == 1) {
          $scope.$broadcast("reloadRecord", 2);
        }
      }
    }); */

    $scope.setTab = function (index) {
        $scope.tab = index;
    };
    $scope.back = function () {
        window.history.go(-1);
    };
    $scope.screenCalibrationRecord = {
        show: false,
        open: function open(updatePatientFactory, customerInfoFactory) {
            this.patientInfo = updatePatientFactory.object;
            this.customerInfo = customerInfoFactory.vo;
            this.show = true;
        },
        close: function close() {
            this.show = false;
        }
    };
    $scope.showHistoryModal = function () {
        $scope.historyModal = true;
        $scope.modifyAdmin = true;
    };

    $scope.hideHistory = function () {
        $scope.historyModal = false;
        $scope.modifyAdmin = false;
    };

    $scope.date = {};

    $scope.searchCount = function () {
        $scope.countFactory = new ObjectFactory();
        $scope.countFactory.saveOrQuery("/admin/statMedicalRecordFeeCount.json", {
            medicalRecordId: $scope.medicalRecordId
        });
    };
    $scope.searchCount();

    $scope.searchInfo = function () {
        $scope.getMedicalObjectFactory = new ObjectFactory();
        var medicalPromise = $scope.getMedicalObjectFactory.saveOrQuery("/admin/getMedicalRecord.json", { id: $scope.medicalRecordId });
        medicalPromise.then(function (res) {
            $scope.patientId = res.result.object.patientId;
            $scope.date.checkYear = res.result.object.checkYear;

            $scope.updatePatientFactory = new ObjectFactory();
            var promise = $scope.updatePatientFactory.saveOrQuery("/admin/getPatientInfo.json", { id: $scope.patientId });
            promise.then(function (res) {
                $scope.customerId = res.result.object.customerId;

                /* if (res.result.object.patientBirthday) {
                    $scope.date.birthday = res.result.object.patientBirthday;
                } */
                $scope.customerInfoFactory = new ObjectFactory();
                var customerPromise = $scope.customerInfoFactory.saveOrQuery("/admin/getCustomerVo.json", { customerId: res.result.object.customerId });
            });
        });
    };
    $scope.searchInfo();
    $scope.updatePatient = {};
    $scope.updatePatient.modal = false;
    $scope.showPatient = function () {
        $scope.updatePatient.modal = true;
    };

    $scope.modal = {};
    $scope.modal.computeModal = false;
    $scope.hidePatient = function () {
        $scope.modifyAdmin = false;
        $scope.modal.computeModal = false;

        $scope.historyModal = false;
    };

    $scope.showFee = function () {
        $scope.modal.computeModal = true;

        $scope.tabSave = 1;
    };

    $scope.showEndClinic = function () {
        $scope.modal.computeModal = true;

        $scope.tabSave = 2;
    };
    $scope.showPatientModal = function () {
        $scope.updateStudentInfo.params.patientId = $scope.patientId;
        $scope.updateStudentInfo.medicalRecordId = $scope.medicalRecordId;
        $scope.updateStudentInfo.show = true;
    };
    $scope.updateStudentInfo = {
        show: false,
        params: {},
        callback: function callback(result) {
            Popup.notice("修改患者信息成功!");
            $scope.updateStudentInfo.show = false;
            $scope.searchInfo();
            if ($scope.tab == 1) {
                $scope.$broadcast("reloadRecord", 2);
            }
        }
    };
}]);
