angular.module('bestvisionWeb').controller('myMedicalRecordListCtrl', ['$scope', '$window', 'Popup', '$uibModal', '$stateParams', '$rootScope', '$state', 'ObjectFactory', 'DateUtilFactory', 'StorageFactory', 'ListFactory', '$http', function ($scope, $window, Popup, $uibModal, $stateParams, $rootScope, $state, ObjectFactory, DateUtilFactory, StorageFactory, ListFactory, $http) {

    $scope.token = localStorage.getItem('pcToken');
    var store = JSON.parse(StorageFactory.getItem('myMedicalRecordList'));
    $scope.obj = store ? store : {};
    if ($scope.obj.firstVisitFrom) {
        $scope.obj.firstVisitFrom = new Date($scope.obj.firstVisitFrom);
    }
    if ($scope.obj.rightTimer) {
        $scope.rightTimer = new Date($scope.obj.rightTimer);
    }
    $scope.sex = [{ id: 1, name: '男' }, { id: 2, name: '女' }];
    $scope.obj.customerId = $stateParams.customerId;
    $scope.obj.patientId = $stateParams.patientId;

    $scope.getCustomerInfo = function () {
        $scope.CustomerVoFactory = new ObjectFactory();
        if ($scope.obj.customerId) {
            var customerPromise = $scope.CustomerVoFactory.saveOrQuery('/admin/getCustomerVo.json', { customerId: $scope.obj.customerId });
            customerPromise.then(function (res) {
                console.log(res);
                if (res.vo) {
                    $scope.customerName = res.vo.customer.customerName;
                }
            });
        }
    };
    $scope.getCustomerInfo();

    $scope.getPaitentInfo = function () {
        $scope.getPaitentInfoFactory = new ObjectFactory();
        if ($scope.obj.patientId) {
            var patientPromise = $scope.getPaitentInfoFactory.saveOrQuery('/admin/getPatientInfo.json', { id: $scope.obj.patientId });
            patientPromise.then(function (res) {
                console.log(res);

                $scope.patientName = res.result.object.patientName;
            });
        }
    };
    $scope.getPaitentInfo();

    $scope.clearPage = function () {
        $scope.obj.page = 0;
        $scope.searchMedicalRecordlist();
    };

    $scope.searchMedicalRecordlist = function () {

        var pageSize = 12;
        var pageStart = $scope.obj.page ? $scope.obj.page * pageSize : 0;
        if ($scope.obj.firstVisitFrom) {
            $scope.obj.firstVisitFrom = DateUtilFactory.origin($scope.obj.firstVisitFrom);
        } else {
            delete $scope.obj.firstVisitFrom;
        }
        if ($scope.rightTimer) {
            $scope.obj.firstVisitTo = DateUtilFactory.plus($scope.rightTimer);
            $scope.obj.rightTimer = $scope.rightTimer;
        } else {
            delete $scope.obj.firstVisitTo;
        }

        StorageFactory.setItem('myMedicalRecordList', JSON.stringify($scope.obj));
        $scope.getMedicalRecordListFactory = new ListFactory('/admin/getMedicalRecordListOfDoctor.json', pageStart, pageSize, $scope.obj);
        var promise = $scope.getMedicalRecordListFactory.nextPage();
        promise.then(function (data) {
            console.log(data);

            $("#Pagination").pagination($scope.getMedicalRecordListFactory.count, {

                items_per_page: pageSize,
                current_page: $scope.obj.page,
                callback: function callback(index) {
                    $scope.obj.page = index;
                    StorageFactory.setItem('myMedicalRecordList', JSON.stringify($scope.obj));
                    $scope.getMedicalRecordListFactory.clearAndSetIndex(index * pageSize);
                    $scope.getMedicalRecordListFactory.nextPage();
                }
            });
        });
    };

    $scope.searchMedicalRecordlist();

    $scope.getMedicalRecord = function (id, patientId) {
        $scope.getMedicalObjectFactory = new ObjectFactory();
        var medicalPromise = $scope.getMedicalObjectFactory.saveOrQuery('/admin/getMedicalRecord.json', { id: id });
        medicalPromise.then(function (res) {

            if (res.object.medicalRecordType == 5) {
                $state.go('adminSalesRecord.myMaterialBill', { medicalRecordId: id, patientId: res.object.patientId });
            } else {
                $state.go('adminMyRecord.myMemberRecord', { medicalRecordId: id, patientId: res.object.patientId });
            };
        });
    };
    $scope.refresh = function () {

        $state.go('myMedicalRecordList', { customerId: null, patientId: null }, { reload: true });
    };

    $scope.object = {};
    $scope.quickAdd = false;
    $scope.showAddPatient = function () {
        $scope.quickAdd = true;
        $scope.modifyAdmin = true;
    };
    $scope.hidePatient = function () {
        $scope.quickAdd = false;
        $scope.modifyAdmin = false;
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("myMemberCtrl", ["$scope", "$stateParams", "Popup", "$state", "DateUtilFactory", "ObjectFactory", "HttpFactory", "ListFactory", "$http", "$timeout", function ($scope, $stateParams, Popup, $state, DateUtilFactory, ObjectFactory, HttpFactory, ListFactory, $http, $timeout) {
  $scope.getAdminConf = function () {
    window.grantAuth.getFrontAuth(ObjectFactory).then(function (res) {
      $timeout(function () {
        $scope.canTriageSelf = res;
        console.log(res.doctorTriageSelf);
        res.doctorTriageSelf === 1 ? $scope.queryWaitingList() : '';
      });
    }, function (error) {
      Popup.notice(error);
    });
  };
  $scope.getAdminConf();
  $scope.obj = {};
  $scope.obj.status = null;
  $scope.rightTime = new Date();
  $scope.search = function () {
    $scope.obj.startTime = DateUtilFactory.origin($scope.rightTime);
    $scope.obj.endTime = DateUtilFactory.plus($scope.rightTime);
    var pageSize = 9;

    $scope.memberFactory = new ListFactory("/admin/selectCustomerCheckinVoListOfEmployee.json", 0, pageSize, $scope.obj);
    var promise = $scope.memberFactory.nextPage();
    promise.then(function (data) {
      $(".Paginations").pagination($scope.memberFactory.count, {
        items_per_page: pageSize,

        callback: function callback(index) {
          $scope.memberFactory.clearAndSetIndex(index * pageSize);
          $scope.memberFactory.nextPage();
        }
      });
    });
  };
  $timeout(function () {
    $scope.search();
  });

  $scope.searchTab = function (status) {
    $scope.obj.status = status;
    $scope.search();
  };

  $scope.medical = {};

  $scope.selectMedicalType = function () {
    $scope.clinckFactory = new ObjectFactory();
    var clinckPromise = $scope.clinckFactory.saveOrQuery("/admin/beginCustomerCheckin.json", { customerCheckinId: $scope.customerCheckinId, medicalRecordType: 1 });
    clinckPromise.then(function (response) {
      if (response.status == 1) {
        Popup.notice(response.errmsg, 2000, function () {});
        $state.go("myMember", {}, { reload: true });
      } else {
        $scope.getMedicalTypeFactory = new ObjectFactory();
        var typePromise = $scope.getMedicalTypeFactory.saveOrQuery("/admin/getMedicalRecord.json", { id: response.result.vo.customerCheckin.medicalRecordId });
        typePromise.then(function (res) {
          if (res.object.medicalRecordType == 5) {
            $state.go("adminSalesRecord.myMaterialBill", {
              medicalRecordId: res.object.id,
              patientId: $scope.patientId
            });
          } else {
            $state.go("adminMyRecord.myMemberRecord", {
              medicalRecordId: res.object.id,
              patientId: $scope.patientId
            });
          }
        });
      }
    });
  };

  $scope.getMedicalRecord = function (id, patientId) {
    $scope.getMedicalObjectFactory = new ObjectFactory();
    var medicalPromise = $scope.getMedicalObjectFactory.saveOrQuery("/admin/getMedicalRecord.json", { id: id });
    medicalPromise.then(function (res) {
      if (res.object.medicalRecordType == 5) {
        $state.go("adminSalesRecord.myMaterialBill", {
          medicalRecordId: id,
          patientId: res.object.patientId
        });
      } else {
        $state.go("adminMyRecord.myMemberRecord", {
          medicalRecordId: id,
          patientId: res.object.patientId
        });
      }
    });
  };

  $scope.clinck = function (id, patientId) {
    $scope.customerCheckinId = id;
    $scope.patientId = patientId;

    Popup.confirm("为该用户创建电子病历？", function () {
      $scope.selectMedicalType();
    }, function () {});
  };
  $scope.queryWaitingList = function () {
    var obj = {
      status: 0,
      keyword: '',
      index: 0,
      length: 20,
      sortType: 'ASC'
    };
    var today = new Date();
    obj.startTime = DateUtilFactory.origin(today);
    obj.endTime = DateUtilFactory.plus(today);
    new ObjectFactory().saveOrQuery("/admin/selectCustomerCheckinVoListOfCompany.json", obj).then(function (res) {
      $scope.waitingList = res.result;
    });
  };
  $scope.receiveSelfAndBeginCustomerCheckin = function (customerCheckinId) {
    Popup.confirm("为该用户创建电子病历？", function () {
      HttpFactory.object('/admin/receiveSelfAndBeginCustomerCheckin.json', {
        customerCheckinId: customerCheckinId,
        medicalRecordType: 1
      }).then(function (res) {
        if (res.status) {
          return Popup.notice(res.errmsg);
        }
        $state.go("adminMyRecord.myMemberRecord", {
          medicalRecordId: res.customerCheckin.medicalRecordId,
          patientId: res.patient.id
        });
      });
    });
  };
}]);
