      var brand = v.brand,
          medicalProduct = v.medicalProduct,
          medicalProductSign = v.medicalProductSign,
          unLockExistSkuCount = v.unLockExistSkuCount,
          lockStorehouse = v.lockStorehouse,
          product = v.product,
          productSku = v.productSku;

      var signType = medicalProductSign.signType + 1;
      // let num = signType == 3 ? "3" : "";
