angular.module("bestvisionWeb").controller("refundFeeCtrl", ["$scope", "Popup", "DateUtilFactory", "$uibModal", "$stateParams", "$state", "ObjectFactory", "ListFactory", "$http", "$timeout", function ($scope, Popup, DateUtilFactory, $uibModal, $stateParams, $state, ObjectFactory, ListFactory, $http, $timeout) {
  $scope.adminConf = {};
  $scope.getAdminConf = function () {
    window.grantAuth.getFrontAuth(ObjectFactory).then(function (res) {
      $timeout(function () {
        $scope.adminConf = res;
      });
    }, function (error) {
      Popup.notice(error);
    });
  };
  $scope.getAdminConf();
  $scope.schoolInfo = {
    name: "schoolInfo",
    idName: "schoolInfo",
    ajaxUrl: "/admin/getSchoolVoList.json",
    ajaxParams: {
      schoolType: 0
    },
    isshow: false,
    id: "",
    inputVal: "",
    inputPlaceHolder: "请选择学校",
    info: null,
    key: "school",
    key2: "schoolName",
    fn: function fn() {
      $scope.obj.schoolId = this.id ? this.id : null;
      $scope.searchEmployeeRank();
    },
    type: "Object"
  };
  var pageSize = 20;
  $scope.obj = {
    startTime: "",
    endTime: ""
  };
  $scope.data = {};
  // $scope.obj.refundStatus = 0;
  // $scope.date = $stateParams.date;
  $scope.status = [{ id: "", name: "全部" }, { id: 0, name: "现金" }, { id: 1, name: "微信支付" }, { id: 2, name: "支付宝支付" }, { id: 3, name: "银行卡" }];
  $scope.token = localStorage.getItem("pcToken");

  $scope.obj.companyId = "";

  $scope.showSelect = function (cashflowId) {
    $scope.cashflowId = cashflowId;
  };
  $scope.hideSelect = function () {
    $scope.cashflowId = null;
  };

  $scope.otherPay = {};
  $scope.payObjectFactory = new ObjectFactory();
  var paypromise = $scope.payObjectFactory.saveOrQuery("/admin/getCorpPayChannel.json");
  paypromise.then(function (res) {
    var obj = res.result.object;
    $scope.otherPay.channelName1 = obj.channelName1;
    $scope.otherPay.channelName2 = obj.channelName2;
    $scope.otherPay.channelName3 = obj.channelName3;
    $scope.otherPay.channelName4 = obj.channelName4;
    $scope.otherPay.channelName5 = obj.channelName5;
  });
  $scope.unpayListPopout = {
    show: false,
    single: true, //只显示单条数据
    params: { customerId: null },
    callback: function callback() {
      this.show = false;
      this.params.customerId = null;
    }
  };
  $scope.goDetail = function (refund) {
    console.log(refund);
    if (refund.refundScene === 1) {
      var url = $state.href("payBackDetail", { refundLogId: refund.refundSourceId });
      window.open(url, "_blank");
      return;
    }
    $scope.unpayListPopout.params.customerId = refund.refundSourceId;
    $scope.unpayListPopout.show = true;
  };

  $scope.data.startTime = DateUtilFactory.setWuiNowZero();
  $scope.data.rightTimer = DateUtilFactory.setWuiNow();
  $scope.dealList = function (data) {
    $scope.pageList = [];
    var isFirst = true;
    var pageList = data.reduce(function (pre, next) {
      isFirst = true;
      next.feeDataList.forEach(function (feeData) {
        if (isFirst) {
          Object.assign(feeData, next);
        }
        pre.push(feeData);
        isFirst = false;
      });
      return pre;
    }, []);
    // console.log(pageList);
    $scope.pageList = pageList;
  };
  $scope.searchEmployeeRank = function () {
    // console.log($scope.data.startTime);
    // console.log($scope.data.rightTimer);
    if ($scope.data.startTime && $scope.data.rightTimer) {
      $scope.obj.startTime = DateUtilFactory.originMin($scope.data.startTime);
      $scope.obj.endTime = DateUtilFactory.plusMinute($scope.data.rightTimer);

      $scope.EmployeeList = new ListFactory("/admin/selectCashflowRefundFeeVoList.json", 0, pageSize, $scope.obj);
      var promise = $scope.EmployeeList.nextPage();
      promise.then(function (data) {
        $scope.dealList(data.items);
        $("#Pagination").pagination($scope.EmployeeList.count, {
          items_per_page: pageSize,
          callback: function callback(index) {
            $scope.EmployeeList.clearAndSetIndex(index * pageSize);
            $scope.EmployeeList.nextPage().then(function (res) {
              $scope.dealList(res.items);
            });
          }
        });
      });
    }
  };
  $scope.searchEmployeeRank();
}]);
"use strict";

