angular.module("bestvisionWeb").controller("successRateCtrl", ["$scope", "ArraySet", "DateUtilFactory", "daochuFactory", "HttpFactory", "$stateParams", "$state", "ObjectFactory", "ListFactory", "$http", "$timeout", function ($scope, ArraySet, DateUtilFactory, daochuFactory, HttpFactory, $stateParams, $state, ObjectFactory, ListFactory, $http, $timeout) {
  var corpInfo = localStorage.getItem('corpInfo');
  corpInfo = corpInfo == null ? { companyTitle: '门店', employeeTitle: '视光师' } : JSON.parse(corpInfo);
  $scope.obj = {
    startTime: new Date(),
    rightTimer: new Date(),
    endTime: ""
  };

  $scope.token = localStorage.getItem("pcToken");

  var authStr = daochuFactory.getAuthStr();

  $scope.daochu = function () {
    window.location.href = API_HOST + "/admin/downloadEmployeeSuccessRateList.htm?startTime=" + $scope.obj.startTime.getTime() + "&endTime=" + $scope.obj.endTime.getTime() + "&employeeType=" + $scope.defineList[$scope.defineIndex].tab + authStr;
  };
  $scope.defineList = [{
    name: '单次推荐人',
    url: 'getFirstDoctorSalesDataList',
    tab: 1,
    colspan: 5,
    showCategory: true
  }, {
    name: '接诊' + corpInfo.employeeTitle,
    url: 'getDoctorSalesDataList',
    tab: 2,
    colspan: 6,
    showPerf: true
  }, {
    name: '验配师',
    url: 'getOptometristSalesDataList',
    tab: 3,
    colspan: 4
  }, {
    name: '会员推荐人',
    url: 'getIntroducerSalesDataList',
    showCategory: true,
    tab: 4,
    colspan: 5
  }, {
    name: '成交人',
    url: 'getDealdoneEmployeeSalesDataList',
    tab: 5,
    colspan: 4
  }, {
    name: '维护人',
    url: 'getServiceEmployeeSalesDataList',
    tab: 6,
    colspan: 4
  }];
  $scope.defineIndex = 0;

  $scope.setDefineIndex = function (index) {
    $scope.defineIndex = index;
    $scope.searchEmployeeRank();
  };
  $scope.echartsBarParams = {
    show: false,
    name: '缴费金额',
    seriesData: [],
    yAxis: []
  };
  $scope.searchEmployeeRank = function () {
    $scope.echartsBarParams.show = false;
    if ($scope.obj.startTime && $scope.obj.rightTimer) {
      // let obj = angular.copy($scope.obj)
      /* obj.index = 0;
      obj.length = 10; */
      $scope.obj.startTime = DateUtilFactory.origin($scope.obj.startTime);
      $scope.obj.endTime = DateUtilFactory.plus($scope.obj.rightTimer);
      var url = "/admin/" + $scope.defineList[$scope.defineIndex].url + ".json";
      HttpFactory.list(url, $scope.obj).then(function (res) {
        var yAxis = [],
            cashflow = [],
            employeeList = [];
        var byFormType = {};
        res.list.forEach(function (v) {
          yAxis.push(!v.employeeName ? '无' : v.employeeName);
          cashflow.push(v.cashflowReceivedFromCashier);
          var empList = [{
            value: v.employeeName ? v.employeeName : '无'
          }, {
            value: v.medicalRecordCount
          }, {
            value: v.medicalRecordPatientCount
          }, {
            value: v.cashflowReceivedFromCashier
          }];
          if ($scope.defineList[$scope.defineIndex].showPerf) {
            empList.push({ value: v.kpiTotalMoney });
            empList.push({ type: 'details', value: '详情', id: v.employeeId });
          }
          if ($scope.defineList[$scope.defineIndex].showCategory) {
            !byFormType[v.employeeFromType] && (byFormType[v.employeeFromType] = []);
            byFormType[v.employeeFromType].push(empList);
          } else {
            employeeList.push(empList);
          }
        });
        if ($scope.defineList[$scope.defineIndex].showCategory) {
          for (var i in byFormType) {
            byFormType[i][0].unshift({
              value: window.optionsObj.fromType[i], //v.employeeFromType
              rowspan: byFormType[i].length
            });
            employeeList = employeeList.concat(byFormType[i]);
          }
        }
        $scope.echartsBarParams.yAxis = yAxis;
        $scope.echartsBarParams.seriesData = cashflow;
        $scope.EmployeeList = employeeList;
        $scope.echartsBarParams.show = true;
      });
    }
  };
  $scope.searchEmployeeRank();
  $scope.PerformanceDetail = {
    show: false,
    employeeId: null,
    list: [],
    open: function open(employeeId) {
      this.employeeId = employeeId;
      this.show = true;
      this.callback(0, true);
    },
    callback: function callback(index, loadPagin) {
      var startTime = DateUtilFactory.origin($scope.obj.startTime);
      var endTime = DateUtilFactory.plus($scope.obj.rightTimer);
      HttpFactory.list('/admin/selectMedicalProductKpiDataListOfEmployee.json', {
        employeeId: $scope.PerformanceDetail.employeeId,
        startTime: startTime,
        endTime: endTime,
        index: index,
        length: 10
      }).then(function (res) {
        $scope.PerformanceDetail.list = res.list;
        loadPagin && HttpFactory.pagination("#Pagination", res, $scope.PerformanceDetail.callback);
      });
    },
    close: function close() {
      this.show = false;
    },
    affrim: function affrim() {
      this.show = false;
    }
  };
}]);
"use strict";

