angular.module("bestvisionWeb").controller("dataChartCtrl", ["$scope", "DateUtilFactory", "Popup", "$state", "$stateParams", "ObjectFactory", "utilFactory", "$timeout", function ($scope, DateUtilFactory, Popup, $state, $stateParams, ObjectFactory, utilFactory, $timeout) {
  $scope.obj = {};
  $scope.gender = {};
  $scope.teen = {};
  $scope.mapDest = {};
  $scope.teen.tab = 1;
  $scope.mapDest.tab = 1;

  $scope.cityArr = [];

  $scope.today = new Date();
  $scope.showSelectPlan = function () {
    $scope.obj.showPlanModal = true;
  };

  $scope.changeTeen = function () {
    $scope.teenArr = [];
    $scope.getPromotionVisionYearFactory = new ObjectFactory();
    var visionYearPromise = $scope.getPromotionVisionYearFactory.saveOrQuery("/admin/basicStatVisionOfManageOfCheckYear.json", $scope.obj);
    visionYearPromise.then(function (res) {
      var arr = res.result.list;
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].checkYear) {
          if ($scope.teen.tab == 2) {
            $scope.teenArr.push([arr[i].checkYear + "岁", ((arr[i].visionAlert1Rate + arr[i].visionAlert2Rate + arr[i].visionAlert3Rate) * 100).toFixed(2)]);
          } else {
            $scope.teenArr.push([arr[i].checkYear + "岁", (arr[i].dioptersAlertRate * 100).toFixed(2)]);
          }
        }
      }
    });
  };

  $scope.changeDest = function () {
    $scope.areaArr = [];

    $scope.areaMapChart = false;

    $scope.getPromotionVisionYearFactory = new ObjectFactory();
    var visionAreaPromise = $scope.getPromotionVisionYearFactory.saveOrQuery("/admin/basicStatVisionOfManageOfArea.json", $scope.obj);
    visionAreaPromise.then(function (res) {
      var arr = res.result.list;
      var alertVal;
      for (var i = 0; i < arr.length; i++) {
        if ($scope.mapDest.tab == 1) {
          alertVal = arr[i].dioptersAlertRate * 100;
        } else {
          alertVal = (arr[i].visionAlert1Rate + arr[i].visionAlert2Rate + arr[i].visionAlert3Rate) * 100;
        }

        if (arr[i].area) {
          if (!$scope.obj.provinceAreaId) {
            $scope.areaArr[i] = {
              name: arr[i].area.shortName,
              value: alertVal
            };
          }
          if ($scope.obj.provinceAreaId) {
            $scope.areaArr[i] = { name: arr[i].area.name, value: alertVal };
          }
        }
      }
      $scope.areaMapChart = true;
    });
  };
  $scope.searchAll = function () {
    $scope.progressNumber = null;
    $scope.manageChart = false;
    $scope.shanChart = false;
    $scope.genderChart = false;
    $scope.beforeNumber = [];
    $scope.totalNumber = [];
    $scope.getPromotionVisionFactory = new ObjectFactory();
    var managePromise = $scope.getPromotionVisionFactory.saveOrQuery("/admin/basicStatVisionOfManage.json", $scope.obj);
    managePromise.then(function (res) {
      var total = res.result.object.schoolMateCount + "";
      var totalArr = total.split("");
      if ($scope.getPromotionVisionFactory.result.object.schoolMateCount) {
        $scope.progressNumber = $scope.getPromotionVisionFactory.result.object.examinedSchoolMateCount / $scope.getPromotionVisionFactory.result.object.schoolMateCount * 100;
      } else {
        $scope.progressNumber = 0;
      }

      if (totalArr.length > 3) {
        $scope.beforeNumber = totalArr.slice(0, -3);
        $scope.totalNumber = totalArr.slice(-3);
      } else {
        $scope.totalNumber = totalArr;
      }
      console.log($scope.totalNumber, "total");
      $scope.manageChart = true;
    });
    $scope.threeAlertArr = [];
    $scope.threeYearArr = [];

    $scope.threeVisionArr = [];
    $scope.getPromotionVisionLastYearFactory = new ObjectFactory();
    var lastYearPromise = $scope.getPromotionVisionLastYearFactory.saveOrQuery("/admin/basicStatVisionOfManageOfLast3Year.json", $scope.obj);
    lastYearPromise.then(function (res) {
      var arr = res.result.list;

      for (var i = 0; i < arr.length; i++) {
        $scope.threeYearArr[i] = arr[i].schoolPlanRoot.planName;
        $scope.threeAlertArr[i] = (arr[i].dioptersAlertRate * 100).toFixed(2);
        $scope.threeVisionArr[i] = ((arr[i].visionAlert1Rate + arr[i].visionAlert2Rate + arr[i].visionAlert3Rate) * 100).toFixed(2);
      }
    });
    $scope.changeTeen();
    $scope.schoolArr = [];
    $scope.alertArr = [];
    $scope.jinshiArr = [];
    $scope.schoolNameArr = [];
    $scope.getPromotionVisionSchoolFactory = new ObjectFactory();
    var visionSchoolPromise = $scope.getPromotionVisionSchoolFactory.saveOrQuery("/admin/basicStatVisionOfManageOfSchoolLevel.json", $scope.obj);
    visionSchoolPromise.then(function (res) {
      var arr = res.result.list;
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].schoolLevel) {
          $scope.schoolArr.push({
            name: arr[i].schoolLevel.schoolLevelName,
            value: arr[i].examinedSchoolMateCount
          });
          $scope.schoolNameArr.push(arr[i].schoolLevel.schoolLevelName);
        }

        $scope.jinshiArr[i] = (arr[i].dioptersAlertRate * 100).toFixed(2);
        $scope.alertArr[i] = ((arr[i].visionAlert1Rate + arr[i].visionAlert2Rate + arr[i].visionAlert3Rate) * 100).toFixed(2);
      }
      $scope.shanChart = true;
    });
    $scope.gender.manAlertCount = 0;
    $scope.gender.womanAlertCount = 0;
    $scope.getPromotionVisionGenderFactory = new ObjectFactory();
    var visionPromise = $scope.getPromotionVisionGenderFactory.saveOrQuery("/admin/basicStatVisionOfManageOfGender.json", $scope.obj);
    visionPromise.then(function (res) {
      var arr = res.result.list;
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].gender == 1) {
          $scope.gender.manAlertCount = arr[i].dioptersAlertCount;
        }
        if (arr[i].gender == 2) {
          $scope.gender.womanAlertCount = arr[i].dioptersAlertCount;
        }
      }
      $scope.genderChart = true;
    });
  };
  $scope.accessor = {};

  $scope.searchAreaMap = function () {
    console.log("是不是执行了");
    var areaId;

    if ($scope.obj.provinceAreaId) {
      areaId = $scope.obj.provinceAreaId;
    }
    if ($scope.obj.cityAreaId) {
      areaId = $scope.obj.cityAreaId;
    }
    if ($scope.obj.districtAreaId) {
      areaId = $scope.obj.districtAreaId;
    }
    $scope.getAreaFactory = new ObjectFactory();
    var areaPro = $scope.getAreaFactory.saveOrQuery("/admin/getArea.json", {
      areaId: areaId
    });
    areaPro.then(function (res) {
      $scope.changePlan();
    });
  };

  $scope.test = function () {
    if ($scope.obj.provinceAreaId && !$scope.obj.cityAreaId) {
      if ($scope.accessor.getProvince) {
        $scope.accessor.getProvince(1);
      }
    }
    if ($scope.obj.cityAreaId && !$scope.obj.districtAreaId) {
      if ($scope.accessor.getDistrict) {
        $scope.accessor.getDistrict(1);
      }
    }
    if ($scope.obj.districtAreaId) {
      if ($scope.accessor.getSchool) {
        $scope.accessor.getSchool(1);
      }
    }
  };
  $scope.searchMap = function () {
    $scope.areaArr = [];
    $scope.cityArr = [];
    $scope.areaMapChart = false;

    $scope.getPromotionVisionYearFactory = new ObjectFactory();
    var visionAreaPromise = $scope.getPromotionVisionYearFactory.saveOrQuery("/admin/basicStatVisionOfManageOfArea.json", $scope.obj);
    visionAreaPromise.then(function (res) {
      var arr = res.result.list;
      var tempArr = [];
      for (var i = 0; i < arr.length; i++) {
        var alertVal = (arr[i].dioptersAlertRate * 100).toFixed(2);

        if (arr[i].area) {
          if (!$scope.obj.provinceAreaId) {
            $scope.areaArr[i] = {
              name: arr[i].area.shortName,
              value: alertVal
            };
          }
          if ($scope.obj.provinceAreaId) {
            $scope.areaArr[i] = { name: arr[i].area.name, value: alertVal };
          }
          tempArr.push({
            name: arr[i].area.name,
            value: alertVal
          });
        }
      }

      var tempArrFive = tempArr.sort(function (a, b) {
        return b.value - a.value;
      });
      $scope.cityArr = tempArrFive.slice(0, 5);
      $scope.areaMapChart = true;
    });
  };

  $scope.changePlan = function () {
    $scope.searchMap();
    $scope.searchAll();
  };

  $scope.getPlan = function () {
    new ObjectFactory().saveOrQuery("/admin/getDefaultSchoolPlanRootByAdminId.json").then(function (resp) {
      if (resp.result.object) {
        $scope.obj.planName = resp.result.object.planName;
        $scope.obj.schoolPlanId = resp.result.object.id;
        // $scope.changePlan();
      } else {
        $scope.obj.planName = "请选择筛查计划";
      }
    });
  };
  $scope.getPlan();
}]);
"use strict";

