angular.module("bestvisionWeb").controller("modifySchoolPlanCtrl", ["$scope", "DateUtilFactory", "Popup", "$state", "$stateParams", "ObjectFactory", "utilFactory", "$http", function ($scope, DateUtilFactory, Popup, $state, $stateParams, ObjectFactory, utilFactory, $http) {
  $scope.obj = {};
  if ($scope.$state.current.name == "modifySchoolPlan") {
    $scope.isAreaPlan = false;
    $scope.obj.schoolPlanId = $stateParams.schoolPlanId;
    $scope.getAddressObjectFactory = new ObjectFactory();
    var getPromise = $scope.getAddressObjectFactory.saveOrQuery("/admin/getSchoolPlan.json", { schoolPlanId: $stateParams.schoolPlanId });
    getPromise.then(function (res) {
      $scope.obj.planName = res.result.object.planName;
      // $scope.planTrueName = res.result.object.planNam.slice(7)
      $scope.obj.remark = res.result.object.remark;
      $scope.obj.season = res.result.object.season;
      $scope.obj.year = res.result.object.year;
    });
  } else {
    $scope.isAreaPlan = true;
    $scope.obj.schoolPlanRootId = $stateParams.schoolPlanId;
    $scope.getAddressObjectFactory = new ObjectFactory();
    var getPromise = $scope.getAddressObjectFactory.saveOrQuery("/admin/getSchoolPlanRoot.json", { schoolPlanRootId: $stateParams.schoolPlanId });
    getPromise.then(function (res) {
      $scope.obj.planName = res.result.object.planName;
      // $scope.planTrueName = res.result.object.planNam.slice(7)
      $scope.obj.remark = res.result.object.remark;
      $scope.obj.season = res.result.object.season;
      $scope.obj.year = res.result.object.year;
    });
  }
  $scope.inYears = utilFactory.getInSchoolYear();

  $scope.setSeason = function (tab) {
    $scope.obj.season = tab;
    // if ($scope.isAreaPlan) {
    // }
    $scope.autoName();
  };

  $scope.autoName = function () {
    $scope.obj.planName = $scope.obj.year + "年" + ($scope.obj.season ? window.optionsObj.seasson[$scope.obj.season] : "");
  };
  $scope.addPlan = function () {
    if (!$scope.obj.planName) {
      Popup.notice("体验计划名称不能为空", 2000, function () {});
      return false;
    }
    if (!$scope.obj.year) {
      Popup.notice("所属年份不能为空", 2000, function () {});
      return false;
    }
    if (!$scope.obj.season) {
      Popup.notice("所属季度不能为空", 2000, function () {});
      return false;
    }
    var url = "/admin/updateSchoolPlan.json";
    if ($scope.isAreaPlan) {
      url = "/admin/updateSchoolPlanRoot.json";
    }
    $scope.addAddressObjectFactory = new ObjectFactory();
    var insertpromise = $scope.addAddressObjectFactory.saveOrQuery(url, $scope.obj);
    insertpromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        if ($scope.isAreaPlan) {
          $state.go("areaSchoolPlanList");
        } else {
          $state.go("schoolPlanList");
        }
      }
    });
  };
}]);
'use strict';

angular.module('bestvisionWeb').controller('modifyScreenPromotionCtrl', ['$scope', '$timeout', 'DateUtilFactory', 'QiniuFactory', '$stateParams', 'Popup', '$rootScope', '$state', 'ObjectFactory', 'ListFactory', '$http', function ($scope, $timeout, DateUtilFactory, QiniuFactory, $stateParams, Popup, $rootScope, $state, ObjectFactory, ListFactory, $http) {

    $scope.obj = {};
    $scope.obj.id = $stateParams.promotionId;
    $scope.obj.schoolPlanId = $stateParams.schoolPlanId;
    $scope.getPromotionFactory = new ObjectFactory();
    var promotionPromise = $scope.getPromotionFactory.saveOrQuery('/admin/getPromotionVo.json', { id: $scope.obj.id });
    promotionPromise.then(function (res) {
        $scope.obj.title = res.result.object.promotion.title;
        $scope.obj.address = res.result.object.promotion.address;
        $scope.obj.remark = res.result.object.promotion.remark;
        $scope.checkType = res.result.object.promotion.checkType;
        $scope.obj.classId = res.result.object.promotion.classId;
        $scope.obj.schoolId = res.result.object.promotion.schoolId;
        $scope.obj.teacherId = res.result.object.promotion.teacherId;
        $scope.startTime = new Date(res.result.object.promotion.startTime);

        if ($scope.obj.classId) {
            $scope.getClassFactory = new ObjectFactory();
            var classPromise = $scope.getClassFactory.saveOrQuery('/admin/getSchoolClass.json', { id: $scope.obj.classId });
            classPromise.then(function (res) {
                $scope.classKeyword = res.result.object.className;
            });
        }
        if ($scope.obj.schoolId) {
            $scope.getSchoolObjectFactory = new ObjectFactory();
            var schoolPromise = $scope.getSchoolObjectFactory.saveOrQuery('/admin/getSchoolInfo.json', { id: $scope.obj.schoolId });
            schoolPromise.then(function (res) {

                $scope.modifySchoolName = res.result.object.schoolName;
                $scope.homeName = res.result.object.schoolName;
            });
        }
        if ($scope.obj.teacherId) {
            $scope.getTeacherObjectFactory = new ObjectFactory();
            var teacherpromise = $scope.getTeacherObjectFactory.saveOrQuery('/admin/getSchoolTeacher.json', { id: $scope.obj.teacherId });
            teacherpromise.then(function (res) {

                $scope.modifyTeacherName = res.result.vo.schoolTeacher.teacherName;
            });
        }
    });

    $scope.modify = function () {

        if (!$scope.obj.title) {
            Popup.notice('请输入活动名称');
            return false;
        }

        if ($scope.checkType) {
            if (!$scope.obj.schoolId) {
                Popup.notice('请选择社区');
                return false;
            }
            $scope.obj.classId = null;
            $scope.obj.teacherId = null;
        } else {
            if (!$scope.obj.schoolId) {
                Popup.notice('请选择学校');
                return false;
            }
            if (!$scope.obj.classId) {
                Popup.notice('请选择班级');
                return false;
            }
        }

        $scope.obj.startTime = DateUtilFactory.origin($scope.startTime);
        $scope.obj.endTime = moment(moment($scope.obj.startTime).add(1, 'days').format('x') - 1000)._d;

        $scope.savePromotionFactory = new ObjectFactory();
        var promise = $scope.savePromotionFactory.saveOrQuery('/admin/updatePromotionOfSchool.json', $scope.obj);
        promise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg);
            } else {
                Popup.notice('保存成功');

                var syncPromotionFactory = new ObjectFactory();
                syncPromotionFactory.saveOrQuery('/admin/syncSchoolInfoOfPromotion.json', { promotionId: $scope.obj.id });
                // $state.go('screenPromotionList');
                window.history.back();
            }
        });
    };

    $scope.modifySchoolList = function () {
        $scope.schoolListFactory = new ListFactory('/admin/getSchoolList.json', 0, 10, { keyword: $scope.modifySchoolName, schoolType: 0 });
        $scope.schoolListFactory.nextPage();
        $scope.schoollist = true;
    };
    $scope.hideSchoolList = function () {
        if (!$scope.modifySchoolName) {
            $scope.obj.schoolId = null;
        }
        $timeout(function () {
            $scope.schoollist = false;
        }, 300);
    };

    $scope.modifySchool = function (id, name) {
        if (id != $scope.obj.schoolId) {
            $scope.obj.classId = null;
            $scope.classKeyword = null;
        }

        $scope.modifySchoolName = name;
        $scope.obj.schoolId = id;
    };

    $scope.getClassList = function () {
        $scope.classListFactory = new ListFactory('/admin/getSchoolClassList.json', 0, 50, { keyword: $scope.classKeyword, schoolId: $scope.obj.schoolId });
        $scope.classListFactory.nextPage();
        $scope.classlist = true;
    };

    $scope.hideClassList = function () {

        if (!$scope.classKeyword) {
            $scope.obj.classId = null;
        }
        $timeout(function () {
            $scope.classlist = false;
        }, 300);
    };

    $scope.chooseClass = function (name, id) {
        $scope.classKeyword = name;
        $scope.obj.classId = id;
    };

    $scope.getTeacherList = function () {
        $scope.teacherListFactory = new ListFactory('/admin/getSchoolTeacherList.json', 0, 10, { keyword: $scope.teacherKeyword, schoolId: $scope.obj.schoolId });
        $scope.teacherListFactory.nextPage();
        $scope.teacherlist = true;
    };
    $scope.modifyTeacherList = function () {
        $scope.teacherListFactory = new ListFactory('/admin/getSchoolTeacherList.json', 0, 10, { keyword: $scope.modifyTeacherName, schoolId: $scope.obj.schoolId });
        $scope.teacherListFactory.nextPage();
        $scope.teacherlist = true;
    };
    $scope.hideTeacherList = function () {
        if (!$scope.modifyTeacherName) {
            $scope.obj.teacherId = null;
        }
        $timeout(function () {
            $scope.teacherlist = false;
        }, 300);
    };

    $scope.chooseTeacher = function (id, name) {
        $scope.teacherKeyword = name;
        $scope.obj.teacherId = id;
    };
    $scope.modifyTeacher = function (id, name) {
        $scope.modifyTeacherName = name;
        $scope.obj.teacherId = id;
    };

    $scope.modifyHomeList = function () {
        $scope.homeListFactory = new ListFactory('/admin/getSchoolList.json', 0, 10, { keyword: $scope.homeName, schoolType: 1 });
        $scope.homeListFactory.nextPage();
        $scope.homelist = true;
    };
    $scope.hideHomeList = function () {

        if (!$scope.homeName) {
            $scope.obj.schoolId = null;
        }
        $timeout(function () {
            $scope.homelist = false;
        }, 300);
    };

    $scope.modifyHome = function (id, name) {
        $scope.homeName = name;
        $scope.obj.schoolId = id;
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("multiImportStudentCtrl", ["$scope", "DateUtilFactory", "Popup", "$state", "ObjectFactory", "ListFactory", "$http", "$timeout", "daochuFactory", function ($scope, DateUtilFactory, Popup, $state, ObjectFactory, ListFactory, $http, $timeout, daochuFactory) {
  $scope.tab = 1;
  $scope.switchTab = function (tab) {
    $scope.tab = tab;
    $scope.init();
  };
  $scope.obj = {};
  $scope.data = {};
  $scope.obj.schoolName = "请选择学校";
  $scope.obj.showModal = false;
  $scope.obj.inYear = null;
  $scope.obj.schoolPlanId = null;
  $scope.obj.classId = null;
  $scope.showSelectSchool = function () {
    $scope.obj.showModal = true;
  };
  $scope.showAll = function () {
    $scope.downloadModal = true;
    $scope.saveModal = true;
  };
  $scope.hideAll = function () {
    $scope.downloadModal = false;
    $scope.saveModal = false;
  };
  $scope.init = function () {
    // 获取初始化的筛查计划
    $scope.queryPlan();
    $scope.obj.schoolId = null;
    $scope.obj.schoolName = "请选择学校";
    $scope.schoolPromotionFactory = null;
    $scope.data.filepath = null;
    $scope.createTaskFactory = null;
    $scope.taskListFactory = null;
  };
  // 查询眼科字段
  $scope.queryBodyCorp = function () {
    new ObjectFactory().saveOrQuery("/admin/selectBodyCheckItemListOfCorp.json").then(function (res) {
      $scope.bodyCorpList = res.result.list;
    });
  };
  $scope.queryBodyCorp();
  $scope.queryPlan = function () {
    $scope.getDefaultObjectFactory = new ObjectFactory();
    var defaultpromise = $scope.getDefaultObjectFactory.saveOrQuery("/admin/getDefaultSchoolPlanByAdminId.json");
    defaultpromise.then(function (res) {
      if (!$scope.getDefaultObjectFactory.result.object) {
        $scope.setPlanModal = true;
        return false;
      }
      $scope.obj.schoolPlanId = $scope.getDefaultObjectFactory.result.object.id;
    });
  };
  $scope.queryPlan();

  $scope.searchClass = function () {
    new ObjectFactory().saveOrQuery("/admin/startSchoolPlanSchool.json", {
      schoolId: $scope.obj.schoolId,
      schoolPlanId: $scope.obj.schoolPlanId
    });

    $scope.schoolPromotionFactory = new ListFactory("/admin/selectSchoolPromotionListVoList.json", 0, 200, { schoolPlanId: $scope.obj.schoolPlanId, schoolId: $scope.obj.schoolId });
    $scope.schoolPromotionFactory.nextPage();
  };
  $scope.promotion = {};
  $scope.searchMateName = function (promotionId, name) {
    $scope.promotion.promotionId = promotionId;
    $scope.classmateName = name;

    $scope.mateNameFactory = new ListFactory("/admin/selectSchoolMateCheckVoList.json", 0, 200, { promotionId: promotionId, sortName: "smc.id", sortType: "DESC", status: 0 });
    $scope.mateNameFactory.nextPage();
  };

  $scope.addClass = function () {
    if (!$scope.obj.schoolId) {
      Popup.notice("请选择学校");
      return false;
    }
    var str = API_HOST + "/pc/index.html#!/classList?schoolId=" + $scope.obj.schoolId;
    window.open(str, "_blank");
  };
  $scope.addSchool = function () {
    var str = API_HOST + "/pc/index.html#!/schoolList";
    window.open(str, "_blank");
  };

  $scope.errDisable = true;
  $scope.searchs = function () {
    $scope.errDisable = true;
    var status = 0;
    if (!$scope.obj.schoolPlanId) {
      Popup.notice("请选择筛查计划");
      return false;
    }
    if (!$scope.obj.schoolId) {
      Popup.notice("请选择学校");
      return false;
    }
    $scope.fileType = $scope.tab == 1 ? 8 : 13;
    if (!$scope.data.filepath) {
      Popup.notice("请选择需要导入的文件");
      return false;
    }

    $scope.createTaskFactory = new ObjectFactory();
    var createPromise = $scope.createTaskFactory.saveOrQuery("/admin/createBatchSchoolMateTask.json", {
      filePath: $scope.data.filepath,
      schoolId: $scope.obj.schoolId,
      classId: $scope.obj.classId,
      fileType: $scope.fileType,
      schoolPlanId: $scope.obj.schoolPlanId
    });
    createPromise.then(function (res) {
      $scope.taskId = res.result.object.id;

      if (res.status == 0) {
        if (res.result.object.msg) {
          Popup.notice(res.result.object.msg);
          $scope.errDisable = true;
          status = 1;
        } else {
          $scope.errDisable = false;
        }

        $scope.taskListFactory = new ListFactory("/admin/selectTaskItemList.json", 0, 100, { taskId: $scope.taskId, status: status });
        var taskPromise = $scope.taskListFactory.nextPage();
        taskPromise.then(function (res) {
          res.items.forEach(function (v) {
            var newBody = {};
            newBody = Object.assign(newBody, v.bodyCheckEyeOther, v.bodyCheckInternal, v.bodyCheckLook, v.bodyCheckOut, v.bodyCheckSense, v.bodyCheckTooth);
            v["newBody"] = newBody;
          });
          var pageSize = 100;
          $("#Pagination").pagination($scope.taskListFactory.count, {
            items_per_page: pageSize,

            callback: function callback(index) {
              $scope.taskListFactory.clearAndSetIndex(index * pageSize);
              $scope.taskListFactory.nextPage();
            }
          });
        });
      } else {
        Popup.notice(res.errmsg);
      }
    });
  };
  var authStr = daochuFactory.getAuthStr();
  $scope.downLoad = function (downUrl) {
    window.location.href = API_HOST + "/admin/" + downUrl + ".htm?" + authStr.slice(1);
    // /admin/downloadSchoolMateCheckTemplate.htm // 眼科筛查导入
    // /admin/downloadAllSchoolBodyCheckTemplate.htm //全科体检导入
  };
  $scope.modify = function () {
    $scope.downloadModal = false;
    new ObjectFactory().saveOrQuery("/admin/commitBatchSchoolMateTask.json", {
      taskId: $scope.taskId
    }).then(function (res) {
      if (res.status == 0) {
        $scope.saveModal = false;
        Popup.notice("保存成功");
        $state.go("screenPromotionStudent");
      } else {
        Popup.notice(res.errmsg);
      }
    });
  };
}]);
"use strict";

