angular.module("bestvisionWeb").controller("physicalReportCtrl", ["$scope", "Popup", "$timeout", "HttpFactory", "CommonRequest", function ($scope, Popup, $timeout, HttpFactory, CommonRequest) {
  $scope.isSchoolAuth = null;
  $scope.schoolAuth = {
    modal: false,
    errmsg: ''
  };
  CommonRequest.getReportStatusOfSchoolAdmin(function (auth) {
    if (auth.errmsg) {
      $scope.schoolAuth.modal = true;
      $scope.schoolAuth.errmsg = auth.errmsg;
    }
    $scope.isSchoolAuth = auth.auth; //判断是否是学校权限
  });
  $scope.isPrint = true;
  $scope.screenReportType = 1; //区分筛查计划报告还是体检报告[筛查计划报告：0,体检报告：1]
  $scope.obj = {};
  $scope.printParams = {};
  $scope.timestamp = 0;
  $scope.setTimestamp = function (obj) {
    $scope.timestamp = obj.gmtCreate;
  };
  $scope.printName = ''; //打印使用
  // 获取筛查计划筛选条件
  $scope.screenCondition = {
    params: {},
    getCondition: function getCondition() {
      if (!this.params.schoolPlanId) {
        $scope.setPlanModal = true;
      }
      $scope.obj = this.params;
      $scope.refreshTab(this.params.schoolId ? 2 : 1);
    }
  };
  $scope.schoolCondition = {
    params: {},
    getCondition: function getCondition() {
      $scope.obj = this.params;
      $scope.refreshTab(this.params.schoolId ? 2 : 1);
    }
  };
  $scope.request = function (tab) {
    if ($scope.isSchoolAuth && tab === 1) {
      return;
    }

    var examineUrl = {
      1: "statBodyOfPlan",
      2: "statBodyOfSchool"
    };
    HttpFactory.object("/admin/" + examineUrl[tab] + ".json", {
      schoolPlanId: $scope.obj.schoolPlanId,
      schoolId: $scope.obj.schoolId,
      inYear: $scope.obj.inYear,
      classId: $scope.obj.classId
    }).then(function (res) {
      $scope.tab = tab;
      $scope.tabShow = true;
      $scope.data = res;
      $scope.setTimestamp(res);
      if (tab === 1) {
        $scope.printParams.name = res.schoolPlan.planName;
        $scope.printName = res.schoolPlan.planName;
      } else if (tab === 2) {
        $scope.printName = res.school.schoolName;
      }
    });
  };

  $scope.refreshTab = function (tab) {
    $scope.tabShow = false;
    $scope.data = null;
    $timeout(function () {
      $scope.request(tab);
    }, 100);
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("posCtrl", ["$scope", "Popup", "$rootScope", "$state", "ObjectFactory", "ListFactory", "$timeout", function ($scope, Popup, $rootScope, $state, ObjectFactory, ListFactory, $timeout) {
  $scope.obj = {};
  $scope.pageSize = 20;
  $scope.status = [{ id: 0, name: "正常" }, { id: 1, name: "停用" }];
  $scope.posInfo = {
    idName: "posInfo",
    ajaxUrl: "/admin/getCompanyList.json",
    isshow: false,
    id: "",
    inputVal: "",
    inputPlaceHolder: "请选择门店",
    info: null,
    key: "companyName",
    key2: "",
    fn: function fn() {
      $scope.deviceInfo.companyId = this.info.id;
    },
    type: "List"
  };
  $scope.statusManage = {
    status: null,
    tablist: [{ status: null, name: "全部" }, { status: 0, name: "正常", ionc: "#41b2a6" }, { status: 1, name: "停用", ionc: "#de6262" }],
    callback: function callback() {
      $scope.obj.status = this.status;
      $scope.searchPosList();
    }
  };

  $scope.mobileChange = function () {
    var loginInfo = commonFn.getSession("loginInfo");
    if (!loginInfo) {
      return Popup.notice("没有登录信息！");
    }
    var mobile = loginInfo.mobile;
    $scope.corpList = new ListFactory("/auth/getMyAdminCorpList.json", 0, 20, {
      mobile: mobile
    });
    var promise2 = $scope.corpList.nextPage();
    promise2.then(function (data) {
      // if ($scope.corpList.count >= 1) {
      //   console.log(data);
      // }
    });
  };
  $scope.mobileChange();
  $scope.obj.status = null;

  $scope.searchPosList = function () {
    $scope.getPosListFactory = new ListFactory("/admin/selectPosDeviceList.json", 0, $scope.pageSize, $scope.obj);
    var promise = $scope.getPosListFactory.nextPage();

    promise.then(function (data) {
      $("#Pagination").pagination($scope.getPosListFactory.count, {
        items_per_page: $scope.pageSize,
        callback: function callback(index) {
          $scope.getPosListFactory.clearAndSetIndex(index * $scope.pageSize);
          $scope.getPosListFactory.nextPage();
        }
      });
    });
  };
  $scope.searchPosList();
  $scope.deviceModalOptions = {
    type: ["添加", "编辑"],
    status: 0,
    updateType: function updateType(type) {
      this.status = type;
    }
  };
  $scope.showAdd = function () {
    $scope.posInfo.isshow = false;
    $scope.deviceModalOptions.updateType(0);
    $scope.posInfo.id = "";
    $scope.posInfo.inputVal = "";
    $timeout(function () {
      $scope.deviceInfo = {};
      $scope.posInfo.isshow = true;
      $scope.addDeviceModal = true;
    });
  };

  $scope.deviceInfo = {};
  $scope.posDevice = function () {
    var type = $scope.deviceModalOptions.status; //0 是添加，1是编辑
    var reqUrl = type ? "updatePosDeviceCompany" : "insertPosDevice";
    if (!$scope.deviceInfo.posDeviceSn) {
      return Popup.notice("请输入打印机编号");
    }
    if (!$scope.deviceInfo.remark) {
      return Popup.notice("请输入眼底相机名称");
    }
    $timeout(function () {
      new ObjectFactory().saveOrQuery("/admin/" + reqUrl + ".json", $scope.deviceInfo).then(function (res) {
        if (res.status !== 0) {
          return Popup.notice(res.errmsg);
        }
        Popup.notice(type ? "修改成功" : "添加成功");
        $scope.addDeviceModal = false;
        $scope.posInfo.isshow = false;
        if (type) {
          $scope.getFundus($scope.deviceInfo.posDeviceId).then(function (result) {
            $timeout(function () {
              $scope.getPosListFactory.items[$scope.nowChoiceIndex] = result;
            });
          });
        } else {
          $scope.searchPosList();
        }
      });
    }, 100);
  };
  $scope.nowChoiceIndex = null;
  $scope.getFundus = function (posDeviceId) {
    return new Promise(function (resolve, reject) {
      new ObjectFactory().saveOrQuery("/admin/getPosDevice.json", {
        posDeviceId: posDeviceId
      }).then(function (res) {
        if (res.status !== 0) {
          Popup.notice(res.errmsg);
          return reject(false);
        }
        resolve(res.result.object);
      });
    });
  };
  $scope.changeStatus = function (posDeviceId, status) {
    new ObjectFactory().saveOrQuery("/admin/updatePosDeviceStatus.json", {
      posDeviceId: posDeviceId,
      status: status
    }).then(function (res) {
      Popup.notice(res.status ? res.errmsg : "修改成功");
    });
  };

  $scope.updateDevice = function (device, index) {
    $scope.posInfo.isshow = false;
    $scope.nowChoiceIndex = index;
    $scope.getFundus(device.posDevice.id).then(function (res) {
      $scope.deviceModalOptions.updateType(1);
      $scope.deviceInfo = {
        remark: res.posDevice.remark,
        posDeviceSn: res.posDevice.posDeviceSn,
        posDeviceId: res.posDevice.id,
        companyId: res.company.id
      };
      $scope.posInfo.id = res.company.id;
      $scope.posInfo.inputVal = res.company.companyName;
      $timeout(function () {
        $scope.posInfo.isshow = true;
        $scope.addDeviceModal = true;
      });
    });
  };
  $scope.deleteDevice = function (posDeviceId) {
    Popup.confirm("确定删除么", function () {
      new ObjectFactory().saveOrQuery("/admin/deletePosDevice.json", {
        posDeviceId: posDeviceId
      }).then(function (res) {
        if (res.status) {
          return Popup.notice(res.errmsg);
        }
        Popup.notice("删除成功");
        $scope.searchPosList();
      });
    }, function () {});
  };
}]);
"use strict";

