angular.module("bestvisionWeb").controller("projectionScreenCtrl", ["$scope", "$rootScope", "$window", "Popup", "$stateParams", "$state", "ObjectFactory", "ListFactory", "websocketFactory", "$http", "$timeout", function ($scope, $rootScope, $window, Popup, $stateParams, $state, ObjectFactory, ListFactory, websocketFactory, $http, $timeout) {
  $scope.chartType = 1;
  var socketType = socketType1;
  $scope.connectAble = websocketFactory.isConnect;
  $scope.sendMsg = function (info) {
    console.log("send msg");
    info.socketType = socketType;
    websocketFactory.mqtt_sendMsg(JSON.stringify(info));
  };
  $scope.getSet = function () {
    if (!$scope.connectAble) return;
    var visionTest = window.commonFn.getSession("visionTest");
    console.log(visionTest);
    if (!visionTest) return;
    $scope.sendMsg(visionTest);
  };
  $scope.getSet();
  websocketFactory.mqtt_setType(socketType, function (msg) {
    try {
      $timeout(function () {
        var result = JSON.parse(msg);
        console.log("接受数据", result);
        $scope.getLastest(result);
      });
    } catch (error) {
      console.log("error MSG:", error);
    }
  });
  $scope.height = $window.screen.height;
  $scope.width = $window.screen.width;
  var getchart = function getchart() {
    $scope.getEyeChartFactory = new ObjectFactory();
    var promise = $scope.getEyeChartFactory.saveOrQuery("/admin/getEyeChartOfMine.json", { chartType: $scope.chartType });

    promise.then(function (res) {
      var eyeChart = res.result.object.eyeChart;

      $scope.eyeChartId = eyeChart.id;
      // $scope.getLastest();
    });
  };
  getchart($scope.chartType);
  var adminToken = localStorage.getItem("pcToken");
  $scope.homeFactory = new ObjectFactory();
  $scope.homeFactory.saveOrQuery("/auth/isAdminTokenOk.json", {
    adminToken: adminToken
  });

  $scope.goBack = function () {
    new ObjectFactory().saveOrQuery("/admin/resetEyeChartOfMine.json", {
      chartType: $scope.chartType
    }).then(function (res) {
      if (res.status == 0) {
        $state.go("home");
      }
    });
  };
  // toggleFull(true);
  if (window.commonFn.judgeScreen($scope.width, $scope.height)) {
    $(".vision-table").height($scope.height - 60);
  }
  new ObjectFactory().saveOrQuery("/admin/autoChartSizeForPad.json", {
    width: $scope.width,
    height: $scope.height
  }).then(function (res) {
    $(".vision-table_img").width(res.result.object);
  });

  window.onload = function () {
    document.addEventListener("touchstart", function (event) {
      if (event.touches.length > 1) {
        event.preventDefault();
      }
    }, { passive: false });

    document.addEventListener("touchmove", function (event) {
      event = event.originalEvent || event;
      if (event.scale !== 1) {
        event.preventDefault();
      }
    }, { passive: false });

    var lastTouchEnd = 0;
    document.addEventListener("touchend", function (event) {
      var now = new Date().getTime();
      if (now - lastTouchEnd <= 300) {
        event.preventDefault();
      }
      lastTouchEnd = now;
    }, false);

    // 阻止双指放大
    // document.documentElement.addEventListener('gesturestart', function(event) {
    //     event.preventDefault();
    // });
  };
  $scope.modal = false;
  // 指示棒图片路径
  $scope.imgUrl = "https://image.wanmeishili.com/FoMTcWnyGGoet_ykRtxgnP0B7YB2";
  $scope.getMsg = function () {
    new ObjectFactory().saveOrQuery("/admin/getSchoolCheckConf.json").then(function (res) {
      $scope.imgUrl = res.result.object.indicatorBarImage;
    });
    var chartType = $scope.chartType;
    new ObjectFactory().saveOrQuery("/admin/getRandFirstEyeChartFileByChartType.json", {
      chartType: chartType
    }).then(function (res) {
      $scope.default_picture = res.result.object.eyeChartFileUrl;
    });
  };
  $scope.getMsg();
  $scope.getLastest = function (result) {
    if (result.eyeChartId != $scope.eyeChartId) {
      return;
    }
    new ObjectFactory().saveOrQuery("/admin/getEyeChartPicVoForPad.json", {
      eyeChartId: $scope.eyeChartId,
      charIndex: result.charIndex,
      charValue: result.charValue,
      width: $scope.width,
      height: $scope.height
    }).then(function (response) {
      var resObj = response.object;
      if (resObj) {
        $timeout(function () {
          var eyeChartFile = resObj.eyeChartFile,
              eyeChartPic = resObj.eyeChartPic;

          if (eyeChartFile && eyeChartFile.eyeChartFileUrl) {
            $scope.default_picture_type = eyeChartFile.id;
          }
          $scope.modal = true; //指示棒
          $scope.endModal = false;
          $scope.msgModal = false;
          var yOff = eyeChartPic.charY + "px";
          var yOffScoll = eyeChartPic.chartY;
          var xOff = eyeChartPic.charX + "px";
          $(".vision-table_line").css("top", yOff);
          // $(".vision-table").scrollTop(yOffScoll);
          $("#move").css("transform", "translateY(-" + yOffScoll + "px)");
          $(".vision-table_hand").css({ top: yOff, left: xOff });
        }, 10);
      }
    });
  };
  $scope.$on("$destroy", function () {
    websocketFactory.mqtt_remove(socketType);
  });
}]);
"use strict";

angular.module("bestvisionWeb").controller("reachStoreAppointAllReportCtrl", ["$scope", "ObjectFactory", "ListFactory", "$timeout", "Popup", "daochuFactory", function ($scope, ObjectFactory, ListFactory, $timeout, Popup, daochuFactory) {
  // 获取筛查计划筛选条件
  $scope.screenCondition = {
    screenList: [{
      key: "classId",
      url: "statAppointSchoolMateOfClass",
      statLevel: 4
    }, {
      key: "inYear",
      url: "statAppointSchoolMateOfInYear",
      statLevel: 3
    }, {
      key: "schoolId",
      url: "statAppointSchoolMateOfSchool",
      statLevel: 2
    }, {
      key: "schoolPlanId",
      url: "statAppointSchoolMateOfPlan",
      statLevel: 1
    }],
    params: {},
    getCondition: function getCondition() {
      var list = this.screenList;
      for (var i = 0; i < list.length; i++) {
        if (this.params[list[i].key]) {
          this.params.statLevel = list[i].statLevel;
          return this.queryTable();
        }
      }
    },
    queryTable: function queryTable() {
      var params = angular.copy(this.params);
      new ObjectFactory().saveOrQuery("/admin/statAppointSchoolMateOfCorp.json", params).then(function (res) {
        var array = res.object;
        $scope.storeList = array;
      });
    }
  };
  $scope.exportDefault = function () {
    var params = angular.copy($scope.screenCondition.params);
    for (var i in params) {
      if (!params[i]) {
        delete params[i];
      }
    }
    daochuFactory.EXPOSE("downloadAppointSchoolMateStatVoListOfCorp", params);
  };
}]);
