    var startTime = void 0,
        endTime = void 0;
    switch (dateSearch) {
      case "1":
        startTime = new Date();
        endTime = new Date();
        break;
      case "2":
        var nowWeek = DateUtilFactory.nowWeek(new Date());
        startTime = new Date(nowWeek[0]);
        endTime = new Date(nowWeek[1]);
        break;
      default:
        startTime = null;
        endTime = null;
        break;
    }
    $scope.dateSearch = dateSearch;
