angular.module("bestvisionWeb").controller("screenConditionBatchGroupSendCtrl", ["$scope", "$stateParams", "Popup", "ObjectFactory", "ListFactory", "$state", "DateUtilFactory", "$timeout", function ($scope, $stateParams, Popup, ObjectFactory, ListFactory, $state, DateUtilFactory, $timeout) {
    $scope.addressInfo = {
        templateAddressType: "1",
        groupList: optionsObj.drainageAddress,
        click: function click(i) {
            this.templateAddressType = i;
        }
    };
    $scope.setPlanModal = false;
    $scope.object = {};
    /* $scope.getSchoolCheckConf = function () {
        new ObjectFactory()
            .saveOrQuery(`/admin/getSchoolCheckConf.json`)
            .then((res) => {
                if (res.status) {
                    return Popup.notice(res.errmsg);
                }
                $scope.templateAddress = optionsObj.drainageAddress.find(
                    (v) => v.status == res.result.object.templateAddressType
                ).name;
            });
    };
    $scope.getSchoolCheckConf(); */
    $scope.obj = {
        taskName: ""
    };
    $scope.user = {
        corpId: null
    };
    /* $scope.visionCorrectStatusArrayStatus = {
       show: false,
       status: null,
       tablist: [],
       callback: function () {
         $scope.checkCode = this.status
         $scope.object.checkCode = this.status;
         $scope.search(0, true)
       }
     };*/
    $scope.getCondition = {
        show: false,
        search: function search(obj) {
            obj.keyword = $scope.object.keyword;
            $scope.object = obj;
            $scope.search(0, true);
        }
    };
    $scope.sendTimeInfo = {
        sendTime: 0,
        groupList: [{
            name: "定时发送",
            status: 0,
            temp: { time: "" },
            data: [{ time: "" }],
            onCallBack: function onCallBack() {
                // console.log(this.data);
            },
            addOne: function addOne() {
                this.data.push(angular.copy(this.temp));
            },
            subOne: function subOne(i) {
                this.data.splice(i, 1);
            }
        }, {
            name: "立即发送",
            status: 1
        }],
        click: function click(i) {
            this.sendTime = i;
        }
    };
    $scope.sendTypeList = [{
        name: "短信通知",
        k: "sms",
        key: "smsEnable",
        value: true,
        reqUrl: "/admin/selectCorpSmsByCorpId.json",
        count: 0,
        countKey: "smsCount",
        unit: "条"
    }, {
        name: "电话通知",
        k: "voice",
        key: "voiceEnable",
        value: false,
        reqUrl: "/admin/selectCorpVoiceByCorpId.json",
        count: 0,
        countKey: "currentCount",
        unit: "分钟"
    }];
    /* 查询电话短信剩余数量 */
    $scope.sendTypeList.forEach(function (type) {
        new ObjectFactory().saveOrQuery(type.reqUrl).then(function (result) {
            $scope.user.corpId = result.object.corpId;
            type.count = result.object[type.countKey];
        });
    });
    $scope.choseTable = {
        show: false,
        key: "sms", //sms,voice
        sceneType: 7,
        props: {}, //从模板中选中信息返回
        smsInfo: null,
        voiceInfo: null,
        openPopout: function openPopout(key, id) {
            this.key = key;
            this.props = {};
            this.props.id = id;
            this.show = true;
        },
        back: function back() {
            var _this = this;

            this[this.key + "Info"] = this.props;
            $scope.sendTypeList.find(function (v) {
                return v.k === _this.key;
            })["templateId"] = this.props[this.key + "Template"].id;
        }
    };
    /* 选择发送类型 */
    $scope.choseMessage = function (t_index, event) {
        $scope.sendTypeList.forEach(function (v, i) {
            v.value = false;
        });
        $scope.sendTypeList[t_index].value = true;
        /* if (!isEmpty) {
          return event.preventDefault();
        } */
    };
    $scope.preview = false;
    /*请求参数处理*/
    $scope.getParams = function () {
        var newObj = angular.copy($scope.screenCondition.params);
        newObj.hasMobile = true;
        Object.assign(newObj, $scope.object);
        return newObj;
    };
    $scope.payComponent = {
        show: false,
        type: "",
        error: "您的短信/电话余额不足！充值后可创建此活动。",
        callBack: function callBack() {
            $scope.sendTask();
        }
    };
    $scope.sendTask = function () {
        if ($scope.exportObject.exportCount <= 0) {
            return Popup.notice("请选择要发放的人群!");
        }
        var sendObj = $scope.getParams();
        /* 判断活动名称 */
        if (!$scope.obj.taskName) {
            return Popup.notice("请输入活动名称！");
        }
        sendObj.taskName = $scope.obj.taskName;
        /* 判断模板选择 */
        var isChoseModel = false;
        $scope.sendTypeList.forEach(function (v, index) {
            // sendObj[v.key] = 0;
            if (v.value && v.templateId) {
                // sendObj[v.key] = 1;
                sendObj["templateId"] = v.templateId;
                sendObj["sendType"] = index;
                isChoseModel = true;
            }
        });
        if (!isChoseModel) {
            return Popup.notice("请选择发送模板！");
        }
        /* 判断发送时间 */
        var _$scope$sendTimeInfo = $scope.sendTimeInfo,
            sendTime = _$scope$sendTimeInfo.sendTime,
            groupList = _$scope$sendTimeInfo.groupList;
        // sendObj.birthdayEqual = 0;

        var planExecuteTime = [];
        if (sendTime === 1) {
            planExecuteTime.push(DateUtilFactory.originMin(DateUtilFactory.setNow()));
        } else {
            groupList[0].data.forEach(function (v) {
                if (v.time) {
                    planExecuteTime.push(DateUtilFactory.originMin(v.time));
                }
            });
            if (!planExecuteTime.length) {
                return Popup.notice("请选择发送时间！");
            }
        }
        sendObj.planExecuteTime = planExecuteTime;
        sendObj.templateAddressType = $scope.addressInfo.templateAddressType;
        // console.log(sendObj);
        // return;
        new ObjectFactory().saveOrQuery("/admin/createScreenTemplateBatchSendTask.json", sendObj).then(function (result) {
            if (result.status) {
                var type = result.result.status;
                if (type) {
                    $scope.payComponent.type = type.toLowerCase();
                    $scope.payComponent.show = true;
                }
                return Popup.notice(result.errmsg);
            }
            $state.go("screenConditionBatch");
        });
    };
    /* 如果是查看界面，则调用接口 */
    $scope.searchKey = {
        keyword: ""
    };
    $scope.searchValue = {};
    $scope.screenCondition = {
        params: {},
        getCondition: function getCondition() {
            if (!$scope.screenCondition.params.schoolPlanId) {
                $scope.setPlanModal = true;
                return;
            }
            $scope.search();
        }
    };
    $scope.search = function () {
        if ($scope.isFilterPage) return;
        $scope.exportObject = $scope.getParams();
    };

    $scope.searchTask = function () {
        var pageSize = 10;
        $scope.detailsFactory = new ListFactory("/admin/selectScreenTemplateBatchSendTaskDetails.json", 0, pageSize, {
            taskScreenTemplateBatchSendId: $stateParams.taskScreenTemplateBatchSendId,
            keyword: $scope.searchKey.keyword
        });
        var promise = $scope.detailsFactory.nextPage();
        promise.then(function (data) {
            var taskDetail = data.allData.taskDetail;

            $scope.searchValue = taskDetail;
            var schoolBodyStatParam = taskDetail.schoolBodyStatParam;

            $scope.getCondition.filter = schoolBodyStatParam;
            $scope.getCondition.show = true;
            $scope.screenConditionFixed = {
                params: {
                    planName: taskDetail.schoolPlanName,
                    schoolName: taskDetail.schoolName,
                    schoolClassName: taskDetail.schoolClassName,
                    schoolPlanId: schoolBodyStatParam.schoolPlanId,
                    schoolId: schoolBodyStatParam.schoolId,
                    inYear: schoolBodyStatParam.inYear,
                    classId: schoolBodyStatParam.classId
                }
            };
            /*let map = {
              visionArrayStatus: "visionArray",
              visionStatus: "visionCorrectStatusArray",
              dioptricStatus: "dioptersArray"
            };
            for (let i in map) {
              dealWithFixListBack(i, schoolMateCheckParam[map[i]]);
            }
            $scope.schemeAdvice.updateIndex(schoolMateCheckParam.left68);
            $scope.commonIllness.updateIndex(schoolMateCheckParam.commonRemark);*/
            $("#Pagination2").pagination($scope.detailsFactory.count, {
                items_per_page: pageSize,
                callback: function callback(index) {
                    $scope.detailsFactory.clearAndSetIndex(index * pageSize);
                    $scope.detailsFactory.nextPage();
                }
            });
        });
    };
    $scope.isFilterPage = false;
    if ($stateParams.taskScreenTemplateBatchSendId) {
        $scope.isFilterPage = true;
        $scope.searchTask();
    } else {
        $scope.getCondition.show = true;
    }
}]);
