angular.module("bestvisionWeb").controller("screenConditionBatchGroupSendLookCtrl", ["$scope", "Popup", "ObjectFactory", "ListFactory", "$stateParams", "$timeout", function ($scope, Popup, ObjectFactory, ListFactory, $stateParams, $timeout) {
  $scope.obj = {
    sendType: null
  };
  $scope.obj.taskScreenTemplateBatchSendId = $stateParams.taskScreenTemplateBatchSendId;
  /* $scope.requirementType = {
    status: null,
    tablist: [
      { status: null, name: "全部" },
      { status: "0", name: "短信", ionc: "#de6262" },
      { status: "1", name: "电话", ionc: "#41b2a6" },
    ],
    callback: function () {
      $scope.obj.sendType = this.status;
      $scope.selectListForDetails();
    },
  }; */
  $scope.paramsObj = null; //保存活动详情
  $scope.paramsList = []; //保存发放详情
  $scope.selectListForDetails = function () {
    var dealWithDetails = function dealWithDetails(_ref) {
      var allData = _ref.allData;
      var list = allData.list,
          taskDetial = allData.taskDetial;

      $scope.paramsObj = taskDetial; //保存活动详情
      // let { status } = $scope.requirementType;
      var list2 = list.reduce(function (prev, next) {
        if (next.smsLog) {
          var obj = angular.copy(next);
          obj.model = "短信模板";
          obj.gmtCreate = obj.smsLog.gmtCreate;
          obj.content = obj.smsLog.smsContent;
          prev.push(obj);
        }
        if (next.voiceLog) {
          next.model = "语音模板";
          next.gmtCreate = next.voiceLog.gmtCreate;
          next.content = next.voiceLog.voiceContent;
          prev.push(next);
        }
        return prev;
      }, []);
      // console.log(list2);
      $timeout(function () {
        $scope.paramsList = list2; //保存发放详情
      });
    };
    var pageSize = 10;
    var list = new ListFactory("/admin/selectTaskTemplateBatchSendLogVoList.json", 0, pageSize, $scope.obj);
    var promise = list.nextPage();
    promise.then(function (data) {
      dealWithDetails(data);
      $("#Pagination").pagination(list.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          list.clearAndSetIndex(index * pageSize);
          list.nextPage().then(dealWithDetails);
        }
      });
    });
  };
  $scope.selectListForDetails();
}]);
