      schoolId2: $scope.object.schoolId,
      inYear2: $scope.object.inYear,
      classId2: $scope.object.classId,
      gender2: $scope.object.gender,
      checkYear2: $scope.object.checkYear,
      schoolPoint2: $scope.object.schoolPoint,
