angular.module("bestvisionWeb").controller("screenInStoreCtrl", ["$scope", "ObjectFactory", "ListFactory", "$timeout", "Popup", "WechatConfig", function ($scope, ObjectFactory, ListFactory, $timeout, Popup, WechatConfig) {
  $scope.lock = {
    needLock: false,
    ableclose: false, //是否允许关闭解锁弹框
    lookBack: function lookBack() {
      $scope.selectCorpSchoolPlanVoList();
    },
    open: function open() {
      this.ableclose = true;
      this.needLock = true;
    }
  };
  $scope.isLookFun = function () {
    window.grantAuth.isUnlockFun(ObjectFactory, "screenInStore").then(function (resolve) {
      $timeout(function () {
        $scope.lock.lookBack();
      });
    }, function (err) {
      if (err) {
        return Popup.notice(err);
      }
      $timeout(function () {
        $scope.lock.needLock = true;
      });
    });
  };
  $scope.isLookFun();
  $scope.requirementList = [{
    title: "配置到店计划及检查项",
    icon: "#icon-ico_xitongshezhi_xiangmuweihu",
    description: "可对每个到店筛查计划设置检查项，家长可实时查看检查进度。"
  }, {
    title: "打印物料",
    icon: "#icon-a-24gl-printer",
    description: "一家门店对应一个台卡，家长到店可扫描台卡上的二维码进行筛查。"
  }, {
    title: "设置筛查信息",
    icon: "#icon-tijiaoxuqiu",
    description: "提前创建到店计划、学校、班级，支持提前导入学生信息。(提前导入的学生信息必须包含姓名、手机号和证件号)"
  }, {
    title: "家长到店扫码",
    icon: "#icon-app_icon_saoma",
    description: "家长直接录入或输入已导入的学生信息生成检测码，视光师扫码筛查。"
  }];
  // 将选中的状态返回
  function dealWithFixList(fixList) {
    return fixList.reduce(function (save, next) {
      next.isChose && save.push(next.status);
      return save;
    }, []);
  }
  // 配置计划的季节
  $scope.seasonArray = {
    fix: true,
    key: "name",
    fixList: [{ status: null, name: "全部", isChose: true }, { status: 1, name: "春季" }, { status: 3, name: "秋季" }, { status: 2, name: "暑假" }, { status: 4, name: "寒假" }],
    callback: function callback() {
      $scope.search.seasonArray = dealWithFixList(this.fixList);
      $scope.selectSchoolPlanList();
    }
  };
  // 配置筛查项目
  $scope.operation = function (index, switchDisable) {
    var checkCode = $scope.switchList[index].schoolPlanCheckSwitch.checkCode;
    var storeSchoolPlanId = $scope.storeSchoolPlan.id;
    var object = {};
    object.storeSchoolPlanId = storeSchoolPlanId;
    object.checkCode = checkCode;
    object.switchDisable = switchDisable;
    new ObjectFactory().saveOrQuery("/admin/updateSchoolPlanCheckSwitch.json", object).then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        $scope.switchList[index].schoolPlanCheckSwitch.switchDisable = res.object.switchDisable;
        Popup.notice("" + (!switchDisable ? "已开启" : "已关闭"));
      }
    });
  };
  // 查询当前到店筛查计划
  $scope.selectCorpSchoolPlanVoList = function () {
    new ObjectFactory().saveOrQuery("/admin/getCorpSchoolPlanVoOfCompany.json").then(function (res) {
      if (res.object) {
        $scope.storeSchoolPlan = res.object.schoolPlan; //当前到店筛查计划
        var list = res.object.switchList;
        var index = list.findIndex(function (v) {
          return v.schoolPlanCheckSwitch.checkCode === "eye_check_diopter";
        });
        if (index !== -1) {
          list[index].bodyCheckVo = {
            bodyCheck: { checkName: "屈光检查" },
            bodyCheckItemList: [{
              bodyCheckItem: {
                itemName: "球镜"
              }
            }, {
              bodyCheckItem: {
                itemName: "柱镜"
              }
            }, {
              bodyCheckItem: {
                itemName: "轴位"
              }
            }, {
              bodyCheckItem: {
                itemName: "眼压"
              }
            }, {
              bodyCheckItem: {
                itemName: "眼轴"
              }
            }, {
              bodyCheckItem: {
                itemName: "角膜曲率K1"
              }
            }, {
              bodyCheckItem: {
                itemName: "角膜曲率K2"
              }
            }, {
              bodyCheckItem: {
                itemName: "角膜曲率D1"
              }
            }, {
              bodyCheckItem: {
                itemName: "角膜曲率D2"
              }
            }]
          };
        }
        var index2 = list.findIndex(function (v) {
          return v.schoolPlanCheckSwitch.checkCode === "eye_check_vision";
        });
        if (index2 !== -1) {
          list[index2].bodyCheckVo = {
            bodyCheck: { checkName: "视力检查" },
            bodyCheckItemList: [{
              bodyCheckItem: {
                itemName: "裸眼视力"
              }
            }, {
              bodyCheckItem: {
                itemName: "戴镜视力"
              }
            }, {
              bodyCheckItem: {
                itemName: "戴镜类型"
              }
            }]
          };
        }
        $scope.switchList = list; //当前检查项目配置
      }
    });
  };
  $scope.search = {};
  // 弹窗查询 计划
  var fn = function fn() {
    if ($scope.storeSchoolPlan) {
      var index = $scope.selectSchoolPlanListOfStore.items.findIndex(function (v) {
        return v.id === $scope.storeSchoolPlan.id;
      });
      if (index !== -1) {
        $scope.selectSchoolPlanListOfStore.items[index].nowPlan = true;
      }
    }
  };
  $scope.selectSchoolPlanList = function () {
    var obj = angular.copy($scope.search);
    obj.status = 0;
    var pageSize = 10;
    $scope.selectSchoolPlanListOfStore = new ListFactory("/admin/selectSchoolPlanList.json", 0, pageSize, obj);
    var listPromise = $scope.selectSchoolPlanListOfStore.nextPage();
    listPromise.then(function (res) {
      fn();
      $("#Pagination").pagination($scope.selectSchoolPlanListOfStore.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.selectSchoolPlanListOfStore.clearAndSetIndex(index * pageSize);
          $scope.selectSchoolPlanListOfStore.nextPage().then(function (res) {
            fn();
          });
        }
      });
    });
  };
  $scope.showplan = false; //切换计划的弹框
  // 切换计划
  $scope.switchPlan = function () {
    $scope.selectSchoolPlanList();
    window.commonFn.openMaskFun();
    $scope.showplan = true;
  };
  $scope.closePlan = function () {
    window.commonFn.closeMaskFun();
    $scope.showplan = false;
  };
  // 设置当前到店筛查计划
  $scope.cutPlan = function (storeSchoolPlan) {
    $scope.saveStore(storeSchoolPlan);
  };
  // 当前门店
  window.grantAuth.hasAuthForCompany(ObjectFactory).then(function (result) {
    $timeout(function () {
      if (result) {
        $scope.companyInfo = result;
      } else {
        Popup.notice("未设置门店!");
      }
    });
  });

  $scope.picture = true;

  // 下载物料
  $scope.downLoad = function (isNeedAppoint) {
    $scope.picture = isNeedAppoint;
    if (!$scope.companyInfo) return Popup.notice("请设置门店！");
    var companyId = $scope.companyInfo.id;
    new ObjectFactory().saveOrQuery("/admin/getCompanyQrcode.json", {
      companyId: companyId,
      isNeedAppoint: isNeedAppoint
    }).then(function (res) {
      var url = WechatConfig.showqrcode(res.result.object);
      $scope.srcimg = url;
      $timeout(function () {
        $("#ele1").jqprint({
          debug: false,
          importCSS: true,
          printContainer: true,
          operaSupport: false,
          timeout: 2000
        });
      });
    });
  };

  // 保存
  $scope.saveStore = function (storeSchoolPlan) {
    var storeSchoolPlanId = storeSchoolPlan.id;
    if (!$scope.companyInfo) {
      return Popup.notice("请设置门店！");
    }
    var companyId = $scope.companyInfo.id;
    new ObjectFactory().saveOrQuery("/admin/setCorpSchoolPlan.json", {
      storeSchoolPlanId: storeSchoolPlanId,
      companyId: companyId
    }).then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        Popup.notice("保存成功！");
        $scope.closePlan();
        $scope.selectCorpSchoolPlanVoList();
      }
    });
  };
}]);
