  // 移动
  $scope.translateY = function (item, moveUp) {
    HttpFactory.object('/admin/moveSchoolCheckWechatShow.json', {
      moveSchoolCheckWechatShowId: item.id,
      moveUp: moveUp
    });
    // 偏移
    var index = $scope.showList.findIndex(function (v, index) {
      return v.id === item.id;
    });
    var temp = null;
    if (!moveUp) {
      // 边界处理
      if (index + 1 >= $scope.showList.length) {
        return;
      }
      // 交换
      temp = $scope.showList[index + 1];
      $scope.showList[index + 1] = $scope.showList[index];
      $scope.showList[index] = temp;
    } else {
      // 边界处理
      if (index - 1 < 0) {
        return;
      }
      // 交换
      temp = $scope.showList[index - 1];
      $scope.showList[index - 1] = $scope.showList[index];
      $scope.showList[index] = temp;
    }
  };
