angular.module("bestvisionWeb").controller("addGroupeditCtrl", ["$scope", "Popup", "$timeout", "$rootScope", "$state", "ListFactory", "ObjectFactory", "CalulateClass", function ($scope, Popup, $timeout, $rootScope, $state, ListFactory, ObjectFactory, CalulateClass) {
  $scope.Calulate = new CalulateClass();
  $scope.CalulateBack = function (key, setKey) {
    $scope.Calulate.calulateCheckCombo(key, $scope.obj[key], $scope.itemArr).then(function (res) {
      $timeout(function () {
        var isBool = typeof res === "boolean";
        if (isBool) {
          $scope.obj[key] = null;
        }
        $scope.obj[setKey] = isBool ? null : res;
      });
    });
  };
  $scope.obj = {};
  $scope.obj.status = 0;
  $scope.obj.packageType = 1;
  // $scope.obj.packageRate = 100;
  $scope.itemArr = [];
  $scope.add = function () {
    if (!$scope.obj.packageName) {
      Popup.notice("套餐名称不能为空");
      return false;
    }

    var arr = [];
    for (var i = 0; i < $scope.itemArr.length; i++) {
      arr.push($scope.itemArr[i].id);
    }
    $scope.obj.examineIdArray = arr;
    if (!$scope.obj.examineIdArray.length) {
      Popup.notice("检查列表不能为空");
      return false;
    }

    /* if ($scope.obj.packageRate) {
      Popup.notice("套餐折扣不能为空");
      return false;
    } */
    if ($scope.obj.packageRate > 0) {
      if (/^[1-9]\d*$/.test($scope.obj.packageRate)) {
        if ($scope.obj.packageRate > 100) {
          Popup.notice("套餐折扣必须小于100", 3000, function () {});
          return false;
        }
      } else {
        Popup.notice("套餐折扣必须为正整数", 3000, function () {});
        return false;
      }
    } else if ($scope.obj.packageRate == 0) {} else {
      Popup.notice("套餐折扣必须为正整数", 3000, function () {});
      return false;
    }

    $scope.adminObjectFactory = new ObjectFactory();
    var promise = $scope.adminObjectFactory.saveOrQuery("/admin/insertPackage.json", $scope.obj);
    promise.then(function (res) {
      if (res.status == 0) {
        // $state.go('supplierList');
        window.history.back();
      } else {
        Popup.notice(res.errmsg, 3000, function () {});
      }
    });
  };

  $scope.searchProductWord = function () {
    $scope.schoolListFactory = new ListFactory("/admin/getExamineVoList.json", 0, 12, { status: 0, examineType: 1, keyword: $scope.obj.keyword });
    var checkPromise = $scope.schoolListFactory.nextPage();
    checkPromise.then(function (res) {
      var pageSize = 12;
      $(".second-pagination").pagination($scope.schoolListFactory.count, {
        items_per_page: pageSize,

        callback: function callback(index) {
          $scope.schoolListFactory.clearAndSetIndex(index * pageSize);
          var nextPromise = $scope.schoolListFactory.nextPage();
          nextPromise.then(function (resp) {
            $scope.selectId($scope.schoolListFactory.index);
          });
        }
      });
    });
  };
  $scope.checkItemIdArray = [];

  $scope.selectId = function (idx) {
    $scope.isAll = true;

    var count = [];
    var arr = $scope.checkItemIdArray.slice(idx - 12, idx);

    for (var i = 0; i < arr.length; i++) {
      if (arr[i]) {
        count.push(arr[i]);
      }
    }

    if (count.length == $scope.schoolListFactory.items.length) {
      $scope.isAll = true;
    } else {
      $scope.isAll = false;
    }
  };

  $scope.checkAll = function () {
    if ($scope.isAll) {
      for (var i = 0; i < $scope.schoolListFactory.items.length; i++) {
        $scope.checkItemIdArray[i + $scope.schoolListFactory.index - 12] = $scope.schoolListFactory.items[i].examine.id;
      }
    } else {
      for (var j = 0; j < $scope.schoolListFactory.items.length; j++) {
        $scope.checkItemIdArray[j + $scope.schoolListFactory.index - 12] = null;
      }
    }
  };

  $scope.itemNameArr = [];

  var getItemNameFactory;
  $scope.modifyCheck = function () {
    var arr = [];
    for (var k = 0; k < $scope.checkItemIdArray.length; k++) {
      if ($scope.itemNameArr.indexOf($scope.checkItemIdArray[k]) == -1) {
        arr.push($scope.checkItemIdArray[k]);
      }
    }

    for (var i = 0; i < arr.length; i++) {
      if (arr[i]) {
        getItemNameFactory = new ObjectFactory();
        var namePromise = getItemNameFactory.saveOrQuery("/admin/getExamineVo.json", { examineId: arr[i] });
        namePromise.then(function (res) {
          $scope.itemNameArr.push(res.result.object.examine.id);
          $scope.itemArr.push({
            examineName: res.result.object.examine.examineName,
            unitName: res.result.object.examine.unitName,
            marketPrice: res.result.object.examine.marketPrice,
            id: res.result.object.examine.id
          });
          $scope.CalulateBack("packageRate", "packageFee");
        });
      }
    }
    $scope.schoolModal = false;
  };

  $scope.deleteItem = function (idx) {
    $scope.itemNameArr.splice(idx, 1);
    $scope.itemArr.splice(idx, 1);
    $scope.CalulateBack("packageRate", "packageFee");
  };

  $scope.showCheckModal = function () {
    $scope.checkItemIdArray = [];
    $scope.schoolModal = true;
    $scope.searchProductWord();
  };
}]);
'use strict';

angular.module('bestvisionWeb').controller('addInspectCtrl', ['$scope', '$location', 'Popup', '$rootScope', '$state', 'ObjectFactory', 'ListFactory', function ($scope, $location, Popup, $rootScope, $state, ObjectFactory, ListFactory) {

    $scope.obj = {};
    $scope.obj.checkItemType = 1;
    $scope.obj.singleValue = 1;

    $scope.obj.status = 0;
    $scope.medicalCheckItemExceptList = [{
        checkItemValueMin: null,
        checkItemValueMax: null,
        gender: 0,
        ageMin: null,
        ageMax: null
    }];
    $scope.medicalCheckItemValueList = [{
        rank1: 1,
        checkItemValue: null
    }];

    $scope.addValueItem = function () {
        $scope.medicalCheckItemValueList.push({
            rank1: $scope.medicalCheckItemValueList.length + 1,
            checkItemValue: null
        });
    };

    $scope.deleteValueItem = function (idx) {
        $scope.medicalCheckItemValueList.splice(idx, 1);
    };

    $scope.addItem = function () {
        $scope.medicalCheckItemExceptList.push({
            checkItemValueMin: null,
            checkItemValueMax: null,
            gender: 0,
            ageMin: null,
            ageMax: null
        });
    };

    $scope.deleteItem = function (idx) {
        $scope.medicalCheckItemExceptList.splice(idx, 1);
    };

    $scope.confirm = function (val) {
        if (val) {
            if (!/^[+-]?\d+(\.\d{1,6})?$/.test(val)) {
                Popup.notice('参数值为数字，可以精确到小数点后6位', 2000, function () {});
                return false;
            }
        }
    };

    $scope.checkBlack = function (val) {

        if (val && val.indexOf(' ') !== -1) {

            Popup.notice('不能输入空格');
        }
    };

    $scope.back = function () {
        window.history.back();
    };

    $scope.addInspect = function () {

        if ($scope.obj.checkItemValueMin) {
            if (!/^[+-]?\d+(\.\d{1,6})?$/.test($scope.obj.checkItemValueMin)) {
                Popup.notice('参数值为数字，可以精确到小数点后6位', 2000, function () {});
                return false;
            }
        }

        if ($scope.obj.checkItemValueMax) {
            if (!/^[+-]?\d+(\.\d{1,6})?$/.test($scope.obj.checkItemValueMax)) {
                Popup.notice('参数值为数字，可以精确到小数点后6位', 2000, function () {});
                return false;
            }
        }

        if ($scope.except) {
            $scope.obj.exceptSample = 1;
            $scope.obj.medicalCheckItemExceptListJson = JSON.stringify($scope.medicalCheckItemExceptList);
        } else {
            $scope.obj.exceptSample = 0;

            $scope.obj.medicalCheckItemExceptListJson = JSON.stringify([]);
        }

        if ($scope.choose) {
            $scope.obj.valueSet = 1;
            $scope.obj.medicalCheckItemValueListJson = JSON.stringify($scope.medicalCheckItemValueList);
        } else {
            $scope.obj.valueSet = 0;

            $scope.obj.medicalCheckItemValueListJson = JSON.stringify([]);
        }

        if ($scope.obj.checkItemType == 1) {
            $scope.obj.singleValue = 1;
        } else {
            $scope.obj.exceptSample = 0;
            $scope.obj.checkItemValueMin = null;
            $scope.obj.checkItemValueMax = null;
            $scope.obj.medicalCheckItemExceptListJson = JSON.stringify([]);
        }

        $scope.addInspectFactory = new ObjectFactory();
        var addPromise = $scope.addInspectFactory.saveOrQuery('/admin/insertMedicalCheckItem.json', $scope.obj);

        addPromise.then(function (res) {
            if (res.status == 0) {
                // $state.go('systemSetting.InspectList')
                window.history.back();
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };
}]);
