angular.module('bestvisionWeb').controller('addProcessCenterCtrl', ['$scope', 'Popup', '$rootScope', '$state', 'ListFactory', 'ObjectFactory', function ($scope, Popup, $rootScope, $state, ListFactory, ObjectFactory) {
    $scope.obj = {};

    $scope.add = function () {
        var companyIdArrayJson = [];
        for (var i = 0; i < $scope.selectedName.length; i++) {
            companyIdArrayJson[i] = $scope.selectedName[i].id;
        }

        $scope.obj.companyIdArray = companyIdArrayJson;

        $scope.adminObjectFactory = new ObjectFactory();
        var promise = $scope.adminObjectFactory.saveOrQuery('/admin/insertMachineCenterOfChainStore.json', $scope.obj);
        promise.then(function (res) {
            if (res.status == 0) {
                Popup.notice("新增成功");
                $state.go("systemSetting.processCenter");
            } else {
                Popup.notice(res.errmsg, 3000, function () {});
            }
        });
    };

    $scope.selected = [];
    //创建变量用来保存选中结果

    var updateSelected = function updateSelected(action, id) {
        if (action == 'add' && $scope.selected.indexOf(id) == -1) {
            $scope.selected.push(id);
        }
        if (action == 'remove' && $scope.selected.indexOf(id) != -1) {
            $scope.selected.splice($scope.selected.indexOf(id), 1);
        }
    };

    //全选操作
    $scope.selectAll = function ($event) {
        var checkbox = $event.target;
        var action = checkbox.checked ? 'add' : 'remove';
        for (var i = 0; i < $scope.hospitalListFactory.items.length; i++) {
            var contact = $scope.hospitalListFactory.items[i];
            updateSelected(action, contact.id);
        }
    };

    $scope.isAllSelected = function () {

        var count = 0;

        if (!$scope.selected.length) {
            return false;
        }

        for (var i = 0; i < $scope.hospitalListFactory.items.length; i++) {
            var contact = $scope.hospitalListFactory.items[i];

            for (var j = 0; j < $scope.selected.length; j++) {
                if (contact.id == $scope.selected[j]) {
                    count = count + 1;
                }
            }
        }

        if (count == 15) {
            return true;
        } else {
            return false;
        }
    };

    //更新某一列数据的选择
    $scope.updateSelection = function ($event, id) {
        var checkbox = $event.target;

        var action = checkbox.checked ? 'add' : 'remove';
        updateSelected(action, id);
    };

    $scope.isSelected = function (id) {

        return $scope.selected.indexOf(id) >= 0;
    };

    $scope.company = {};
    $scope.company.status = 0;

    $scope.searchHospital = function () {

        $scope.hospitalListFactory = new ListFactory('/admin/getCompanyList.json', 0, 15, $scope.company);
        var hospitalPromise = $scope.hospitalListFactory.nextPage();
        hospitalPromise.then(function (res) {
            var pageSize = 15;
            $("#Pagination").pagination($scope.hospitalListFactory.count, {
                items_per_page: pageSize,
                callback: function callback(index) {
                    $scope.hospitalListFactory.clearAndSetIndex(index * pageSize);
                    $scope.hospitalListFactory.nextPage();
                }
            });
        });
    };

    $scope.selectedName = [];
    $scope.selectCompany = function () {

        if (!$scope.selected.length) {
            Popup.notice("请选择参数");
            return false;
        }

        for (var i = 0; i < $scope.selected.length; i++) {

            $scope.getHospitalInfoFactory = new ObjectFactory();
            var getSupplierPromise = $scope.getHospitalInfoFactory.saveOrQuery('/admin/getHospitalInfo.json', { id: $scope.selected[i] });
            getSupplierPromise.then(function (res) {

                $scope.selectedName.push({
                    name: res.object.companyName,
                    id: res.object.id
                });
            });
        }

        $scope.addDepotModal = false;
    };
    $scope.delteCompany = function (idx) {
        $scope.selectedName.splice(idx, 1);
    };

    $scope.showAddModal = function () {
        $scope.selected = [];
        $scope.addDepotModal = true;

        var arr = [];
        for (var i = 0; i < $scope.selectedName.length; i++) {
            arr[i] = $scope.selectedName[i].id;
        }
        $scope.company.excludeIdArray = arr;
        $scope.searchHospital();
    };
    var corpInfo = localStorage.getItem('corpInfo');
    corpInfo = corpInfo == null ? { companyTitle: '门店', employeeTitle: '视光师' } : JSON.parse(corpInfo);
    var companyTitle = corpInfo.companyTitle;
    $scope.addDepot = function () {

        if (!$scope.obj.machineCenterName) {
            Popup.notice('名称不能为空', 3000, function () {});
            return false;
        };

        $scope.add();
    };
}]);
'use strict';

angular.module('bestvisionWeb').controller('addProductPlanCtrl', ['$scope', 'Popup', '$timeout', '$rootScope', '$state', 'ListFactory', 'ObjectFactory', function ($scope, Popup, $timeout, $rootScope, $state, ListFactory, ObjectFactory) {
    $scope.obj = {};
    $scope.obj.status = 0;
    $scope.obj.packageType = 2;
    $scope.itemArr = [];
    $scope.add = function () {

        if (!$scope.obj.packageName) {
            Popup.notice('套餐名称不能为空');
            return false;
        }

        var arr = [];
        for (var i = 0; i < $scope.itemArr.length; i++) {
            var itemrate = $scope.itemArr[i].packageItemRate;
            var itemcount = $scope.itemArr[i].packageItemCount;
            if (itemcount === '' || itemcount === null) {

                Popup.notice('套餐件数不能为空');
                return false;
            }

            if (itemcount > 0) {
                if (/^[1-9]\d*$/.test(itemcount)) {} else {
                    Popup.notice('商品件数必须为正整数', 3000, function () {});
                    return false;
                }
            } else if (itemcount == 0) {
                Popup.notice('商品件数必须为正整数', 3000, function () {});
                return false;
            } else {
                Popup.notice('商品件数必须为正整数', 3000, function () {});
                return false;
            }

            if (itemrate === '' || itemrate === null) {

                Popup.notice('套餐折扣不能为空');
                return false;
            }

            if (itemrate > 0) {
                if (/^[1-9]\d*$/.test(itemrate)) {
                    if (itemrate > 100) {
                        Popup.notice('商品折扣必须在100以内', 3000, function () {});
                        return false;
                    }
                } else {
                    Popup.notice('商品折扣必须为正整数', 3000, function () {});
                    return false;
                }
            } else if (itemrate == 0) {} else {
                Popup.notice('商品折扣必须为正整数', 3000, function () {});
                return false;
            }

            arr.push({
                productId: $scope.itemArr[i].id,
                packageItemRate: itemrate,
                packageItemCount: itemcount

            });
        }
        if (!arr.length) {
            Popup.notice('商品列表不能为空');
            return false;
        }

        $scope.obj.productPackageListJson = JSON.stringify(arr);

        $scope.adminObjectFactory = new ObjectFactory();
        var promise = $scope.adminObjectFactory.saveOrQuery('/admin/insertPackage.json', $scope.obj);
        promise.then(function (res) {
            if (res.status == 0) {
                // $state.go('supplierList');
                window.history.back();
            } else {
                Popup.notice(res.errmsg, 3000, function () {});
            }
        });
    };

    $scope.searchProductWord = function () {
        $scope.schoolListFactory = new ListFactory('/admin/getProductVoList.json', 0, 12, { status: 0, keyword: $scope.keyword, productType: 1 });
        var checkPromise = $scope.schoolListFactory.nextPage();
        checkPromise.then(function (res) {

            var pageSize = 12;
            $(".second-pagination").pagination($scope.schoolListFactory.count, {

                items_per_page: pageSize,

                callback: function callback(index) {

                    $scope.schoolListFactory.clearAndSetIndex(index * pageSize);
                    var nextPromise = $scope.schoolListFactory.nextPage();
                    nextPromise.then(function (resp) {

                        $scope.selectId($scope.schoolListFactory.index);
                    });
                }
            });
        });
    };
    $scope.checkItemIdArray = [];

    $scope.selectId = function (idx) {
        $scope.isAll = true;

        var count = [];
        var arr = $scope.checkItemIdArray.slice(idx - 12, idx);

        for (var i = 0; i < arr.length; i++) {
            if (arr[i]) {
                count.push(arr[i]);
            }
        }

        if (count.length == $scope.schoolListFactory.items.length) {
            $scope.isAll = true;
        } else {
            $scope.isAll = false;
        }
    };

    $scope.checkAll = function () {

        if ($scope.isAll) {

            for (var i = 0; i < $scope.schoolListFactory.items.length; i++) {
                $scope.checkItemIdArray[i + $scope.schoolListFactory.index - 12] = $scope.schoolListFactory.items[i].product.id;
            }
        } else {

            for (var j = 0; j < $scope.schoolListFactory.items.length; j++) {
                $scope.checkItemIdArray[j + $scope.schoolListFactory.index - 12] = null;
            }
        }
    };

    $scope.itemNameArr = [];

    var getItemNameFactory;
    $scope.modifyCheck = function () {

        var arr = [];
        // for (var k = 0; k < $scope.checkItemIdArray.length; k++) {

        //     if ($scope.itemNameArr.indexOf($scope.checkItemIdArray[k]) == -1) {
        //         arr.push($scope.checkItemIdArray[k]);
        //     }
        // }
        for (var k = 0; k < $scope.checkItemIdArray.length; k++) {

            if ($scope.checkItemIdArray[k]) {
                arr.push($scope.checkItemIdArray[k]);
            }
        }

        for (var i = 0; i < arr.length; i++) {

            if (arr[i]) {

                getItemNameFactory = new ObjectFactory();
                var namePromise = getItemNameFactory.saveOrQuery('/admin/getProductVo.json', { productId: arr[i] });
                namePromise.then(function (res) {
                    $scope.itemNameArr.push(res.result.object.product.id);
                    $scope.itemArr.push({
                        examineName: res.result.object.product.productName,
                        id: res.result.object.product.id,
                        packageItemRate: 100,
                        packageItemCount: 1
                    });
                });
            }
        }

        $scope.schoolModal = false;
    };

    $scope.deleteItem = function (idx) {

        $scope.itemNameArr.splice(idx, 1);
        $scope.itemArr.splice(idx, 1);
    };

    $scope.showCheckModal = function () {
        $scope.checkItemIdArray = [];
        $scope.schoolModal = true;
        $scope.searchProductWord();
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("addProjectCardCtrl", ["$scope", "Popup", "$state", "ObjectFactory", "$stateParams", function ($scope, Popup, $state, ObjectFactory, $stateParams) {
  $scope.edit = $stateParams.id ? true : false; //编辑新增页面
  $scope.obj = {};
  /* 默认值 */
  $scope.obj.unitName = "次";
  $scope.obj.status = 0;
  $scope.obj.allowReturnCard = 1;
  $scope.obj.allowChangePrice = 1;
  $scope.obj.allowChangeNumber = 1;
  $scope.obj.disableValidMonths = true; //默认有效期为永久
  /* 选择图片的类 */
  $scope.choseImg = {
    type: "",
    show: false,
    coverImgUrl: ""
  };
  $scope.allowList = [{ id: 0, name: "允许" }, { id: 1, name: "不允许" }];
  $scope.status = [{ id: 0, name: "正常" }, { id: 1, name: "停用" }];
  $scope.getImgArray = []; //显示多选图片的数组
  $scope.searchTrainerCard = function (trainerCardId) {
    new ObjectFactory().saveOrQuery("/admin/getTrainerCard.json", {
      trainerCardId: trainerCardId
    }).then(function (res) {
      if (res.status) {
        return Popup.notice(res.errmsg);
      }
      $scope.obj = res.result.object;
      if (res.result.object.imageDescription) {
        $scope.getImgArray = res.result.object.imageDescription.split(",");
        $scope.obj.imageDescription = $scope.getImgArray[0];
      }
      $scope.obj.trainerCardId = trainerCardId;
      !$scope.obj.validMonths && ($scope.obj.disableValidMonths = true); //默认有效期为永久
    });
  };
  $stateParams.id && $scope.searchTrainerCard($stateParams.id);

  /* 必填项 */
  var mustKey = {
    trainerCardName: "请输入次卡名称",
    marketPrice: "请输入售价",
    unitName: "请输入单位",
    numbers: "请输入次数",
    allowReturnCard: "请选择允许退卡",
    allowChangePrice: "请选择允许改价",
    allowChangeNumber: "请选择允许改次",
    status: "请选择状态"
  };
  $scope.description_popout = false;
  $scope.cancelPopout = function () {
    $scope.description_popout = false;
  };
  $scope.$watch("choseImg.coverImgUrl", function (newv, oldv) {
    if (newv) {
      $scope.obj[$scope.choseImg.type] = newv;
      $scope.choseImg.type = "";
    }
  });
  /* 选择图片 */
  $scope.chooseCoverImg = function (type) {
    $scope.choseImg.type = type;
    $scope.choseImg.show = true;
  };
  $scope.projectCard = function () {
    //   console.log($scope.getImgArray); //保存了选中图片的数组
    for (var i in mustKey) {
      if ($scope.obj[i] == undefined || $scope.obj[i] == null) {
        return Popup.notice(mustKey[i]);
      }
    }
    if ($scope.getImgArray.length) {
      $scope.obj.imageDescription = $scope.getImgArray.join(",");
    }
    var reqUrl = $stateParams.id ? "/admin/updateTrainerCard.json" : "/admin/addTrainerCard.json";
    /* console.log("$scope.obj");
    console.log($scope.obj);
    return; */
    new ObjectFactory().saveOrQuery(reqUrl, $scope.obj).then(function (res) {
      if (res.status) {
        return Popup.notice(res.errmsg);
      }
      $state.go("systemSetting.projectCard");
    });
  };
  $scope.changeStatus = function (key) {
    $scope.obj[key] = !$scope.obj[key];
    $scope.obj.validMonths = null;
    $scope.obj.remindDays = null;
  };
}]);
'use strict';

