angular.module('bestvisionWeb').controller('customerChargeItemCtrl', ['$scope', '$location', 'Popup', '$rootScope', '$state', 'ObjectFactory', 'ListFactory', function ($scope, $location, Popup, $rootScope, $state, ObjectFactory, ListFactory) {

    $scope.obj = {};
    $scope.obj.status = null;
    $scope.searchTab = function (tab) {
        $scope.obj.status = tab;
        $scope.search();
    };
    $scope.pageSize = 20;
    $scope.search = function () {
        $scope.getModelNameListFactory = new ListFactory('/admin/selectModelNameVoList.json', 0, $scope.pageSize, $scope.obj);
        var promise = $scope.getModelNameListFactory.nextPage();

        promise.then(function (data) {
            console.log(data);
            $("#Pagination").pagination($scope.getModelNameListFactory.count, {
                items_per_page: $scope.pageSize,
                callback: function callback(index) {
                    $scope.getModelNameListFactory.clearAndSetIndex(index * $scope.pageSize);
                    $scope.getModelNameListFactory.nextPage();
                }
            });
        });
    };

    $scope.search();
    $scope.paramPageSize = 12;
    $scope.serachArr = function () {

        $scope.paramListFactory = new ListFactory('/admin/selectParamNameVoList.json', 0, $scope.paramPageSize, { paramType: 1, status: 0, keyword: $scope.paramKeyword });
        var paramPromise = $scope.paramListFactory.nextPage();
        paramPromise.then(function (data) {
            $(".second-pagination").pagination($scope.paramListFactory.count, {
                items_per_page: $scope.paramPageSize,
                callback: function callback(index) {
                    $scope.paramListFactory.clearAndSetIndex(index * $scope.paramPageSize);
                    $scope.paramListFactory.nextPage();
                }
            });
        });
    };
    $scope.showAddModal = function () {
        $scope.serachArr();
        $scope.checkbillModal = true;
    };

    $scope.selete = {};
    var selectValue = function selectValue(id, tab) {

        var url = '';
        var param = {};
        if (tab == 1) {
            url = "/admin/selectModelValueList.json";
            param.modelNameId = id;
        } else {
            url = "/admin/selectParamValueList.json";
            param.paramNameId = id;
        }
        $scope.modelValeObjectFactory = new ObjectFactory();
        $scope.modelValeObjectFactory.saveOrQuery(url, param);
    };

    $scope.showImport = function (name, id) {

        $scope.selete.seletedName = name;
        $scope.selete.seletedId = id;
        $scope.seleteModal = true;
        selectValue(id, 2);
    };

    $scope.importParam = function () {

        if (!$scope.selete.seletedName) {
            Popup.notice("参数名不能为空");
            return false;
        }

        $scope.copyParamObjectFactory = new ObjectFactory();
        var getSupplierPromise = $scope.copyParamObjectFactory.saveOrQuery('/admin/copyParamNameAndValue.json', { paramType: 1, paramNameId: $scope.selete.seletedId, newName: $scope.selete.seletedName });
        getSupplierPromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice("导入成功");
                $scope.seleteModal = false;
                $scope.checkbillModal = false;
                $scope.search();
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };

    $scope.showModalName = function (id, tab) {
        $scope.modelNameModal = true;
        selectValue(id, tab);
    };
}]);
'use strict';

