angular.module('bestvisionWeb').controller('materialCertificateCtrl', ['$scope', 'Popup', '$stateParams', '$rootScope', '$state', 'ObjectFactory', function ($scope, Popup, $stateParams, $rootScope, $state, ObjectFactory) {
    $scope.obj = {};
    $scope.obj.productId = $stateParams.productId;
    $scope.productSkuId = $stateParams.productSkuId;

    $scope.localTime = new Date().getTime();
    $scope.supplierQualifyArr = [];

    $scope.getProductVoFactory = new ObjectFactory();
    var getSupplierPromise = $scope.getProductVoFactory.saveOrQuery('/admin/getProductVoOnly.json', { productId: $scope.obj.productId });
    getSupplierPromise.then(function (res) {

        $scope.warningQualifyExpiresDays = res.object.product.warningQualifyExpiresDays;
    });

    $scope.getSupplierQualifyObjectFactory = new ObjectFactory();
    var supplierPromise = $scope.getSupplierQualifyObjectFactory.saveOrQuery('/admin/selectProductQualifyList.json', { productId: $scope.obj.productId });
    supplierPromise.then(function (res) {

        var arr = res.result.list;
        for (var i = 0; i < arr.length; i++) {

            $scope.supplierQualifyArr[i] = {
                qualifyTitle: arr[i].qualifyTitle,
                qualifyCode: arr[i].qualifyCode,
                qualifyFile: arr[i].qualifyFile,
                qualifyFileName: arr[i].qualifyFileName,
                qualifyPermanent: arr[i].qualifyPermanent,
                qualifyExpireDateLong: arr[i].qualifyExpireDate == null ? null : new Date(arr[i].qualifyExpireDate)
            };
        }

        console.log($scope.supplierQualifyArr);
    });

    $scope.showModal = function () {
        $scope.anzhuangShow = true;
        $scope.title.qualifyTitle = '';
        $scope.title.other = '';
    };
    $scope.hideModal = function () {
        $scope.anzhuangShow = false;
    };

    $scope.title = {};
    $scope.selectQuanlify = function () {
        if ($scope.title.qualifyTitle == 'other') {
            if (!$scope.title.other) {
                Popup.notice("请输入资质名称");
                return false;
            } else {
                $scope.title.qualifyTitle = $scope.title.other;
            }
        }

        $scope.supplierQualifyArr.push({
            qualifyTitle: $scope.title.qualifyTitle,
            qualifyCode: '',
            qualifyFile: '',
            qualifyPermanent: 1,
            qualifyExpireDateLong: null
        });
        $scope.anzhuangShow = false;
    };

    $scope.setPermanent = function (val, idx, e) {
        e.stopPropagation();
        console.log(val);
        if (val === 1) {
            $scope.supplierQualifyArr[idx].qualifyExpireDateLong = null;
        }
    };
    $scope.download = function (path) {
        console.log(path);
        if (!path) {
            Popup.notice("请上传文件");
            return false;
        }
        $scope.getTaskUrlFactory = new ObjectFactory();
        var urlPromise = $scope.getTaskUrlFactory.saveOrQuery('/auth/privateDownloadUrl.json', { url: path });
        urlPromise.then(function (res) {
            // window.location.href = res.object;
            window.open(res.object, '_blank');
        });
    };

    $scope.deleteItem = function (idx) {

        Popup.confirm('确认删除么', function () {

            $scope.supplierQualifyArr.splice(idx, 1);
        }, function () {});
    };
    $scope.modify = function () {

        if ($scope.warningQualifyExpiresDays > 0) {
            if (!/^[1-9]\d*$/.test($scope.warningQualifyExpiresDays)) {
                Popup.notice('预警天数必须为整数');
                return;
            };
        } else if ($scope.warningQualifyExpiresDays === 0) {
            console.log($scope.warningQualifyExpiresDays);
        } else {
            Popup.notice('预警天数必须大于0');
            return;
        }
        $scope.updateSupplierDayObjectFactory = new ObjectFactory();
        $scope.updateSupplierDayObjectFactory.saveOrQuery('/admin/updateProductWarningQualifyExpiresDays.json', { productId: $scope.obj.productId, warningQualifyExpiresDays: $scope.warningQualifyExpiresDays });
        console.log($scope.supplierQualifyArr);
        for (var i = 0; i < $scope.supplierQualifyArr.length; i++) {

            if ($scope.supplierQualifyArr[i].qualifyPermanent === 1) {
                $scope.supplierQualifyArr[i].qualifyExpireDateLong = null;
            } else {
                if (!$scope.supplierQualifyArr[i].qualifyExpireDateLong) {
                    Popup.notice("请选择资质过期时间");
                    return false;
                } else {
                    if (typeof $scope.supplierQualifyArr[i].qualifyExpireDateLong !== 'number') {
                        $scope.supplierQualifyArr[i].qualifyExpireDateLong = $scope.supplierQualifyArr[i].qualifyExpireDateLong.getTime();
                    }
                }
            }
        }
        console.log($scope.supplierQualifyArr);
        $scope.obj.productQualifyListJson = JSON.stringify($scope.supplierQualifyArr);

        $scope.saveSupplierQualifyObjectFactory = new ObjectFactory();
        var savePromise = $scope.saveSupplierQualifyObjectFactory.saveOrQuery('/admin/saveProductQualifyList.json', $scope.obj);
        savePromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice("保存成功");
            } else {
                Popup.notice(res.errmsg, 3000, function () {});
            }
        });
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("materialImportCtrl", ["$scope", "Popup", "$interval", "$rootScope", "$state", "ListFactory", "ObjectFactory", function ($scope, Popup, $interval, $rootScope, $state, ListFactory, ObjectFactory) {
  $scope.status = [{ id: null, name: "全部" }, { id: 1, name: "错误" }, { id: 0, name: "正确" }];
  $scope.obj = {};
  $scope.obj.status = null;

  $scope.idxNum = 0;

  $scope.searchTaskList = function () {
    $scope.getTaskListFactory = new ListFactory("/admin/selectTaskList.json", $scope.idxNum * 10, 10);
    var promise = $scope.getTaskListFactory.nextPage();
    promise.then(function (res) {
      var pageSize = 10;
      $(".pagination-list").pagination($scope.getTaskListFactory.count, {
        items_per_page: pageSize,
        current_page: $scope.idxNum,
        callback: function callback(index) {
          $scope.idxNum = index;
          $scope.getTaskListFactory.clearAndSetIndex(index * pageSize);
          $scope.getTaskListFactory.nextPage();
        }
      });
    });
  };
  $scope.searchTaskList();

  $scope.download = function (path) {
    $scope.getTaskUrlFactory = new ObjectFactory();
    var urlPromise = $scope.getTaskUrlFactory.saveOrQuery("/auth/privateDownloadUrl.json", { url: path });
    urlPromise.then(function (res) {
      window.location.href = res.object;
    });
  };

  $scope.timePromise = $interval(function () {
    $scope.searchTaskList();
  }, 5000);
  $scope.interval = true;
  $scope.setInterval = function (interval) {
    if (interval) {
      $scope.timePromise = $interval(function () {
        $scope.searchTaskList();
      }, 5000);
    } else {
      if (angular.isDefined($scope.timePromise)) {
        $interval.cancel($scope.timePromise);
      }
    }
  };
  $scope.$on("$destroy", function () {
    if (angular.isDefined($scope.timePromise)) {
      $interval.cancel($scope.timePromise);
    }
  });

  $scope.importModal = false;

  $scope.hideModal = function () {
    $scope.importModal = false;
  };
  $scope.showModal = function (id, status) {
    $scope.taskId = id;
    if (status == 4) {
      $scope.obj.status = 1;
    }
    if (status == 3) {
      $scope.obj.status = 0;
    }

    $scope.importModal = true;
    $scope.searchList();
  };

  $scope.searchList = function () {
    $scope.getTaskItemFactory = new ListFactory("/admin/selectTaskItemList.json", 0, 4, { taskId: $scope.taskId, status: $scope.obj.status });
    var importPromise = $scope.getTaskItemFactory.nextPage();
    importPromise.then(function (res) {
      var pageSize = 4;
      $(".pagination-record").pagination($scope.getTaskItemFactory.count, {
        items_per_page: pageSize,
        callback: function callback(index) {
          $scope.getTaskItemFactory.clearAndSetIndex(index * pageSize);
          $scope.getTaskItemFactory.nextPage();
        }
      });
    });
  };
}]);
"use strict";

angular.module("bestvisionWeb").controller("materiallistCtrl", ["$scope", "$location", "$timeout", "Popup", "HttpFactory", "daochuFactory", "$state", "ListFactory", "StorageFactory", "ObjectFactory", "Utils", function ($scope, $location, $timeout, Popup, HttpFactory, daochuFactory, $state, ListFactory, StorageFactory, ObjectFactory, Utils) {
  var pa = $location.path();
  var res = pa.split("/");
  $scope.lock = {
    needLock: false,
    ableclose: true, //是否允许关闭解锁弹框
    lookBack: function lookBack() {
      $state.go(res[1] + ".batchMaterial");
    },
    open: function open() {
      this.needLock = true;
    }
  };
  $scope.firstCheckStatus = {
    show: false,
    status: null,
    tablist: [{ status: null, name: "首营审批", class: "maxwidth_66" }, { status: 0, name: "通过", ionc: "#41b2a6" }, { status: 1, name: "拒绝", ionc: "#de6262" }],
    callback: function callback() {
      $scope.obj.productFirstMarketCheckStatus = this.status;
      $scope.searchSupplierList();
    }
  };
  $scope.obj = {};
  $scope.obj.priceFromInclude = null;
  $scope.obj.priceToInclude = null;
  $scope.obj.model1Keyword = "";
  $scope.obj.model2Keyword = "";
  $scope.obj.keyword = "";
  $scope.obj.categoryId = "";
  $scope.obj.brandId = "";
  $scope.obj.status = 0;
  $scope.obj.canBeDiscounted = "";
  $scope.obj.allowPoints = "";
  $scope.obj.qualifyExpiresWarning = false;
  $scope.obj.page = 0;
  $scope.categoryAll = true;
  var store = JSON.parse(StorageFactory.getItem("materiallist"));

  if (store) {
    $scope.obj.status = store.status;
    $scope.obj.page = store.page ? store.page : 0;
    $scope.obj.canBeDiscounted = store.canBeDiscounted;
    $scope.obj.allowPoints = store.allowPoints;
    $scope.obj.keyword = store.keyword ? store.keyword : "";
    $scope.obj.priceFromInclude = store.priceFromInclude ? store.priceFromInclude : "";
    $scope.obj.priceToInclude = store.priceToInclude ? store.priceToInclude : "";
    $scope.firstCheckStatus.status = $scope.obj.productFirstMarketCheckStatus = Utils.isNull(store.productFirstMarketCheckStatus) ? null : store.productFirstMarketCheckStatus;
    $scope.obj.qualifyExpiresWarning = store.qualifyExpiresWarning;
    $scope.obj.model1Keyword = store.model1Keyword ? store.model1Keyword : "";
    $scope.obj.model2Keyword = store.model2Keyword ? store.model2Keyword : "";
    $scope.obj.categoryId = store.categoryId ? store.categoryId : "";
    $scope.categoryAll = store.categoryId ? false : true;
    $scope.getCategoryFactory = new ObjectFactory();
    var catPromise = $scope.getCategoryFactory.saveOrQuery("/admin/getCategory.json", { categoryId: $scope.obj.categoryId });

    catPromise.then(function (res) {
      if (res.result.object) {
        if (res.result.object.familyId) {
          $scope.seletedCategory = res.result.object.familyId;
          $scope.seletedCategoryId = res.result.object.id;
          $scope.childList = res.result.object.familyId;
        } else {
          $scope.seletedCategory = res.result.object.id;
        }
      }
    });

    $scope.obj.brandId = store.brandId ? store.brandId : "";
  }

  $scope.firstCheckStatus.show = true;
  $scope.status = [{ id: "", name: "全部" }, { id: 0, name: "正常" }, { id: 1, name: "停用" }];

  $scope.isLookFun = function () {
    window.grantAuth.isUnlockFun(ObjectFactory, "addLens").then(function (resolve) {
      $timeout(function () {
        $scope.pasDue = resolve;
        $scope.lock.lookBack();
      });
    }, function (err) {
      if (err) {
        return Popup.notice(err);
      }
      $timeout(function () {
        $scope.lock.needLock = true;
      });
    });
  };
  $scope.searchCateCount = function () {
    $scope.searchCategoryObjectFactory = new ObjectFactory();
    $scope.searchCategoryObjectFactory.saveOrQuery("/admin/getCategoryTree2LevelWithSkuCount.json", { productType: 1 });
  };
  $scope.searchCateCount();
  $scope.categoryChildList = false;
  $scope.parentId = "";

  $scope.productSkuIdArray = [];
  $scope.object = {};
  $scope.object.status = 0;
  $scope.object.allowPoints = 1;
  $scope.object.canBeDiscounted = 1;

  var authStr = daochuFactory.getAuthStr();
  $scope.daochu = function () {
    var priceToInclude = "";
    var priceFromInclude = "";
    if ($scope.obj.priceFromInclude === null) {
      priceFromInclude = "";
    } else {
      priceFromInclude = $scope.obj.priceFromInclude;
    }
    if ($scope.obj.priceToInclude === null) {
      priceToInclude = "";
    } else {
      priceToInclude = $scope.obj.priceToInclude;
    }
    window.location.href = API_HOST + "/admin/downloadProductSkuVoList.htm?keyword=" + encodeURIComponent($scope.obj.keyword) + "&model1Keyword=" + encodeURIComponent($scope.obj.model1Keyword) + "&model2Keyword=" + encodeURIComponent($scope.obj.model2Keyword) + "&categoryId=" + $scope.obj.categoryId + "&status=" + $scope.obj.status + "&brandId=" + $scope.obj.brandId + "&priceFromInclude=" + priceFromInclude + "&priceToInclude=" + priceToInclude + "&qualifyExpiresWarning=" + $scope.obj.qualifyExpiresWarning + "&canBeDiscounted=" + $scope.obj.canBeDiscounted + "&allowPoints=" + $scope.obj.allowPoints + "&index=" + $scope.downloadIndex + "&length=" + $scope.pageSize + authStr;
    $scope.downloadModal = false;
  };
  $scope.goAdd = function (path) {
    if (path === "batchMaterial") {
      $scope.lock.lookBack();
      return;
    }
    var result = res[1] + "." + path;
    $state.go(result);
  };

  $scope.changeSeletedProduct = function (tab) {
    var arrLabel = [];
    for (var i = 0; i < $scope.productSkuIdArray.length; i++) {
      if ($scope.productSkuIdArray[i] != null && $scope.productSkuIdArray[i] != "null") {
        arrLabel.push($scope.productSkuIdArray[i]);
      }
    }
    var paramObj = {};
    paramObj.productSkuIdArray = arrLabel;
    if (tab == 1) {
      paramObj.status = $scope.object.status;
    } else if (tab == 2) {
      paramObj.allowPoints = $scope.object.allowPoints;
    } else {
      paramObj.canBeDiscounted = $scope.object.canBeDiscounted;
    }

    $scope.changeStatusObjectFactory = new ObjectFactory();
    var statusPromise = $scope.changeStatusObjectFactory.saveOrQuery("/admin/updateByProductSkuIdArraySelective.json", paramObj);
    statusPromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
          for (var j = 0; j < arrLabel.length; j++) {
            if (arrLabel[j] == $scope.getSupplierListFactory.items[i].productSku.id) {
              if (tab == 1) {
                $scope.getSupplierListFactory.items[i].productSku.status = $scope.object.status;
              } else if (tab == 2) {
                $scope.getSupplierListFactory.items[i].productSku.allowPoints = $scope.object.allowPoints;
              } else {
                $scope.getSupplierListFactory.items[i].productSku.canBeDiscounted = $scope.object.canBeDiscounted;
              }
            }
          }
        }

        Popup.notice("修改成功");
        $scope.hideTagModal();
      }
    });
  };

  $scope.labelBtn = true;

  $scope.hideTagModal = function (event) {
    $scope.tagModal = false;
    $scope.discountModal = false;
    $scope.pointModal = false;
  };

  $scope.checkAll = function () {
    if ($scope.isAll) {
      for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
        $scope.productSkuIdArray[i + $scope.getSupplierListFactory.index - $scope.pageSize] = $scope.getSupplierListFactory.items[i].productSku.id;
        $scope.labelBtn = false;
      }
    } else {
      for (var j = 0; j < $scope.getSupplierListFactory.items.length; j++) {
        $scope.productSkuIdArray[j + $scope.getSupplierListFactory.index - $scope.pageSize] = null;
        $scope.labelBtn = true;
      }
    }
  };

  $scope.setLabelBtn = function () {
    var arrLabel = [];

    for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
      if ($scope.productSkuIdArray[i + $scope.getSupplierListFactory.index - $scope.pageSize] != "null" && $scope.productSkuIdArray[i + $scope.getSupplierListFactory.index - $scope.pageSize] != null) {
        $scope.labelBtn = false;
        arrLabel.push($scope.productSkuIdArray[i + $scope.getSupplierListFactory.index - $scope.pageSize]);
      }
    }

    if (!arrLabel.length) {
      $scope.labelBtn = true;
    }
    if (arrLabel.length != $scope.getSupplierListFactory.items.length) {
      $scope.isAll = false;
    } else {
      $scope.isAll = true;
    }
  };

  $scope.searchTab = function (index) {
    console.log(index);
    $scope.obj.page = 0;
    if (index === undefined) {
      $scope.obj.status = "";
    } else {
      $scope.obj.status = index;
    }

    $scope.searchSupplierList();
  };
  $scope.searchDiscount = function (index) {
    if (index === undefined) {
      $scope.obj.canBeDiscounted = "";
    } else {
      $scope.obj.canBeDiscounted = index;
    }
    $scope.obj.page = 0;
    $scope.searchSupplierList();
  };
  $scope.searchPoints = function (index) {
    if (index === undefined) {
      $scope.obj.allowPoints = "";
    } else {
      $scope.obj.allowPoints = index;
    }
    $scope.obj.page = 0;
    $scope.searchSupplierList();
  };
  $scope.modifyMaterial = function (id, skuId) {
    var result = res[1] + "." + "materialModify";
    console.log(skuId);
    $state.go(result, { productId: id, productSkuId: skuId });
  };

  $scope.chooseCategory = function (id, bool) {
    $scope.obj.categoryId = id;
    $scope.childList = id;
    $scope.seletedCategory = id;
    $scope.categoryChildList = !$scope.categoryChildList;
    $scope.obj.page = 0;
    $scope.searchSupplierList();
    if ($scope.parentId !== id) {
      $scope.parentId = id;
      $scope.seletedCategoryId = "";
    }
    if (bool) {
      $scope.categoryAll = true;
    } else {
      $scope.categoryAll = false;
    }
  };
  $scope.chooseCategoryId = function (id, event) {
    event.stopPropagation();
    $scope.seletedCategoryId = id;
    $scope.obj.categoryId = id;
    $scope.obj.page = 0;
    $scope.searchSupplierList();
  };

  $scope.selectBrandId = function (id, name) {
    $scope.obj.brandId = id;
    $scope.keyword = name;
    $scope.brandlist = false;
    $scope.obj.page = 0;
    $scope.searchSupplierList();
  };

  $scope.clearSearchSupplierList = function () {
    $scope.obj.page = 0;
    $scope.searchSupplierList();
  };

  $scope.getBrandFactory = new ObjectFactory();
  $scope.getBrandFactory.saveOrQuery("/admin/getBrandListOfProduct.json");

  $scope.hideBrandlist = function () {
    $scope.brandlist = false;
  };
  $scope.downloadIndex = 0;
  $scope.pageSize = 20;

  $scope.searchSupplierList = function () {
    var pageStart = $scope.obj.page ? $scope.obj.page * $scope.pageSize : 0;
    StorageFactory.setItem("materiallist", JSON.stringify($scope.obj));
    $scope.downloadIndex = 0;
    $scope.getSupplierListFactory = new ListFactory("/admin/getProductSkuVoList.json", pageStart, $scope.pageSize, $scope.obj);
    var promise = $scope.getSupplierListFactory.nextPage();
    promise.then(function (data) {
      $(".pagination-account").pagination($scope.getSupplierListFactory.count, {
        items_per_page: $scope.pageSize,
        current_page: $scope.obj.page,
        callback: function callback(index) {
          $scope.obj.page = index;
          StorageFactory.setItem("materiallist", JSON.stringify($scope.obj));
          $scope.downloadIndex = index * $scope.pageSize;
          $scope.getSupplierListFactory.clearAndSetIndex(index * $scope.pageSize);
          var nextPromise = $scope.getSupplierListFactory.nextPage();

          nextPromise.then(function (response) {
            console.log($scope.getSupplierListFactory);

            var count = 0;
            for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
              for (var j = 0; j < $scope.productSkuIdArray.length; j++) {
                if ($scope.getSupplierListFactory.items[i].productSku.id == $scope.productSkuIdArray[j]) {
                  count = count + 1;
                }
              }
            }

            if ($scope.productSkuIdArray.length && $scope.getSupplierListFactory.items.length) {
              if (count == $scope.getSupplierListFactory.items.length) {
                $scope.isAll = true;
              } else {
                $scope.isAll = false;
              }
            } else {
              $scope.isAll = false;
            }
          });
        }
      });
    });
  };
  $scope.searchSupplierList();

  $scope.changePage = function () {
    $scope.productSkuIdArray = [];
    $scope.isAll = false;

    $scope.searchSupplierList();
  };
  $scope.data = {
    filepath: null
  };

  $scope.store = {};

  $scope.createTask = function () {
    if (!$scope.data.filepath) {
      Popup.notice("请选择文件");
      return;
    }
    $scope.createTaskFactory = new ObjectFactory();
    var createPromise = $scope.createTaskFactory.saveOrQuery("/admin/createProductBatchFileTask.json", { filePath: $scope.data.filepath });
    createPromise.then(function (res) {
      console.log(res);
      if (res.status == 0) {
        $scope.importModal = false;
        Popup.notice("导入任务正在执行中");
        $state.go("materialImport");
      }
    });
  };
  $scope.deleteBatch = function () {
    if ($scope.labelBtn) return;
    Popup.confirm('物资收费删除后不可恢复，确定要删除？', function () {
      var productSkuIdArray = $scope.productSkuIdArray.filter(function (v) {
        return v;
      });
      HttpFactory.object('/admin/deleteProductSkus.json', {
        productSkuIdArray: productSkuIdArray
      }).then(function () {
        Popup.notice('删除成功!');
        $scope.labelBtn = true;
        $scope.isAll = false;
        $scope.productSkuIdArray = [];
        $scope.searchSupplierList();
      });
    });
  };
}]);
"use strict";

function _toConsumableArray(arr) { if (Array.isArray(arr)) { for (var i = 0, arr2 = Array(arr.length); i < arr.length; i++) { arr2[i] = arr[i]; } return arr2; } else { return Array.from(arr); } }

angular.module("bestvisionWeb").controller("materialModifyCtrl", ["$scope", "Popup", "CommonRequest", "ListFactory", "$location", "$anchorScroll", "$stateParams", "Utils", "CommonRemark", "ObjectFactory", "FirstApprovalConfig", function ($scope, Popup, CommonRequest, ListFactory, $location, $anchorScroll, $stateParams, Utils, CommonRemark, ObjectFactory, FirstApprovalConfig) {
  $scope.firstApproval = angular.copy(FirstApprovalConfig);
  $scope.CommonRemark = CommonRemark;
  $scope.productId = $stateParams.productId;
  $scope.productSkuId = $stateParams.productSkuId;
  $scope.obj = {};

  $scope.unitNames = window.optionsObj.unitNames;
  $scope.status = [{ id: 0, name: "正常" }, { id: 1, name: "停用" }];
  $scope.discounts = [{ id: 1, name: "是" }, { id: 0, name: "否" }];
  $scope.selectCategoryItemVoList = function (categoryId) {
    CommonRequest.selectCategoryItemVoList(categoryId, function (res) {
      $scope.categoryItemVoList = res;
    });
  };
  $scope.categoryItemVoList = [];
  $scope.getProductVoFactory = new ObjectFactory();
  var getSupplierPromise = $scope.getProductVoFactory.saveOrQuery("/admin/getProductVoOnly.json", { productId: $scope.productId });
  getSupplierPromise.then(function (res) {
    $scope.obj = res.object;
    $scope.obj.brandId = res.object.brand.id;
    $scope.obj.categoryId = res.object.category.id;
    //查询有无特殊属性列表
    CommonRequest.selectCategoryItemVoList(res.object.category.id, function (categoryItem) {
      $scope.categoryItemVoList = Utils.commonComponentFormat.set(categoryItem, res.object.product.productSpecialItem);
    });
    $scope.getSupplierFactory = new ObjectFactory();
    var supplierPromise = $scope.getSupplierFactory.saveOrQuery("/admin/getSupplier.json", { id: $scope.obj.product.mainSupplierId });
    supplierPromise.then(function (resp) {
      if (resp.result.object) {
        $scope.supplierWord = resp.result.object.supplierName;
      }
    });

    $scope.searchSpecList();
  });

  $scope.pagesize = 100;

  $scope.searchSpecList = function () {
    $scope.getProductVoIndexFactory = new ObjectFactory();
    var indexPromise = $scope.getProductVoIndexFactory.saveOrQuery("/admin/selectProductSkuIndex.json", { productId: $scope.productId, productSkuId: $scope.productSkuId });
    indexPromise.then(function (res) {
      var productIdx = res.result.object + 1;
      var pageIdx = Math.ceil(productIdx / $scope.pagesize) - 1;
      $scope.pageNum = pageIdx;

      $scope.getProductVoObjectFactory = new ListFactory("/admin/selectProductSkuList.json", pageIdx * $scope.pagesize, $scope.pagesize, { productId: $scope.productId });
      var promise = $scope.getProductVoObjectFactory.nextPage();

      promise.then(function (data) {
        $scope.storeCustomeIndex = $scope.getProductVoObjectFactory.count;
        $scope.storeCustomeIndexArr = [];
        $scope.num = data.count;
        $scope.obj.skuList = data.items;
        $location.hash("anchor" + $scope.productSkuId);
        $anchorScroll();

        $("#Pagination").pagination($scope.getProductVoObjectFactory.count, {
          items_per_page: $scope.pagesize,
          current_page: pageIdx,
          callback: function callback(index) {
            $scope.pageNum = index;
            $scope.getProductVoObjectFactory.clearAndSetIndex(index * $scope.pagesize);
            var nextPromise = $scope.getProductVoObjectFactory.nextPage();
            nextPromise.then(function (res) {
              $scope.obj.skuList = res.items;
              $scope.storeCustomeIndex = $scope.getProductVoObjectFactory.count;
              $scope.storeCustomeIndexArr = [];
            });
          }
        });
      });
    });
  };

  $scope.parentId = "";

  $scope.hideBrandlist = function () {
    $scope.brandlist = false;
  };

  $scope.showCategory = function () {
    $scope.categoryModal = true;
  };

  $scope.hideCategory = function () {
    $scope.categoryModal = false;
  };

  $scope.tab = {};
  $scope.setTab = function (idx) {
    $scope.tabIdx = idx;

    $scope.tab.unitName == null;
    $scope.tab.costPrice == null;
    $scope.tab.marketPrice == null;
    $scope.tab.status == null;
    $scope.tab.canBeDiscounted == null;
    $scope.setAllModal = true;
    $scope.tab.kpiPrice == null;
  };

  $scope.setAllProduct = function () {
    var selectObj = {};
    selectObj.productId = $stateParams.productId;

    if ($scope.tabIdx == 1) {
      if ($scope.tab.unitName == null || $scope.tab.unitName == undefined) {
        Popup.notice("请输入单位", 3000, function () {});
        return;
      }

      for (var i = 0; i < $scope.obj.skuList.length; i++) {
        $scope.obj.skuList[i].unitName = $scope.tab.unitName;
      }
      selectObj.unitName = $scope.tab.unitName;
    }
    if ($scope.tabIdx == 2) {
      if ($scope.tab.costPrice == null || $scope.tab.costPrice == undefined) {
        Popup.notice("请输入成本价", 3000, function () {});
        return;
      }

      if ($scope.tab.costPrice > 0) {
        if (!/^\d+(\.\d{1,2})?$/.test($scope.tab.costPrice)) {
          Popup.notice("成本价只能精确到2位小数", 3000, function () {});
          return false;
        }
      } else if ($scope.tab.costPrice == 0) {} else {
        Popup.notice("成本价不能小于0", 3000, function () {});
        return;
      }

      for (var i = 0; i < $scope.obj.skuList.length; i++) {
        $scope.obj.skuList[i].costPrice = $scope.tab.costPrice;
      }

      selectObj.costPrice = $scope.tab.costPrice;
    }
    if ($scope.tabIdx == 3) {
      if ($scope.tab.marketPrice == null || $scope.tab.marketPrice == undefined) {
        Popup.notice("请输入零售价", 3000, function () {});
        return;
      }

      if ($scope.tab.marketPrice > 0) {
        if (!/^\d+(\.\d{1,2})?$/.test($scope.tab.marketPrice)) {
          Popup.notice("成本价只能精确到2位小数", 3000, function () {});
          return false;
        }
      } else if ($scope.tab.marketPrice == 0) {} else {
        Popup.notice("零售价不能小于0", 3000, function () {});
        return;
      }

      for (var i = 0; i < $scope.obj.skuList.length; i++) {
        $scope.obj.skuList[i].marketPrice = $scope.tab.marketPrice;
      }

      selectObj.marketPrice = $scope.tab.marketPrice;
    }
    if ($scope.tabIdx == 4) {
      if ($scope.tab.status == null || $scope.tab.status == undefined) {
        Popup.notice("请选择状态", 3000, function () {});
        return;
      }

      for (var i = 0; i < $scope.obj.skuList.length; i++) {
        $scope.obj.skuList[i].status = $scope.tab.status;
      }
      selectObj.status = $scope.tab.status;
    }
    if ($scope.tabIdx == 5) {
      if ($scope.tab.canBeDiscounted == null || $scope.tab.canBeDiscounted == undefined) {
        Popup.notice("请选择是否折扣", 3000, function () {});
        return;
      }

      for (var i = 0; i < $scope.obj.skuList.length; i++) {
        $scope.obj.skuList[i].canBeDiscounted = $scope.tab.canBeDiscounted;
      }
      selectObj.canBeDiscounted = $scope.tab.canBeDiscounted;
    }
    if ($scope.tabIdx == 6) {
      if ($scope.tab.allowPoints == null || $scope.tab.allowPoints == undefined) {
        Popup.notice("请选择是否积分", 3000, function () {});
        return;
      }

      for (var i = 0; i < $scope.obj.skuList.length; i++) {
        $scope.obj.skuList[i].allowPoints = $scope.tab.allowPoints;
      }
      selectObj.allowPoints = $scope.tab.allowPoints;
    }

    if ($scope.tabIdx == 7) {
      /* if (
        $scope.tab.kpiPrice == null ||
        $scope.tab.kpiPrice == undefined
      ) {
        return Popup.notice("请输入绩效");
      } */
      for (var i = 0; i < $scope.obj.skuList.length; i++) {
        $scope.obj.skuList[i].kpiPrice = $scope.tab.kpiPrice;
      }
      selectObj.kpiPrice = $scope.tab.kpiPrice;
    }

    $scope.changeProducSkuFactory = new ObjectFactory();
    var changepromise = $scope.changeProducSkuFactory.saveOrQuery("/admin/changeProductSkuSelectiveByProductId.json", selectObj);
    changepromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg);
      } else {
        Popup.notice("修改成功");
        $scope.setAllModal = false;
      }
    });
  };

  $scope.searchCategoryObjectFactory = new ObjectFactory();
  $scope.searchCategoryObjectFactory.saveOrQuery("/admin/getCategoryTree2Level.json");

  $scope.selectCategory = function (arr, name, id) {
    $scope.selectCategoryItemVoList(id);
    $scope.categoryChildren = arr;
    // $scope.obj.categoryId = id;
    $scope.seletedCategory = id;
    // $scope.categoryName = name;
    if ($scope.parentId !== id) {
      $scope.parentId = id;
      $scope.obj.categoryId = id;
      $scope.obj.category.categoryName = name;
      $scope.seletedCategoryId = "";
    }
  };

  $scope.selectCategoryId = function (categoryName, id) {
    $scope.obj.category.categoryName = categoryName;
    $scope.obj.categoryId = id;
    $scope.seletedCategoryId = id;
    $scope.selectCategoryItemVoList(id);
  };

  $scope.modify = function () {
    if (!$scope.obj.product.productName) {
      Popup.notice("产品名称不能为空", 2000, function () {});
      return;
    }
    if (!$scope.obj.brandId) {
      Popup.notice("品牌不能为空", 2000, function () {});
      return;
    }
    if (!$scope.obj.categoryId) {
      Popup.notice("类目不能为空", 2000, function () {});
      return;
    }
    if (!$scope.obj.product.productCode) {
      Popup.notice("产品编码不能为空", 2000, function () {});
      return;
    }
    $scope.productSkuListJson = JSON.stringify($scope.obj.skuList);
    if (!/^\d+$/.test($scope.obj.product.warningQuantity)) {
      Popup.notice("库存不足预警数量必须为正整数", 2000, function () {});
      return;
    }
    if (!/^\d+$/.test($scope.obj.product.warningExpiresDays)) {
      Popup.notice("近有效期预警天数必须为正整数", 2000, function () {});
      return;
    }

    for (var i = 0; i < $scope.obj.skuList.length; i++) {
      if ($scope.obj.product.modelType != 1) {
        if ($scope.obj.skuList[i].model1 == "") {
          $scope.obj.skuList[i].model1 = "无";
        }
      }
      if ($scope.obj.product.modelType != 2) {
        if ($scope.obj.skuList[i].model2 == "") {
          $scope.obj.skuList[i].model2 = "无";
        }
      }

      if ($scope.obj.skuList[i].costPrice == null || $scope.obj.skuList[i].costPrice == undefined) {
        Popup.notice("请输入成本价", 3000, function () {});
        return;
      }

      if ($scope.obj.skuList[i].costPrice > 0) {
        if (!/^\d+(\.\d{1,2})?$/.test($scope.obj.skuList[i].costPrice)) {
          Popup.notice("成本价只能精确到2位小数", 3000, function () {});
          return false;
        }
      } else if ($scope.obj.skuList[i].costPrice == 0) {} else {
        Popup.notice("成本价不能小于0", 3000, function () {});
        return;
      }

      if ($scope.obj.skuList[i].marketPrice == null || $scope.obj.skuList[i].marketPrice == undefined) {
        Popup.notice("请输入零售价", 3000, function () {});
        return;
      }

      if ($scope.obj.skuList[i].marketPrice > 0) {
        if (!/^\d+(\.\d{1,2})?$/.test($scope.obj.skuList[i].marketPrice)) {
          Popup.notice("零售价只能精确到2位小数", 3000, function () {});
          return false;
        }
      } else if ($scope.obj.skuList[i].marketPrice == 0) {} else {
        Popup.notice("零售价不能小于0", 3000, function () {});
        return;
      }
    }
    var productSpecialItemJson = JSON.stringify(Utils.commonComponentFormat.get($scope.categoryItemVoList));
    $scope.updateProductObjectFactory = new ObjectFactory();
    var updatepromise = $scope.updateProductObjectFactory.saveOrQuery("/admin/updateProductAndSkuList.json", {
      id: $scope.productId,
      productName: $scope.obj.product.productName,
      mainSupplierId: $scope.obj.product.mainSupplierId,
      productCode: $scope.obj.product.productCode,
      remark: $scope.obj.product.remark,
      factory: $scope.obj.product.factory,
      factoryLicense: $scope.obj.product.factoryLicense,
      englishName: $scope.obj.product.englishName,
      pinyin: $scope.obj.product.pinyin,
      model1Name: $scope.obj.product.model1Name,
      model2Name: $scope.obj.product.model2Name,
      warningExpiresDays: $scope.obj.product.warningExpiresDays,
      warningQuantity: $scope.obj.product.warningQuantity,
      highWarningQuantity: $scope.obj.product.highWarningQuantity,
      productSkuListJson: $scope.productSkuListJson,
      productSpecialItemJson: productSpecialItemJson,
      brandId: $scope.obj.brandId,
      categoryId: $scope.obj.categoryId
    });
    updatepromise.then(function (res) {
      if (res.status == 1) {
        Popup.notice(res.errmsg, 2000, function () {});
      } else {
        Popup.notice("修改成功", 2000, function () {});
        // $state.go('systemSetting.materiallist');
        // window.history.back(-2)
        var arr = res.result.list;
        for (var j = 0; j < arr.length; j++) {
          $scope.obj.skuList[j] = arr[j];
        }
        var productId = $scope.productId;
        CommonRequest.isProductNeedFirstMarketCheck(productId, function (needCheck) {
          if (!needCheck) return;
          $scope.firstApproval.setProductId(productId);
          $scope.firstApproval.open(true);
        });
      }
    });
  };

  $scope.back = function () {
    window.history.back(-2);
  };
  $scope.pinyin = function () {
    $scope.getpinyinObjectFactory = new ObjectFactory();
    var promise = $scope.getpinyinObjectFactory.saveOrQuery("/admin/getPinyin.json", { src: $scope.obj.product.productName });
    promise.then(function (res) {
      $scope.obj.product.pinyin = res.object;
    });
  };
  $scope.deleteProduct = function (index) {
    if (!$scope.storeCustomeIndexArr) {
      $scope.storeCustomeIndexArr = [];
    }
    $scope.storeCustomeIndexArr.push($scope.obj.skuList[index].customeIndex);
    $scope.obj.skuList.splice(index, 1);
  };

  $scope.addProductList = function () {
    var index = $scope.obj.skuList.length - 1;

    if ($scope.obj.product.model1Name != "无") {
      if (!$scope.obj.skuList[index].model1) {
        Popup.notice("请填写规格一", 2000, function () {});
        return;
      }
    }

    if ($scope.obj.product.model2Name != "无") {
      if (!$scope.obj.skuList[index].model2) {
        Popup.notice("请填写规格二", 2000, function () {});

        return;
      }
    }

    if ($scope.obj.skuList[index].costPrice == null || $scope.obj.skuList[index].costPrice == undefined) {
      Popup.notice("请输入成本价", 3000, function () {});
      return;
    }

    if ($scope.obj.skuList[index].costPrice > 0) {
      if (!/^\d+(\.\d{1,2})?$/.test($scope.obj.skuList[index].costPrice)) {
        Popup.notice("成本价只能精确到2位小数", 3000, function () {});
        return false;
      }
    } else if ($scope.obj.skuList[index].costPrice == 0) {} else {
      Popup.notice("成本价不能小于0", 3000, function () {});
      return;
    }

    if ($scope.obj.skuList[index].marketPrice == null || $scope.obj.skuList[index].marketPrice == undefined) {
      Popup.notice("请输入零售价", 3000, function () {});
      return;
    }

    if ($scope.obj.skuList[index].marketPrice > 0) {
      if (!/^\d+(\.\d{1,2})?$/.test($scope.obj.skuList[index].marketPrice)) {
        Popup.notice("零售价只能精确到2位小数", 3000, function () {});
        return false;
      }
    } else if ($scope.obj.skuList[index].marketPrice == 0) {} else {
      Popup.notice("零售价不能小于0", 3000, function () {});
      return;
    }

    if (!$scope.obj.skuList[index].skuCode) {
      Popup.notice("请输入条形码", 3000, function () {});
      return;
    }

    if ($scope.obj.skuList.length > 999) {
      Popup.notice("最多只能999条", 2000, function () {});
      return;
    }

    var skucode = "";

    $scope.num = $scope.num + 1;
    var numlength = $scope.num + "";

    var storeCustomeIndex = 0;
    if ($scope.storeCustomeIndex === undefined) {
      $scope.storeCustomeIndex = $scope.getProductVoObjectFactory.count + 1;
      storeCustomeIndex = $scope.storeCustomeIndex;
    } else {
      if ($scope.storeCustomeIndexArr && $scope.storeCustomeIndexArr.length) {
        storeCustomeIndex = Math.min.apply(Math, _toConsumableArray($scope.storeCustomeIndexArr));
        $scope.storeCustomeIndexArr.splice($scope.storeCustomeIndexArr.indexOf(storeCustomeIndex), 1);
      } else {
        ++$scope.storeCustomeIndex;
        storeCustomeIndex = $scope.storeCustomeIndex;
      }
    }
    if (String(storeCustomeIndex).length == 1) {
      skucode = $scope.obj.product.productCode + "00" + storeCustomeIndex;
    } else if (String(storeCustomeIndex).length == 2) {
      skucode = $scope.obj.product.productCode + "0" + storeCustomeIndex;
    } else {
      skucode = $scope.obj.product.productCode + storeCustomeIndex + "";
    }
    $scope.obj.skuList.push({
      customeIndex: storeCustomeIndex,
      model1: $scope.obj.skuList[index].model1,
      model2: $scope.obj.skuList[index].model2,
      skuCode: skucode,
      unitName: $scope.obj.skuList[index].unitName,
      costPrice: $scope.obj.skuList[index].costPrice,
      marketPrice: $scope.obj.skuList[index].marketPrice,
      status: $scope.obj.skuList[index].status,
      canBeDiscounted: $scope.obj.skuList[index].canBeDiscounted,
      allowPoints: $scope.obj.skuList[index].allowPoints
    });
  };

  $scope.imgIndex = 0;
  $scope.imgModalModify = false;
  $scope.chooseImg = function (idx) {
    $scope.imgModalModify = true;
    $scope.imgIndex = idx;
  };
}]);
'use strict';

angular.module('bestvisionWeb').controller('medicalFeesListCtrl', ['$scope', 'Popup', 'HttpFactory', '$state', 'ObjectFactory', 'ListFactory', function ($scope, Popup, HttpFactory, $state, ObjectFactory, ListFactory) {
    $scope.obj = {};
    $scope.status = [{ id: null, name: '全部状态' }, { id: 0, name: '正常' }, { id: 1, name: '停用' }];
    $scope.obj.status = null;
    $scope.obj.examineType = 2;
    $scope.examineIdArray = [];

    $scope.object = {};
    $scope.object.status = 0;
    $scope.discount = {};
    $scope.discount.canBeDiscounted = 1;

    $scope.pageSize = 20;

    $scope.searchSupplierList = function () {
        $scope.getSupplierListFactory = new ListFactory('/admin/getExamineVoList.json', 0, $scope.pageSize, $scope.obj);
        var promise = $scope.getSupplierListFactory.nextPage();

        promise.then(function (data) {

            $("#Pagination").pagination($scope.getSupplierListFactory.count, {
                items_per_page: $scope.pageSize,
                callback: function callback(index) {
                    $scope.getSupplierListFactory.clearAndSetIndex(index * $scope.pageSize);
                    var nextPromise = $scope.getSupplierListFactory.nextPage();
                    nextPromise.then(function (response) {
                        var count = 0;
                        for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
                            for (var j = 0; j < $scope.examineIdArray.length; j++) {

                                if ($scope.getSupplierListFactory.items[i].examine.id == $scope.examineIdArray[j]) {
                                    count = count + 1;
                                }
                            }
                        }
                        if ($scope.examineIdArray.length && $scope.getSupplierListFactory.items && count) {
                            if (count == $scope.getSupplierListFactory.length) {
                                $scope.isAll = true;
                            } else {
                                $scope.isAll = false;
                            }
                        } else {
                            $scope.isAll = false;
                        }
                    });
                }
            });
        });
    };
    $scope.searchSupplierList();

    $scope.searchTab = function (index) {
        $scope.obj.status = index;
        $scope.searchSupplierList();
    };
    $scope.searchDiscount = function (index) {
        $scope.obj.canBeDiscounted = index;
        $scope.searchSupplierList();
    };

    $scope.labelBtn = true;

    $scope.hideTagModal = function (event) {

        $scope.tagModal = false;
        $scope.discountModal = false;
    };

    $scope.changeStatus = function () {
        var arrLabel = [];
        for (var i = 0; i < $scope.examineIdArray.length; i++) {
            if ($scope.examineIdArray[i] != null && $scope.examineIdArray[i] != 'null') {

                arrLabel.push($scope.examineIdArray[i]);
            }
        }
        $scope.object.examineIdArray = arrLabel;
        $scope.changeStatusObjectFactory = new ObjectFactory();
        var statusPromise = $scope.changeStatusObjectFactory.saveOrQuery('/admin/updateByExamineIdArraySelective.json', $scope.object);
        statusPromise.then(function (res) {

            if (res.status == 1) {
                Popup.notice(res.errmsg);
            } else {
                console.log($scope.getSupplierListFactory);
                for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
                    for (var j = 0; j < arrLabel.length; j++) {
                        if (arrLabel[j] == $scope.getSupplierListFactory.items[i].examine.id) {

                            $scope.getSupplierListFactory.items[i].examine.status = $scope.object.status;
                        }
                    }
                }

                Popup.notice('修改成功');
                $scope.tagModal = false;
            }
        });
    };

    $scope.changeDiscount = function () {
        var arrLabel = [];
        console.log($scope.examineIdArray);
        for (var i = 0; i < $scope.examineIdArray.length; i++) {
            if ($scope.examineIdArray[i] != null && $scope.examineIdArray[i] != 'null') {

                arrLabel.push($scope.examineIdArray[i]);
            }
        }
        $scope.discount.examineIdArray = arrLabel;
        $scope.changeDiscountObjectFactory = new ObjectFactory();
        var discountPromise = $scope.changeDiscountObjectFactory.saveOrQuery('/admin/updateByExamineIdArraySelective.json', $scope.discount);
        discountPromise.then(function (res) {
            if (res.status == 1) {
                Popup.notice(res.errmsg);
            } else {
                Popup.notice('修改成功');
                $scope.discountModal = false;
                // $scope.isAll = false;
                // $scope.labelBtn = true;
                // $scope.examineIdArray = [];

                for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
                    for (var j = 0; j < arrLabel.length; j++) {
                        if (arrLabel[j] == $scope.getSupplierListFactory.items[i].examine.id) {
                            $scope.getSupplierListFactory.items[i].examine.canBeDiscounted = $scope.discount.canBeDiscounted;
                        }
                    }
                }
            }
        });
    };

    $scope.checkAll = function () {

        if ($scope.isAll) {

            for (var i = 0; i < $scope.getSupplierListFactory.items.length; i++) {
                $scope.examineIdArray[i + $scope.getSupplierListFactory.index - $scope.pageSize] = $scope.getSupplierListFactory.items[i].examine.id;
                $scope.labelBtn = false;
            }
        } else {

            for (var j = 0; j < $scope.getSupplierListFactory.items.length; j++) {
                $scope.examineIdArray[j + $scope.getSupplierListFactory.index - $scope.pageSize] = null;
                $scope.labelBtn = true;
            }
        }
    };

    $scope.setLabelBtn = function () {

        var arrLabel = [];

        for (var i = 0; i < $scope.getSupplierListFactory.length; i++) {
            if ($scope.examineIdArray[i + $scope.getSupplierListFactory.index - $scope.pageSize] != 'null' && $scope.examineIdArray[i + $scope.getSupplierListFactory.index - $scope.pageSize] != null) {
                $scope.labelBtn = false;
                arrLabel.push($scope.examineIdArray[i + $scope.getSupplierListFactory.index - $scope.pageSize]);
            }
        }
        console.log(arrLabel);
        console.log($scope.getSupplierListFactory.items.length);
        if (!arrLabel.length) {
            $scope.labelBtn = true;
        }
        if (arrLabel.length != $scope.getSupplierListFactory.items.length) {
            $scope.isAll = false;
        } else {
            $scope.isAll = true;
        }
    };

    $scope.deleteBatch = function () {
        if ($scope.labelBtn) return;
        Popup.confirm('挂号收费删除后不可恢复，确定要删除？', function () {
            var examineIdArray = $scope.examineIdArray.filter(function (v) {
                return v;
            });
            HttpFactory.object('/admin/deleteExamines.json', {
                examineIdArray: examineIdArray
            }).then(function () {
                Popup.notice('删除成功!');
                $scope.labelBtn = true;
                $scope.isAll = false;
                $scope.examineIdArray = [];
                $scope.searchSupplierList();
            });
        });
    };
}]);
'use strict';

angular.module('bestvisionWeb').controller('memberChannelListCtrl', ['$scope', 'HttpFactory', 'Popup', '$rootScope', '$state', 'ObjectFactory', 'ListFactory', function ($scope, HttpFactory, Popup, $rootScope, $state, ObjectFactory, ListFactory) {

    $scope.obj = {};
    $scope.dealRoom = function (dealList) {
        var specList = [];
        //ai 写的代码
        dealList.forEach(function (item) {
            item.root.childList = item.childList;
            specList.push(item.root);
            if (item.childList && item.childList.length) {
                item.childList.forEach(function (child) {
                    child.root.childList = item.childList;
                    child.root.fatherId = item.root.id;
                    child.root.display = true;
                    specList.push(child.root);
                });
            }
        });
        $scope.specList = specList;
    };
    $scope.searchSpecList = function (index, loadPagin) {
        HttpFactory.list("/admin/getChannelTagTreeVoPage.json", {
            index: index,
            length: 10,
            keyword: $scope.obj.keyword,
            familyId: 0
        }).then(function (res) {
            $scope.sourceTotal = res.count;
            $scope.dealRoom(res.list);
            loadPagin && HttpFactory.pagination("#Pagination", res, $scope.searchSpecList);
        });
        return;
        $scope.getSupplierListFactory = new ListFactory('/admin/getChannelTagTreeVoPage.json', 0, 10, $scope.obj);
        var promise = $scope.getSupplierListFactory.nextPage();
        var pageSize = 10;
        promise.then(function (data) {
            $("#Pagination").pagination($scope.getSupplierListFactory.count, {
                items_per_page: pageSize,
                callback: function callback(index) {
                    $scope.getSupplierListFactory.clearAndSetIndex(index * pageSize);
                    $scope.getSupplierListFactory.nextPage();
                }
            });
        });
    };
    $scope.searchSpecList(0, true);
    $scope.showChild = function (item) {
        if (!item.childList) {
            return;
        }
        item.isChose = !item.isChose;
        item.childList.forEach(function (child) {
            $scope.specList.forEach(function (spec) {
                if (spec.id === child.root.id) {
                    spec.display = !spec.display;
                }
            });
        });
    };
    $scope.searchTab = function (idx) {
        $scope.obj.status = idx;
        $scope.searchSpecList(0, true);
    };

    $scope.modify = {};
    $scope.add = {};

    $scope.showModify = function (name, id) {
        $scope.smsContent = id;
        $scope.modify.tagName = name;
    };
    $scope.tagNameShow = true;
    $scope.confirmBlur = function () {
        if ($scope.add.tagName) {
            $scope.tagNameShow = true;
        } else {
            $scope.tagNameShow = false;
        }
    };
    $scope.memberSource = {
        familyId: 0,
        isFirstSon: false,
        getName: function getName() {
            return ($scope.memberSource.familyId !== 0 ? '子' : '') + '来源';
        }
    };
    $scope.addSupplier = function () {
        if (!$scope.add.tagName) {
            Popup.notice('请输入会员来源名称', 3000, function () {});
            return false;
        }
        var add = function add() {
            $scope.adminObjectFactory = new ObjectFactory();
            var promise = $scope.adminObjectFactory.saveOrQuery('/admin/insertChannelTag.json', {
                tagName: $scope.add.tagName,
                familyId: $scope.memberSource.familyId
            });
            promise.then(function (res) {
                if (res.status == 0) {
                    Popup.notice('新增成功', 3000, function () {});
                    $scope.searchSpecList(0, true);
                    $scope.isShow = false;
                } else {
                    Popup.notice(res.errmsg, 3000, function () {});
                }
            });
        };
        /*  if ($scope.memberSource.familyId != 0 && $scope.memberSource.isFirstSon) {
             return Popup.confirm('原本在“一级分类名称”分类下的会员，将统一挪动到“一级分类名称”下新创建的“二级分类名称”子分类中，确认创建该子分类吗？', add)
         } */
        add();
    };
    $scope.modifyTag = function (id, event, idx) {
        event.stopPropagation();
        if (!$scope.modify.tagName) {
            Popup.notice('来源名不能为空');
            return false;
        }
        $scope.modify.id = id;
        $scope.modifyTagFactory = new ObjectFactory();
        var modifyTagPromise = $scope.modifyTagFactory.saveOrQuery('/admin/updateChannelTag.json', $scope.modify);
        modifyTagPromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice('修改成功');
                $scope.smsContent = null;
                $scope.specList[idx].tagName = res.result.object.tagName;
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };

    $scope.showModal = function (familyId, childList) {
        childList === null ? childList = [] : childList;
        $scope.memberSource.familyId = familyId;
        $scope.memberSource.isFirstSon = !childList.length;
        $scope.add.tagName = null;
        $scope.isShow = true;
    };
    $scope.hideModal = function () {
        $scope.isShow = false;
    };
    $scope.cancel = function (event) {
        $scope.smsContent = null;
        event.stopPropagation();
    };
    $scope.deleteTemplate = function (id) {
        $scope.deleteTemplateObjectFactory = new ObjectFactory();
        var deletePromise = $scope.deleteTemplateObjectFactory.saveOrQuery("/admin/deleteChannelTag.json", {
            id: id
        });
        deletePromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice("删除成功");
                $scope.searchSpecList(0, true);
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };
    $scope.recovery = function (id) {
        $scope.recoveryTemplateObjectFactory = new ObjectFactory();
        var deletePromise = $scope.recoveryTemplateObjectFactory.saveOrQuery("/admin/enableMedicalRecordTemplate.json", {
            id: id
        });
        deletePromise.then(function (res) {
            if (res.status == 0) {
                Popup.notice("恢复成功");
                $scope.searchSpecList(0, true);
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };

    $scope.tab = 1;
    $scope.setRecyle = function (tab) {
        $scope.obj.keyword = null;
        if (tab == 1) {
            $scope.tab = 2;
            $scope.obj.status = 1;
        } else {
            $scope.tab = 1;
            $scope.obj.status = 0;
        }
        $scope.searchSpecList(0, true);
    };
    $scope.talking = function () {
        var father = 'father:';
        var son = 'son:';
        var mom = 'mom:';
    };
}]);
'use strict';

