angular.module("bestvisionWeb").controller("stockAdminCtrl", ["$scope", "Popup", "$rootScope", "$state", "ObjectFactory", "$timeout", function ($scope, Popup, $rootScope, $state, ObjectFactory, $timeout) {
    $scope.tab = 0;
    $scope.obj = {};
    $scope.releaseStock = 0;
    $scope.judgeReleaseStock = function (_ref) {
        var releaseStock = _ref.releaseStock,
            releaseStockEnable = _ref.releaseStockEnable,
            releaseStockDaysBefore = _ref.releaseStockDaysBefore;

        // Byte releaseStockEnable     0:下单后一直不释放库存 1:要释放库存
        // Byte releaseStockDaysBefore 就诊当天为第一天，0:第二天凌晨释放库存 14:第十五天凌晨释放库存 29:第三十天凌晨释放库存
        var stockList = ['0,0', '1,0', '1,14', '1,29'];
        if (releaseStock !== undefined) {
            var sList = stockList[releaseStock].split(',');
            return {
                releaseStockEnable: Number(sList[0]),
                releaseStockDaysBefore: Number(sList[1])
            };
        }
        var stock = [releaseStockEnable, releaseStockDaysBefore].join('');
        var rStock = stockList.findIndex(function (s) {
            return s === stock;
        });
        if (rStock !== -1) {
            $scope.releaseStock = rStock;
            return;
        }
        //不释放库存
        if (releaseStockEnable === 0) {
            $scope.releaseStock = 0;
            return;
        }
        //释放库存
        if (releaseStockEnable === 1) {
            //第二天释放
            if (releaseStockDaysBefore === 0) {
                $scope.releaseStock = 1;
                return;
            }
            //第十五天释放
            if (releaseStockDaysBefore === 1) {
                $scope.releaseStock = 2;
                return;
            }
            //第三十天释放
            if (releaseStockDaysBefore === 2) {
                $scope.releaseStock = 3;
                return;
            }
        }
    };
    window.getStockSet(ObjectFactory).then(function (res) {
        $scope.obj.enableNegativeStock = res.enableNegativeStock;
        $scope.obj.enableTransferStock = res.enableTransferStock;
        $scope.obj.enableStockDateChange = res.enableStockDateChange;
        $scope.obj.stockExpiresWarningWhenOrder = res.stockExpiresWarningWhenOrder;
        $scope.obj.orderRefundStorehouse = res.orderRefundStorehouse;
        $scope.obj.modelShow = res.modelShow;
        $scope.judgeReleaseStock(res);
        MiniVersion.IsMiniVersion(ObjectFactory).then(function (isMiniVersion) {
            $timeout(function () {
                if (isMiniVersion) {
                    $scope.isMiniVersion = true;
                    $scope.obj.stockOutWhenPayOrder = 0;
                    return;
                }
                $scope.isMiniVersion = false;
                $scope.obj.stockOutWhenPayOrder = res.stockOutWhenPayOrder;
            });
        });
    });
    $scope.setTab = function (tab) {
        $scope.tab = tab;
    };
    $scope.modify = function () {
        $scope.savePointFactory = new ObjectFactory();
        var promise = $scope.savePointFactory.saveOrQuery("/admin/saveStockConf.json", $scope.obj);
        promise.then(function (res) {
            if (res.status == 0) {
                Popup.notice("修改成功");
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };
    $scope.modifyStock = function () {
        var vo = $scope.judgeReleaseStock({
            releaseStock: $scope.releaseStock
        });
        new ObjectFactory().saveOrQuery("/admin/saveStockConfReleaseStock.json", vo).then(function (res) {
            if (res.status == 0) {
                Popup.notice("修改成功");
            } else {
                Popup.notice(res.errmsg);
            }
        });
    };
}]);
"use strict";

angular.module("bestvisionWeb").controller("suiFangJieLunTemCtrl", ["$scope", "$stateParams", "Popup", "$rootScope", "$timeout", "$state", "ListFactory", "ObjectFactory", function ($scope, $stateParams, Popup, $rootScope, $timeout, $state, ListFactory, ObjectFactory) {
  $scope.obj = {};
  $scope.obj.id = $stateParams.id;
  $scope.obj.shared = 1; //模板类型默认为共享使用
  $scope.getContent = function () {
    $scope.getPackageFactory = new ObjectFactory();
    var packagePromise = $scope.getPackageFactory.saveOrQuery("/admin/getFollowUpResultTemplateVo.json", { id: $scope.obj.id });
    packagePromise.then(function (res) {
      $scope.obj = res.result.object.followUpResultTemplate;
    });
  };
  $stateParams.id && $scope.getContent();

  $scope.add = function () {
    if (!$scope.obj.templateName) {
      Popup.notice("模板名称不能为空");
      return false;
    }
    if (!$scope.obj.templateResult) {
      Popup.notice("随访内容不能为空");
      return false;
    }
    $scope.adminObjectFactory = new ObjectFactory();
    //如果是修改则需要携带id,默认为新增
    var url = $stateParams.id ? "/admin/updateFollowUpResultTemplate.json" : "/admin/insertFollowUpResultTemplate.json";
    var promise = $scope.adminObjectFactory.saveOrQuery(url, $scope.obj);
    promise.then(function (res) {
      if (res.status == 0) {
        window.history.back();
      } else {
        Popup.notice(res.errmsg, 3000, function () {});
      }
    });
  };
}]);
"use strict";

